$device_online = false;
$device_online_timestamp = (int) round(microtime(true) * 1000);
$active_node_detail = [];
$want_node_id = trim((string) ($resolved_node_id ?? ''));
if (!empty($device_ui_info['node_details']) && is_array($device_ui_info['node_details'])) {
    if ($want_node_id !== '') {
        foreach ($device_ui_info['node_details'] as $detail) {
            if (!is_array($detail)) {
                continue;
            }
            $detail_id = trim((string) ($detail['id'] ?? $detail['node_id'] ?? ''));
            if ($detail_id !== '' && strcasecmp($detail_id, $want_node_id) === 0) {
                $active_node_detail = $detail;
                break;
            }
        }
    }
}

