            continue;
        }
        $pageNo = trim((string) ($uiRow['page_no'] ?? ''));
        $pageName = trim((string) ($uiRow['page_name'] ?? ''));
        $baseSequence = max(1, (int) ($uiRow['sequence'] ?? 1));
        $parameters = [];
        if (!empty($uiRow['parameters']) && is_array($uiRow['parameters'])) {
            $parameters = $uiRow['parameters'];
        } elseif (!empty($uiRow['parameter'])) {
            $parameters = [(string) $uiRow['parameter']];
        }
        foreach ($parameters as $parameterIndex => $parameterName) {
            $parameterName = trim((string) $parameterName);
            if ($parameterName === '') {
                continue;
            }
            $resolvedPageNo = $pageNo !== '' ? $pageNo : '1';
            $resolvedPageName = $pageName !== '' ? $pageName : ('Page ' . $resolvedPageNo);
            $rows[] = [
                'page_no' => $resolvedPageNo,
                'page_name' => $resolvedPageName,
                'parameter' => $parameterName,
                'sequence' => $baseSequence + (int) $parameterIndex,
                'api' => [],
            ];
        }
    }
}

if (empty($rows)) {
    $saved_schema_for_rows = !empty($ui_theme['schema']) && is_array($ui_theme['schema']) ? $ui_theme['schema'] : [];
    $schemaControls = !empty($saved_schema_for_rows['controls']) && is_array($saved_schema_for_rows['controls'])
        ? $saved_schema_for_rows['controls']
        : [];
    foreach ($schemaControls as $index => $control) {
        if (!is_array($control)) {
            continue;
        }
        $parameterName = trim((string) ($control['parameterName'] ?? $control['parameter'] ?? $control['label'] ?? ''));
        if ($parameterName === '') {
            continue;
        }
        $pageNo = trim((string) ($control['pageNo'] ?? '1'));
        $pageName = trim((string) ($control['pageName'] ?? ('Page ' . $pageNo)));
        $rows[] = [
            'page_no' => $pageNo !== '' ? $pageNo : '1',
            'page_name' => $pageName !== '' ? $pageName : ('Page ' . ($pageNo !== '' ? $pageNo : '1')),
            'parameter' => $parameterName,
            'sequence' => (int) ($control['sequence'] ?? ($index + 1)),
            'api' => [],
        ];
    }
}


// Canonical schema endpoint used by Studio and Flutter:
// /v8/api_schema.php?model_no={modelno}&node_id={node_id}

$pages = [];
$savedPageMap = [];
if (!empty($model_data['page_names_array']) && is_array($model_data['page_names_array'])) {
    $savedPageMap = $model_data['page_names_array'];
} elseif (!empty($model_data['page_names'])) {
    $decodedPageMap = json_decode((string) $model_data['page_names'], true);
    if (is_array($decodedPageMap)) {
        $savedPageMap = $decodedPageMap;
    }
}

foreach ($savedPageMap as $savedPageNo => $savedPageName) {
    $savedPageNo = trim((string) $savedPageNo);
    if ($savedPageNo === '') {
        continue;
    }
    $pages[$savedPageNo] = [
        'page_no' => $savedPageNo,
        'page_name' => trim((string) $savedPageName) !== '' ? (string) $savedPageName : ('Page ' . $savedPageNo),
        'params' => [],
    ];
}

$knownPageNumbers = [];
foreach ($rows as $row) {
    $rawPageNo = trim((string) ($row['page_no'] ?? ''));
    if ($rawPageNo !== '') {
        $knownPageNumbers[$rawPageNo] = true;
    }
}

$nextGeneratedPageNo = 1;
if (!empty($knownPageNumbers)) {
    $numericPageNos = array_map('intval', array_keys($knownPageNumbers));
    $nextGeneratedPageNo = max($numericPageNos) + 1;
}
$generatedPageMap = [];

foreach ($rows as $index => $row) {
    $pageNo = trim((string) ($row['page_no'] ?? ''));
    if ($pageNo === '') {
        $pageName = trim((string) ($row['page_name'] ?? ''));
        $fallbackKey = $pageName !== '' ? strtolower($pageName) : ('row_' . $index);
        if (!isset($generatedPageMap[$fallbackKey])) {
            while (isset($knownPageNumbers[(string) $nextGeneratedPageNo])) {
                $nextGeneratedPageNo++;
            }
            $generatedPageMap[$fallbackKey] = (string) $nextGeneratedPageNo;
            $knownPageNumbers[(string) $nextGeneratedPageNo] = true;
            $nextGeneratedPageNo++;
        }
        $pageNo = $generatedPageMap[$fallbackKey];
    }


    
    if (!isset($pages[$pageNo])) {
        $pages[$pageNo] = [
            'page_no' => $pageNo,
            'page_name' => $row['page_name'] ?? ('Page ' . $pageNo),
            'params' => [],
        ];
    }

    $pages[$pageNo]['params'][] = [
        'parameter' => $row['parameter'] ?? '',
        'sequence' => (int) ($row['sequence'] ?? 0),
        'api' => !empty($row['api']) && is_array($row['api']) ? $row['api'] : [],
        'buttons' => [],
    ];
}

uksort($pages, function ($a, $b) {
    return ((int) $a) <=> ((int) $b);
});

foreach ($pages as &$page) {
    usort($page['params'], function ($a, $b) {
        return ((int) $a['sequence']) <=> ((int) $b['sequence']);
    });
}
unset($page);

$pages = array_values($pages);

