if (!function_exists('view_ui_is_text_input_type')) {
    function view_ui_is_text_input_type($apiType, $apiAccess = '')
    {
        $apiType = strtolower(trim((string) $apiType));
        $apiAccess = strtolower(trim((string) $apiAccess));

        if ($apiType === '') {
            return false;
        }

        if ($apiType === 'console' || $apiType === 'cmd' || strpos($apiType, 'enter text') !== false || $apiType === 'entertext') {
            return true;
        }

        if (strpos($apiType, 'text field') !== false || strpos($apiType, 'text input') !== false) {
            return true;
        }

        // Access no longer gates detection: a read-only text field still renders as a
        // text component, it is simply not editable. See view_ui_api_access_is_writable.
        return strpos($apiType, 'text') !== false;
    }
}

if (!function_exists('view_ui_is_direction_parameter')) {
    function view_ui_is_direction_parameter($paramName)
    {
        $paramName = strtolower(trim((string) $paramName));
        if ($paramName === '') {
            return false;
        }
        if (strpos($paramName, 'data flow') !== false || strpos($paramName, 'dataflow') !== false) {
            return false;
        }

        return $paramName === 'direction' || (bool) preg_match('/(^|[^a-z0-9])direction([^a-z0-9]|$)/', $paramName);
    }

    function view_ui_extract_option_tokens($raw)
    {
        if (is_array($raw)) {
            $tokens = [];
            foreach ($raw as $item) {
                $tokens = array_merge($tokens, view_ui_extract_option_tokens($item));
            }
            return $tokens;
        }
        $text = trim((string) $raw);
        if ($text === '' || $text === '[]') {
            return [];
        }
        if (preg_match_all('/\[([^\]]*)\]/', $text, $matches)) {
            $found = [];
            foreach ($matches[1] as $match) {
                $match = trim((string) $match);
                if ($match !== '') {
                    $found[] = $match;
                }
            }
            if (!empty($found)) {
                return $found;
            }
        }

        return [$text];
    }

    function view_ui_direction_options(array $apiMeta = [])
    {
        $labels = view_ui_extract_option_tokens($apiMeta['items'] ?? []);
        $values = view_ui_extract_option_tokens($apiMeta['item_values'] ?? []);
        $pairs = [];
        if (empty($labels)) {
            $pairs = [
                ['label' => '0', 'value' => '0'],
                ['label' => '1', 'value' => '1'],
            ];
        } else {
            foreach ($labels as $index => $label) {
                $pairs[] = [
                    'label' => (string) $label,
                    'value' => array_key_exists($index, $values) ? (string) $values[$index] : (string) $label,
                ];
            }
        }

        $uniqueValues = [];
        foreach ($pairs as $pair) {
            $uniqueValues[$pair['value']] = true;
        }
        if (count($uniqueValues) < count($pairs)) {
            foreach ($pairs as $index => $pair) {
                $pairs[$index]['value'] = $pair['label'];
            }
        }

        $mapped = [];
        $antiTokens = ['1', 'ccw', 'anticlockwise', 'anticlock', 'counterclockwise', 'counterclock', 'reverse', 'rev'];
        $cwTokens = ['0', 'cw', 'clockwise', 'clock', 'forward', 'fwd'];
        foreach ($pairs as $index => $pair) {
            $token = strtolower((string) preg_replace('/[^a-z0-9]+/', '', (string) $pair['label']));
            if (in_array($token, $antiTokens, true)) {
                $isAnti = true;
            } elseif (in_array($token, $cwTokens, true)) {
                $isAnti = false;
            } else {
                $isAnti = ($index === 1);
            }
            $mapped[] = [
                'label' => $isAnti ? 'Anti-clockwise' : 'Clockwise',
                'value' => (string) $pair['value'],
            ];
        }
        if (count($mapped) < 2) {
            return [
                ['label' => 'Clockwise', 'value' => isset($mapped[0]['value']) ? $mapped[0]['value'] : '0'],
                ['label' => 'Anti-clockwise', 'value' => '1'],
            ];
        }

        return array_slice($mapped, 0, 2);
    }
}

if (!function_exists('view_ui_match_api_ui_type_to_catalog_id')) {
    function view_ui_match_api_ui_type_to_catalog_id($apiType, $paramName = '')
    {
        $apiType = strtolower(trim((string) $apiType));
        $paramName = strtolower(trim((string) $paramName));
        $normalizedApiType = trim((string) preg_replace('/\s+/', ' ', (string) preg_replace('/[^a-z0-9]+/', ' ', $apiType)));

        if ($apiType === '' && $paramName === '') {
            return 'auto';
        }

        if (function_exists('view_ui_is_direction_parameter') && view_ui_is_direction_parameter($paramName)) {
            $blockedTypes = ['none', 'no', 'na', 'n/a', 'null', 'false', 'disabled'];
            if ($apiType === '' || !in_array($apiType, $blockedTypes, true)) {
                return 'segmented';
            }
        }

        $candidates = [
            ['id' => 'autoTriggerTimer', 'patterns' => ['auto trigger with timer'], 'exact' => false],
            ['id' => 'pushButton', 'patterns' => ['push button big', 'push button', 'power button'], 'exact' => false],
            ['id' => 'brightnessSlider', 'patterns' => ['brightness slider'], 'exact' => false],
            ['id' => 'airflowSlider', 'patterns' => ['airflow slider'], 'exact' => false],
            ['id' => 'cctSlider', 'patterns' => ['cct slider'], 'exact' => false],
            ['id' => 'saturationSlider', 'patterns' => ['saturation slider'], 'exact' => false],
            ['id' => 'hueSliderCustom', 'patterns' => ['hue slider custom'], 'exact' => false],
            ['id' => 'hueSlider', 'patterns' => ['hue slider'], 'exact' => false],
            ['id' => 'hueCircle', 'patterns' => ['hue circle'], 'exact' => false],
            ['id' => 'toastDisplay', 'patterns' => ['toast display'], 'exact' => false],
            ['id' => 'toggleSwitch', 'patterns' => ['toggle switch', 'toggle button', 'toggle', 'switch', 'checkbox', 'lock icon'], 'exact' => false],
            ['id' => 'notification', 'patterns' => ['notification'], 'exact' => false],
            ['id' => 'enterText', 'patterns' => ['text', 'text field', 'text input', 'enter text', 'entertext'], 'exact' => false],
            ['id' => 'cmd', 'patterns' => ['cmd', 'console'], 'exact' => true],
            ['id' => 'slider', 'patterns' => ['slider'], 'exact' => true],
            ['id' => 'dropdown', 'patterns' => ['drop down', 'drop-down', 'dropdown button', 'dropdownbutton', 'dropdown', 'select'], 'exact' => false],
            ['id' => 'trigger', 'patterns' => ['text trigger', 'trigger'], 'exact' => false],
            ['id' => 'display', 'patterns' => ['status led', 'network icon', 'alaram icon', 'alarm icon', 'eye icon', 'display'], 'exact' => false],
            ['id' => 'button', 'patterns' => ['button big', 'button'], 'exact' => false],
        ];

        usort($candidates, function ($a, $b) {
            $aLen = 0;
            foreach ($a['patterns'] as $pattern) {
                $aLen = max($aLen, strlen($pattern));
            }
            $bLen = 0;
            foreach ($b['patterns'] as $pattern) {
                $bLen = max($bLen, strlen($pattern));
            }
            return $bLen <=> $aLen;
        });

        foreach ($candidates as $item) {
            foreach ($item['patterns'] as $pattern) {
                $normalizedPattern = trim((string) preg_replace('/\s+/', ' ', (string) preg_replace('/[^a-z0-9]+/', ' ', $pattern)));
                $matched = !empty($item['exact'])
                  ? ($apiType === $pattern || $normalizedApiType === $normalizedPattern)
                  : ($apiType === $pattern || strpos($apiType, $pattern) !== false || $normalizedApiType === $normalizedPattern || preg_match('/(^| )' . preg_quote($normalizedPattern, '/') . '( |$)/', $normalizedApiType));
                if (!$matched) {
                    continue;
                }
                if ($item['id'] === 'button' && strpos($apiType, 'push button') !== false) {
                    continue;
                }
                if ($item['id'] === 'trigger' && strpos($apiType, 'auto trigger') !== false) {
                    continue;
                }
                if ($item['id'] === 'hueSlider' && strpos($apiType, 'custom') !== false) {
                    continue;
                }
                if ($item['id'] === 'slider' && $apiType !== 'slider') {
                    continue;
                }
                return $item['id'];
            }
        }

        if ($paramName !== '') {
            if (strpos($paramName, 'brightness') !== false || strpos($paramName, 'dimmer') !== false || strpos($paramName, 'light level') !== false) {
                return 'brightnessSlider';
            }
            if (strpos($paramName, 'airflow') !== false || strpos($paramName, 'fan speed') !== false) {
                return 'airflowSlider';
            }
            if (strpos($paramName, 'cct') !== false || strpos($paramName, 'color temp') !== false) {
                return 'cctSlider';
            }
            if (strpos($paramName, 'saturation') !== false) {
                return 'saturationSlider';
            }
            if (strpos($paramName, 'hue') !== false && strpos($paramName, 'circle') !== false) {
                return 'hueCircle';
            }
            if (strpos($paramName, 'hue') !== false) {
                return 'hueSlider';
            }
            if (strpos($paramName, 'power') !== false) {
                return 'toggleSwitch';
            }
            if (strpos($paramName, 'level') !== false) {
                return 'hueCircle';
            }
        }

        return 'auto';
    }
}

if (!function_exists('view_ui_detect_component_type')) {
    function view_ui_extract_command_ui_type(array $apiMeta)
    {
        $frame = !empty($apiMeta['frame']) && is_array($apiMeta['frame']) ? $apiMeta['frame'] : [];
        $commands = !empty($frame['commands']) && is_array($frame['commands']) ? $frame['commands'] : [];
        foreach ($commands as $field) {
            if (!is_array($field)) {
                continue;
            }
            $description = strtolower(trim((string) ($field['Field_description'] ?? $field['field_description'] ?? $field['default_name'] ?? '')));
            $uiType = trim((string) ($field['ui_type'] ?? $field['uiType'] ?? ''));
            $normalizedType = strtolower($uiType);
            if ($uiType === '' || in_array($normalizedType, ['none', 'no', 'na', 'n/a', 'null', 'false', 'disabled'], true)) {
                continue;
            }
            if (in_array($description, ['data', 'trigger'], true)) {
                return $uiType;
            }
        }
        foreach ($commands as $field) {
            if (!is_array($field)) {
                continue;
            }
            $uiType = trim((string) ($field['ui_type'] ?? $field['uiType'] ?? ''));
            $normalizedType = strtolower($uiType);
            if ($uiType !== '' && !in_array($normalizedType, ['none', 'no', 'na', 'n/a', 'null', 'false', 'disabled'], true)) {
                return $uiType;
            }
        }
        return '';
    }

    function view_ui_detect_component_type($paramName, array $apiMeta = [])
    {
        $hasSelectedApiPart = !empty($apiMeta['ui_type_source']) && !empty($apiMeta['ui_type']);
        $apiType = strtolower(trim((string) ($hasSelectedApiPart ? ($apiMeta['ui_type'] ?? '') : (view_ui_extract_command_ui_type($apiMeta) ?: ($apiMeta['ui_type'] ?? '')))));
        $apiAccess = strtolower(trim((string) ($apiMeta['access'] ?? '')));
        $matched = view_ui_match_api_ui_type_to_catalog_id($apiType, $paramName);
        if ($matched !== 'auto') {
            return $matched;
        }
        if (view_ui_is_text_input_type($apiType, $apiAccess)) {
            return (strpos($apiType, 'console') !== false || strpos($apiType, 'cmd') !== false) ? 'cmd' : 'enterText';
        }
        return 'auto';
    }
}

if (!function_exists('view_ui_is_auto_trigger_component')) {
    function view_ui_is_auto_trigger_component($uiType, $paramName = '', $catalogType = '')
    {
        $catalogType = trim((string) $catalogType);
        if ($catalogType === 'autoTriggerTimer') {
            return true;
        }

        $uiType = strtolower(trim((string) $uiType));
        $normalized = preg_replace('/[^a-z0-9]+/', ' ', $uiType);
        $normalized = trim((string) preg_replace('/\s+/', ' ', (string) $normalized));
        if ($normalized !== '' && (strpos($normalized, 'auto trigger') !== false || strpos($normalized, 'autotrigger') !== false)) {
            return true;
        }

        return view_ui_match_api_ui_type_to_catalog_id($uiType, $paramName) === 'autoTriggerTimer';
    }

    function view_ui_api_has_auto_trigger_component(array $apiMeta, array $apiComponents = [])
    {
        $candidates = $apiComponents;
        if (empty($candidates)) {
            $candidates = [$apiMeta];
        }
        if (!empty($apiMeta['ui_components']) && is_array($apiMeta['ui_components'])) {
            foreach ($apiMeta['ui_components'] as $component) {
                $candidates[] = $component;
            }
        }

        foreach ($candidates as $component) {
            if (!is_array($component)) {
                continue;
            }
            $uiType = (string) ($component['ui_type'] ?? '');
            $catalogType = (string) ($component['catalogComponentType'] ?? ($component['componentType'] ?? ''));
            $paramName = (string) ($component['parameter'] ?? ($component['parameterName'] ?? ($apiMeta['parameter'] ?? '')));
            if (view_ui_is_auto_trigger_component($uiType, $paramName, $catalogType)) {
                return true;
            }
        }

        return view_ui_is_auto_trigger_component(
            (string) ($apiMeta['ui_type'] ?? ''),
            (string) ($apiMeta['parameter'] ?? ($apiMeta['parameterName'] ?? ''))
        );
    }
}

if (!function_exists('view_ui_extract_all_ui_components')) {
    function view_ui_api_ui_type_is_usable($uiType)
    {
        $normalizedType = strtolower(trim((string) $uiType));
        return $normalizedType !== '' && !in_array($normalizedType, ['none', 'no', 'na', 'n/a', 'null', 'false', 'disabled'], true);
    }

    function view_ui_flag_is_true($value)
    {
        if (is_array($value)) {
            foreach ($value as $item) {
                if (view_ui_flag_is_true($item)) {
                    return true;
                }
            }
            return false;
        }

        $raw = strtolower(trim((string) $value));
        if ($raw === '') {
            return false;
        }

        $decoded = json_decode($raw, true);
        if (is_array($decoded)) {
            return view_ui_flag_is_true($decoded);
        }

        return in_array($raw, ['1', 'true', 'yes', 'on'], true);
    }

    function view_ui_source_has_multiple_ui(array $apiMeta, $source)
    {
        $source = strtolower(trim((string) $source));
        $bySource = [];
        if (!empty($apiMeta['multiple_ui_by_source']) && is_array($apiMeta['multiple_ui_by_source'])) {
            $bySource = $apiMeta['multiple_ui_by_source'];
        }
        $frame = !empty($apiMeta['frame']) && is_array($apiMeta['frame']) ? $apiMeta['frame'] : [];
        if (empty($bySource) && !empty($frame['multiple_ui_by_source']) && is_array($frame['multiple_ui_by_source'])) {
            $bySource = $frame['multiple_ui_by_source'];
        }
        if (array_key_exists($source, $bySource)) {
            return view_ui_flag_is_true($bySource[$source]);
        }

        $flags = $frame['multiple_ui'] ?? ($apiMeta['multiple_ui'] ?? []);
        if (!is_array($flags)) {
            return $source === 'command' && view_ui_flag_is_true($flags);
        }
        $index = $source === 'response' ? 1 : ($source === 'error' ? 2 : 0);
        if (isset($flags[$index]) && view_ui_flag_is_true($flags[$index])) {
            return true;
        }
        if ($source === 'command') {
            foreach ($flags as $flag) {
                if (view_ui_flag_is_true($flag)) {
                    return true;
                }
            }
        }
        return false;
    }

    function view_ui_field_level(array $field)
    {
        $level = strtolower(trim((string) ($field['field_level'] ?? ($field['fieldLevel'] ?? 'bytewise'))));
        return $level === 'bitwise' ? 'bitwise' : 'bytewise';
    }

    function view_ui_source_has_bitwise_ui(array $fields)
    {
        foreach ($fields as $field) {
            if (!is_array($field)) {
                continue;
            }
            if (view_ui_field_level($field) === 'bitwise' && view_ui_api_ui_type_is_usable($field['ui_type'] ?? ($field['uiType'] ?? ''))) {
                return true;
            }
        }
        return false;
    }

    function view_ui_should_skip_bytewise_parent(array $field, array $parentIdsWithBitwiseUi, $hasBitwiseUi)
    {
        if (view_ui_field_level($field) === 'bitwise') {
            return false;
        }
        $fieldId = (int) ($field['id'] ?? ($field['field_id'] ?? ($field['fieldId'] ?? 0)));
        if ($fieldId > 0 && isset($parentIdsWithBitwiseUi[$fieldId])) {
            return true;
        }
        $mode = strtolower(trim((string) ($field['bitwise_mode'] ?? ($field['bitwiseMode'] ?? ''))));
        return $mode === 'bitwise' && $hasBitwiseUi;
    }

    function view_ui_build_frame_component(array $field, $index, $source, array $apiMeta)
    {
        $uiType = trim((string) ($field['ui_type'] ?? ($field['uiType'] ?? '')));
        if (!view_ui_api_ui_type_is_usable($uiType)) {
            return null;
        }
        $displayValue = !empty($field['display_value']) && is_array($field['display_value']) ? $field['display_value'] : [];
        $fieldDescription = trim((string) ($field['Field_description'] ?? ($field['field_description'] ?? ($field['default_name'] ?? ''))));
        $level = view_ui_field_level($field);
        if ($fieldDescription === '' && $level === 'bitwise') {
            $startBit = trim((string) ($field['start_bit'] ?? ($field['startBit'] ?? '')));
            $fieldDescription = $startBit !== '' ? ('Bit ' . $startBit) : 'Bitwise field';
        }
        return array_merge($apiMeta, [
            'ui_type' => $uiType,
            'ui_type_source' => $source,
            'field_index' => $index,
            'field_description' => $fieldDescription !== '' ? $fieldDescription : ($field['Field_description'] ?? ($field['field_description'] ?? ($field['default_name'] ?? null))),
            'default' => $field['value'] ?? ($field['asperui_value'] ?? ($apiMeta['default'] ?? null)),
            'items' => !empty($field['asperui']) && is_array($field['asperui']) ? $field['asperui'] : ($apiMeta['items'] ?? []),
            'item_values' => !empty($field['asperui_values']) && is_array($field['asperui_values']) ? $field['asperui_values'] : ($apiMeta['item_values'] ?? []),
            'sno_asperui' => !empty($field['sno_asperui']) && is_array($field['sno_asperui']) ? $field['sno_asperui'] : ($apiMeta['sno_asperui'] ?? []),
            'minimum' => $displayValue['min'] ?? ($apiMeta['minimum'] ?? null),
            'maximum' => $displayValue['max'] ?? ($apiMeta['maximum'] ?? null),
            'step' => $field['slider_step_value'] ?? ($apiMeta['step'] ?? null),
            'access' => $field['ui_description'] ?? ($apiMeta['access'] ?? null),
            'field_level' => $level,
            'parent_field_id' => (int) ($field['parent_field_id'] ?? ($field['parentFieldId'] ?? 0)),
            'start_bit' => $field['start_bit'] ?? ($field['startBit'] ?? null),
            'end_bit' => $field['end_bit'] ?? ($field['endBit'] ?? null),
        ]);
    }

    function view_ui_extract_selected_frame_component(array $fields, $source, array $apiMeta)
    {
        $selectedIndex = null;
        foreach ($fields as $index => $field) {
            if (!is_array($field)) {
                continue;
            }
            $description = strtolower(trim((string) ($field['Field_description'] ?? $field['field_description'] ?? $field['default_name'] ?? '')));
            $uiType = trim((string) ($field['ui_type'] ?? ($field['uiType'] ?? '')));
            if (in_array($description, ['data', 'trigger'], true) && view_ui_api_ui_type_is_usable($uiType)) {
                $selectedIndex = $index;
                break;
            }
        }
        if ($selectedIndex === null) {
            foreach ($fields as $index => $field) {
                if (!is_array($field)) {
                    continue;
                }
                $uiType = trim((string) ($field['ui_type'] ?? ($field['uiType'] ?? '')));
                if (view_ui_api_ui_type_is_usable($uiType)) {
                    $selectedIndex = $index;
                    break;
                }
            }
        }
        if ($selectedIndex === null || empty($fields[$selectedIndex]) || !is_array($fields[$selectedIndex])) {
            return null;
        }

        return view_ui_build_frame_component($fields[$selectedIndex], $selectedIndex, $source, $apiMeta);
    }

    function view_ui_extract_all_ui_components(array $apiMeta)
    {
        if (!empty($apiMeta['ui_components']) && is_array($apiMeta['ui_components'])) {
            $components = [];
            foreach ($apiMeta['ui_components'] as $component) {
                if (!is_array($component) || !view_ui_api_ui_type_is_usable($component['ui_type'] ?? '')) {
                    continue;
                }
                $component['frame'] = !empty($apiMeta['frame']) && is_array($apiMeta['frame']) ? $apiMeta['frame'] : ($component['frame'] ?? null);
                $component['command_id'] = $apiMeta['command_id'] ?? ($component['command_id'] ?? null);
                $component['function_code'] = $apiMeta['function_code'] ?? ($component['function_code'] ?? null);
                $component['action_id'] = $apiMeta['action_id'] ?? ($component['action_id'] ?? null);
                $components[] = $component;
            }
            if (!empty($components)) {
                return $components;
            }
        }

        $frame = !empty($apiMeta['frame']) && is_array($apiMeta['frame']) ? $apiMeta['frame'] : [];
        $components = [];
        foreach (['command' => 'commands', 'response' => 'response', 'error' => 'error'] as $source => $frameKey) {
            $fields = !empty($frame[$frameKey]) && is_array($frame[$frameKey]) ? $frame[$frameKey] : [];
            $hasBitwiseUi = view_ui_source_has_bitwise_ui($fields);
            if (view_ui_source_has_multiple_ui($apiMeta, $source) || $hasBitwiseUi) {
                $parentIdsWithBitwiseUi = [];
                foreach ($fields as $field) {
                    if (!is_array($field) || view_ui_field_level($field) !== 'bitwise') {
                        continue;
                    }
                    if (!view_ui_api_ui_type_is_usable($field['ui_type'] ?? ($field['uiType'] ?? ''))) {
                        continue;
                    }
                    $parentId = (int) ($field['parent_field_id'] ?? ($field['parentFieldId'] ?? 0));
                    if ($parentId > 0) {
                        $parentIdsWithBitwiseUi[$parentId] = true;
                    }
                }
                foreach ($fields as $index => $field) {
                    if (!is_array($field) || view_ui_should_skip_bytewise_parent($field, $parentIdsWithBitwiseUi, $hasBitwiseUi)) {
                        continue;
                    }
                    $component = view_ui_build_frame_component($field, $index, $source, $apiMeta);
                    if ($component !== null) {
                        $components[] = $component;
                    }
                }
                continue;
            }
            $component = view_ui_extract_selected_frame_component($fields, $source, $apiMeta);
            if ($component !== null) {
                $components[] = $component;
            }
        }

        return !empty($components) ? $components : [$apiMeta];
    }
}
if (!function_exists('view_ui_api_access_is_writable')) {
    /**
     * A field is editable only when the linked API row says so. An empty or unknown
     * access column is treated as read-only so the UI never offers an edit the
     * device cannot accept.
     */
    function view_ui_api_access_is_writable(array $apiMeta, $source = '')
    {
        $source = strtolower(trim((string) ($source !== '' ? $source : ($apiMeta['ui_type_source'] ?? ''))));
        if (in_array($source, ['response', 'error'], true)) {
            return false;
        }

        $access = strtolower(trim((string) ($apiMeta['access'] ?? '')));
        if ($access === '') {
            return false;
        }

        return strpos($access, 'write') !== false || $access === 'w' || $access === 'rw';
    }
}

if (!function_exists('view_ui_resolve_component_value')) {
    /**
     * Value shown on the card in place of the old UI-type caption. Only values that
     * exist in the linked API row are used; nothing is synthesised.
     */
    function view_ui_resolve_component_value(array $apiMeta, $componentType = '', $fallback = '')
    {
        $value = $apiMeta['default'] ?? null;
        if (is_array($value)) {
            $value = reset($value);
        }
        $value = trim((string) $value);

        if ($value === '' && !empty($apiMeta['items']) && is_array($apiMeta['items'])) {
            foreach ($apiMeta['items'] as $item) {
                $item = trim((string) $item);
                if ($item !== '') {
                    $value = $item;
                    break;
                }
            }
        }

        if ($value === '' && is_numeric($apiMeta['minimum'] ?? null)) {
            $value = (string) (0 + $apiMeta['minimum']);
        }

        if ($value === '') {
            return $fallback;
        }

        $unit = trim((string) ($apiMeta['unit'] ?? ($apiMeta['units'] ?? '')));

        return $unit !== '' ? $value . ' ' . $unit : $value;
    }
}

