      overflow: hidden;
      text-overflow: ellipsis;
    }

    #studio-theme-section .studio-color-grid,
    #studio-params-section .studio-color-grid,
    #studio-general-section .studio-color-grid {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 8px;
    }

    #studio-theme-section .studio-color-row,
    #studio-params-section .studio-color-row,
    #studio-general-section .studio-color-row {
      display: flex;
      flex-direction: column;
