    <?php if (empty($pages)): ?>
      <div class="empty-ui">No UI parameters selected yet.</div>
    <?php else: ?>
      <section class="slider-shell" aria-label="Linked page slider">
        <div class="slide-window">
          <div class="slide-track" id="slide-track">
            <?php foreach ($pages as $index => $page): ?>
              <article class="page-slide" data-page-title="<?= esc($page['page_name']) ?>" data-page-no="<?= esc($page['page_no']) ?>">
                <div class="param-list">
                  <?php foreach ($page['params'] as $paramIndex => $param): ?>
                    <?php
                    $paramName = trim((string) ($param['parameter'] ?? ''));
                    $paramLower = strtolower($paramName);
                    $isGetStatusParam = strpos(str_replace(['_', '-'], ' ', $paramLower), 'get status') !== false;
                    $apiMeta = !empty($param['api']) && is_array($param['api']) ? $param['api'] : [];
                    $apiComponents = view_ui_extract_all_ui_components($apiMeta);
                    if (view_ui_api_has_auto_trigger_component($apiMeta, $apiComponents)) {
                        continue;
                    }
                    $hasRelatedApiComponents = !empty($apiMeta) && is_array($apiMeta) && view_ui_api_ui_type_is_usable($apiMeta['ui_type'] ?? ($apiComponents[0]['ui_type'] ?? ''));
                    $hasMultipleApiComponents = count($apiComponents) > 1;
                    if ($hasRelatedApiComponents):
                    ?>
                    <div class="param-group-card<?= $isGetStatusParam ? ' is-get-status-group' : '' ?>" data-get-status="<?= $isGetStatusParam ? '1' : '0' ?>" data-param-key="<?= esc($page['page_no'] . ':' . ($paramName ?: 'Parameter')) ?>" data-param-name="<?= esc($paramName ?: 'Parameter') ?>" data-sequence="<?= esc($param['sequence']) ?>">
                      <div class="param-group-header">
                        <span class="field-label"><?= esc($paramName ?: 'Parameter') ?></span>
                        <span class="param-group-count"><?= esc((string) count($apiComponents)) ?> UI</span>
                      </div>
                      <div class="param-component-stack">
                    <?php endif;
                    foreach ($apiComponents as $apiComponentIndex => $apiComponentMeta):
                    $apiMeta = is_array($apiComponentMeta) ? $apiComponentMeta : $apiMeta;
                    $apiSource = trim((string) ($apiMeta['ui_type_source'] ?? ''));
                    $apiFieldIndex = isset($apiMeta['field_index']) ? (string) $apiMeta['field_index'] : (string) $apiComponentIndex;
                    $apiComponentKey = trim((string) preg_replace('/[^a-z0-9]+/', '-', strtolower($apiSource . '-' . $apiFieldIndex . '-' . (string) ($apiMeta['ui_type'] ?? ''))), '-');
                    if ($apiComponentKey === '') {
                        $apiComponentKey = 'api-' . ($apiComponentIndex + 1);
                    }
                    $componentType = view_ui_detect_component_type($paramName, $apiMeta);
                    // Grouped singles keep the parameter name on the group header.
                    // Multiple UI must label each inner card with its field name.
                    $displayParamName = $paramName;
                    if ($hasMultipleApiComponents) {
                        $uiTypeName = trim((string) ($apiMeta['ui_type'] ?? ''));
                        if ($uiTypeName !== '' && $uiTypeName === strtolower($uiTypeName)) {
                            $uiTypeName = ucwords($uiTypeName);
                        } elseif ($uiTypeName !== '' && $uiTypeName === strtoupper($uiTypeName)) {
                            $uiTypeName = ucwords(strtolower($uiTypeName));
                        }
                        $fieldName = trim((string) ($apiMeta['field_description'] ?? ''));
                        $genericField = in_array(strtolower($fieldName), ['data', 'trigger', 'command', 'response', 'error', 'none', ''], true);
                        $displayParamName = $uiTypeName !== ''
                            ? $uiTypeName
                            : ((!$genericField && strcasecmp($fieldName, $paramName) !== 0)
                                ? $fieldName
                                : ($apiSource !== '' ? ucfirst($apiSource) : ('UI ' . ($apiComponentIndex + 1))));
                    } elseif ($hasRelatedApiComponents) {
                        $displayParamName = $apiSource !== '' ? ucfirst($apiSource) : ('API ' . ($apiComponentIndex + 1));
                    }
                    $displayParamValue = view_ui_resolve_component_value($apiMeta, $componentType, '');
                    if ($componentType === 'segmented' && view_ui_is_direction_parameter($paramName)) {
                        $directionOptions = view_ui_direction_options(is_array($apiMeta) ? $apiMeta : []);
                        if ($displayParamValue === '' || strcasecmp($displayParamValue, (string) $paramName) === 0) {
                            $displayParamValue = (string) ($directionOptions[0]['value'] ?? '0');
                        }
                    }
                    $isPower = in_array($componentType, ['toggleSwitch', 'switch'], true) || strpos($paramLower, 'power') !== false;
                    $stackedComponentTypes = ['slider', 'brightnessSlider', 'airflowSlider', 'cctSlider', 'saturationSlider', 'hueSlider', 'hueSliderCustom', 'autoTriggerTimer', 'hueCircle', 'powerGauge', 'needleGauge', 'segmented', 'linearGauge'];
                    $isTimer = in_array($componentType, $stackedComponentTypes, true);
                    $isTrigger = in_array($componentType, ['button', 'pushButton'], true);
                    $isDropdown = in_array($componentType, ['dropdown', 'notification'], true);
                    $isTextInput = in_array($componentType, ['enterText', 'textField', 'cmd'], true);
                    $apiAccess = strtolower(trim((string) ($apiMeta['access'] ?? '')));
                    $fieldSource = strtolower(trim((string) ($apiMeta['ui_type_source'] ?? $apiSource)));
                    // Editable only when the linked API row grants write access.
                    // cmd is device output, so it is never editable.
                    $isReadOnlyProtocol = $componentType === 'cmd'
                        || !view_ui_api_access_is_writable($apiMeta, $fieldSource);
                    $isRangeLike = in_array($componentType, ['slider', 'brightnessSlider', 'airflowSlider', 'cctSlider', 'saturationSlider', 'hueSlider', 'hueSliderCustom', 'autoTriggerTimer'], true);
                    $rangeMin = is_numeric($apiMeta['minimum'] ?? null) ? (float) $apiMeta['minimum'] : 0;
                    $rangeMax = is_numeric($apiMeta['maximum'] ?? null) ? (float) $apiMeta['maximum'] : 100;
                    if ($rangeMax <= $rangeMin) {
                        $rangeMax = $rangeMin + 100;
                    }
                    $paramKey = $page['page_no'] . ':' . $paramName . ($hasRelatedApiComponents ? ':' . $apiComponentKey : '');
                    $parameterIcons = $active_ui_theme['parameterIcons'] ?? [];
                    if (is_object($parameterIcons)) {
                        $parameterIcons = (array) $parameterIcons;
                    }
                    if (!is_array($parameterIcons)) {
                        $parameterIcons = [];
                    }
                    $paramIcon = !empty($parameterIcons[$paramKey]) ? $parameterIcons[$paramKey] : $active_ui_theme['parameterIcon'];
                    $apiSourceLower = strtolower($apiSource);
                    $isGetStatusResponse = $isGetStatusParam && $apiSourceLower === 'response';
                    $isGetStatusCommand = $isGetStatusParam && $apiSourceLower === 'command';
                    $openResponsePanel = false;
                    $closeResponsePanel = false;
                    if ($isGetStatusResponse) {
                        $prevSource = $apiComponentIndex > 0
                            ? strtolower(trim((string) ($apiComponents[$apiComponentIndex - 1]['ui_type_source'] ?? '')))
                            : '';
                        $nextSource = isset($apiComponents[$apiComponentIndex + 1])
                            ? strtolower(trim((string) ($apiComponents[$apiComponentIndex + 1]['ui_type_source'] ?? '')))
                            : '';
                        $openResponsePanel = $prevSource !== 'response';
                        $closeResponsePanel = $nextSource !== 'response';
                    }
                    $getStatusCardClass = $isGetStatusResponse ? ' is-get-status-response' : ($isGetStatusCommand ? ' is-get-status-command' : '');
                    ?>
                    <?php if ($openResponsePanel): ?>
                    <div class="get-status-response-panel" data-expanded="0">
                      <div class="get-status-response-inner">
                    <?php endif; ?>
                    <div class="param-card<?= ($hasRelatedApiComponents ? ' is-grouped-component' : '') . ($isTimer ? ' layout-stacked' : '') . $getStatusCardClass ?>" data-get-status-command="<?= $isGetStatusCommand ? '1' : '0' ?>" data-param-key="<?= esc($paramKey) ?>" data-param-name="<?= esc($paramName ?: 'Parameter') ?>" data-api-ui-source="<?= esc($apiSource) ?>" data-api-field-index="<?= esc($apiFieldIndex) ?>" data-component-label="<?= esc($displayParamName ?: 'Component') ?>" data-component-value="<?= esc($displayParamValue ?: '') ?>" data-sequence="<?= esc($param['sequence']) ?>" data-component-type="<?= esc($componentType) ?>" data-api-meta="<?= esc(json_encode($apiMeta, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE)) ?>">
                      <div class="param-main-row">
                        <button type="button" class="param-icon" data-icon-picker-trigger="1" data-icon="<?= esc($paramIcon) ?>" aria-label="Change <?= esc($paramName ?: 'parameter') ?> icon"><?= view_ui_icon($paramIcon) ?></button>
                        <div>
                          <?php if (!$hasRelatedApiComponents || $hasMultipleApiComponents): ?><span class="field-label"><?= esc($displayParamName ?: 'Parameter') ?></span><?php endif; ?>
                          <span class="field-value"><?php if ($componentType === 'cmd'): ?><span class="param-cmd-console param-component"><span class="param-cmd-prompt" aria-hidden="true">&gt;</span><textarea class="param-text-input param-cmd-input" readonly rows="1" aria-label="<?= esc($paramName ?: 'cmd') ?>"><?= esc($displayParamValue) ?></textarea></span><?php elseif ($isTextInput): ?><span class="param-text-input-wrap param-component"><input type="text" class="param-text-input" value="<?= esc($displayParamValue) ?>" <?= $isReadOnlyProtocol ? 'readonly' : '' ?> aria-label="<?= esc($paramName ?: 'parameter') ?>"><?php if (!$isReadOnlyProtocol): ?><button type="button" class="param-send-btn" aria-label="Send <?= esc($paramName ?: 'parameter') ?>"><?= view_ui_icon('send') ?></button><?php endif; ?></span><?php else: ?><?= $isPower && $displayParamValue === '' ? 'ON' : esc($displayParamValue !== '' ? $displayParamValue : '--') ?><?php endif; ?></span>
                        </div>

                        <?php if ($isPower): ?>
                          <span class="toggle-visual" aria-hidden="true"></span>
                        <?php elseif ($isTrigger): ?>
                          <span class="action-dot" aria-hidden="true"></span>
                        <?php elseif ($isDropdown): ?>
                          <select class="param-dropdown param-component is-placeholder" required aria-label="<?= esc($displayParamName ?: ($paramName ?: 'parameter')) ?>">
                            <option value="" selected disabled>Choose</option>
                            <?php
                            $dropdownItems = !empty($apiMeta['items']) && is_array($apiMeta['items']) ? array_values($apiMeta['items']) : [];
                            $dropdownValues = !empty($apiMeta['item_values']) && is_array($apiMeta['item_values']) ? array_values($apiMeta['item_values']) : [];
                            if (count($dropdownValues) > 1 && count($dropdownItems) === 1 && preg_match('/^\d+$/', trim((string) $dropdownItems[0])) && (int) $dropdownItems[0] === count($dropdownValues)) {
                                $dropdownItems = $dropdownValues;
                            }
                            $dropdownCount = max(count($dropdownItems), count($dropdownValues));
                            for ($dropdownIndex = 0; $dropdownIndex < $dropdownCount; $dropdownIndex++):
                                $dropdownLabel = trim((string) ($dropdownItems[$dropdownIndex] ?? ($dropdownValues[$dropdownIndex] ?? '')));
                                $dropdownValue = trim((string) ($dropdownValues[$dropdownIndex] ?? $dropdownLabel));
                                if ($dropdownLabel === '' && $dropdownValue === '') {
                                    continue;
                                }
                                if ($dropdownLabel === '') {
                                    $dropdownLabel = $dropdownValue;
                                }
                            ?>
                              <option value="<?= esc($dropdownValue) ?>"><?= esc($dropdownLabel) ?></option>
                            <?php endfor; ?>
                          </select>
                        <?php endif; ?>
                      </div>
                      <?php if ($isRangeLike): ?>
                        <div class="range-visual param-component" aria-hidden="true">
                          <div class="range-values">
                            <span><?= esc((string) $rangeMin) ?></span>
                            <strong><?= esc((string) ($apiMeta['default'] ?? $rangeMin)) ?></strong>
                            <span><?= esc((string) $rangeMax) ?></span>
                          </div>
                          <div class="range-line"></div>
                        </div>
                      <?php endif; ?>
                    </div>
                    <?php if ($closeResponsePanel): ?>
                      </div>
                    </div>
                    <?php endif; ?>
                    <?php endforeach; ?>
                    <?php if ($hasRelatedApiComponents): ?>
                      </div>
                    </div>
                    <?php endif; ?>
                  <?php endforeach; ?>
                </div>
              </article>
            <?php endforeach; ?>
          </div>
        </div>

        <div class="progress-shell" aria-hidden="true">
          <div class="progress-bar" id="slide-progress"></div>
        </div>

        <div class="slider-controls">
          <button type="button" class="slide-arrow" id="prev-slide" aria-label="Previous page">
            <?= view_ui_icon('arrow-left') ?>
          </button>

          <div class="page-buttons" aria-label="Page buttons">
            <?php foreach ($pages as $index => $page): ?>
              <button type="button" class="page-button<?= $index === 0 ? ' is-active' : '' ?>" data-slide-index="<?= esc($index) ?>">
                <?= esc($index + 1) ?>
              </button>
            <?php endforeach; ?>
          </div>

          <button type="button" class="slide-arrow" id="next-slide" aria-label="Next page">
            <?= view_ui_icon('arrow-right') ?>
          </button>
        </div>
      </section>
    <?php endif; ?>

    <section class="device-details-view" id="device-info-modal" aria-hidden="true" aria-labelledby="device-info-title">
      <header class="device-details-head">
        <button type="button" class="device-details-back" id="device-info-close-btn" aria-label="Back to controls">
