      return value;
    }

    function resolveSliderHueAngle(value, min, max, config) {
      const safeMin = Number.isFinite(min) ? min : 0;
      let safeMax = Number.isFinite(max) ? max : (config && config.defaultHueMax ? config.defaultHueMax : 360);
      if (safeMax <= safeMin) safeMax = safeMin + 360;
      const numeric = parseFloat(value);
      const clamped = Number.isFinite(numeric) ? Math.max(safeMin, Math.min(safeMax, numeric)) : safeMin;
      const ratio = safeMax === safeMin ? 0 : (clamped - safeMin) / (safeMax - safeMin);
      return Math.round(ratio * 360);
    }

    function formatSliderDisplayValue(value, min, max, config) {
      config = config || SLIDER_VARIANT_CONFIG.slider;
      const numeric = parseFloat(value);
      const clamped = Number.isFinite(numeric) ? numeric : (Number.isFinite(min) ? min : 0);
      const safeMin = Number.isFinite(min) ? min : 0;
      let safeMax = Number.isFinite(max) ? max : 255;
      if (safeMax <= safeMin) safeMax = safeMin + 255;

      if (config.mapKelvin) {
        if (safeMax > 1000) {
          return String(Math.round(clamped)) + (config.valueSuffix || 'K');
        }
        const kelvin = Math.round(2700 + ((clamped - safeMin) / (safeMax - safeMin)) * 3800);
        return String(kelvin) + (config.valueSuffix || 'K');
      }

      if (config.valueAsPercent) {
        const percent = safeMax === safeMin ? 0 : Math.round(((clamped - safeMin) / (safeMax - safeMin)) * 100);
        return String(percent) + (config.valueSuffix || '%');
      }

      if (config.valueSuffix === '°') {
        return String(Math.round(clamped)) + '°';
      }

      if (config.valueSuffix) {
        return String(Math.round(clamped)) + config.valueSuffix;
      }

      return String(Math.round(clamped * 100) / 100);
    }

    function buildSliderRangeLabels(min, max, config) {
      config = config || SLIDER_VARIANT_CONFIG.slider;
      const minText = config.minLabel != null ? config.minLabel : ('Min ' + min);
      let maxText = config.maxLabel != null ? config.maxLabel : ('Max ' + max);
      if (config.variant === 'timer' && config.maxLabel == null) {
        maxText = String(max) + (config.valueSuffix || 's');
      }
      return { minText: minText, maxText: maxText };
    }
    function buildSliderVisualSpec(componentType, override, meta, min, max, currentValue) {
      const config = getSliderVariantConfig(componentType || 'slider');
      const colors = getEffectiveComponentColors(override || {});
      const safeMin = Number.isFinite(min) ? min : 0;
      const safeMax = Number.isFinite(max) && max > safeMin ? max : (safeMin + (config.defaultHueMax || 255));
      const numericValue = parseFloat(currentValue);
      const clampedValue = Number.isFinite(numericValue) ? Math.max(safeMin, Math.min(safeMax, numericValue)) : safeMin;
      const labels = buildSliderRangeLabels(safeMin, safeMax, config);
      const isDark = String(currentTheme.themeMode || '').toLowerCase() === 'dark';
      const cardBg = colors.cardColor || currentTheme.cardColor;
      const shellBg = currentTheme.shellColor || currentTheme.backgroundColor;
      const defaultBg = isDark
        ? 'linear-gradient(180deg,' + cardBg + ' 0%,' + shellBg + ' 100%)'
