          thumbColor: config.thumbFromHue ? 'hsl(' + resolveSliderHueAngle(clampedValue, safeMin, safeMax, config) + ',78%,52%)' : '#22C55E'
        },
        'hue-custom': {
          background: isDark ? 'linear-gradient(180deg,#111827 0%,#1F2937 100%)' : 'linear-gradient(180deg,#F8FAFC 0%,#F1F5F9 100%)',
          trackGradient: 'linear-gradient(90deg,#EF4444 0%,#F97316 14%,#EAB308 28%,#22C55E 42%,#06B6D4 57%,#3B82F6 71%,#A855F7 85%,#EF4444 100%)',
          activeTrackColor: '#22C55E',
          inactiveTrackColor: '#94A3B8',
          thumbColor: config.thumbFromHue ? 'hsl(' + resolveSliderHueAngle(clampedValue, safeMin, safeMax, config) + ',78%,52%)' : '#22C55E',
          tickMarks: true,
