        }
      };
      const visual = specs[config.variant] || specs.default;
      return Object.assign({
        variant: config.variant,
        componentType: componentType || 'slider',
        label: (getParameterCatalogEntry(componentType || '') && getParameterCatalogEntry(componentType || '').sliderLabel) || null,
        icon: config.icon || 'gauge',
