    function buildGaugeGeometryProps(bounds, type) {
      const cx = NEEDLE_GAUGE_VIEW_WIDTH / 2;
      const cy = NEEDLE_GAUGE_PIVOT_Y;
      const radius = NEEDLE_GAUGE_RADIUS;
      const strokeWidth = 14;
      const viewBox = computeGaugeViewBox(cx, cy, radius, strokeWidth);
      const angle = gaugeValueToAngle(bounds.value, bounds.min, bounds.max);
      return {
        type: type || 'needleGauge',
        alignment: 'center',
        horizontalAlignment: 'center',
        verticalAlignment: 'center',
        opening: { startAngle: POWER_GAUGE_ARC_START, sweepAngle: POWER_GAUGE_ARC_SWEEP, endAngle: POWER_GAUGE_ARC_START + POWER_GAUGE_ARC_SWEEP },
        viewBox: { minX: viewBox.minX, minY: viewBox.minY, width: viewBox.width, height: viewBox.height, attr: viewBox.attr },
        viewport: { width: NEEDLE_GAUGE_VIEW_WIDTH, height: NEEDLE_GAUGE_VIEW_HEIGHT },
        center: { x: cx, y: cy },
        radius: radius,
        strokeWidth: strokeWidth,
        needle: {
          structure: type === 'powerGauge' ? 'triangle-pointer' : 'line-needle-with-tip-dot',
          pivot: { x: cx, y: cy, radius: type === 'powerGauge' ? 11 : 10 },
          angle: angle,
          length: type === 'powerGauge' ? radius - 18 : radius - 12,
          width: type === 'powerGauge' ? 16 : 3.5,
          tipRadius: type === 'powerGauge' ? 0 : 4,
          cap: 'round',
          borderColor: '#FFFFFF',
          borderWidth: type === 'powerGauge' ? 2 : 1.5
        }
      };
    }

