    function buildValidationRulesFromControls(controls) {
      const rules = {};
      (controls || []).forEach(function(control) {
        const key = control.parameterKey || control.id;
        if (!key) return;
        const constraints = control.constraints || {};
        const rule = {
          required: control.visible !== false,
          valueType: control.valueType || 'string'
        };
        if (constraints.minimum != null) rule.min = constraints.minimum;
        if (constraints.maximum != null) rule.max = constraints.maximum;
        if (constraints.step != null) rule.step = constraints.step;
        if (control.valueType === 'string') rule.maxLength = 512;
        if (control.valueType === 'enum' && Array.isArray(control.options) && control.options.length) {
          rule.enum = control.options.map(function(option) {
            return option.value != null ? option.value : option.label;
          });
        }
        if (control.protocolMeta && control.protocolMeta.access) {
          rule.access = control.protocolMeta.access;
        }
        rules[key] = rule;
      });
      return rules;
    }

    function buildPermissionsSchema(controls) {
      const controlRules = {};
      (controls || []).forEach(function(control) {
        const key = control.parameterKey || control.id;
        if (!key) return;
        const access = control.protocolMeta && control.protocolMeta.access
          ? String(control.protocolMeta.access).toLowerCase()
          : 'read-write';
        controlRules[key] = {
          read: access !== 'write-only' && access !== 'write',
          write: access !== 'read-only' && access !== 'read',
          roles: ['viewer', 'operator', 'admin']
        };
      });
      return {
        model: 'role-based',
        defaultRole: 'operator',
        roles: {
          viewer: { canView: true, canControl: false, canConfigure: false },
          operator: { canView: true, canControl: true, canConfigure: false },
          admin: { canView: true, canControl: true, canConfigure: true }
        },
        controls: controlRules
      };
    }

