    function formatIndianDateTime(value) {
      const source = value instanceof Date ? value : new Date();
      const parts = new Intl.DateTimeFormat('en-GB', {
        timeZone: 'Asia/Kolkata',
        year: 'numeric',
        month: '2-digit',
        day: '2-digit',
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit',
        hour12: false
      }).formatToParts(source);
      const get = function(type) {
        const part = parts.find(function(item) { return item.type === type; });
        return part ? part.value : '00';
      };
      let hour = get('hour');
      if (hour === '24') hour = '00';
      const date = get('year') + '-' + get('month') + '-' + get('day');
      const time = hour + ':' + get('minute') + ':' + get('second');
      return {
        ist: date + ' ' + time + ' IST',
        iso: date + 'T' + time + '+05:30',
        timezone: 'Asia/Kolkata'
      };
    }

    function formatIndianIsoDate(value) {
      return formatIndianDateTime(value).ist;
    }

