            background: colors.accentSoft,
            icon: 'scan',
            iconSize: 18,
            iconColor: colors.accent,
            action: 'openScanner',
            plugin: 'qrBarcodeScan',
            screen: 'qrScanner',
            accessibilityLabel: 'Scan QR code'
          },
          back: {
            width: 36,
            height: 36,
            radius: 999,
            background: colors.accentSoft,
            icon: 'chevron-left',
            iconColor: colors.accent
          }
        }
      };
    }

    function buildOpenScannerSchemaAction(overrides) {
      const extra = overrides && typeof overrides === 'object' ? overrides : {};
      return {
        type: 'native',
        value: 'openScanner',
        plugin: 'qrBarcodeScan',
        screen: extra.screen || 'qrScanner',
        schemaPath: extra.schemaPath || 'wifiProvisioning.screens.qrScanner',
        payload: {
          feature: 'qrBarcodeScan',
          formats: extra.formats || ['qr'],
          camera: extra.camera || 'back',
          facing: extra.facing || 'environment',
          resultBinding: extra.resultBinding || 'state.scanResult.value',
          onSuccessAction: extra.onSuccessAction || 'onScanSuccess',
          onCancelAction: extra.onCancelAction || 'onScanCancel',
          onErrorAction: extra.onErrorAction || 'onScanError',
          platforms: {
            app: {
              behavior: 'openCameraScanner',
              screen: extra.screen || 'qrScanner',
              cameraPage: true
            },
            web: {
              behavior: extra.webBehavior || 'showCameraScannerPage',
              screen: extra.screen || 'qrScanner'
            }
          }
        }
      };
    }

    function buildWifiProvisioningSchema(resolvedNodeId) {
      const visual = buildWifiProvisioningVisualContract();
      const colors = visual.colors;
      const screenStyle = {
        backgroundColor: colors.background,
        surfaceColor: colors.surface,
        textColor: colors.text,
        mutedTextColor: colors.mutedText,
        accentColor: colors.accent,
        borderColor: colors.border,
        gradient: visual.gradient.screen
      };
      const tracker = {
        id: 'wifiFlowTracker',
        type: 'stepTracker',
        labels: ['Network', 'Password', 'Setup', 'Done'],
        labelKeys: ['wifi.tracker.network', 'wifi.tracker.password', 'wifi.tracker.setup', 'wifi.tracker.done'],
        geometry: {
          layout: 'horizontal',
          columns: 'auto 1fr auto 1fr auto 1fr auto',
          gap: 6,
          padding: [2, 2, 4, 2],
          circleSize: 22,
          lineHeight: 2,
          lineRadius: 999,
          labelGap: 4,
          labelMinWidth: 42
        },
        states: {
          pending: {
            circleFill: colors.trackerPendingFill,
            circleText: colors.trackerPendingText,
            labelColor: colors.trackerPendingText,
            lineColor: colors.trackerLinePending
          },
          active: {
            circleFill: colors.accent,
            circleText: colors.onAccent,
            labelColor: colors.accent,
            lineColor: colors.accent,
            fontWeight: 800
          },
          completed: {
            circleFill: colors.success,
            circleText: colors.onAccent,
            labelColor: colors.text,
            lineColor: colors.success,
            icon: 'check'
          }
        },
        activeStepByScreen: {
          wifiNetworkPicker: 0,
          wifiPassword: 1,
          deviceDiscovery: 2,
          provisioning: 2,
          cloudConfirmation: 2,
          wifiSuccess: 3,
          wifiError: 2
        }
      };
      const signalQuality = {
        binding: 'item.rssi',
        thresholds: [
          { minRssi: -50, label: 'Excellent', token: 'excellent', color: colors.success, background: colors.successSoft },
          { minRssi: -60, label: 'Good', token: 'good', color: colors.success, background: colors.successSoft },
          { minRssi: -70, label: 'Fair', token: 'fair', color: colors.warning, background: colors.warningSoft },
          { minRssi: null, label: 'Weak', token: 'weak', color: colors.error, background: colors.errorSoft }
        ],
        recommendedChip: { label: 'Best', token: 'best', color: colors.accent, background: colors.accentSoft }
      };
      const networkRowPresentation = {
        layout: 'grid',
        columns: '44px 1fr auto',
        gap: 12,
        minHeight: 74,
        padding: [12, 14, 12, 14],
        dividerColor: colors.border,
        leadingIcon: {
          icon: 'wifi',
          size: 20,
          box: 44,
          radius: 16,
          background: colors.accentSoft,
          color: colors.accent
        },
        titleBinding: 'item.ssid',
        chips: [
          { id: 'frequency', text: '2.4 GHz', source: 'static' },
          { id: 'security', textBinding: 'item.securityLabel', fallbackBinding: 'item.security' },
          { id: 'quality', from: 'signalQuality' },
          { id: 'recommended', text: 'Best', showWhen: 'item.recommended == true', token: 'best' }
        ],
        trailing: {
          signalBars: { binding: 'item.rssi', barCount: 4, onColor: colors.accent, offColor: colors.trackerPendingFill },
          lockIcon: { icon: 'lock', size: 16, color: colors.mutedText, hideWhen: 'item.open == true || item.security == "Open"' },
          chevron: { icon: 'chevron-right', size: 16, color: colors.mutedText }
        }
      };
      const componentStyles = {
        stepTracker: tracker,
        heroCard: {
          radius: visual.radius.hero,
          padding: visual.spacing.heroPadding,
          minHeight: 96,
          gap: 14,
          layout: 'iconLeft',
          iconBox: { size: 56, radius: 999, background: 'rgba(255,255,255,0.14)', iconSize: 22, iconColor: colors.onHero },
          gradient: visual.gradient.hero,
          shadow: visual.shadows.hero,
          border: { size: 1, color: 'rgba(255,255,255,0.28)' }
        },
        sectionHeader: {
          layout: 'spaceBetween',
          padding: [2, 4, 2, 4],
          titleStyle: visual.typography.sectionTitle
        },
        wifiNetworkList: {
          radius: visual.radius.card,
          background: colors.surface,
          border: { size: 1, color: colors.border },
          shadow: visual.shadows.card,
          overflow: 'hidden'
        },
        wifiNetworkRow: networkRowPresentation,
        chip: {
          minHeight: 20,
          paddingH: 8,
          radius: 999,
          font: visual.typography.chip,
          default: { background: '#F1F4F8', color: colors.mutedText }
        },
        passwordField: {
          label: 'Password',
          obscureText: true,
          persist: false,
          height: 52,
          radius: 16,
          borderSize: 1.5,
          borderColor: colors.border,
          focusBorderColor: colors.accent,
          leadingIcon: { icon: 'key', size: 18, color: colors.accent },
          visibilityToggle: { showIcon: 'eye', hideIcon: 'eye-off', size: 18, color: colors.mutedText }
        },
        helperNote: {
          font: visual.typography.helper,
          icon: 'lock',
          iconSize: 14,
          iconColor: colors.accent
        },
        primaryButton: visual.buttons.primary,
        circularGauge: {
          size: 148,
          strokeWidth: 8,
          trackColor: colors.trackerPendingFill,
          progressColor: colors.accent,
          cap: 'round',
          valueSuffix: '%',
          label: 'Status',
          valueTypography: visual.typography.gaugeValue,
          captionTypography: visual.typography.gaugeCaption
        },
        dotProgress: {
          count: WIFI_PROVISIONING_STEPS.length,
          size: 8,
          gap: 7,
          currentScale: 1.4,
          pending: colors.trackerPendingFill,
          current: colors.accent,
          completed: colors.success
        },
        stageFocusCard: {
          minHeight: 52,
          radius: 16,
          padding: [12, 14, 12, 14],
          background: colors.surface,
          border: { size: 1, color: colors.border },
          shadow: visual.shadows.card,
          leadingDot: { size: 10, color: colors.accent, pulse: true }
        },
        successCard: {
          radius: visual.radius.card,
          padding: [28, 18, 20, 18],
          background: colors.surface,
          shadow: visual.shadows.card,
          iconBox: { size: 72, radius: 24, background: colors.success, icon: 'check', iconColor: colors.onAccent }
        },
        cameraScanner: {
          layout: 'fullScreen',
          background: '#05070C',
          camera: 'back',
          facing: 'environment',
          formats: ['qr'],
          viewfinder: {
            shape: 'roundedRect',
            radius: 28,
            cornerSize: 28,
            cornerColor: colors.accent,
            overlay: 'rgba(5,7,12,0.46)'
          },
          instruction: {
            title: 'Scan QR',
            body: 'Align the QR code inside the frame',
            color: '#FFFFFF'
          }
        },
        selectedNetworkCard: {
          layout: 'grid',
          columns: '48px 1fr auto',
          gap: 12,
          padding: 14,
          radius: visual.radius.card,
          background: colors.surface,
          border: { size: 1, color: colors.border },
          shadow: visual.shadows.card
        }
      };
      const wifiState = buildWifiProvisioningState();
      const progressEvents = [
        'createDevice',
        'connect',
        'wifiConfigApplied',
        'deviceConfirmed',
        'cloudRegistration',
        'cloudAssociation',
        'onlineConfirmation'
      ];
      const nativeCapabilities = {
        ensurePermissions: {
          method: 'wifi.ensurePermissions',
          platform: 'android',
          platforms: ['android', 'ios', 'flutter'],
          returns: { granted: 'boolean', missing: 'string[]' }
        },
        scanRouterNetworks: {
          method: 'wifi.scanRouterNetworks',
          platform: 'android',
          platforms: ['android', 'ios', 'flutter'],
          filter: {
            excludeSsidPrefix: 'EWIFI_',
            frequencyMHz: { min: 2400, max: 2500 },
            uniqueBy: 'ssid',
            sort: 'rssiDesc'
          },
          returns: { networks: 'WifiNetwork[]' }
        },
        scanDeviceSoftAp: {
          method: 'wifi.scanDeviceSoftAp',
          platform: 'android',
          platforms: ['android', 'ios', 'flutter'],
          filter: { ssidPrefix: 'EWIFI_' },
          selection: {
            whenExplicitSsidProvided: 'exactCaseInsensitiveMatch',
            whenNoExplicitSsid: 'requireExactlyOne',
            minimumRssiDbm: -75
          },
          returns: { ssid: 'string', rssi: 'number' }
        },
        startProvisioning: {
          method: 'wifi.startProvisioning',
          platform: 'android',
          platforms: ['android', 'ios', 'flutter'],
          arguments: {
            nodeId: '$runtime.nodeId',
            devicePop: '$runtime.devicePop',
            accessToken: '$runtime.accessToken',
            username: '$runtime.username',
            routerSsid: '$state.wifiProvisioning.selectedRouter.ssid',
            routerPassword: '$state.wifiProvisioning.routerPassword',
            deviceSoftApSsid: '$state.wifiProvisioning.selectedDeviceSoftAp.ssid'
          },
          progressEvents: progressEvents.slice(),
          progressBinding: {
            event: 'state.wifiProvisioning.stage',
            index: 'state.wifiProvisioning.stageIndex',
            busy: 'state.wifiProvisioning.busy',
            errorCode: 'state.wifiProvisioning.errorCode',
            errorMessage: 'state.wifiProvisioning.errorMessage'
          },
          terminalStates: ['success', 'appliedUnconfirmed', 'failure', 'cancelled']
        },
        cancelProvisioning: {
          method: 'wifi.cancelProvisioning',
          platform: 'android',
          platforms: ['android', 'ios', 'flutter']
        },
        confirmCloudOnline: {
          method: 'wifi.confirmCloudOnline',
          platform: 'android',
          platforms: ['android', 'ios', 'flutter'],
          arguments: {
            nodeId: '$runtime.nodeId',
            accessToken: '$runtime.accessToken'
          },
          returns: { onlineConfirmed: 'boolean' }
        }
      };
      return {
        contractVersion: '1.3.0',
        mode: 'schema-ui-native-capability',
        productionReady: true,
        entryScreen: 'wifiNetworkPicker',
        supportedWidgets: [
          'stepTracker',
          'heroCard',
          'sectionHeader',
          'wifiNetworkList',
          'selectedNetworkCard',
          'textField',
          'helperNote',
          'button',
          'iconButton',
          'circularGauge',
          'dotProgress',
          'stageFocusCard',
          'successCard',
          'cameraScanner'
        ],
        identity: {
          modelNo: modelNo || '',
          nodeId: resolvedNodeId || null,
          nodeIdBinding: '_clientConnection.nodeId',
          appId: 'efactor_' + String(modelNo || 'device_ui').toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, ''),
          softApPrefix: 'EWIFI_',
          targetBand: '2.4GHz'
        },
        security: {
          persistRouterPassword: false,
          persistAccessTokenInSchema: false,
          persistPopInSchema: false,
          persistWifiConfigPassword: false,
          runtimeOnlyFields: ['accessToken', 'routerPassword', 'devicePop'],
          redactInLogs: ['accessToken', 'routerPassword', 'devicePop'],
          stateFieldPolicy: {
            routerPassword: { persist: false, redactInLogs: true, schemaMustNotContainValue: true },
            availableNetworks: { persist: false },
            selectedRouter: { persist: false },
            selectedDeviceSoftAp: { persist: false }
          }
        },
        libraries: {
          pluginId: 'efactor.wifi',
          implementation: 'native-library',
          bindBy: 'methodChannel',
          aliasAllowed: true,
          bindMethodsFrom: 'wifiProvisioning.nativeCapabilities.*.method',
          required: true,
          flutter: {
            plugin: 'efactor_wifi',
            methodChannel: 'efactor/wifi',
            eventChannel: 'efactor/wifi/events',
            dispatcher: 'WifiProvisioningPlugin'
          },
          android: {
            package: 'tech.efactor.wifi',
            className: 'WifiProvisioningModule',
            methodChannel: 'efactor/wifi',
            eventChannel: 'efactor/wifi/events',
            permissions: [
              'android.permission.ACCESS_FINE_LOCATION',
              'android.permission.ACCESS_WIFI_STATE',
              'android.permission.CHANGE_WIFI_STATE',
              'android.permission.CHANGE_NETWORK_STATE',
              'android.permission.NEARBY_WIFI_DEVICES'
            ]
          },
          ios: {
            module: 'EfactorWifi',
            className: 'WifiProvisioningModule',
            methodChannel: 'efactor/wifi',
            eventChannel: 'efactor/wifi/events',
            permissions: [
              'NSLocationWhenInUseUsageDescription',
              'NSLocalNetworkUsageDescription',
              'com.apple.developer.networking.wifi-info'
            ]
          }
        },
        scanner: {
          enabled: true,
          entryScreen: 'qrScanner',
          plugin: 'qrBarcodeScan',
          action: 'openScanner',
          headerButtonId: 'headerScanQr',
          sourceScreen: 'wifiNetworkPicker',
          resultBinding: 'state.scanResult.value',
          library: {
            pluginId: 'qrBarcodeScan',
            implementation: 'native-camera',
            bindBy: 'methodChannel',
            required: true,
            flutter: {
              plugin: 'mobile_scanner',
              methodChannel: 'efactor/scan',
              dispatcher: 'QrBarcodeScanPlugin'
            },
            android: {
              package: 'tech.efactor.scan',
              className: 'QrBarcodeScanModule',
              methodChannel: 'efactor/scan',
              permissions: ['android.permission.CAMERA']
            },
            ios: {
              module: 'EfactorScan',
              className: 'QrBarcodeScanModule',
              methodChannel: 'efactor/scan',
              permissions: ['NSCameraUsageDescription']
            },
            methods: {
              openScanner: 'scan.openCameraScanner'
            }
          }
        },
        actions: {
          headerScanQr: {
            type: 'navigate',
            screen: 'qrScanner',
            schemaPath: 'wifiProvisioning.screens',
            plugin: 'qrBarcodeScan',
            native: buildOpenScannerSchemaAction()
          },
          openScanner: buildOpenScannerSchemaAction()
        },
        events: {
          channel: 'efactor/wifi/events',
          names: {
            progress: 'wifi.provisioning.progress',
            terminal: 'wifi.provisioning.terminal',
            scanResult: 'wifi.scan.networks',
            qrScan: 'scan.qr.result',
            error: 'wifi.error'
          }
        },
        types: {
          WifiNetwork: {
            ssid: 'string',
            bssid: 'string?',
            rssi: 'number',
            frequencyMHz: 'number',
            security: 'Open|WEP|WPA|WPA2|WPA3|WPA2_WPA3',
            securityLabel: 'string',
            open: 'boolean'
          },
          DeviceSoftAp: {
            ssid: 'string',
            rssi: 'number'
          },
          ProgressEvent: {
            name: 'string',
            stageIndex: 'number',
            message: 'string',
            terminalState: 'success|appliedUnconfirmed|failure|cancelled|null'
          }
        },
        errorCodes: {
          PERMISSION_DENIED: 'Wi-Fi permission was denied.',
          NODE_ID_MISSING: 'Node ID is required before provisioning.',
          TOKEN_MISSING: 'Authenticated session token is required.',
          SCAN_FAILED: 'Unable to scan nearby Wi-Fi networks.',
          NO_NETWORKS: 'No 2.4 GHz networks found.',
          SOFTAP_NOT_FOUND: 'No EWIFI_ device network found.',
          SOFTAP_AMBIGUOUS: 'More than one EWIFI_ device network was found.',
          INVALID_PASSWORD: 'The Wi-Fi password was rejected.',
          PROVISION_FAILED: 'Device provisioning failed.',
          CLOUD_TIMEOUT: 'The device did not come online in time.',
          CANCELLED: 'Wi-Fi setup was cancelled.'
        },
        runtimeInputs: {
          nodeId: { source: '_clientConnection.nodeId', required: true },
          devicePop: { source: '_clientConnection.nodeId', policy: 'sameAsNodeId', required: true, schemaMustNotContainValue: true },
          accessToken: { source: 'authenticatedSession.accessToken', required: true, schemaMustNotContainValue: true },
          username: { source: 'authenticatedSession.emailOrUsername', required: true, schemaMustNotContainValue: true },
          deviceSoftAp: { source: 'nativeScan', prefix: 'EWIFI_', explicitSsidOptional: true },
          targetWifiBand: { value: '2.4GHz', frequencyMHz: { min: 2400, max: 2500 } }
        },
        state: wifiState,
        nativeCapabilities: nativeCapabilities,
        progressMap: [
          { event: 'sessionStart', stageIndex: 0, label: WIFI_PROVISIONING_STEPS[0], source: 'client' },
          { event: 'createDevice', stageIndex: 1, label: WIFI_PROVISIONING_STEPS[1], source: 'native' },
          { event: 'connect', stageIndex: 2, label: WIFI_PROVISIONING_STEPS[2], source: 'native' },
          { event: 'wifiConfigApplied', stageIndex: 3, label: WIFI_PROVISIONING_STEPS[3], source: 'native' },
          { event: 'deviceConfirmed', stageIndex: 4, label: WIFI_PROVISIONING_STEPS[4], source: 'native' },
          { event: 'wifiConnected', stageIndex: 5, label: WIFI_PROVISIONING_STEPS[5], source: 'optional' },
          { event: 'cloudRegistration', stageIndex: 6, label: WIFI_PROVISIONING_STEPS[6], source: 'native' },
          { event: 'cloudAssociation', stageIndex: 7, label: WIFI_PROVISIONING_STEPS[7], source: 'native' },
          { event: 'onlineConfirmation', stageIndex: 8, label: WIFI_PROVISIONING_STEPS[8], source: 'native' }
        ],
        flow: {
          launcher: 'actions.openWifiConfig',
          entryScreen: 'wifiNetworkPicker',
          successScreen: 'wifiSuccess',
          errorScreen: 'wifiError',
          back: {
            wifiNetworkPicker: 'close',
            wifiPassword: 'wifiNetworkPicker',
            deviceDiscovery: { screen: 'wifiPassword', whenOpen: 'wifiNetworkPicker' },
            provisioning: { screen: 'wifiPassword', whenOpen: 'wifiNetworkPicker' },
            cloudConfirmation: { screen: 'wifiPassword', whenOpen: 'wifiNetworkPicker' },
            wifiSuccess: 'close',
            wifiError: 'wifiNetworkPicker'
          }
        },
        theme: visual,
        tracker: tracker,
        signalQuality: signalQuality,
        componentStyles: componentStyles,
        postProvision: {
          setOnline: { binding: 'state.online', value: true },
          refresh: [
            { dataSource: 'wifiConfig', binding: 'state.wifiConfig', excludeFields: ['password'], usage: 'statusOnly' },
            { dataSource: 'deviceState', binding: 'state.parameters' }
          ],
          enableTransports: ['mqtt', 'deviceCommands'],
          controlReadyWhen: 'state.wifiProvisioning.onlineConfirmed == true',
          deviceControl: {
            transport: 'mqtt',
            adapter: 'dataSources.deviceCommands',
            bindingRoot: 'state.parameters',
            topics: 'mqtt.topics'
          }
        },
        screens: [
          {
            id: 'wifiNetworkPicker',
            type: 'screen',
            title: 'Select Wi-Fi',
            subtitle: 'Select your 2.4 GHz home Wi-Fi network',
            trackerStep: 0,
            style: screenStyle,
            header: {
              backButton: visual.buttons.back,
              title: 'Select Wi-Fi',
              titleStyle: visual.typography.title,
              trailing: {
                id: 'headerScanQr',
                type: 'iconButton',
                icon: 'scan',
                label: 'Scan QR code',
                accessibilityLabel: 'Scan QR code',
                placement: 'end',
                styleRef: 'wifiProvisioning.theme.buttons.scanIcon',
                plugin: 'qrBarcodeScan',
                action: {
                  type: 'navigate',
                  screen: 'qrScanner',
                  schemaPath: 'wifiProvisioning.screens',
                  plugin: 'qrBarcodeScan',
                  native: buildOpenScannerSchemaAction()
                }
              }
            },
            prerequisites: ['ensurePermissions'],
            onEnter: {
              type: 'nativeCapability',
              capability: 'scanRouterNetworks',
              resultBinding: 'state.wifiProvisioning.availableNetworks',
              onErrorScreen: 'wifiError'
            },
            onBack: { type: 'wifi.close' },
            body: [
              {
                id: 'wifiPickerHero',
                type: 'heroCard',
                styleRef: 'wifiProvisioning.componentStyles.heroCard',
                icon: 'wifi',
                eyebrow: 'Home network',
                title: 'Choose Wi-Fi',
                body: 'Your device connects on 2.4 GHz.'
              },
              {
                id: 'nearbyNetworksHeader',
                type: 'sectionHeader',
                styleRef: 'wifiProvisioning.componentStyles.sectionHeader',
                title: 'Nearby networks',
                trailing: {
                  id: 'rescanWifi',
                  type: 'button',
                  text: 'Rescan',
                  icon: 'refresh-cw',
                  placement: 'end',
                  styleRef: 'wifiProvisioning.theme.buttons.rescan',
                  action: {
                    type: 'nativeCapability',
                    capability: 'scanRouterNetworks',
                    resultBinding: 'state.wifiProvisioning.availableNetworks'
                  }
                }
              },
              {
                id: 'wifiNetworkList',
                type: 'wifiNetworkList',
                styleRef: 'wifiProvisioning.componentStyles.wifiNetworkList',
                binding: 'state.wifiProvisioning.availableNetworks',
                emptyText: 'No 2.4 GHz networks found.',
                item: {
                  titleBinding: 'item.ssid',
                  subtitleBinding: 'item.securityLabel',
                  signalBinding: 'item.rssi',
                  securityBinding: 'item.security',
                  openBinding: 'item.open',
                  presentation: networkRowPresentation,
                  signalQuality: signalQuality
                },
                onSelect: {
                  type: 'wifi.selectRouter',
                  valueBinding: 'state.wifiProvisioning.selectedRouter',
                  nextScreen: 'wifiPassword',
                  nextScreenWhenOpen: 'deviceDiscovery',
                  skipPasswordWhenOpen: true,
                  openWhen: 'item.open == true || item.security == "Open"'
                }
              }
            ]
          },
          {
            id: 'qrScanner',
            type: 'screen',
            title: 'Scan QR',
            subtitle: 'Use the camera to scan a QR code',
            style: Object.assign({}, screenStyle, { backgroundColor: '#05070C', surfaceColor: '#05070C' }),
            header: {
              backButton: Object.assign({}, visual.buttons.back, { iconColor: '#FFFFFF', background: 'rgba(255,255,255,0.12)' }),
              title: 'Scan QR',
              titleStyle: Object.assign({}, visual.typography.title, { color: '#FFFFFF' })
            },
            onEnter: buildOpenScannerSchemaAction(),
            onBack: { type: 'navigate', screen: 'wifiNetworkPicker' },
            onScanSuccess: {
              type: 'update',
              value: 'state.scanResult.value={scan.value}',
              payload: {
                source: 'scanner',
                persist: true,
                fields: {
                  value: '{scan.value}',
                  format: '{scan.format}',
                  scannedAt: '{scan.scannedAt}'
                }
              }
            },
            body: [
              {
                id: 'qrCameraView',
                type: 'cameraScanner',
                styleRef: 'wifiProvisioning.componentStyles.cameraScanner',
                camera: 'back',
                facing: 'environment',
                formats: ['qr'],
                overlay: {
                  viewfinder: true,
                  instructionTitle: 'Scan QR',
                  instruction: 'Align the QR code inside the frame'
                },
                resultBinding: 'state.scanResult.value',
                action: buildOpenScannerSchemaAction()
              }
            ]
          },
          {
            id: 'wifiPassword',
            type: 'screen',
            title: 'Enter password',
            subtitleBinding: 'state.wifiProvisioning.selectedRouter.ssid',
            trackerStep: 1,
            style: screenStyle,
            header: {
              backButton: visual.buttons.back,
              title: 'Enter password',
              titleStyle: visual.typography.title
            },
            onBack: { type: 'navigate', screen: 'wifiNetworkPicker' },
            body: [
              {
                id: 'wifiPasswordHero',
                type: 'heroCard',
