            },
            body: [
              {
                id: 'provisioningGauge',
                type: 'circularGauge',
                styleRef: 'wifiProvisioning.componentStyles.circularGauge',
                percentFrom: {
                  binding: 'state.wifiProvisioning.stageIndex',
                  map: 'wifiProvisioning.progressMap',
                  fallbackFormula: '((stageIndex + 1) / 9) * 84 + 10'
                },
                label: 'Status',
                captionBinding: 'state.wifiProvisioning.stage'
              },
              {
                id: 'provisioningTitle',
                type: 'text',
                textBinding: 'state.wifiProvisioning.stage'
              },
              {
                id: 'provisioningDots',
                type: 'dotProgress',
                styleRef: 'wifiProvisioning.componentStyles.dotProgress',
                binding: 'state.wifiProvisioning.stageIndex'
              },
              {
                id: 'provisioningFocus',
                type: 'stageFocusCard',
                styleRef: 'wifiProvisioning.componentStyles.stageFocusCard',
                textBinding: 'state.wifiProvisioning.stage'
              },
              {
                id: 'provisioningProgress',
                type: 'stepProgress',
                binding: 'state.wifiProvisioning.stageIndex',
                eventBinding: 'state.wifiProvisioning.stage',
                steps: WIFI_PROVISIONING_STEPS.slice(),
                progressMap: 'wifiProvisioning.progressMap',
                visible: false
              }
            ],
            onEnter: {
              type: 'nativeCapability',
              capability: 'startProvisioning',
              progressBinding: {
                event: 'state.wifiProvisioning.stage',
                index: 'state.wifiProvisioning.stageIndex',
                busy: 'state.wifiProvisioning.busy'
              },
              onSuccessScreen: 'wifiSuccess',
              onAppliedUnconfirmedScreen: 'cloudConfirmation',
              onFailureScreen: 'wifiError'
            }
          },
          {
            id: 'cloudConfirmation',
            type: 'screen',
            title: 'Connecting',
            subtitle: 'Wi-Fi credentials were applied. Waiting for cloud confirmation.',
            trackerStep: 2,
            style: screenStyle,
            header: {
              backButton: visual.buttons.back,
              title: 'Connecting',
              titleStyle: visual.typography.title
            },
            onBack: {
              type: 'sequence',
              steps: [
                { type: 'nativeCapability', capability: 'cancelProvisioning' },
                { type: 'navigate', screen: 'wifiPassword' }
              ]
            },
            body: [
              {
                id: 'cloudConfirmationGauge',
                type: 'circularGauge',
                styleRef: 'wifiProvisioning.componentStyles.circularGauge',
                value: 97,
                label: 'Status',
                caption: 'Going online'
              },
              {
                id: 'cloudConfirmationDots',
                type: 'dotProgress',
                styleRef: 'wifiProvisioning.componentStyles.dotProgress',
                completed: true
              },
              {
                id: 'cloudConfirmationFocus',
                type: 'stageFocusCard',
                styleRef: 'wifiProvisioning.componentStyles.stageFocusCard',
                text: 'Confirming cloud connection'
              }
            ],
            onEnter: {
              type: 'nativeCapability',
              capability: 'confirmCloudOnline',
              resultBinding: 'state.wifiProvisioning.onlineConfirmed',
              onSuccessScreen: 'wifiSuccess',
              onErrorScreen: 'wifiError'
            }
          },
          {
            id: 'wifiSuccess',
            type: 'screen',
            title: 'Connected',
            subtitle: 'The device is online and Wi-Fi setup is complete.',
            trackerStep: 3,
            style: screenStyle,
            header: {
              backButton: visual.buttons.back,
              title: 'Connected',
              titleStyle: visual.typography.title
            },
            onBack: { type: 'wifi.close' },
            body: [
              {
                id: 'wifiSuccessHero',
                type: 'heroCard',
                styleRef: 'wifiProvisioning.componentStyles.heroCard',
                variant: 'success',
                gradient: visual.gradient.heroSuccess,
                icon: 'check-circle',
                eyebrow: 'Setup complete',
                title: 'Device connected',
                body: 'The device is online and ready to use.'
              },
              {
                id: 'wifiSuccessCard',
                type: 'successCard',
                styleRef: 'wifiProvisioning.componentStyles.successCard',
                icon: 'check',
                title: 'You\'re all set',
                bodyPrefix: 'Connected to ',
                ssidBinding: 'state.wifiProvisioning.selectedRouter.ssid',
                onlineBinding: 'state.wifiProvisioning.onlineConfirmed',
                onlineStateBinding: 'state.online',
                onlineLabelBinding: 'state.onlineLabel',
                chips: [
                  {
                    id: 'online',
                    text: 'Online',
                    token: 'good',
                    stateBinding: 'state.wifiProvisioning.onlineConfirmed',
                    visibleWhen: 'state.wifiProvisioning.onlineConfirmed == true',
                    textBinding: 'state.onlineLabel'
                  },
                  {
                    id: 'ssid',
                    textBinding: 'state.wifiProvisioning.selectedRouter.ssid',
                    token: 'best',
                    visibleWhen: 'state.wifiProvisioning.selectedRouter.ssid != null && state.wifiProvisioning.selectedRouter.ssid != ""'
                  }
                ]
              },
              {
                id: 'wifiDone',
                type: 'button',
                text: 'Done',
                placement: 'inline',
                styleRef: 'wifiProvisioning.componentStyles.primaryButton',
                action: {
                  type: 'wifi.close',
                  refreshBindings: ['state.wifiConfig', 'state.online', 'state.parameters'],
                  enableTransports: ['mqtt', 'deviceCommands'],
                  excludeRefreshFields: ['password']
                }
              }
            ]
          },
          {
            id: 'wifiError',
            type: 'screen',
            title: 'Wi-Fi setup failed',
            subtitleBinding: 'state.wifiProvisioning.errorMessage',
            trackerStep: 2,
            style: screenStyle,
            header: {
              backButton: visual.buttons.back,
              title: 'Wi-Fi setup failed',
              titleStyle: visual.typography.title
            },
            onBack: { type: 'wifi.reset', nextScreen: 'wifiNetworkPicker' },
            body: [
              {
                id: 'wifiErrorHero',
                type: 'heroCard',
                styleRef: 'wifiProvisioning.componentStyles.heroCard',
                variant: 'error',
                gradient: visual.gradient.heroError,
                icon: 'triangle-alert',
                eyebrow: 'Could not finish',
                title: 'Wi-Fi setup failed',
                bodyBinding: 'state.wifiProvisioning.errorMessage'
              },
              {
                id: 'retryWifi',
                type: 'button',
                text: 'Try again',
                placement: 'bottomAnchored',
                styleRef: 'wifiProvisioning.componentStyles.primaryButton',
                action: { type: 'wifi.reset', nextScreen: 'wifiNetworkPicker' }
              }
            ]
          }
        ],
        developerInstructions: [
          'Bind native library methods from wifiProvisioning.libraries to wifiProvisioning.nativeCapabilities.*.method.',
          'Read runtimeInputs from the authenticated session and _clientConnection. Never persist accessToken, routerPassword, or devicePop in schema or logs.',
          'openWifiConfig must present wifiProvisioning.screens starting at entryScreen. Do not use dataSources.wifiConfig as the password or SSID source for setup.',
          'Map native progress events through wifiProvisioning.progressMap into state.wifiProvisioning.stageIndex and stage.',
          'After wifiSuccess, refresh wifi status only, set state.online, enable mqtt/deviceCommands, and bind controls through state.parameters.',
          'Render wifiProvisioning screens from wifiProvisioning.theme, tracker, componentStyles, and each screen.body. Do not use the device green/peach theme for these screens.'
        ],
        nodeId: resolvedNodeId || null
      };
    }

    function buildDeviceInfoPageSchema(resolvedNodeId, schemaApiUrl) {
      const detailRow = function(id, label, rowOptions) {
        rowOptions = rowOptions || {};
        const row = {
          id: id,
          type: 'detailRow',
          label: label,
          valueBinding: rowOptions.valueBinding || null,
          sideValueBinding: rowOptions.sideValueBinding || null,
          hrefBinding: rowOptions.hrefBinding || null,
          subtitle: rowOptions.subtitle || null,
          icon: rowOptions.icon || null
        };
        if (rowOptions.trailingAction) {
          row.trailingAction = rowOptions.trailingAction;
        }
        return row;
      };

      const removeDeviceConfirm = {
        title: 'Remove device',
        message: 'Remove this device from your account?',
        fields: ['deviceId', 'name', 'type']
      };

      return {
        version: '1.0.0',
        entryScreen: 'gatewayDetails',
        presentation: 'modal',
        title: 'Gateway Details',
        dataSource: 'deviceInfo',
        dataUrl: schemaApiUrl || '',
        responsePath: 'node_details[0].config',
        infoPath: 'info',
        fieldBindings: {
          deviceId: 'node_details[0].id|node_details[0].node_id|node_details[0].config.node_id',
          name: 'info.name|devices[0].name|info.product',
          type: 'info.type|info.product_type|devices[0].type',
          network: 'info.SSID|info.ssid|info.Access_Point|info.access_point',
          firmware: 'info.fw_version|info.firmware_version|info.version',
          guaranteeUrl: 'info.Guarantee_Card|info.guarantee_card',
          userGuideUrl: 'info.Video|info.user_guide|info.User_Guide',
          helpUrl: 'info.Need_Help|info.need_help',
          ticketsUrl: 'info.Track_Tickets|info.track_tickets|info.Auto_Test|info.auto_test'
        },
        theme: {
          backgroundColor: currentTheme.backgroundColor || '#F8FAFC',
          surfaceColor: currentTheme.cardColor || '#FFFFFF',
          textColor: currentTheme.textColor || '#0F172A',
          mutedTextColor: currentTheme.mutedTextColor || '#64748B',
          borderColor: currentTheme.borderColor || '#E2E8F0',
          accentColor: currentTheme.accentColor || '#2563EB'
        },
        screens: {
          gatewayDetails: {
            id: 'gatewayDetails',
            type: 'screen',
            title: 'Gateway Details',
            layout: 'scroll',
            sections: [
              {
                id: 'identity',
                type: 'group',
                rows: [
                  detailRow('deviceId', 'Device Id', {
                    valueBinding: 'node_details[0].id',
                    trailingAction: {
                      id: 'device_info_delete_inline',
                      action: 'removeDevice',
                      icon: 'trash-2',
                      label: 'Delete device',
                      confirm: removeDeviceConfirm
                    }
                  }),
                  detailRow('name', 'Name', { sideValueBinding: 'info.name' }),
                  detailRow('type', 'Type', { sideValueBinding: 'info.type' }),
                  detailRow('network', 'Network Connection', {
                    valueBinding: 'info.SSID',
                    icon: 'wifi'
                  })
                ]
              },
              {
                id: 'firmware',
                type: 'group',
                rows: [
                  detailRow('firmware', 'Firmware Version', { sideValueBinding: 'info.fw_version' })
                ]
              },
              {
                id: 'support',
                type: 'group',
                rows: [
                  detailRow('guarantee', 'Guarantee Card', {
                    subtitle: 'Terms & Conditions',
                    hrefBinding: 'info.Guarantee_Card',
                    icon: 'file'
                  }),
                  detailRow('userGuide', 'User Guide', {
                    subtitle: 'Troubleshooting',
                    hrefBinding: 'info.Video',
                    icon: 'chevron-right'
                  }),
                  detailRow('help', 'Need Help?', {
                    subtitle: 'Chat with us',
                    hrefBinding: 'info.Need_Help',
                    icon: 'help-circle'
                  }),
                  detailRow('tickets', 'Track tickets', {
                    subtitle: 'Your service requests',
                    hrefBinding: 'info.Auto_Test',
                    icon: 'inbox'
                  })
                ]
              },
              {
                id: 'removeDeviceFooter',
                type: 'group',
                style: 'footerAction',
                rows: [
                  {
                    id: 'device_info_delete_button',
                    type: 'button',
                    label: 'Delete Device',
                    icon: 'trash-2',
                    action: 'removeDevice',
                    style: 'danger',
                    confirm: removeDeviceConfirm
                  }
                ]
              }
            ]
          }
        },
        actions: {
          openDeviceInfo: {
            type: 'present',
            schemaPath: 'infoPage',
            entryScreen: 'gatewayDetails',
            load: 'deviceInfo'
          },
          closeDeviceInfo: {
            type: 'dismiss'
          },
          removeDevice: {
            type: 'api',
            method: 'POST',
            url: removeDeviceUrl || '',
            // Token goes in Authorization header only — never in URL or body.
            fallbackUrl: 'v8/iot_api_creation.php?action=remove_node',
            // node_id is the Device Id shown in the info page — MUST be in the POST body.
            body: {
              node_id: '$runtime.nodeId'
            },
            requestSchema: {
              type: 'object',
              required: ['node_id'],
              properties: {
                node_id: {
                  type: 'string',
                  binding: 'device.node_id'
                }
              }
            },
            nativeApi: {
              method: 'POST',
              url: String(v8DeviceApiBase || 'https://efactor.tech/v8/iot_api_creation.php').replace(/\/+$/, ''),
              query: { action: 'remove_node' },
              headers: {
                'Content-Type': 'application/json',
                Authorization: { $secureState: 'session.iotAccessToken' }
              },
              body: { node_id: '{{device.node_id}}' }
            },
            query: {
              action: 'remove_node'
            },
            auth: {
              type: 'session',
              header: 'Authorization'
            },
            confirm: removeDeviceConfirm,
            refresh: ['schema', 'deviceInfo']
          }
        },
        inlineActions: {
          deviceInfoDeleteInline: {
            id: 'device_info_delete_inline',
            rowId: 'deviceId',
            icon: 'trash-2',
            label: 'Delete device',
            action: 'removeDevice'
          }
        },
        footerActions: {
          deleteDevice: {
            id: 'device_info_delete_button',
            label: 'Delete Device',
            icon: 'trash-2',
            action: 'removeDevice'
          }
        },
        developerInstructions: [
          'openDeviceInfo must present infoPage.screens starting at entryScreen gatewayDetails.',
          'Load deviceInfo from dataSources.deviceInfo or infoPage.dataUrl before rendering detail rows.',
          'Resolve infoPage.fieldBindings with the same precedence as studio normalizeDeviceInfo().',
          'Device Id row shows trailingAction Delete device (trash icon). Footer shows Delete Device button after Track tickets.',
          'Both removeDevice triggers must confirm before calling v8/iot_api_creation.php?action=remove_node with node_id in the JSON body and access_token in the Authorization header. Never put access_token in the URL or body.'
        ],
        nodeId: resolvedNodeId || null
      };
    }

    function buildExtendedSchemaContract(options) {
      const controls = options.controls || [];
      const pages = options.pages || [];
      const deviceParameters = options.deviceParameters || {};
      const deviceConfig = options.deviceConfig || {};
      const activeIndex = options.activeIndex || 0;
      const activePageId = options.activePageId || '';
      const activePageNo = options.activePageNo || '';
      const primary = options.primary || 'power';
      const resolvedNodeId = getStudioNodeId() || modelNo || '';

      const pageRoutes = pages.map(function(page, index) {
        return {
          id: page.id,
          route: '/device/' + encodeURIComponent(resolvedNodeId || modelNo || 'model') + '/page/' + page.pageNo,
          pageNo: page.pageNo,
          titleKey: 'page.' + page.pageNo + '.title',
          index: index,
          controlIds: page.controlIds || [],
          deepLink: 'efactor://device/' + encodeURIComponent(resolvedNodeId || modelNo || 'model') + '/page/' + page.pageNo
        };
      });

      return {
        permissions: buildPermissionsSchema(controls),
        validation: Object.assign({}, SCHEMA_DYNAMIC_VALIDATION, {
          mode: 'onChange',
          showInlineErrors: true,
          rules: buildValidationRulesFromControls(controls),
          conditionalVisibility: {
            supported: true,
            expressions: (controls || []).filter(function(control) {
              return control.visible === false;
            }).map(function(control) {
              return {
                controlId: control.id,
                parameterKey: control.parameterKey,
                visible: false,
                expression: 'settings.componentOverrides["' + (control.parameterKey || control.id) + '"].hidden !== true'
              };
            })
          }
        }),
        deviceState: {
          namespace: 'device.parameters',
          bindingRoot: 'state.parameters',
          parameters: deviceParameters,
          config: deviceConfig,
          primary: primary,
          node_id: resolvedNodeId,
          connectivity: {
            online: true,
            lastSync: null,
            source: 'deviceState'
          },
          sync: {
            strategy: 'live-binding',
            optimisticUpdates: true,
            reconcileOnReconnect: true
          }
        },
        navigationGraph: {
          graph: {
            initialRouteId: activePageId || (pages[0] && pages[0].id) || null,
            initialPageNo: activePageNo || (pages[0] && pages[0].pageNo) || '1',
            routes: pageRoutes,
            transitions: {
              type: 'slide',
              durationMs: 280,
              axis: 'horizontal'
            }
          },
          deepLinks: pageRoutes.map(function(route) {
            return { pattern: route.deepLink, routeId: route.id, pageNo: route.pageNo };
          }),
          backStack: {
            enabled: true,
            rootRouteId: pages[0] ? pages[0].id : null
          }
        },
        dashboard: {
          type: 'device-control',
          layout: 'vertical-pager',
          modelNo: modelNo || '',
          activePageIndex: activeIndex,
          pages: pages.map(function(page) {
            return {
              id: page.id,
              pageNo: page.pageNo,
              title: page.title,
              subtitle: page.subtitle,
              controlIds: page.controlIds || [],
              controlCount: page.controlCount || 0,
              widgetTreeRef: 'page_slide_' + page.index
            };
          }),
          grid: null,
          sections: ['header', 'brandStrip', 'paramList', 'pager', 'footer']
        },
        localization: buildLocalizationSchema(controls, pages, (modelNo || 'Efactor Device') + ' Control'),
        offline: {
          enabled: true,
          cacheStrategy: 'stale-while-revalidate',
          queueCommands: true,
          persistTheme: true,
          persistLastKnownState: true,
          syncOnReconnect: true,
          storage: {
            theme: 'device_ui_theme_' + (modelNo || 'model'),
            schema: 'device_ui_schema_' + (modelNo || 'model'),
            state: 'device_ui_state_' + (modelNo || 'model')
          }
        },
        apiContracts: {
          deviceInfo: {
            id: 'deviceInfo',
            type: 'rest',
            method: 'GET',
            url: buildSchemaApiUrlForStudio(resolvedNodeId),
            auth: { type: 'session', credentials: 'same-origin' },
            requestSchema: { type: 'object', properties: {} },
            responseSchema: { type: 'object', path: 'node_details[0].config' },
            polling: { enabled: false, intervalMs: 30000 },
            caching: { enabled: true, ttlSeconds: 300, strategy: 'network-first' },
            retry: { maxAttempts: 3, backoffMs: 500, retryOn: [408, 429, 500, 502, 503, 504] }
          },
          removeDevice: {
            id: 'removeDevice',
            type: 'rest',
            method: 'POST',
            url: removeDeviceUrl || (String(v8DeviceApiBase || '').replace(/\/+$/, '') + '?action=remove_node'),
            auth: {
              type: 'session',
              // Token sent via Authorization header only — never in URL or body.
              header: 'Authorization',
              credentials: 'same-origin'
            },
            // node_id is the Device Id shown in the info page — MUST be in the POST body.
            body: {
              node_id: '$runtime.nodeId'
            },
            requestSchema: {
              type: 'object',
              required: ['node_id'],
              properties: {
                node_id: {
                  type: 'string',
                  description: 'Device node_id — the Device Id shown in the info page.',
                  binding: 'device.node_id'
                }
              }
            },
            // nativeApi: Flutter-native path — uses runtime Authorization token, no session cookie needed.
            nativeApi: {
              method: 'POST',
              url: String(v8DeviceApiBase || 'https://efactor.tech/v8/iot_api_creation.php').replace(/\/+$/, ''),
              query: { action: 'remove_node' },
              headers: {
                'Content-Type': 'application/json',
                Authorization: { $secureState: 'session.iotAccessToken' }
              },
              body: { node_id: '{{device.node_id}}' }
            },
            query: {
              action: 'remove_node'
            },
            response: {
              successField: 'success',
              statusField: 'status',
              messageField: 'message',
              nodeIdField: 'node_id'
            },
            responseSchema: { type: 'object', properties: { success: { type: 'boolean' }, status: { type: 'string' }, message: { type: 'string' }, description: { type: 'string' } } },
            confirmBeforeExecute: true,
            refreshAfter: ['getDevices', 'getAllNodesStatus']
          },
          parameters: {
            id: 'parameters',
            type: 'rest',
            method: 'GET',
            url: buildSchemaApiUrlForStudio(resolvedNodeId),
            auth: { type: 'session', credentials: 'same-origin' },
            responseSchema: { type: 'array' },
            caching: { enabled: true, ttlSeconds: 120 }
          },
          scanResult: {
            id: 'scanResult',
            type: 'rest',
            method: 'GET',
            url: buildScanApiUrlForStudio(),
            auth: { type: 'none' },
            query: { model_no: modelNo || '', node_id: resolvedNodeId || '' },
            responseSchema: { type: 'object', path: 'scanResult|data|result|root' },
            valueBinding: 'state.scanResult.value',
            load: 'onAction',
            caching: { enabled: false }
          },
          wifiConfig: {
            id: 'wifiConfig',
            type: 'rest',
            method: 'GET',
            url: buildScanApiUrlForStudio(),
            auth: { type: 'none' },
            query: { model_no: modelNo || '', node_id: resolvedNodeId || '' },
            responseSchema: { type: 'object', path: 'wifi|wifiConfig|data.wifi|data.wifiConfig|result.wifi|result.wifiConfig|root' },
            valueBinding: 'state.wifiConfig',
            load: 'onAction',
            caching: { enabled: false },
            usage: 'postProvisionStatusRefresh',
            provisioningUiSource: false,
            excludeFields: ['password'],
            securityNotice: 'Do not use this REST response as the router-password source for provisioning UI. Router credentials are runtime-only.'
          },
          saveTheme: {
