    function ensureSchemaDisabledVisualState(node) {
      if (!schemaControlHasDisabledFlag(node)) return;
      const DISABLED_OPACITY = 0.45;
      node.props = node.props || {};
      if (typeof node.props.disabledOpacity !== 'number') {
