    function ensureDeviceFrameHasCommandId(control) {
      if (!control) return control;
      const meta = control.protocolMeta && typeof control.protocolMeta === 'object' ? control.protocolMeta : {};
      const name = control.parameterName || control.parameter || control.label || control.id || 'frame';
      let frame = control.deviceFrame && typeof control.deviceFrame === 'object'
