            control.component.interactive = false;
            control.component.readOnly = true;
            control.component.props = Object.assign({}, control.component.props || {}, {
              readOnly: true,
              enabled: true,
              interactive: false,
              disabledOpacity: 1,
              textColor: currentTheme.textColor || '#0F172A',
              valueColor: currentTheme.textColor || '#0F172A',
              disabledTextColor: currentTheme.textColor || '#0F172A',
              readOnlyTextColor: currentTheme.textColor || '#0F172A'
            });
            control.component.style = control.component.style || {};
            control.component.style.color = currentTheme.textColor || '#0F172A';
            control.component.style.textColor = currentTheme.textColor || '#0F172A';
