        page.controlCount = page.controlIds.length;
      });

      ['state', 'navigation', 'dashboard'].forEach(function(section) {
        const pages = schema[section] && schema[section].pages;
        if (!Array.isArray(pages)) return;
        pages.forEach(function(page) {
          const pageNo = String(page.pageNo || '');
          if (!byPage[pageNo]) return;
          if (Array.isArray(page.controlIds)) page.controlIds = byPage[pageNo].slice();
          page.controlCount = byPage[pageNo].length;
        });
      });

      if (schema.navigation && schema.navigation.graph && Array.isArray(schema.navigation.graph.routes)) {
        schema.navigation.graph.routes.forEach(function(route) {
