      }

      schema.settings = schema.settings || {};
      schema.settings.controlOrder = controlIds.slice();
      schema.settings.parameterIcons = pruneObjectMapToKeys(schema.settings.parameterIcons, liveKeys);
      schema.settings.componentOverrides = pruneObjectMapToKeys(schema.settings.componentOverrides, liveKeys);
