      };
      syncControlLists(schema.ui && schema.ui.widgetTree);
      syncControlLists(schema.extensions && schema.extensions.universalUi);

      if (schema.state && schema.state.device) {
        schema.state.device.parameters = deviceParameters;
      }
      if (schema.deviceState) {
        schema.deviceState.parameters = deviceParameters;
      }
      if (schema.permissions && schema.permissions.controls) {
        schema.permissions.controls = pruneObjectMapToKeys(schema.permissions.controls, liveKeys);
      }

      return schema;
    }

    function controlSchemaVariant(componentType) {
      const renderType = resolveParameterRenderType(componentType);
      if (renderType === 'switch' || renderType === 'button' || renderType === 'elevatedButton') return 'action';
      if (renderType === 'slider' || renderType === 'powerGauge' || renderType === 'needleGauge' || renderType === 'linearGauge') return 'slider';
      if (renderType === 'segmented' || renderType === 'dropdown') return 'segmented';
      if (isRegisteredComponentType(componentType)) return 'custom';
      return 'status';
    }

    function controlDataOperation(componentType, meta) {
      if (meta && !protocolAccessIsWritable(meta)) return 'read';
      const renderType = resolveParameterRenderType(componentType);
      if (renderType === 'button') return 'write';
      if (renderType === 'elevatedButton') return 'execute';
      if (renderType === 'linearGauge') return 'read';
      return 'write';
    }

    function previewIncludesFooterSaveButton() {
      return Boolean(phoneShell && phoneShell.querySelector('.footer-actions'));
    }

    function buildRangeInteractionEvents(binding) {
        return [
          { event: 'onChanged', action: { type: 'update', binding: binding } },
