    }

    function isProtocolToggleSwitch(meta) {
      const uiType = protocolUiTypeText(meta);
      return uiType === 'toggle switch' || uiType === 'toggle button' || uiType.indexOf('toggle switch') !== -1;
    }

    function canonicalCatalogTypeFromProtocol(meta, paramName, fallbackType) {
      if (isProtocolToggleSwitch(meta)) {
