      return control;
    }

    function isGetStatusParameter(name) {
      return String(name || '').toLowerCase().replace(/[_-]+/g, ' ').indexOf('get status') !== -1;
    }

    function getStatusRevealBinding(control) {
      const pageNo = String((control && control.pageNo) || '');
      const name = String((control && (control.parameterName || control.parameter || control.label)) || '');
      return 'state.getStatusResponse.' + parameterKeySlug(pageNo + ':' + name) + '.open';
    }

    function applyGetStatusResponseContract(control, meta) {
      if (!control || !isGetStatusParameter(control.parameterName || control.parameter || control.label)) {
        return control;
      }
      const source = String((meta && meta.ui_type_source) || '').toLowerCase();
      if (source !== 'response' && source !== 'error') return control;
      applyReadOnlyProtocolContract(control, Object.assign({}, meta || {}, {
        access: 'read',
        ui_type_source: source
      }));
      if (source !== 'response') return control;
      const revealBinding = getStatusRevealBinding(control);
      if (!control.component || typeof control.component !== 'object') control.component = {};
      control.component.props = Object.assign({}, control.component.props || {}, {
        initiallyExpanded: false,
        collapsed: true,
        revealBinding: revealBinding,
        visibleWhen: revealBinding + ' == true'
