      control.visible = control.visible !== false;
      return control;
    }

    function applyGetStatusCommandContract(control, meta) {
      if (!control || !isGetStatusParameter(control.parameterName || control.parameter || control.label)) {
        return control;
      }
      if (!protocolAccessIsWritable(meta)) return control;
      const catalogType = canonicalCatalogTypeFromProtocol(meta, control.parameterName || control.parameter || control.label, control.componentType);
      const schemaType = resolveSchemaComponentType(catalogType);
      const entry = getParameterCatalogEntry(catalogType) || getComponentLibraryEntry(schemaType) || getComponentLibraryEntry(catalogType);
      const widget = (entry && entry.flutterWidget) || flutterWidgetForComponentType(catalogType) || flutterWidgetForComponentType(schemaType);
      if (schemaType && schemaType !== 'auto') {
        control.componentType = schemaType;
        control.controlType = schemaType;
      } else if (control.componentType && !control.controlType) {
        control.controlType = control.componentType;
      }
      if (widget && widget !== 'ListTile') {
        control.flutterWidget = widget;
      }
      if (entry && entry.valueType && entry.valueType !== 'auto') {
        control.valueType = entry.valueType;
      }
      if (control.component) {
        if (schemaType && schemaType !== 'auto') control.component.type = schemaType;
        if (widget && widget !== 'ListTile') control.component.flutterWidget = widget;
        if (entry && entry.valueType && entry.valueType !== 'auto') {
          control.component.valueType = entry.valueType;
        }
