    function attachCanonicalDeviceFrames(controls, deviceConfig, controlActions) {
      const framesByName = {};
      const devices = deviceConfig && Array.isArray(deviceConfig.devices) ? deviceConfig.devices : [];
      devices.forEach(function(device) {
        const pages = device && device.pages && typeof device.pages === 'object' ? device.pages : {};
        Object.keys(pages).forEach(function(pageName) {
          (pages[pageName] || []).forEach(function(item) {
            const frame = item && item.frame;
            const name = String((frame && frame.name) || '').toLowerCase().trim();
            if (name) framesByName[name] = frame;
          });
        });
      });

      function resolveFrame(name, meta) {
        const key = String(name || '').toLowerCase().trim();
        if (key && framesByName[key]) return framesByName[key];
        const slug = key.replace(/[^a-z0-9]+/g, '');
        if (slug) {
          const frameNames = Object.keys(framesByName);
          for (let i = 0; i < frameNames.length; i += 1) {
            const frameSlug = frameNames[i].replace(/[^a-z0-9]+/g, '');
            if (frameSlug === slug || frameSlug.indexOf(slug) !== -1 || slug.indexOf(frameSlug) !== -1) {
              return framesByName[frameNames[i]];
            }
          }
        }
        if (meta && meta.frame && typeof meta.frame === 'object') return meta.frame;
        return null;
      }

      (controls || []).forEach(function(control) {
        if (!control) return;
        // Attach canonical frame formatting to every control (command/response/error),
        // not only the writable power/toggle controls.
        const name = String(control.parameterName || control.parameter || control.label || '').toLowerCase().trim();
        const meta = control.protocolMeta || {};
        const resolved = resolveFrame(name, meta);
        if (resolved) {
