        } else if (!control.deviceFrame) {
          control.deviceFrame = buildDeviceFrameFromMeta(name || control.id || 'frame', meta);
        } else {
          control.deviceFrame = normalizeDeviceFrame(control.deviceFrame, name || 'frame', meta);
        }
        if (!control.protocolMeta || typeof control.protocolMeta !== 'object') {
          control.protocolMeta = {};
