        ensureDeviceFrameHasCommandId(control);
        if (control.action && controlActions && controlActions[control.action] && controlActions[control.action].input) {
          controlActions[control.action].input.commands = control.deviceFrame.commands || [];
          controlActions[control.action].input.response = control.deviceFrame.response || [];
          controlActions[control.action].input.error = control.deviceFrame.error || [];
          controlActions[control.action].input.frameName = control.deviceFrame.name || name;
        }
      });
    }

    function controlOrderIndexForKey(order, key) {
      if (!key || !Array.isArray(order) || !order.length) return -1;
      const exact = order.indexOf(key);
      if (exact !== -1) return exact;
      let best = -1;
      for (let i = 0; i < order.length; i += 1) {
        const item = String(order[i] || '');
        if (!item) continue;
        if (key === item || key.indexOf(item + ':') === 0) {
          if (best === -1 || i < best) best = i;
        }
      }
      return best;
    }

    function isStudioDarkTheme() {
      return String(currentTheme.themeMode || '').toLowerCase() === 'dark';
    }

    function themeInputFillColor(fallback) {
      if (isStudioDarkTheme()) {
        return currentTheme.backgroundColor || currentTheme.shellColor || '#0B1220';
      }
      return fallback || '#FFFFFF';
    }

    function themeInputTextColor(fallback) {
      return isStudioDarkTheme() ? '#FFFFFF' : (fallback || currentTheme.textColor || '#0F172A');
    }

    function themeWellColor() {
      return isStudioDarkTheme() ? '#111827' : '#F8FAFC';
    }

    function buildTextFieldVisualContract(options) {
      const opts = options || {};
      const colors = opts.colors || {};
      const fill = themeInputFillColor(colors.cardColor);
      return {
        fillColor: fill,
        backgroundColor: fill,
        borderColor: isStudioDarkTheme() ? '#475569' : (colors.borderColor || currentTheme.borderColor || '#E2E8F0'),
        focusedBorderColor: colors.accentColor || currentTheme.accentColor || '#2563EB',
        disabledBorderColor: currentTheme.borderColor || '#E2E8F0',
        borderWidth: parseInt(currentTheme.borderSize || 1, 10),
        borderRadius: 12,
        contentPadding: { top: 10, right: 12, bottom: 10, left: 12 },
        horizontalPadding: 12,
        verticalPadding: 10,
        height: 44,
        minHeight: 44,
        fontFamily: currentTheme.fontFamily || 'Inter',
        fontSize: 14,
        fontWeight: 600,
        textColor: themeInputTextColor(colors.textColor),
        disabledTextColor: themeInputTextColor(colors.textColor),
        readOnlyTextColor: themeInputTextColor(colors.textColor),
        hintColor: currentTheme.mutedTextColor || '#64748B'
      };
    }

    /* cmd is device output presented as a console readout, so it overrides the
       light text-field chrome with the terminal palette the preview uses. */
    function buildCmdTerminalProps() {
      return {
        variant: 'terminal',
        promptSymbol: '>',
        promptColor: '#4ADE80',
        caretColor: '#4ADE80',
        fontFamily: 'monospace',
        fontSize: 12,
        fontWeight: 600,
        fillColor: '#0B0F17',
        backgroundColor: '#0B0F17',
        borderColor: '#1F2937',
        focusedBorderColor: '#1F2937',
        borderWidth: 1,
        borderRadius: 8,
        textColor: '#E5E7EB',
        hintColor: '#6B7280',
        selectable: true,
        minLines: 1,
        maxLines: null,
        expands: true,
        softWrap: true,
        keyboardType: 'multiline'
      };
    }

    function buildSendButtonProps(binding, visible, colors) {
      const palette = colors || {};
      return {
        visible: Boolean(visible),
        icon: 'send',
        size: 32,
        borderRadius: 9,
        backgroundColor: palette.accentColor || currentTheme.accentColor || '#2563EB',
        iconColor: '#FFFFFF',
        iconSize: 15,
        action: { type: 'send', binding: binding }
      };
    }

    function buildDropdownVisualContract(options) {
      const opts = options || {};
      const colors = opts.colors || {};
      const fieldFill = themeInputFillColor(colors.cardColor);
      const fieldText = themeInputTextColor(colors.textColor);
      return {
        fieldHeight: 44,
        fieldBackground: fieldFill,
        fieldBorderColor: isStudioDarkTheme() ? '#475569' : (colors.borderColor || currentTheme.borderColor || '#E2E8F0'),
        fieldBorderWidth: parseInt(currentTheme.borderSize || 1, 10),
        fieldRadius: 12,
        fieldPadding: { top: 10, right: 12, bottom: 10, left: 12 },
        hint: 'Choose',
        chevronIcon: 'chevron-down',
        selectedTextStyle: {
          fontFamily: currentTheme.fontFamily || 'Inter',
          fontSize: 14,
          fontWeight: 700,
          color: fieldText
        },
        popupBackground: fieldFill,
        popupRadius: 12,
        popupElevation: 8,
        popupShadow: '0 12px 28px rgba(18,50,70,0.16)',
        optionRowHeight: 44,
        optionPadding: { top: 10, right: 12, bottom: 10, left: 12 },
        optionTextStyle: {
          fontFamily: currentTheme.fontFamily || 'Inter',
          fontSize: 14,
          fontWeight: 600,
          color: fieldText
        },
        maxPopupHeight: 280,
        selectedOptionBackground: 'rgba(37,99,235,0.10)',
        hoverOptionBackground: 'rgba(15,23,42,0.06)'
      };
    }

    function resolveDropdownSelectedValue(valueText, options) {
      const raw = valueText == null ? '' : String(valueText).trim();
      if (!raw) return '';
      const list = Array.isArray(options) ? options : [];
      if (!list.length) return raw;
      const match = list.find(function(opt) {
        return String(opt.value) === raw || String(opt.label) === raw;
      });
      return match ? String(match.value) : raw;
    }

    function findPreviewParamCardForControl(control) {
      const raw = String((control && (control.parameterKey || control.id)) || '');
      if (!raw) return null;
      const cards = document.querySelectorAll('.page-slide .param-card');
      for (let i = 0; i < cards.length; i++) {
        const key = cards[i].dataset.paramKey || '';
        if (key === raw || parameterKeySlug(key) === raw || parameterKeySlug(key) === parameterKeySlug(raw)) {
          return cards[i];
        }
      }
      return null;
    }

    function paramCardGroupLayout(card) {
      if (!card || !card.classList || !card.classList.contains('is-grouped-component')) {
        return { grouped: false, first: true, last: true };
      }
      const group = card.closest('.param-group-card');
      const cards = group
        ? Array.from(group.querySelectorAll(':scope > .param-component-stack > .param-card'))
        : [card];
      const index = cards.indexOf(card);
      return {
        grouped: true,
        first: index <= 0,
        last: index === cards.length - 1 || index < 0
      };
    }

    function validateCanonicalDeviceUiSchema(schema) {
      const result = { valid: true, errors: [], warnings: [] };
      const controls = Array.isArray(schema && schema.controls) ? schema.controls : [];
      const byId = {};
      controls.forEach(function(control) {
        if (!control || !control.id) {
          result.errors.push('Control is missing canonical id.');
          return;
        }
        if (byId[control.id]) {
          result.errors.push('Duplicate control id: ' + control.id);
        }
        byId[control.id] = control;
      });

      const lists = [];
      walkSchemaTree(schema && schema.ui && schema.ui.widgetTree, function(node) {
        if (node && node.type === 'schemaControlList' && node.properties && Array.isArray(node.properties.controlIds)) {
          lists.push(node.properties.controlIds);
        }
      });
      lists.forEach(function(list) {
        list.forEach(function(id) {
          if (!byId[id]) {
            result.errors.push('schemaControlList.controlIds item does not match controls[].id: ' + id);
          }
        });
      });

      (schema.pages || []).forEach(function(page) {
        (page && page.controlIds ? page.controlIds : []).forEach(function(id) {
          if (!byId[id]) {
            result.errors.push('pages[].controlIds item does not match controls[].id: ' + id);
          }
        });
      });

      const order = schema && schema.settings && Array.isArray(schema.settings.controlOrder)
        ? schema.settings.controlOrder
        : [];
      order.forEach(function(id) {
        if (!byId[id]) {
          result.errors.push('settings.controlOrder item does not match controls[].id: ' + id);
        }
      });
      const allowedParameterKeys = {};
      const nodeId = String((schema.node_id && schema.node_id.id) || (schema.meta && schema.meta.app && schema.meta.app.nodeId) || '');
      controls.forEach(function(control) {
        const meta = control.protocolMeta || {};
        const writable = protocolAccessIsWritable(meta);
        const uiType = protocolUiTypeText(meta);
        const widget = String((control.component && control.component.flutterWidget) || control.flutterWidget || '').toLowerCase();
        const expectedBinding = 'device.parameters.' + (control.parameterKey || parameterKeySlug(control.id));
        if (control.parameterKey) allowedParameterKeys[control.parameterKey] = true;
        if (control.binding && control.binding !== expectedBinding) {
          result.errors.push(control.id + ': binding must be ' + expectedBinding);
        }
        if (uiType.indexOf('toggle') !== -1) {
          if (control.componentType === 'slider' || widget === 'schemaslider') {
            result.errors.push(control.id + ': Toggle Switch was generated as a slider.');
          }
          if (widget === 'powerbutton' && !writable) {
            result.errors.push(control.id + ': Read Toggle Switch was generated as a PowerButton.');
          }
          if (control.valueType && control.valueType !== 'boolean') {
            result.errors.push(control.id + ': Toggle Switch valueType must be boolean.');
          }
        }
        if (!writable) {
          const events = [].concat(control.events || [], (control.component && control.component.events) || []);
          events.forEach(function(ev) {
            const type = ev && ev.action && String(ev.action.type || '').toLowerCase();
            if (type === 'send' || type === 'update') {
              result.errors.push(control.id + ': Read access still has a ' + type + ' event.');
            }
          });
        }
        if (writable) {
          const commands = control.deviceFrame && Array.isArray(control.deviceFrame.commands) ? control.deviceFrame.commands : [];
          const hasCommandId = commands.some(function(field) {
            return deviceFrameFieldName(field) === 'commandid' && !isEmptyFrameValue(field && field.value);
          });
          if (!hasCommandId) {
            result.errors.push(control.id + ': writable control deviceFrame is missing CommandId value.');
          }
        }
        if (isGetStatusParameter(control.parameterName || control.parameter || control.label) && !writable) {
          const type = String(control.componentType || '').toLowerCase();
          const responseWidget = String(flutterWidgetForComponentType(control.componentType || control.controlType) || '').toLowerCase();
          if (control.controlType && String(control.controlType).toLowerCase() !== type) {
            result.errors.push(control.id + ': Get Status response componentType and controlType do not agree.');
          }
          if (responseWidget && responseWidget !== 'listtile' && widget && widget !== responseWidget) {
            result.errors.push(control.id + ': Get Status response componentType and flutterWidget do not agree.');
          }
        }
        if (isGetStatusParameter(control.parameterName || control.parameter || control.label) && writable) {
          const type = String(control.componentType || '').toLowerCase();
          const expectedWidget = String(flutterWidgetForComponentType(control.componentType || control.controlType) || '').toLowerCase();
          if (control.controlType && String(control.controlType).toLowerCase() !== type) {
            result.errors.push(control.id + ': Get Status command componentType and controlType do not agree.');
          }
          if (expectedWidget && expectedWidget !== 'listtile' && widget && widget !== expectedWidget) {
            result.errors.push(control.id + ': Get Status command componentType and flutterWidget do not agree.');
          }
        }
        if (control.componentType && control.flutterWidget) {
          const type = String(control.componentType).toLowerCase();
          if (type === 'switch' && widget !== 'switch') {
            result.errors.push(control.id + ': componentType and flutterWidget do not agree.');
          }
        }
        if ((control.componentType === 'slider' || widget === 'schemaslider') && (control.valueType === 'boolean' || control.initialValue === false || control.initialValue === true)) {
          result.errors.push(control.id + ': schemaSlider is bound to a boolean value.');
        }
      });

      const parameterBags = [
        schema.state && schema.state.device && schema.state.device.parameters,
        schema.deviceState && schema.deviceState.parameters
      ];
      parameterBags.forEach(function(bag) {
        if (!bag || typeof bag !== 'object') return;
        Object.keys(bag).forEach(function(key) {
          if (!allowedParameterKeys[key]) {
            result.errors.push('Duplicate parameter-binding alias: ' + key);
          }
        });
      });

      if (nodeId && schema.meta && schema.meta.links) {
        ['parameters', 'deviceInfo'].forEach(function(key) {
          const url = String(schema.meta.links[key] || '');
          if (url && url.indexOf('node_id=') !== -1 && url.indexOf(encodeURIComponent(nodeId)) === -1 && url.indexOf(nodeId) === -1) {
            result.errors.push('meta.links.' + key + ' node_id does not match schema node_id.');
          }
        });
      }

      if (order.length && controls.length) {
        const sequenced = controls.slice().sort(function(a, b) {
          const pageA = parseInt(a.pageNo, 10) || 0;
          const pageB = parseInt(b.pageNo, 10) || 0;
          if (pageA !== pageB) return pageA - pageB;
          return (a.sequence || 0) - (b.sequence || 0);
        }).map(function(control) { return control.id; });
        const mismatch = sequenced.some(function(id, index) {
          return order[index] && order[index] !== id;
        });
        if (mismatch) {
          result.warnings.push('settings.controlOrder does not match controls[].sequence order.');
        }
      }

      result.valid = result.errors.length === 0;
      return result;
    }

    function buildControlInteractionEvents(componentType, binding, options) {
      const writable = !options || options.writable !== false;
      if (!writable) return [];
      const renderType = resolveParameterRenderType(componentType);
      if (renderType === 'switch') {
        return [
          { event: 'onChanged', action: { type: 'update', binding: binding } },
          { event: 'onChanged', action: { type: 'send', binding: binding } }
        ];
      }
      if (renderType === 'slider' || renderType === 'powerGauge' || renderType === 'needleGauge') {
        return buildRangeInteractionEvents(binding);
      }
      if (renderType === 'button' || renderType === 'elevatedButton') {
        return [{ event: 'onTap', action: { type: 'send', binding: binding } }];
      }
      if (renderType === 'dropdown' || renderType === 'segmented' || componentType === 'buttonGroup') {
        return [
          { event: 'onChanged', action: { type: 'update', binding: binding } },
          { event: 'onSelected', action: { type: 'send', binding: binding } }
        ];
      }
      if (componentType === 'fireControlPanel' || componentType === 'FireControlPanel') {
        return [
          { event: 'onCommand', action: { type: 'update', binding: binding } },
          { event: 'onCommand', action: { type: 'send', binding: binding } }
        ];
      }
      if (renderType === 'textField') {
        return [
          { event: 'onChanged', action: { type: 'update', binding: binding } },
          { event: 'onSubmitted', action: { type: 'send', binding: binding } },
          // Fired by the send button that now sits beside an editable field.
          { event: 'onSendTap', action: { type: 'send', binding: binding } }
        ];
      }
      return [];
    }

    function buildControlDataActionId(controlId) {
      return 'update_' + String(controlId || 'control').replace(/[^a-zA-Z0-9]+/g, '_');
    }

    function buildControlDataAction(controlId, componentType, binding, meta, parameterName, frame) {
      const actionId = buildControlDataActionId(controlId);
      const deviceFrame = frame && typeof frame === 'object' ? frame : buildDeviceFrameFromMeta(parameterName, meta);
      const dataField = findDeviceFrameDataField(deviceFrame);
      return {
        id: actionId,
        definition: {
          type: 'dataOperation',
          dataSource: 'deviceCommands',
          operation: controlDataOperation(componentType, meta),
          input: {
            modelNo: '$app.modelNo',
            parameter: parameterName,
            value: '$' + binding,
            commandId: meta.command_id || meta.commandId || null,
            functionCode: meta.function_code || meta.functionCode || null,
            actionId: meta.action_id || meta.actionId || null,
            frameName: deviceFrame.name || parameterName,
            multipleUi: deviceFrame.multiple_ui || ['false', 'false', 'false'],
            triggerUi: deviceFrame.trigger_ui || ['false', 'false', 'false'],
            commands: Array.isArray(deviceFrame.commands) ? deviceFrame.commands : [],
            response: Array.isArray(deviceFrame.response) ? deviceFrame.response : [],
            error: Array.isArray(deviceFrame.error) ? deviceFrame.error : [],
            dataField: dataField ? {
              name: dataField.default_name || parameterName,
              byteStart: dataField.byte_start_position || null,
              noOfBytes: dataField.no_of_bytes || null,
              uiType: dataField.ui_type || meta.ui_type || null,
              asperui: Array.isArray(dataField.asperui) ? dataField.asperui : (meta.items || []),
              asperuiValues: Array.isArray(dataField.asperui_values) ? dataField.asperui_values : (meta.item_values || []),
              snoAsperui: Array.isArray(dataField.sno_asperui) ? dataField.sno_asperui : (meta.sno_asperui || []),
              displayValue: dataField.display_value || {
                min: meta.minimum != null ? String(meta.minimum) : '',
                max: meta.maximum != null ? String(meta.maximum) : ''
              },
              access: dataField.ui_description || meta.access || null
            } : null
          }
        }
      };
    }

    function findDeviceFrameDataField(frame) {
      const commands = frame && Array.isArray(frame.commands) ? frame.commands : [];
      let fallback = null;
      for (let index = 0; index < commands.length; index += 1) {
        const field = commands[index];
        if (!field || typeof field !== 'object') continue;
        const description = String(field.Field_description || field.default_name || '').toLowerCase();
        const uiType = String(field.ui_type || '').toLowerCase();
        if (description === 'data' || description === 'trigger') return field;
        if (!fallback && uiType && uiType !== 'none') fallback = field;
      }
      return fallback;
    }

    function emptyDeviceFrameField(name, byteStart, extra) {
      return Object.assign({
        default_name: name,
        value: '',
        Field_description: name,
        no_of_bytes: 1,
        byte_start_position: byteStart,
        ui_type: 'None',
        local_control: 'enable'
      }, extra || {});
    }

    function noneDeviceFrameField() {
      return {
        default_name: 'None',
        value: null,
        Field_description: 'None',
        no_of_bytes: 0,
        byte_start_position: 0,
        ui_type: 'None',
        local_control: 'enable'
      };
    }

    function deviceFrameFieldName(field) {
      return String((field && (field.Field_description || field.field_description || field.default_name)) || '')
        .toLowerCase()
        .replace(/[\s_]+/g, '')
        .trim();
    }

    function isEmptyFrameValue(value) {
      return value === '' || value === null || typeof value === 'undefined';
    }

    function looksLikeProtocolHex(value) {
      const raw = String(value == null ? '' : value).trim().replace(/^0x/i, '').replace(/[\s:_-]+/g, '').toUpperCase();
      return raw !== '' && /^[0-9A-F]+$/.test(raw);
    }

    function normalizeProtocolHex(value, byteCount) {
      let raw = String(value == null ? '' : value).trim().replace(/^0x/i, '').replace(/[\s:_-]+/g, '').toUpperCase();
      if (!raw || !/^[0-9A-F]+$/.test(raw)) return '';
      if (raw.length % 2 !== 0) raw = '0' + raw;
      const bytes = Math.max(0, parseInt(byteCount, 10) || 0);
      if (bytes > 0) {
        const width = bytes * 2;
        if (raw.length < width) raw = raw.padStart(width, '0');
        else if (raw.length > width) raw = raw.slice(-width);
      }
      return raw;
    }

    function hydrateDeviceFrameFields(fields, meta) {
      meta = meta && typeof meta === 'object' && !Array.isArray(meta) ? meta : {};
      const commandId = meta.command_id || meta.commandId;
      const functionCode = meta.function_code || meta.functionCode;
      const actionId = meta.action_id || meta.actionId;
      return (Array.isArray(fields) ? fields : []).map(function(field) {
        if (!field || typeof field !== 'object' || Array.isArray(field)) return field;
        const next = Object.assign({}, field);
        const name = deviceFrameFieldName(next);
        let bytes = parseInt(next.no_of_bytes, 10);
        if (!Number.isFinite(bytes) || bytes < 1) bytes = 1;
        next.no_of_bytes = bytes;
        // Only promote asperui → wire when asperui is protocol hex (Rule 1).
        if (isEmptyFrameValue(next.value) && !isEmptyFrameValue(next.asperui_value) && looksLikeProtocolHex(next.asperui_value)) {
          next.value = next.asperui_value;
        }
        if (!isEmptyFrameValue(next.value)) {
          if (name === 'terminator' && !looksLikeProtocolHex(next.value)) {
            next.value = '0A';
            if (isEmptyFrameValue(next.asperui_value) || !looksLikeProtocolHex(next.asperui_value)) next.asperui_value = '0A';
          } else if (looksLikeProtocolHex(next.value)) {
            next.value = normalizeProtocolHex(next.value, bytes);
          } else if (name !== 'commandid' && name !== 'functioncode' && name !== 'actionid') {
            if (isEmptyFrameValue(next.asperui_value) || looksLikeProtocolHex(next.asperui_value)) {
              next.asperui_value = next.value;
            }
            next.value = '00'.repeat(bytes);
          }
          return next;
        }
        let fill = null;
        if (name === 'commandid' && !isEmptyFrameValue(commandId)) fill = normalizeProtocolHex(commandId, bytes) || commandId;
        else if (name === 'functioncode' && !isEmptyFrameValue(functionCode)) fill = normalizeProtocolHex(functionCode, bytes) || functionCode;
        else if (name === 'actionid' && !isEmptyFrameValue(actionId)) fill = normalizeProtocolHex(actionId, bytes) || actionId;
        else if (name === 'terminator') fill = '0A';
        if (fill != null) {
          next.value = fill;
          if (isEmptyFrameValue(next.asperui_value)) next.asperui_value = fill;
        }
        return next;
      });
    }

    function isEmptyFrameSlot(field) {
      if (!field || typeof field !== 'object') return true;
      const label = String(field.Field_description || field.field_description || field.default_name || '').trim();
      const hasName = label !== '' && !/^field_\d+$/i.test(label) && label.toLowerCase() !== 'none';
      const value = field.value;
      const hasValue = value !== null && typeof value !== 'undefined' && value !== '' && !(Array.isArray(value) && !value.length);
      const start = parseInt(field.byte_start_position, 10);
      const uiType = String(field.ui_type || '').toLowerCase().trim();
      const hasUi = uiType !== '' && uiType !== 'none';
      return !hasName && !hasValue && !hasUi && !(Number.isFinite(start) && start >= 1);
    }

    function repairDeviceFrameBytePositions(fields) {
      let nextPosition = 1;
      const repaired = [];
      (Array.isArray(fields) ? fields : []).forEach(function(field) {
        if (!field || typeof field !== 'object' || Array.isArray(field)) return;
        if (isEmptyFrameSlot(field)) return;
        const next = Object.assign({}, field);
        const name = deviceFrameFieldName(next);
        let bytes = parseInt(next.no_of_bytes, 10);
        if (!Number.isFinite(bytes) || bytes < 1) bytes = 1;
        let start = parseInt(next.byte_start_position, 10);
        if (!Number.isFinite(start)) start = 0;
        if (start === 0 && name === 'trigger') {
          next.no_of_bytes = bytes;
          repaired.push(next);
          return;
        }
        if (start < 1) start = nextPosition;
        next.no_of_bytes = bytes;
        next.byte_start_position = start;
        nextPosition = Math.max(nextPosition, start + bytes);
        repaired.push(next);
      });
      return repaired;
    }

    function ensureDeviceFrameWriteSlots(commands, meta) {
      meta = meta && typeof meta === 'object' && !Array.isArray(meta) ? meta : {};
      let commandId = meta.command_id || meta.commandId;
      let functionCode = meta.function_code || meta.functionCode;
      let actionId = meta.action_id || meta.actionId;
      if (!isEmptyFrameValue(commandId)) commandId = normalizeProtocolHex(commandId, 1) || commandId;
      if (!isEmptyFrameValue(functionCode)) functionCode = normalizeProtocolHex(functionCode, 1) || functionCode;
      if (!isEmptyFrameValue(actionId)) actionId = normalizeProtocolHex(actionId, 1) || actionId;
      const list = Array.isArray(commands) ? commands.slice() : [];
      const present = { commandid: false, functioncode: false, actionid: false, terminator: false };
      let nextPosition = 1;
      list.forEach(function(field) {
        const name = deviceFrameFieldName(field);
        if (Object.prototype.hasOwnProperty.call(present, name)) present[name] = true;
        const start = parseInt(field && field.byte_start_position, 10);
        let bytes = parseInt(field && field.no_of_bytes, 10);
        if (!Number.isFinite(bytes) || bytes < 1) bytes = 1;
        if (Number.isFinite(start) && start > 0) nextPosition = Math.max(nextPosition, start + bytes);
      });
      const inserts = [];
      if (!present.commandid && !isEmptyFrameValue(commandId)) {
        inserts.push(emptyDeviceFrameField('CommandId', 1, { value: commandId, asperui_value: commandId, type: 'Fixed Value', data_type: 'UnsignedInt' }));
      }
      if (!present.functioncode && !isEmptyFrameValue(functionCode)) {
        inserts.push(emptyDeviceFrameField('Function Code', 2, { value: functionCode, asperui_value: functionCode, type: 'Fixed Value', data_type: 'UnsignedInt' }));
      }
      if (!present.actionid && !isEmptyFrameValue(actionId)) {
        inserts.push(emptyDeviceFrameField('ActionId', 3, { value: actionId, asperui_value: actionId, type: 'Fixed Value', data_type: 'UnsignedInt' }));
      }
      let out = inserts.length ? inserts.concat(list) : list;
      // Rule 2: writable/Send frames always close with Terminator 0A.
      if (!present.terminator && meta.ensure_terminator === true) {
        out = out.concat([emptyDeviceFrameField('Terminator', nextPosition, { value: '0A', asperui_value: '0A', type: 'Fixed Value', data_type: 'UnsignedInt' })]);
      }
      return out;
    }

    function mergeDeviceFrameFieldLists(primary, secondary) {
      const byName = {};
      (Array.isArray(secondary) ? secondary : []).forEach(function(field, index) {
        if (!field || typeof field !== 'object') return;
        const name = deviceFrameFieldName(field);
        if (name) byName[name] = field;
        byName['#' + index] = field;
      });
      return (Array.isArray(primary) ? primary : []).map(function(field, index) {
        if (!field || typeof field !== 'object') return field;
        const other = byName[deviceFrameFieldName(field)] || byName['#' + index];
        if (!other) return field;
        const next = Object.assign({}, field);
        if (isEmptyFrameValue(next.value) && !isEmptyFrameValue(other.value)) next.value = other.value;
        if (isEmptyFrameValue(next.asperui_value) && !isEmptyFrameValue(other.asperui_value)) next.asperui_value = other.asperui_value;
        ['asperui', 'asperui_values', 'sno_asperui'].forEach(function(key) {
          if ((!Array.isArray(next[key]) || !next[key].length) && Array.isArray(other[key]) && other[key].length) {
            next[key] = other[key];
          }
        });
        return next;
      });
    }

    function mergeDeviceConfigPages(builtPages, livePages) {
      if (!livePages || typeof livePages !== 'object' || Array.isArray(livePages) || !Object.keys(livePages).length) {
        return builtPages;
      }
      if (!builtPages || typeof builtPages !== 'object' || !Object.keys(builtPages).length) {
        return livePages;
      }
      const builtByFrame = {};
      Object.keys(builtPages).forEach(function(pageName) {
        (builtPages[pageName] || []).forEach(function(item) {
          const name = String((item && item.frame && item.frame.name) || '').toLowerCase();
          if (name) builtByFrame[name] = item.frame;
        });
      });
      const out = {};
      Object.keys(livePages).forEach(function(pageName) {
        out[pageName] = (livePages[pageName] || []).map(function(item) {
          const frame = item && item.frame && typeof item.frame === 'object' ? item.frame : {};
          const built = builtByFrame[String(frame.name || '').toLowerCase()];
          if (!built) return item;
          return {
            frame: {
              name: frame.name || built.name,
              multiple_ui: Array.isArray(frame.multiple_ui) ? frame.multiple_ui : built.multiple_ui,
              trigger_ui: Array.isArray(frame.trigger_ui) ? frame.trigger_ui : built.trigger_ui,
              commands: hydrateDeviceFrameFields(mergeDeviceFrameFieldLists(frame.commands, built.commands)),
              response: hydrateDeviceFrameFields(mergeDeviceFrameFieldLists(frame.response, built.response)),
              error: hydrateDeviceFrameFields(mergeDeviceFrameFieldLists(frame.error, built.error))
            }
          };
        });
      });
      Object.keys(builtPages).forEach(function(pageName) {
        if (!out[pageName]) out[pageName] = builtPages[pageName];
      });
      return out;
    }

    function normalizeDeviceFrame(frame, parameterName, meta) {
      const name = String((frame && frame.name) || parameterName || 'frame');
      meta = meta && typeof meta === 'object' && !Array.isArray(meta) ? meta : {};
      if (frame && typeof frame === 'object' && !Array.isArray(frame) && Array.isArray(frame.commands) && frame.commands.length) {
        const access = String(meta.access || '').toLowerCase();
        const writableMeta = access === '' || access.indexOf('write') !== -1;
        const slotMeta = writableMeta ? Object.assign({}, meta, { ensure_terminator: true }) : meta;
        const commands = repairDeviceFrameBytePositions(
          ensureDeviceFrameWriteSlots(hydrateDeviceFrameFields(frame.commands, slotMeta), slotMeta)
        );
        const multipleUi = Array.isArray(frame.multiple_ui) ? frame.multiple_ui : ['false', 'false', 'false'];
        const bySource = frame.multiple_ui_by_source && typeof frame.multiple_ui_by_source === 'object'
          ? frame.multiple_ui_by_source
          : { command: multipleUi[0] || 'false', response: multipleUi[1] || 'false', error: multipleUi[2] || 'false' };
        return {
          name: name,
          multiple_ui: [bySource.command || multipleUi[0] || 'false', bySource.response || multipleUi[1] || 'false', bySource.error || multipleUi[2] || 'false'],
          multiple_ui_by_source: {
            command: bySource.command || multipleUi[0] || 'false',
            response: bySource.response || multipleUi[1] || 'false',
            error: bySource.error || multipleUi[2] || 'false'
          },
          trigger_ui: Array.isArray(frame.trigger_ui) ? frame.trigger_ui : ['false', 'false', 'false'],
          commands: commands,
          response: repairDeviceFrameBytePositions(hydrateDeviceFrameFields(Array.isArray(frame.response) ? frame.response : [], meta)),
          error: repairDeviceFrameBytePositions(hydrateDeviceFrameFields(Array.isArray(frame.error) ? frame.error : [], meta))
        };
      }
      return buildDeviceFrameFromMeta(name, Object.assign({}, meta, frame && typeof frame === 'object' ? { frame: frame } : {}));
    }

    function buildDeviceFrameFromMeta(parameterName, meta) {
      meta = meta && typeof meta === 'object' && !Array.isArray(meta) ? meta : {};
      if (meta.frame && typeof meta.frame === 'object' && !Array.isArray(meta.frame) && Array.isArray(meta.frame.commands) && meta.frame.commands.length) {
        return normalizeDeviceFrame(meta.frame, parameterName, meta);
      }

      const commands = [];
      commands.push(emptyDeviceFrameField('CommandId', 1, {
        value: meta.command_id || meta.commandId || ''
      }));
      commands.push(emptyDeviceFrameField('Function Code', 2, {
        value: meta.function_code || meta.functionCode || ''
      }));
      let bytePos = 3;
      if (meta.action_id || meta.actionId) {
        commands.push(emptyDeviceFrameField('ActionId', bytePos, {
          value: meta.action_id || meta.actionId
        }));
        bytePos += 1;
      }

      const access = String(meta.access || 'Read/Write');
      const uiType = meta.ui_type || 'Text';
      const isTrigger = String(uiType).toLowerCase().indexOf('trigger') !== -1 || String(uiType).toLowerCase() === 'button';
      commands.push({
        default_name: 'Data',
        asperui_value: meta.default != null && meta.default !== '' ? meta.default : parameterName,
        value: meta.default != null && meta.default !== '' ? meta.default : parameterName,
        Field_description: isTrigger ? 'Trigger' : 'Data',
        type: 'Fixed Value',
        data_type: 'UnsignedInt',
        no_of_bytes: 1,
        byte_start_position: isTrigger ? 0 : bytePos,
        ui_type: uiType,
        local_control: 'enable',
        ui_ids: 0,
        asperui: Array.isArray(meta.items) ? meta.items : [],
        sno_asperui: Array.isArray(meta.sno_asperui) ? meta.sno_asperui : [],
        asperui_values: Array.isArray(meta.item_values) ? meta.item_values : [],
        ui_description: access,
        slider_step_value: meta.step != null ? meta.step : '',
        display_value: {
          min: meta.minimum != null ? String(meta.minimum) : '',
          max: meta.maximum != null ? String(meta.maximum) : ''
        }
      });
      if (!isTrigger) {
        commands.push(emptyDeviceFrameField('Terminator', bytePos + 1, { value: '' }));
      }

      const multipleUi = Array.isArray(meta.multiple_ui) ? meta.multiple_ui : ['false', 'false', 'false'];
      return {
        name: parameterName,
        multiple_ui: multipleUi,
        multiple_ui_by_source: meta.multiple_ui_by_source && typeof meta.multiple_ui_by_source === 'object'
          ? meta.multiple_ui_by_source
          : { command: multipleUi[0] || 'false', response: multipleUi[1] || 'false', error: multipleUi[2] || 'false' },
        trigger_ui: Array.isArray(meta.trigger_ui) ? meta.trigger_ui : [isTrigger ? 'true' : 'false', 'false', 'false'],
        commands: commands,
        response: [noneDeviceFrameField()],
        error: [noneDeviceFrameField()]
      };
    }

    function buildDeviceConfigFromControls(controls) {
      const pages = {};
      let primary = null;
      const liveConfig = (deviceUiInfo && deviceUiInfo.deviceConfig && typeof deviceUiInfo.deviceConfig === 'object')
        ? deviceUiInfo.deviceConfig
        : {};
      const liveDevice = (liveConfig.devices && liveConfig.devices[0] && typeof liveConfig.devices[0] === 'object')
        ? liveConfig.devices[0]
        : {};
      const liveInfo = Object.assign({}, liveConfig.info || {}, (deviceUiInfo && deviceUiInfo.info) || {});
      const resolvedNodeId = getStudioNodeId()
        || (liveConfig.node_id)
        || (deviceUiInfo && deviceUiInfo.nodes)
        || '';
      const infoSource = liveInfo;
      const seenFrames = {};

      const addFrame = function(pageName, frame, parameterName) {
        const key = String(pageName || '') + '::' + String((frame && frame.name) || parameterName || '').toLowerCase();
        if (seenFrames[key]) return;
        seenFrames[key] = true;
        if (!pages[pageName]) pages[pageName] = [];
        pages[pageName].push({ frame: frame });
        if (!primary && String(parameterName || frame.name || '').toLowerCase() === 'power') {
          primary = frame.name || parameterName;
        }
      };

      (Array.isArray(pageData) ? pageData : []).forEach(function(page) {
        const pageName = String(page.page_name || ('Page' + (page.page_no || '1') + '.Operation'));
        (page.params || []).forEach(function(param) {
          const parameterName = String(param.parameter || '').trim();
          if (!parameterName) return;
          const api = param.api && typeof param.api === 'object' ? param.api : {};
          const frame = normalizeDeviceFrame(api.frame || null, parameterName, api);
          addFrame(pageName, frame, parameterName);
        });
      });

      (controls || []).forEach(function(control) {
        if (!control) return;
        const parameterName = String(control.parameterName || control.parameter || control.label || '').trim();
        if (!parameterName) return;
        const pageName = String(control.pageName || ('Page' + (control.pageNo || '1') + '.Operation'));
        const frame = control.deviceFrame
          ? normalizeDeviceFrame(control.deviceFrame, parameterName, control.protocolMeta || {})
          : buildDeviceFrameFromMeta(parameterName, control.protocolMeta || {});
        addFrame(pageName, frame, parameterName);
      });

      if (!primary) {
        const firstPage = Object.keys(pages)[0];
        if (firstPage && pages[firstPage][0] && pages[firstPage][0].frame) {
          primary = pages[firstPage][0].frame.name;
        }
      }
      const pageCount = Object.keys(pages).length;
      const livePages = (liveDevice.pages && typeof liveDevice.pages === 'object' && Object.keys(liveDevice.pages).length)
        ? mergeDeviceConfigPages(pages, liveDevice.pages)
        : pages;
      const productName = liveDevice.name || infoSource.name || modelNo || '';
      const liveMac = (function() {
        const attrs = Array.isArray(liveDevice.attributes) ? liveDevice.attributes : [];
        for (let i = 0; i < attrs.length; i++) {
          if (String((attrs[i] && attrs[i].name) || '').toLowerCase() === 'mac') {
            return attrs[i].value || '';
          }
        }
        return '';
      })();
      const deviceAttributes = [
        { name: 'Device Id', value: resolvedNodeId }
      ];
      if (liveMac) {
        deviceAttributes.push({ name: 'mac', value: liveMac });
      }
      const rootAttributes = (Array.isArray(liveConfig.attributes) && liveConfig.attributes.length)
        ? liveConfig.attributes
        : [
            { name: 'serial_num', value: '1345' },
            { name: 'model', value: 'wifi' }
          ];
      const info = {
        fw_version: infoSource.fw_version || '1.5.1',
        model: infoSource.model || modelNo || '',
        name: productName,
        type: infoSource.type || 'IOT',
        product_type: infoSource.product_type || 'IOT',
        SSID: infoSource.SSID || null,
        Access_Point: infoSource.Access_Point || null,
        Guarantee_Card: infoSource.Guarantee_Card || null,
        Video: infoSource.Video || null,
        Need_Help: infoSource.Need_Help || liveDevice.Need_Help || null,
        chat_status: (infoSource.chat_status != null) ? infoSource.chat_status : null,
        Auto_Test: infoSource.Auto_Test || null
      };
      if (infoSource.SIM_Activation_Request) {
        info.SIM_Activation_Request = infoSource.SIM_Activation_Request;
      }
      const mainDevice = {
        name: liveDevice.name || productName || modelNo || 'device',
        total_pages: (liveDevice.total_pages != null) ? liveDevice.total_pages : (pageCount > 0 ? pageCount : null),
        attributes: deviceAttributes,
        'Device Id': resolvedNodeId,
        pages: livePages,
        primary: liveDevice.primary || primary || 'power',
        type: liveDevice.type || 'efactor.device.',
        brand_logo: liveDevice.brand_logo || null,
        brand_logo_dark: liveDevice.brand_logo_dark || null,
        Need_Help: liveDevice.Need_Help || info.Need_Help || null,
        chat_status: (liveDevice.chat_status != null) ? liveDevice.chat_status : null,
        device_image: liveDevice.device_image || null,
        device_p2p_control: (liveDevice.device_p2p_control != null) ? liveDevice.device_p2p_control : null,
        'Device Communication': (liveDevice['Device Communication'] != null) ? liveDevice['Device Communication'] : null,
        Status: (liveDevice.Status != null) ? liveDevice.Status : null
      };
      const devices = [mainDevice];
      (Array.isArray(liveConfig.devices) ? liveConfig.devices.slice(1) : []).forEach(function(child) {
        if (!child || typeof child !== 'object') return;
        const next = Object.assign({}, child);
        next.pages = pages;
        next.total_pages = mainDevice.total_pages;
        devices.push(next);
      });
      return {
        attributes: rootAttributes,
        config_version: liveConfig.config_version || '2020-03-20',
        devices: devices,
        info: info,
        node_id: resolvedNodeId
      };
    }

    function buildStacEvent(eventName, binding) {
      return {
        event: eventName,
        action: { type: 'update', binding: binding }
      };
    }

    function buildStacWidgetTree(widgetType, binding, props, events) {
      return {
        type: widgetType,
        properties: {
          binding: binding,
          props: props || {},
          events: events || [buildStacEvent('onChanged', binding)]
        }
      };
    }

    const POWER_GAUGE_ARC_START = 150;
    const POWER_GAUGE_ARC_SWEEP = 240;
    const NEEDLE_GAUGE_VIEW_WIDTH = 240;
    const NEEDLE_GAUGE_VIEW_HEIGHT = 208;
    const NEEDLE_GAUGE_PIVOT_Y = 132;
    const NEEDLE_GAUGE_RADIUS = 74;

    function computeGaugeViewBox(cx, cy, r, strokeW) {
      const pad = 8;
      const start = POWER_GAUGE_ARC_START;
      const end = POWER_GAUGE_ARC_START + POWER_GAUGE_ARC_SWEEP;
      let minX = cx - r - strokeW - pad;
      let maxX = cx + r + strokeW + pad;
      let minY = 18;
      let maxY = cy + r + strokeW + pad;
      for (let deg = start; deg <= end; deg += 2) {
        const point = polarGaugePoint(cx, cy, r, deg);
        minX = Math.min(minX, point.x - strokeW - pad);
        maxX = Math.max(maxX, point.x + strokeW + pad);
        minY = Math.min(minY, point.y - strokeW - pad);
        maxY = Math.max(maxY, point.y + strokeW + pad);
      }
      const pivotPad = 14;
      minX = Math.min(minX, cx - pivotPad);
      maxX = Math.max(maxX, cx + pivotPad);
      maxY = Math.max(maxY, cy + pivotPad);
      const width = maxX - minX;
      const height = maxY - minY;
      return {
        minX: minX,
        minY: minY,
        width: width,
        height: height,
        attr: minX.toFixed(1) + ' ' + minY.toFixed(1) + ' ' + width.toFixed(1) + ' ' + height.toFixed(1)
      };
    }

    function isGaugeComponentType(type) {
      return type === 'powerGauge' || type === 'needleGauge';
    }

    function resolveGaugeNumericBounds(meta, valueText) {
      const minRaw = meta.minimum === null || typeof meta.minimum === 'undefined' || meta.minimum === '' ? 0 : parseFloat(meta.minimum);
      const maxRaw = meta.maximum === null || typeof meta.maximum === 'undefined' || meta.maximum === '' ? 100 : parseFloat(meta.maximum);
      const stepRaw = meta.step === null || typeof meta.step === 'undefined' || meta.step === '' ? 1 : parseFloat(meta.step);
      const safeMin = Number.isFinite(minRaw) ? minRaw : 0;
      const safeMax = Number.isFinite(maxRaw) && maxRaw > safeMin ? maxRaw : 100;
      const safeStep = Number.isFinite(stepRaw) && stepRaw > 0 ? stepRaw : 1;
      const defaultRaw = meta.default !== '' && meta.default != null ? parseFloat(String(meta.default).replace(/[^\d.-]/g, '')) : safeMin;
      const parsed = valueText !== '' && valueText != null
        ? parseFloat(String(valueText).replace(/[^\d.-]/g, ''))
        : defaultRaw;
      const safeValue = Number.isFinite(parsed) ? Math.max(safeMin, Math.min(safeMax, parsed)) : safeMin;
      return { min: safeMin, max: safeMax, step: safeStep, value: safeValue };
    }

    function snapGaugeValue(value, min, max, step) {
      const clamped = Math.max(min, Math.min(max, value));
      if (!step || step <= 0) return clamped;
      const steps = Math.round((clamped - min) / step);
      const snapped = min + steps * step;
      const stepDecimals = (String(step).split('.')[1] || '').length;
      return stepDecimals > 0 ? parseFloat(snapped.toFixed(stepDecimals)) : snapped;
    }

    function gaugePivotScreenPoint(svg) {
      const rect = svg.getBoundingClientRect();
      const cx = NEEDLE_GAUGE_VIEW_WIDTH / 2;
      const cy = NEEDLE_GAUGE_PIVOT_Y;
      const viewBox = computeGaugeViewBox(cx, cy, NEEDLE_GAUGE_RADIUS, 14);
      const pivotXRatio = (cx - viewBox.minX) / viewBox.width;
      const pivotYRatio = (cy - viewBox.minY) / viewBox.height;
      return {
        x: rect.left + rect.width * pivotXRatio,
        y: rect.top + rect.height * pivotYRatio
      };
    }

    function gaugeAngleFromPointer(clientX, clientY, svg) {
      const pivot = gaugePivotScreenPoint(svg);
      const angleRad = Math.atan2(clientY - pivot.y, clientX - pivot.x);
      let angleDeg = (angleRad * 180 / Math.PI) + 90;
      while (angleDeg < 0) angleDeg += 360;
      while (angleDeg >= 360) angleDeg -= 360;

      const arcStart = POWER_GAUGE_ARC_START;
      const arcEnd = (arcStart + POWER_GAUGE_ARC_SWEEP) % 360;
      let delta;

      if (angleDeg >= arcStart || angleDeg <= arcEnd) {
        delta = angleDeg >= arcStart ? (angleDeg - arcStart) : ((360 - arcStart) + angleDeg);
      } else {
        const distToEnd = angleDeg - arcEnd;
        const distToStart = arcStart - angleDeg;
        delta = distToEnd <= distToStart ? POWER_GAUGE_ARC_SWEEP : 0;
      }

      return Math.max(0, Math.min(1, delta / POWER_GAUGE_ARC_SWEEP));
    }

    function gaugeValueToAngle(value, min, max) {
      const ratio = max > min ? (value - min) / (max - min) : 0;
      return POWER_GAUGE_ARC_START + ratio * POWER_GAUGE_ARC_SWEEP;
    }

    function gaugePointerToValue(clientX, clientY, svg, min, max, step, shouldSnap) {
      const ratio = gaugeAngleFromPointer(clientX, clientY, svg);
      const raw = min + ratio * (max - min);
      const clamped = Math.max(min, Math.min(max, raw));
      if (shouldSnap === false) return clamped;
      return snapGaugeValue(clamped, min, max, step);
    }

    function ensureGaugeVisualUid(wrap) {
      if (!wrap.dataset.gaugeUid) {
        wrap.dataset.gaugeUid = 'g' + Math.random().toString(36).slice(2, 10);
      }
      return wrap.dataset.gaugeUid;
    }

    function polarGaugePoint(cx, cy, r, angleDeg) {
      const rad = (angleDeg - 90) * Math.PI / 180;
      return { x: cx + r * Math.cos(rad), y: cy + r * Math.sin(rad) };
    }

    function gaugeArcPath(cx, cy, r, startDeg, endDeg) {
      const start = polarGaugePoint(cx, cy, r, endDeg);
      const end = polarGaugePoint(cx, cy, r, startDeg);
      const large = (endDeg - startDeg) > 180 ? 1 : 0;
      return 'M ' + start.x.toFixed(2) + ' ' + start.y.toFixed(2) + ' A ' + r + ' ' + r + ' 0 ' + large + ' 0 ' + end.x.toFixed(2) + ' ' + end.y.toFixed(2);
    }

    function buildAnimatedRadialGaugeProps(bounds, themeOptions) {
      const opts = themeOptions || {};
      const activeColor = opts.activeColor || currentTheme.accentColor || '#7C3AED';
      const inactiveColor = opts.inactiveColor || '#D9DEEB';
      const needleColor = opts.needleColor || '#0F2550';
      const range = bounds.max - bounds.min;
      const zoneAt = function(ratio) { return bounds.min + range * ratio; };
      return {
        radius: 92,
        width: 220,
        height: 172,
        duration: 450,
        curve: 'Curves.easeOutCubic',
        value: bounds.value,
        min: bounds.min,
        max: bounds.max,
        step: bounds.step,
        sweepDegrees: POWER_GAUGE_ARC_SWEEP,
        useLiveBinding: true,
        sendOnChange: true,
        package: 'gauges',
        axis: {
          min: bounds.min,
          max: bounds.max,
          sweepDegrees: POWER_GAUGE_ARC_SWEEP,
          pointer: {
            type: 'GaugePointer.triangle',
            width: 16,
            height: 28,
            borderRadius: 3,
            color: needleColor,
            position: { type: 'GaugePointerPosition.surface', offset: { dx: 0, dy: 2 } },
            border: { color: '#FFFFFF', width: 2.5 }
          },
          style: {
            thickness: 14,
            zoneSpacing: 8,
            blendColors: false,
            cornerRadius: { radius: 8 }
          },
          zones: [
            { from: bounds.min, to: zoneAt(0.55), color: activeColor, cornerRadius: { radius: 8 } },
            { from: zoneAt(0.55), to: zoneAt(0.65), color: activeColor, cornerRadius: { radius: 8 } },
            { from: zoneAt(0.65), to: zoneAt(0.85), color: inactiveColor, cornerRadius: { radius: 8 } },
            { from: zoneAt(0.85), to: bounds.max, color: inactiveColor, cornerRadius: { radius: 8 } }
          ]
        },
        builder: {
          type: 'RadialGaugeLabel',
          style: { color: needleColor, fontSize: 20, fontWeight: 'bold' },
          value: 'value'
        },
        geometry: buildGaugeGeometryProps(bounds, opts.type || 'needleGauge'),
        alignment: 'center',
        opening: { startAngle: POWER_GAUGE_ARC_START, sweepAngle: POWER_GAUGE_ARC_SWEEP },
        needleStructure: buildGaugeGeometryProps(bounds, opts.type || 'needleGauge').needle
      };
    }

    const HUE_ARC_SEGMENTS = 48;

    /* hsl() is fine for the SVG, but the schema has to ship hex so the app does
       not need a colour parser. */
    function hueStopColor(hue) {
      const s = 0.85;
      const l = 0.55;
      const c = (1 - Math.abs(2 * l - 1)) * s;
      const hp = ((hue % 360) + 360) % 360 / 60;
      const x = c * (1 - Math.abs((hp % 2) - 1));
      let r = 0;
      let g = 0;
      let b = 0;
      if (hp < 1) { r = c; g = x; }
      else if (hp < 2) { r = x; g = c; }
      else if (hp < 3) { g = c; b = x; }
      else if (hp < 4) { g = x; b = c; }
      else if (hp < 5) { r = x; b = c; }
      else { r = c; b = x; }
      const m = l - c / 2;
      const channel = function(v) {
        return ('0' + Math.round((v + m) * 255).toString(16)).slice(-2).toUpperCase();
      };
      return '#' + channel(r) + channel(g) + channel(b);
    }

    function buildHueGradientStops(steps) {
      const total = steps && steps > 1 ? steps : 12;
      const stops = [];
      for (let i = 0; i <= total; i++) {
        const position = i / total;
        stops.push({ position: Math.round(position * 1000) / 1000, color: hueStopColor(position * 360) });
      }
      return stops;
    }

    /* The rainbow is drawn as a run of short arcs rather than one gradient
       stroke, because SVG gradients are linear and cannot follow a curve. */
    function renderHueArcSegments(cx, cy, r, startDeg, sweepDeg, strokeW) {
      let out = '';
      for (let i = 0; i < HUE_ARC_SEGMENTS; i++) {
        const a0 = startDeg + (i / HUE_ARC_SEGMENTS) * sweepDeg;
        // Overlap each segment slightly so the joins do not show as hairlines.
        const a1 = startDeg + ((i + 1) / HUE_ARC_SEGMENTS) * sweepDeg + 0.8;
        const hue = Math.round((i / HUE_ARC_SEGMENTS) * 360);
        out += '<path d="' + gaugeArcPath(cx, cy, r, a0, a1) + '" fill="none" stroke="hsl(' + hue + ',85%,55%)" stroke-width="' + strokeW + '" stroke-linecap="butt"/>';
      }
      return out;
    }

    function renderHueCircleSvg(bounds, uid) {
      const cx = NEEDLE_GAUGE_VIEW_WIDTH / 2;
      const cy = NEEDLE_GAUGE_PIVOT_Y;
      const r = NEEDLE_GAUGE_RADIUS;
      const strokeW = 14;
      const viewBox = computeGaugeViewBox(cx, cy, r, strokeW);
      const start = POWER_GAUGE_ARC_START;
      const end = start + POWER_GAUGE_ARC_SWEEP;
      const ratio = bounds.max > bounds.min ? (bounds.value - bounds.min) / (bounds.max - bounds.min) : 0;
      const progressAngle = start + ratio * POWER_GAUGE_ARC_SWEEP;
      const hue = Math.round(ratio * 360);
      const hueColor = 'hsl(' + hue + ',85%,55%)';
      const knob = polarGaugePoint(cx, cy, r, progressAngle);
      return '<svg class="pointer-gauge-svg power-gauge-svg is-hue-circle" viewBox="' + viewBox.attr + '" preserveAspectRatio="xMidYMid meet" role="img" aria-label="Hue ' + hue + ' degrees">' +
        '<path d="' + gaugeArcPath(cx, cy, r, start, end) + '" fill="none" stroke="#E2E8F0" stroke-width="' + strokeW + '" stroke-linecap="round"/>' +
        renderHueArcSegments(cx, cy, r, start, POWER_GAUGE_ARC_SWEEP, strokeW) +
        '<circle cx="' + cx + '" cy="' + cy + '" r="13" fill="' + hueColor + '" stroke="#FFFFFF" stroke-width="3"/>' +
        '<circle cx="' + knob.x.toFixed(1) + '" cy="' + knob.y.toFixed(1) + '" r="9" fill="' + hueColor + '" stroke="#FFFFFF" stroke-width="3.5"/>' +
        '<text x="' + cx + '" y="' + Math.max(24, viewBox.minY + 16).toFixed(1) + '" text-anchor="middle" font-family="Inter,Segoe UI,sans-serif" font-size="10" font-weight="700" fill="#64748B" letter-spacing=".08em">HUE</text>' +
      '</svg>';
    }

    function renderPointerGaugeSvg(bounds, uid) {
      const cx = NEEDLE_GAUGE_VIEW_WIDTH / 2;
      const cy = NEEDLE_GAUGE_PIVOT_Y;
      const r = NEEDLE_GAUGE_RADIUS;
      const strokeW = 14;
      const viewBox = computeGaugeViewBox(cx, cy, r, strokeW);
      const activeColor = currentTheme.accentColor || '#2563EB';
      const inactiveColor = '#E2E8F0';
      const gradId = 'gaugePointerGrad-' + (uid || '0');
      const start = POWER_GAUGE_ARC_START;
      const end = start + POWER_GAUGE_ARC_SWEEP;
      const ratio = bounds.max > bounds.min ? (bounds.value - bounds.min) / (bounds.max - bounds.min) : 0;
      const progressAngle = start + ratio * POWER_GAUGE_ARC_SWEEP;
      const tip = polarGaugePoint(cx, cy, r - 18, progressAngle);
      const left = polarGaugePoint(cx, cy, 12, progressAngle - 90);
      const right = polarGaugePoint(cx, cy, 12, progressAngle + 90);
      const progressArc = ratio > 0.001
        ? '<path d="' + gaugeArcPath(cx, cy, r, start, progressAngle) + '" fill="none" stroke="url(#' + gradId + ')" stroke-width="' + strokeW + '" stroke-linecap="round"/>'
        : '';
      return '<svg class="pointer-gauge-svg power-gauge-svg" viewBox="' + viewBox.attr + '" preserveAspectRatio="xMidYMid meet" role="img" aria-label="Pointer gauge ' + bounds.value + '">' +
        '<defs><linearGradient id="' + gradId + '" x1="0%" y1="0%" x2="100%" y2="0%"><stop offset="0%" stop-color="' + activeColor + '" stop-opacity=".78"/><stop offset="100%" stop-color="' + activeColor + '"/></linearGradient></defs>' +
        '<path d="' + gaugeArcPath(cx, cy, r, start, end) + '" fill="none" stroke="' + inactiveColor + '" stroke-width="' + strokeW + '" stroke-linecap="round"/>' +
        progressArc +
        '<circle cx="' + cx + '" cy="' + cy + '" r="11" fill="#FFFFFF" stroke="' + inactiveColor + '" stroke-width="3"/>' +
        '<polygon points="' + tip.x.toFixed(1) + ',' + tip.y.toFixed(1) + ' ' + left.x.toFixed(1) + ',' + left.y.toFixed(1) + ' ' + right.x.toFixed(1) + ',' + right.y.toFixed(1) + '" fill="' + activeColor + '" stroke="#FFFFFF" stroke-width="2" stroke-linejoin="round"/>' +
        '<text x="' + cx + '" y="' + Math.max(24, viewBox.minY + 16).toFixed(1) + '" text-anchor="middle" font-family="Inter,Segoe UI,sans-serif" font-size="10" font-weight="700" fill="#64748B" letter-spacing=".08em">LEVEL</text>' +
      '</svg>';
    }

    function renderNeedleGaugeSvg(bounds, uid) {
      const cx = NEEDLE_GAUGE_VIEW_WIDTH / 2;
      const cy = NEEDLE_GAUGE_PIVOT_Y;
      const r = NEEDLE_GAUGE_RADIUS;
      const strokeW = 14;
      const viewBox = computeGaugeViewBox(cx, cy, r, strokeW);
      const activeColor = currentTheme.accentColor || '#10B981';
      const inactiveColor = '#E2E8F0';
      const needleColor = '#0F2550';
      const gradId = 'gaugeProgressGrad-' + (uid || '0');
      const start = POWER_GAUGE_ARC_START;
      const end = start + POWER_GAUGE_ARC_SWEEP;
      const ratio = bounds.max > bounds.min ? (bounds.value - bounds.min) / (bounds.max - bounds.min) : 0;
      const progressAngle = start + ratio * POWER_GAUGE_ARC_SWEEP;
      const needleTip = polarGaugePoint(cx, cy, r - 12, progressAngle);
      const progressArc = ratio > 0.001
        ? '<path d="' + gaugeArcPath(cx, cy, r, start, progressAngle) + '" fill="none" stroke="url(#' + gradId + ')" stroke-width="' + strokeW + '" stroke-linecap="round"/>'
        : '';
      return '<svg class="needle-gauge-svg power-gauge-svg" viewBox="' + viewBox.attr + '" preserveAspectRatio="xMidYMid meet" role="img" aria-label="Gauge ' + bounds.value + '">' +
        '<defs><linearGradient id="' + gradId + '" x1="0%" y1="0%" x2="100%" y2="0%"><stop offset="0%" stop-color="' + activeColor + '" stop-opacity=".72"/><stop offset="100%" stop-color="' + activeColor + '"/></linearGradient></defs>' +
        '<path d="' + gaugeArcPath(cx, cy, r, start, end) + '" fill="none" stroke="' + inactiveColor + '" stroke-width="' + strokeW + '" stroke-linecap="round"/>' +
        progressArc +
        '<circle cx="' + cx + '" cy="' + cy + '" r="10" fill="#FFFFFF" stroke="' + inactiveColor + '" stroke-width="3"/>' +
        '<circle cx="' + cx + '" cy="' + cy + '" r="5.5" fill="' + needleColor + '"/>' +
        '<line x1="' + cx + '" y1="' + cy + '" x2="' + needleTip.x.toFixed(1) + '" y2="' + needleTip.y.toFixed(1) + '" stroke="' + needleColor + '" stroke-width="3.5" stroke-linecap="round"/>' +
        '<circle cx="' + needleTip.x.toFixed(1) + '" cy="' + needleTip.y.toFixed(1) + '" r="4" fill="' + activeColor + '" stroke="#FFFFFF" stroke-width="1.5"/>' +
        '<text x="' + cx + '" y="' + Math.max(24, viewBox.minY + 16).toFixed(1) + '" text-anchor="middle" font-family="Poppins,Segoe UI,sans-serif" font-size="10" font-weight="800" fill="#64748B" letter-spacing=".08em">LEVEL</text>' +
      '</svg>';
    }

    function formatGaugeDisplayValue(value, bounds, isDragging) {
      if (isDragging) {
        const decimals = bounds.max - bounds.min <= 10 ? 1 : 0;
        return decimals ? (Math.round(value * 10) / 10) : Math.round(value);
      }
      return snapGaugeValue(value, bounds.min, bounds.max, bounds.step);
    }

    function updatePowerGaugeVisual(wrap, bounds, card, options) {
      if (!wrap) return;
      const opts = options || {};
      const uid = ensureGaugeVisualUid(wrap);
      const displayValue = formatGaugeDisplayValue(bounds.value, bounds, Boolean(opts.isDragging));
      wrap.dataset.value = String(bounds.value);
      wrap.dataset.min = String(bounds.min);
      wrap.dataset.max = String(bounds.max);
      wrap.dataset.step = String(bounds.step);
      const svgHost = wrap.querySelector('.power-gauge-svg-host');
      if (svgHost) svgHost.innerHTML = wrap.dataset.gaugeVariant === 'hue'
        ? renderHueCircleSvg(bounds, uid)
        : (wrap.classList.contains('pointer-gauge-visual')
          ? renderPointerGaugeSvg(bounds, uid)
          : renderNeedleGaugeSvg(bounds, uid));
      const label = wrap.querySelector('.power-gauge-value');
      if (label) label.innerHTML = '<strong>' + displayValue + '</strong> / ' + bounds.max;
      const gaugeInput = wrap.querySelector('.power-gauge-input');
      if (gaugeInput) gaugeInput.value = String(displayValue);
      const valueEl = card ? card.querySelector('.field-value') : null;
      if (valueEl && !valueEl.querySelector('input, select, textarea')) {
        valueEl.textContent = String(displayValue);
      }
      const metaValue = card ? card.querySelector('.meta-value') : null;
      if (metaValue) metaValue.textContent = String(displayValue);
    }

    function bindPowerGaugeInteractions(wrap, card) {
      if (!wrap || wrap.dataset.bound === '1') return;
      wrap.dataset.bound = '1';
      let dragging = false;
      let lastPointer = { x: 0, y: 0 };
      ensureGaugeVisualUid(wrap);

      const applyPointer = function(clientX, clientY, commit) {
        lastPointer.x = clientX;
        lastPointer.y = clientY;
        const svg = wrap.querySelector('.power-gauge-svg');
        if (!svg || !card) return;
        const meta = getEffectiveParamMeta(card);
        const bounds = resolveGaugeNumericBounds(meta, wrap.dataset.value || '');
        bounds.value = gaugePointerToValue(clientX, clientY, svg, bounds.min, bounds.max, bounds.step, commit);
        updatePowerGaugeVisual(wrap, bounds, card, { isDragging: !commit });
        if (commit) {
          const override = getComponentOverride(card.dataset.paramKey);
          override.value = String(bounds.value);
          generateSchema();
        }
      };

      wrap.addEventListener('pointerdown', function(event) {
        if (!event.target.closest('.power-gauge-svg')) return;
        dragging = true;
        wrap.setPointerCapture(event.pointerId);
        applyPointer(event.clientX, event.clientY, false);
        event.preventDefault();
      });
      wrap.addEventListener('pointermove', function(event) {
        if (!dragging) return;
        applyPointer(event.clientX, event.clientY, false);
        event.preventDefault();
      });
      wrap.addEventListener('pointerup', function(event) {
        if (!dragging) return;
        dragging = false;
        applyPointer(event.clientX, event.clientY, true);
        try { wrap.releasePointerCapture(event.pointerId); } catch (error) {}
      });
      wrap.addEventListener('pointercancel', function() {
        if (!dragging) return;
        dragging = false;
        applyPointer(lastPointer.x, lastPointer.y, true);
      });
    }

    function buildNeedleGaugeVisualElement(card, meta, override) {
      const valueEl = card.querySelector('.field-value');
      const resolvedOverride = override || getComponentOverride(card.dataset.paramKey);
      const rawValue = resolvedOverride.value || (valueEl ? valueEl.textContent.trim() : '');
      const bounds = resolveGaugeNumericBounds(meta, rawValue);
      const wrap = document.createElement('div');
      wrap.className = 'needle-gauge-visual power-gauge-visual param-component';
      wrap.innerHTML =
        '<div class="power-gauge-svg-host">' + renderNeedleGaugeSvg(bounds, ensureGaugeVisualUid(wrap)) + '</div>' +
        '<span class="needle-gauge-value power-gauge-value"><strong>' + bounds.value + '</strong> / ' + bounds.max + '</span>' +
        '<input type="hidden" class="power-gauge-input" value="' + bounds.value + '">';
      wrap.dataset.value = String(bounds.value);
      bindPowerGaugeInteractions(wrap, card);
      return wrap;
    }

    function buildPointerGaugeVisualElement(card, meta, override, componentType) {
      const valueEl = card.querySelector('.field-value');
      const resolvedOverride = override || getComponentOverride(card.dataset.paramKey);
      const rawValue = resolvedOverride.value || (valueEl ? valueEl.textContent.trim() : '');
      const bounds = resolveGaugeNumericBounds(meta, rawValue);
      const isHue = componentType === 'hueCircle';
      const wrap = document.createElement('div');
      wrap.className = 'pointer-gauge-visual power-gauge-visual param-component' + (isHue ? ' is-hue-circle' : '');
      // The variant is stored on the node so redraws can pick the same renderer
      // without needing the component type threaded through again.
      if (isHue) wrap.dataset.gaugeVariant = 'hue';
      const uid = ensureGaugeVisualUid(wrap);
      wrap.innerHTML =
        '<div class="power-gauge-svg-host">' + (isHue ? renderHueCircleSvg(bounds, uid) : renderPointerGaugeSvg(bounds, uid)) + '</div>' +
        '<span class="needle-gauge-value power-gauge-value"><strong>' + bounds.value + '</strong> / ' + bounds.max + '</span>' +
        '<input type="hidden" class="power-gauge-input" value="' + bounds.value + '">';
      wrap.dataset.value = String(bounds.value);
      bindPowerGaugeInteractions(wrap, card);
      return wrap;
    }

    function buildPowerGaugeVisualElement(card, meta, override, componentType) {
      return buildPointerGaugeVisualElement(card, meta, override, componentType);
    }

    function getParamDisplayValue(card, componentType, override, valueText) {
      const valueEl = card.querySelector('.field-value');
      const fieldText = valueEl ? valueEl.textContent.trim() : '';
      if (override.value) return String(override.value);
      const renderType = resolveParameterRenderType(componentType);
      if (renderType === 'dropdown') {
        const select = card.querySelector('.param-dropdown');
        if (select) return String(select.value || '');
        return String(valueText || '');
      }
      if (renderType === 'switch') {
        return parseToggleInitialValue(valueText) ? 'ON' : 'OFF';
      }
      if (renderType === 'slider' || renderType === 'powerGauge') {
        return fieldText || String(valueText || '');
      }
      return fieldText || String(valueText || '');
    }

    function buildParameterCardStyle(card, override) {
      const colors = getEffectiveComponentColors(override);
      const grouped = !!(card && card.classList && card.classList.contains('is-grouped-component'));
      return {
        backgroundColor: grouped ? 'transparent' : colors.cardColor,
        borderColor: grouped ? 'transparent' : colors.borderColor,
        borderWidth: grouped ? 0 : parseInt(currentTheme.borderSize || 1, 10),
        borderRadius: grouped ? 0 : parseInt(currentTheme.borderRadius || 18, 10),
        padding: grouped ? 8 : parseInt(currentTheme.cardPadding || 16, 10),
        minHeight: grouped ? 44 : 66,
        leftAccent: {
          visible: true,
          width: 3,
          colorStart: currentTheme.secondaryColor,
          colorEnd: colors.accentColor
        },
        iconBubble: {
          size: 38,
          backgroundColor: 'rgba(37,99,235,0.14)',
          iconColor: colors.iconColor
        },
        fieldLabel: {
          fontFamily: currentTheme.fontFamily || 'Inter',
          fontSize: 11,
          fontWeight: 800,
          color: currentTheme.mutedTextColor,
          uppercase: true
        },
        fieldValue: {
          fontFamily: currentTheme.fontFamily || 'Inter',
          fontSize: 16,
          fontWeight: 700,
          color: colors.textColor
        }
      };
    }

    function buildAccessoryWidgetTree(componentType, card, override, meta, valueText, binding) {
      const colors = getEffectiveComponentColors(override);
      const trackColor = override.statusColor || currentTheme.toggleOffColor;
      const renderType = resolveParameterRenderType(componentType);
      const toggleColors = buildToggleAccessoryColors(override);
      const writable = protocolAccessIsWritable(meta);
      const switchEvents = writable ? [buildStacEvent('onChanged', binding)] : [];

      if (renderType === 'switch') {
        const isOn = parseToggleInitialValue(valueText);
        return {
          events: switchEvents,
          accessory: buildStacWidgetTree('Switch', binding, {
            activeColor: toggleColors.activeColor,
            inactiveColor: toggleColors.inactiveColor,
            activeTrackColor: toggleColors.activeTrackColor,
            activeThumbColor: toggleColors.activeThumbColor,
            inactiveTrackColor: toggleColors.inactiveTrackColor || trackColor,
            inactiveThumbColor: toggleColors.inactiveThumbColor,
            thumbBorderColor: toggleColors.thumbBorderColor,
            useLiveBinding: true,
            trueValues: ['ON', '1', 'true', 'yes'],
            falseValues: ['OFF', '0', 'false', 'no'],
            checked: isOn,
            readOnly: !writable,
            enabled: writable,
            interactive: writable
          }, switchEvents)
        };
      }

      if (renderType === 'slider') {
        const min = meta.minimum === null || typeof meta.minimum === 'undefined' || meta.minimum === '' ? 0 : parseFloat(meta.minimum);
        const max = meta.maximum === null || typeof meta.maximum === 'undefined' || meta.maximum === '' ? 255 : parseFloat(meta.maximum);
        const step = meta.step === null || typeof meta.step === 'undefined' || meta.step === '' ? 1 : parseFloat(meta.step);
        const safeMin = Number.isFinite(min) ? min : 0;
        const safeMax = Number.isFinite(max) ? max : 255;
        const safeStep = Number.isFinite(step) ? step : 1;
        const numericValue = valueText !== '' ? parseFloat(valueText) : (meta.default !== '' && meta.default != null ? parseFloat(meta.default) : safeMin);
        const initialValue = Number.isFinite(numericValue) ? numericValue : safeMin;
        const metaIcon = getParamMetaIcon(card);
        const metaValue = String(card.dataset.sequence || '1');
        const sliderEvents = buildRangeInteractionEvents(binding);
        const variantConfig = getSliderVariantConfig(componentType);
        const sliderVisual = buildSliderVisualSpec(componentType, override, meta, safeMin, safeMax, initialValue);
        const rangeSliderProps = {
            min: safeMin,
            max: safeMax,
            step: safeStep,
            useLiveBinding: true,
            showMinMaxLabels: true,
            activeColor: sliderVisual.activeTrackColor || colors.accentColor,
            inactiveColor: sliderVisual.inactiveTrackColor || '#D9DEEB',
            activeTrackColor: sliderVisual.activeTrackColor || colors.accentColor,
            inactiveTrackColor: sliderVisual.inactiveTrackColor || '#D9DEEB',
            thumbColor: sliderVisual.thumbColor || colors.accentColor,
            trackGradient: sliderVisual.trackGradient,
            variant: variantConfig.variant,
            visual: sliderVisual,
            trackMode: variantConfig.trackMode || 'fill',
            thumbFromHue: Boolean(variantConfig.thumbFromHue),
            valueSuffix: variantConfig.valueSuffix || null,
            kicker: sliderVisual.label,
            container: {
              visible: true,
              backgroundColor: '#F8FAFC',
              borderColor: 'transparent',
              borderWidth: 0,
              borderRadius: 16,
              padding: 14
            },
            trackHeight: 8,
            thumbRadius: 9,
            thumbBorderColor: '#FFFFFF',
            thumbBorderWidth: 2,
            labelColor: currentTheme.mutedTextColor,
            valueColor: colors.accentColor,
            rangeFontSize: sliderVisual.rangeFontSize,
            rangeFontWeight: 600,
            currentValueFontSize: 13,
            currentValueFontWeight: 600,
            kickerFontSize: sliderVisual.kickerFontSize,
            kickerFontWeight: sliderVisual.kickerFontWeight,
            showTickMarks: sliderVisual.showTickMarks
        };
        if (variantConfig.variant === 'timer') {
          Object.assign(rangeSliderProps, buildTimerSliderLabelStyleProps());
        }
        return {
          events: sliderEvents,
          accessory: buildStacWidgetTree('metaChip', binding, {
            icon: metaIcon,
            value: metaValue,
            label: String((card && card.dataset && card.dataset.paramName) || ''),
            text: String((card && card.dataset && card.dataset.paramName) || ''),
            title: String((card && card.dataset && card.dataset.paramName) || ''),
            backgroundColor: override.statusColor || 'rgba(37,99,235,0.12)',
            textColor: colors.accentColor,
            iconColor: colors.accentColor,
            readOnly: true
          }, []),
          rangeRow: buildStacWidgetTree('schemaSlider', binding, rangeSliderProps, sliderEvents)
        };
      }

      if (renderType === 'powerGauge' || renderType === 'needleGauge') {
        const bounds = resolveGaugeNumericBounds(meta, valueText);
        // The hue dial is painted from the spectrum rather than the theme accent,
        // so the schema ships the ramp the preview draws.
        const isHueCircle = componentType === 'hueCircle';
        const hueRatio = bounds.max > bounds.min ? (bounds.value - bounds.min) / (bounds.max - bounds.min) : 0;
        const gaugeProps = buildAnimatedRadialGaugeProps(bounds, {
          activeColor: isHueCircle ? hueStopColor(hueRatio * 360) : colors.accentColor,
          inactiveColor: '#D9DEEB',
          needleColor: isHueCircle ? hueStopColor(hueRatio * 360) : '#0F2550'
        });
        const gaugeEvents = buildRangeInteractionEvents(binding);
        const bundle = {
          events: gaugeEvents,
          accessory: buildStacWidgetTree('metaChip', binding, {
            icon: getParamMetaIcon(card),
            value: String(bounds.value),
            label: String((card && card.dataset && card.dataset.paramName) || ''),
            text: String((card && card.dataset && card.dataset.paramName) || ''),
            title: String((card && card.dataset && card.dataset.paramName) || ''),
            backgroundColor: override.statusColor || 'rgba(37,99,235,0.12)',
            textColor: colors.accentColor,
            iconColor: colors.accentColor,
            readOnly: true
          }, [])
        };
        const gaugeRowProps = Object.assign({}, gaugeProps, {
          useLiveBinding: true,
          variant: isHueCircle ? 'hue' : 'default',
          gradient: isHueCircle ? buildHueGradientStops(12) : null,
          trackMode: isHueCircle ? 'gradient' : 'fill',
          kicker: isHueCircle ? 'HUE' : 'LEVEL'
        });
        if (renderType === 'powerGauge') {
          bundle.gaugeRow = buildStacWidgetTree('AnimatedRadialGauge', binding, gaugeRowProps, gaugeEvents);
        } else {
          bundle.gaugeRow = buildStacWidgetTree('NeedleGauge', binding, gaugeRowProps, gaugeEvents);
        }
        return bundle;
      }

      if (renderType === 'linearGauge') {
        const bounds = resolveGaugeNumericBounds(meta, valueText);
        return {
          events: [],
          accessory: buildStacWidgetTree('metaChip', binding, {
            icon: getParamMetaIcon(card),
            valueBinding: binding,
            useLiveBinding: true,
            label: String((card && card.dataset && card.dataset.paramName) || ''),
            text: String((card && card.dataset && card.dataset.paramName) || ''),
            title: String((card && card.dataset && card.dataset.paramName) || ''),
            backgroundColor: override.statusColor || 'rgba(37,99,235,0.12)',
            textColor: colors.accentColor,
            iconColor: colors.accentColor,
            readOnly: true
          }, []),
          gaugeRow: buildStacWidgetTree('LinearGauge', binding, {
            minimum: bounds.min,
            maximum: bounds.max,
            valueBinding: binding,
            unit: '%',
            activeColor: colors.accentColor,
            inactiveColor: '#D9DEEB',
            showLabel: true,
            useLiveBinding: true
          }, [])
        };
      }

      if (renderType === 'elevatedButton') {
        return {
          events: [{ event: 'onTap', action: { type: 'send', binding: binding } }],
          accessory: buildStacWidgetTree('ElevatedButton', binding, {
            labelBinding: binding,
            backgroundColor: colors.accentColor,
            textColor: '#FFFFFF',
            useLiveBinding: true
          }, [{ event: 'onTap', action: { type: 'send', binding: binding } }])
        };
      }

      if (renderType === 'button') {
        const dotColor = override.statusColor || colors.accentColor;
        const catalogEntry = getParameterCatalogEntry(componentType);
        return {
          events: [buildStacEvent('onTap', binding)],
          accessory: buildStacWidgetTree('PowerButton', binding, {
            color: dotColor,
            borderColor: dotColor,
            size: catalogEntry && catalogEntry.pushButton ? 44 : 36,
            borderWidth: 3,
            shape: 'circle',
            useLiveBinding: true
          }, [buildStacEvent('onTap', binding)])
        };
      }

      if (renderType === 'dropdown') {
        const options = parseOptionPairs(meta, card && card.dataset.paramName);
        const selected = resolveDropdownSelectedValue(valueText, options);
        const dropdownEvents = writable ? [buildStacEvent('onChanged', binding)] : [];
        const dropdownVisual = buildDropdownVisualContract({ colors: colors });
        return {
          events: dropdownEvents,
          accessory: buildStacWidgetTree('DropdownButton', binding, Object.assign({
            options: options,
            hint: 'Choose',
            backgroundColor: override.statusColor || dropdownVisual.fieldBackground,
            textColor: currentTheme.accentColor,
            useLiveBinding: true,
            valueBinding: binding,
            initialValue: selected,
            readOnly: !writable,
            enabled: writable
          }, dropdownVisual), dropdownEvents)
        };
      }

      if (renderType === 'segmented') {
        const options = parseOptionPairs(meta, card && card.dataset.paramName);
        const selectedOptions = options.length ? options : [{ label: 'Low', value: 'Low' }, { label: 'Mid', value: 'Mid' }, { label: 'High', value: 'High' }];
        const selected = matchOptionValue(selectedOptions, valueText, card && card.dataset.paramName);
        const segmentEvents = writable ? [
          buildStacEvent('onChanged', binding),
          { event: 'onSelected', action: { type: 'send', binding: binding } }
        ] : [];
        return {
          events: segmentEvents,
          accessory: buildStacWidgetTree('metaChip', binding, {
            icon: getParamMetaIcon(card),
            value: String(selected || ''),
            label: String((card && card.dataset && card.dataset.paramName) || ''),
            text: String((card && card.dataset && card.dataset.paramName) || ''),
            title: String((card && card.dataset && card.dataset.paramName) || ''),
            backgroundColor: override.statusColor || 'rgba(37,99,235,0.12)',
            textColor: colors.accentColor,
            iconColor: colors.accentColor,
            readOnly: true
          }, []),
          segmentedRow: buildStacWidgetTree('SegmentedControl', binding, {
            options: selectedOptions,
            value: selected,
            container: {
              backgroundColor: themeWellColor(),
              borderColor: 'transparent',
              borderWidth: 0,
              borderRadius: 12,
              padding: 6
            },
            spacing: 0,
            borderWidth: 0,
            borderRadius: 10,
            verticalPadding: 10,
            fontSize: 13,
            fontWeight: 700,
            selectedColor: colors.accentColor,
            selectedTextColor: '#FFFFFF',
            unselectedColor: 'rgba(0,0,0,0)',
            unselectedTextColor: currentTheme.mutedTextColor,
            animationDuration: 180,
            useLiveBinding: true
          }, segmentEvents)
        };
      }

      if (renderType === 'textField' || renderType === 'cmd') {
        const initialValue = valueText || meta.default || '';
        // Matches the preview: a text field is only editable when the API row says so.
        const fieldReadOnly = renderType === 'cmd' || !textFieldIsEditable(meta);
        const textVisual = buildTextFieldVisualContract({ colors: colors });
        const fieldEvents = fieldReadOnly
          ? []
          : [buildStacEvent('onChanged', binding), { event: 'onSendTap', action: { type: 'send', binding: binding } }];
        const fieldProps = Object.assign({
          keyboardType: 'text',
          hintText: meta.default || card.dataset.paramName || 'Enter value',
          maxLines: renderType === 'cmd' ? null : 1,
          minLines: 1,
          expands: renderType === 'cmd',
          readOnly: fieldReadOnly,
          enabled: true,
          interactive: !fieldReadOnly,
          useLiveBinding: true,
          valueBinding: binding,
          initialValue: initialValue
        }, textVisual);
        if (renderType === 'cmd') {
          Object.assign(fieldProps, buildCmdTerminalProps());
        } else {
          fieldProps.sendButton = buildSendButtonProps(binding, !fieldReadOnly, colors);
        }
        return {
          events: fieldEvents,
          accessory: buildStacWidgetTree('TextField', binding, fieldProps, fieldEvents)
        };
      }

      return {
        events: [],
        accessory: null
      };
    }

    function isStackedParamLayout(componentType) {
      const renderType = resolveParameterRenderType(componentType);
      if (renderType === 'fireControlPanel' || componentType === 'FireControlPanel') return true;
      return ['slider', 'powerGauge', 'needleGauge', 'segmented', 'linearGauge', 'buttonGroup', 'fireControlPanel'].indexOf(renderType) !== -1;
    }

    function buildRegisteredComponentAccessoryBundle(componentType, card, override, meta, valueText, binding) {
      const registered = getRegisteredComponent(componentType);
      if (!registered) return null;
      const parsedOptions = parseOptionPairs(meta, card && card.dataset.paramName);
      const initialValue = resolveRegisteredComponentValue(registered, valueText, meta);
      const colors = getEffectiveComponentColors(override);
      const interactionOptions = { writable: protocolAccessIsWritable(meta) };

      if (registered.id === 'buttonGroup') {
        const options = parsedOptions.length ? parsedOptions : (
          Array.isArray(override.options) && override.options.length ? override.options : registered.options
        );
        const props = buildButtonGroupProps(override, meta, registered, options);
        const events = buildControlInteractionEvents('buttonGroup', binding, interactionOptions);
        const bundle = {
          events: events,
          accessory: null,
