      if (renderType === 'slider' || renderType === 'powerGauge' || renderType === 'needleGauge' || renderType === 'linearGauge') return 'number';
      if (renderType === 'segmented' || renderType === 'dropdown' || renderType === 'buttonGroup') return 'enum';
      if (renderType === 'elevatedButton') return 'trigger';
      if (renderType === 'textField' || renderType === 'cmd' || renderType === 'display' || renderType === 'toastDisplay') return 'string';
      return 'string';
    }

    function normalizeParameterStateValue(control) {
      let raw;
      if (typeof control.initialValue !== 'undefined' && control.initialValue !== null) {
        raw = control.initialValue;
      } else if (control.component && typeof control.component.initialValue !== 'undefined' && control.component.initialValue !== null) {
        raw = control.component.initialValue;
      } else {
        raw = control.value;
      }

      const catalogType = control.catalogComponentType || control.componentType || control.controlType || 'auto';
      const renderType = resolveParameterRenderType(catalogType);
      const valueType = control.valueType || resolveControlValueType(control);

      if (valueType === 'boolean' || renderType === 'switch' || renderType === 'button') {
        if (typeof raw === 'boolean') return raw;
        return parseToggleInitialValue(String(raw));
      }
      if (valueType === 'number' || renderType === 'slider' || renderType === 'powerGauge' || renderType === 'needleGauge' || renderType === 'linearGauge') {
        if (typeof raw === 'number' && Number.isFinite(raw)) return raw;
        const parsed = parseFloat(String(raw).replace(/[^\d.-]/g, ''));
        return Number.isFinite(parsed) ? parsed : 0;
      }
      return raw;
    }

    function buildDeviceParametersState(controls) {
      const parameters = {};
      (controls || []).forEach(function(control) {
        const key = control.parameterKey || String(control.binding || '').replace(/^device\.parameters\./, '');
        if (!key) return;
        parameters[key] = normalizeParameterStateValue(control);
      });
      return parameters;
    }

    function fontAssetForFamily(family) {
      const map = {
        Poppins: 'assets/fonts/Poppins-Regular.ttf',
        Inter: 'assets/fonts/Inter-Regular.ttf',
        Roboto: 'assets/fonts/Roboto-Regular.ttf',
        'Open Sans': 'assets/fonts/OpenSans-Regular.ttf'
      };
      return map[family] || null;
    }

    function collectUsedIconNames(controls) {
      const names = new Set([
        currentTheme.parameterIcon || 'gauge',
        currentTheme.iconStyle || 'signal',
        'send',
        'arrow-left',
        'arrow-right',
        'info',
        'scan',
        'wifi',
        'chevron-left',
        'chevron-right',
        'save',
        'lock',
        'check',
        'check-circle',
        'refresh-cw',
        'eye',
        'eye-off',
        'triangle-alert'
      ]);
      (controls || []).forEach(function(control) {
        if (control.icon) names.add(control.icon);
        if (control.metaIcon) names.add(control.metaIcon);
        if (control.component && control.component.props && control.component.props.metaIcon) {
          names.add(control.component.props.metaIcon);
        }
      });
      return Array.from(names).filter(function(name) { return FONTAWESOME_ICONS[name]; });
    }

    function getParamLiveValue(card, componentType, override) {
      const valueEl = card.querySelector('.field-value');
      const renderType = resolveParameterRenderType(componentType);
      if (renderType === 'switch') {
        const toggle = card.querySelector('.param-switch');
        if (toggle) return toggle.classList.contains('is-on') ? 'ON' : 'OFF';
      }
      if (renderType === 'button') {
        const button = card.querySelector('.power-button-ui, .param-button');
        if (button) return button.classList.contains('is-on') ? 'ON' : 'OFF';
      }
      if (renderType === 'slider') {
        const input = card.querySelector('.param-range-input');
        if (input) return input.value;
      }
      if (renderType === 'powerGauge' || renderType === 'needleGauge') {
        const gauge = card.querySelector('.needle-gauge-visual, .power-gauge-visual');
        if (gauge && gauge.dataset.value) return gauge.dataset.value;
        const gaugeInput = card.querySelector('.power-gauge-input');
        if (gaugeInput) return gaugeInput.value;
      }
      if (renderType === 'dropdown') {
        const select = card.querySelector('.param-dropdown');
        if (select) return select.value;
      }
      if (renderType === 'segmented') {
        const seg = card.querySelector('.segmented-visual');
        if (seg && seg.dataset.value) return seg.dataset.value;
      }
      if (renderType === 'textField' || renderType === 'cmd') {
        const input = card.querySelector('.param-text-input');
        if (input) return input.value;
        if (valueEl && valueEl.dataset.liveValue) return valueEl.dataset.liveValue;
      }
      if (renderType === 'linearGauge') {
        const gauge = card.querySelector('.linear-gauge-visual');
        if (gauge && gauge.dataset.value) return gauge.dataset.value;
        const raw = override.value || (valueEl ? valueEl.textContent.trim() : '');
        const parsed = parseFloat(String(raw).replace(/[^\d.-]/g, ''));
        if (Number.isFinite(parsed)) return String(Math.round(parsed));
        return '75';
      }
      if (renderType === 'elevatedButton') {
        const button = card.querySelector('.elevated-action-btn');
        if (button) return button.textContent.trim();
      }
      if (componentType === 'heartRateDisplay') {
        const raw = override.value || (valueEl ? valueEl.textContent.trim() : '');
        const parsed = parseFloat(String(raw).replace(/[^\d.-]/g, ''));
        if (Number.isFinite(parsed)) return String(Math.round(parsed));
        return '72';
      }
      if (componentType === 'sliderWithLabel') {
        const input = card.querySelector('.registered-slider-input');
        if (input) return input.value;
        const raw = override.value || (valueEl ? valueEl.textContent.trim() : '');
        const parsed = parseFloat(String(raw).replace(/[^\d.-]/g, ''));
        if (Number.isFinite(parsed)) return String(Math.round(parsed));
        return '50';
      }
      if (componentType === 'toggleButton' || componentType === 'buttonGroup' || componentType === 'fireControlPanel') {
        const visual = card.querySelector('.registered-visual');
        if (visual && visual.dataset.value) return visual.dataset.value;
      }
      return override.value || (valueEl ? valueEl.textContent.trim() : '');
    }

    function buildRightAccessoryForControl(componentType, card, meta, value, override, paramIndex) {
      const componentColors = getEffectiveComponentColors(override);
      const metaValueElement = card.querySelector('.meta-value');
      const options = parseOptionPairs(meta, card && card.dataset.paramName);
      const minRaw = meta.minimum === null || typeof meta.minimum === 'undefined' || meta.minimum === '' ? null : parseFloat(meta.minimum);
      const maxRaw = meta.maximum === null || typeof meta.maximum === 'undefined' || meta.maximum === '' ? null : parseFloat(meta.maximum);
      const stepRaw = meta.step === null || typeof meta.step === 'undefined' || meta.step === '' ? null : parseFloat(meta.step);
      const registeredComponent = getRegisteredComponent(componentType);
      const renderType = resolveParameterRenderType(componentType);
      const toggleColors = buildToggleAccessoryColors(override);

      if (registeredComponent) {
        return { type: 'registered', component: registeredComponent.name };
      }
      if (renderType === 'switch') {
        return Object.assign({
          type: 'toggle',
          checked: parseToggleInitialValue(value)
        }, toggleColors);
      }
      if (renderType === 'slider') {
        const sliderVisual = buildSliderVisualSpec(componentType, override, meta, Number.isFinite(minRaw) ? minRaw : 0, Number.isFinite(maxRaw) ? maxRaw : 255, value);
        return {
          type: 'sliderRange',
          icon: getParamMetaIcon(card),
          value: metaValueElement ? metaValueElement.textContent.trim() : String(paramIndex + 1),
          min: Number.isFinite(minRaw) ? minRaw : 0,
          max: Number.isFinite(maxRaw) ? maxRaw : 255,
          step: Number.isFinite(stepRaw) ? stepRaw : 1,
          backgroundColor: componentColors.statusColor,
          textColor: componentColors.accentColor,
          activeColor: sliderVisual.activeTrackColor || componentColors.accentColor,
          inactiveColor: sliderVisual.inactiveTrackColor || '#D9DEEB',
          trackColor: sliderVisual.activeTrackColor || componentColors.accentColor,
          activeTrackColor: sliderVisual.activeTrackColor,
          inactiveTrackColor: sliderVisual.inactiveTrackColor,
          activeThumbColor: sliderVisual.thumbColor,
          trackGradient: sliderVisual.trackGradient,
          visual: sliderVisual
        };
      }
      if (renderType === 'powerGauge' || renderType === 'needleGauge') {
        return {
          type: renderType === 'powerGauge' ? 'powerGauge' : 'needleGauge',
          icon: getParamMetaIcon(card),
          value: value,
          min: Number.isFinite(minRaw) ? minRaw : 0,
          max: Number.isFinite(maxRaw) ? maxRaw : 100,
          step: Number.isFinite(stepRaw) ? stepRaw : 1,
          gauge: buildAnimatedRadialGaugeProps(resolveGaugeNumericBounds(meta, value), {
            activeColor: componentColors.accentColor,
            inactiveColor: '#D9DEEB',
            needleColor: '#0F2550'
          })
        };
      }
      if (renderType === 'linearGauge') {
        const bounds = resolveGaugeNumericBounds(meta, value);
        return {
          type: 'linearGauge',
          value: bounds.value,
          min: bounds.min,
          max: bounds.max,
          unit: '%',
          activeColor: componentColors.accentColor,
          inactiveColor: '#D9DEEB',
          showLabel: true
        };
      }
      if (renderType === 'segmented') {
        const segmentOptions = options.length ? options : [{ label: 'Low', value: 'Low' }, { label: 'Mid', value: 'Mid' }, { label: 'High', value: 'High' }];
        return {
          type: 'segmented',
          icon: getParamMetaIcon(card),
          value: value,
          options: segmentOptions,
          container: {
            backgroundColor: '#F8FAFC',
            borderColor: 'transparent',
            borderWidth: 0,
            borderRadius: 12,
            padding: 6
          },
          spacing: 0,
          borderWidth: 0,
          borderRadius: 10,
          verticalPadding: 10,
          fontSize: 13,
          fontWeight: 700,
          selectedColor: componentColors.accentColor,
          selectedTextColor: '#FFFFFF',
          unselectedColor: 'rgba(0,0,0,0)',
          unselectedTextColor: currentTheme.mutedTextColor,
          animationDuration: 180,
          useLiveBinding: true
        };
      }
      if (renderType === 'dropdown') {
        return {
          type: 'dropdown',
          icon: getParamMetaIcon(card),
          value: value,
          options: options,
          textColor: componentColors.textColor
        };
      }
      if (renderType === 'textField') {
        return {
          type: 'textField',
          value: value,
          placeholder: meta.default || ''
        };
      }
      if (renderType === 'button') {
        return {
          type: 'powerButton',
          checked: parseToggleInitialValue(value),
          activeColor: componentColors.accentColor,
          inactiveColor: '#D9DEEB'
        };
      }
      if (renderType === 'elevatedButton') {
        return {
          type: 'elevatedButton',
          label: value || 'COMMAND',
          backgroundColor: componentColors.accentColor,
          textColor: componentColors.textColor || '#FFFFFF'
        };
      }
      return null;
    }

    function buildControlsSchema() {
      const controls = [];
      const controlActions = {};
      const componentTypeOverrides = {};
      const pagesMap = {};

      document.querySelectorAll('.page-slide').forEach(function(slide, pageIndex) {
        const pageNo = String(slide.dataset.pageNo || String(pageIndex + 1));
        const pageName = String(slide.dataset.pageTitle || ('Page ' + pageNo));
        const pageId = 'page_' + pageNo;
        if (!pagesMap[pageNo]) {
          pagesMap[pageNo] = { id: pageId, pageNo: pageNo, title: pageName, index: pageIndex, controlIds: [] };
        }

        sortParamCardsByControlOrder(Array.from(slide.querySelectorAll('.param-card'))).forEach(function(card, paramIndex) {
          const parameterKey = card.dataset.paramKey || '';
          const controlId = parameterKey || ('control_' + pageNo + '_' + paramIndex);
          const override = getComponentOverride(parameterKey);
          const meta = getEffectiveParamMeta(card);
          const labelElement = card.querySelector('.field-label');
          const catalogComponentType = canonicalCatalogTypeFromProtocol(meta, card.dataset.paramName, getResolvedParamComponentType(card));
          const schemaComponentType = resolveSchemaComponentType(catalogComponentType);
          const writable = protocolAccessIsWritable(meta);
          const componentTypeSource = isProtocolToggleSwitch(meta) || (meta.ui_type && (!override.componentType || override.componentType === 'auto' || override.componentType === 'value'))
            ? 'api'
            : (override.componentType && override.componentType !== 'auto' && override.componentType !== 'value' ? 'studio' : 'api');
          const registeredComponent = getRegisteredComponent(catalogComponentType);
          const componentEntry = getAnyComponentEntry(catalogComponentType);
          const icon = getParamIcon(card);
          const label = String(override.title || (labelElement ? labelElement.textContent.trim() : (card.dataset.componentLabel || card.dataset.paramName)) || 'Parameter');
          const rawValue = String(getParamLiveValue(card, catalogComponentType, override));
          let value = sanitizeControlDisplayValue(rawValue, meta, label);
          const binding = controlBindingKey(parameterKey);
          const component = buildInlineComponentSchema(catalogComponentType, card, override, meta, value, binding);
          const interactionEvents = writable
            ? ((component.events && component.events.length)
              ? component.events
              : buildControlInteractionEvents(schemaComponentType, binding, { writable: true }))
            : [];
          if (!writable && component) {
            component.events = [];
            component.readOnly = true;
            component.interactive = false;
          }
          const deviceFrame = buildDeviceFrameFromMeta(card.dataset.paramName || label, meta);
          const dataAction = buildControlDataAction(controlId, schemaComponentType, binding, meta, card.dataset.paramName || label, deviceFrame);
          controlActions[dataAction.id] = dataAction.definition;
          const options = parseOptionPairs(meta, card && card.dataset.paramName);
          if (isDirectionParameter(card.dataset.paramName) && options.length) {
            const directionValue = matchOptionValue(options, value, card.dataset.paramName);
            value = directionValue;
            if (component) {
              component.initialValue = directionValue;
              component.displayValue = directionValue;
              component.options = options;
              if (!component.props || typeof component.props !== 'object') component.props = {};
              component.props.options = options;
              component.props.value = directionValue;
            }
          }
          const constraints = resolveControlNumericConstraints(catalogComponentType, meta, registeredComponent);
          const metaValueElement = card.querySelector('.meta-value');
          const componentColors = getEffectiveComponentColors(override);
          const rightAccessory = buildRightAccessoryForControl(catalogComponentType, card, meta, value, override, paramIndex);
          const valueType = isProtocolToggleSwitch(meta)
            ? 'boolean'
            : (registeredComponent && registeredComponent.valueType
              ? registeredComponent.valueType
              : (componentEntry && componentEntry.valueType && componentEntry.valueType !== 'auto'
                ? (resolveParameterRenderType(catalogComponentType) === 'button' ? 'boolean' : componentEntry.valueType)
                : resolveControlValueType({ catalogComponentType: catalogComponentType, componentType: schemaComponentType })));

          const controlRecord = {
            id: controlId,
            parameterKey: parameterKeySlug(parameterKey),
            parameter: card.dataset.paramName || label,
            parameterName: card.dataset.paramName || label,
            telemetryKey: String(card.dataset.paramName || '').trim(),
            pageNo: pageNo,
            pageName: pageName,
            pageId: pageId,
            sequence: paramIndex + 1,
            componentType: schemaComponentType,
            controlType: schemaComponentType,
            catalogComponentType: catalogComponentType !== schemaComponentType ? catalogComponentType : null,
            componentTypeSource: componentTypeSource,
            valueType: valueType,
            renderAs: 'ParameterCard',
            variant: controlSchemaVariant(schemaComponentType),
            flutterWidget: component.flutterWidget,
            binding: binding,
            initialValue: component.initialValue,
            component: component,
            componentLabel: componentEntry ? componentEntry.label : catalogComponentType,
            icon: icon,
            metaIcon: getParamMetaIcon(card),
            label: label,
            value: component.displayValue,
            visible: !override.hidden,
            events: interactionEvents,
            action: dataAction.id,
            rightAccessory: rightAccessory,
            options: options,
            constraints: constraints,
            protocolMeta: {
              command_id: meta.command_id || meta.commandId || null,
              function_code: meta.function_code || meta.functionCode || null,
              action_id: meta.action_id || meta.actionId || null,
              ui_type: meta.ui_type || null,
              ui_type_source: meta.ui_type_source || null,
              access: meta.access || null,
              items: Array.isArray(meta.items) ? meta.items : [],
              item_values: Array.isArray(meta.item_values) ? meta.item_values : [],
              sno_asperui: Array.isArray(meta.sno_asperui) ? meta.sno_asperui : [],
              minimum: meta.minimum != null ? meta.minimum : null,
              maximum: meta.maximum != null ? meta.maximum : null,
              step: meta.step != null ? meta.step : null,
              default: meta.default != null ? meta.default : null,
              frame: meta.frame && typeof meta.frame === 'object' ? meta.frame : null
            },
            deviceFrame: deviceFrame,
            override: buildComponentOverridePayload(override),
            styles: {
              cardColor: componentColors.cardColor,
              borderColor: componentColors.borderColor,
              statusColor: componentColors.statusColor,
              accentColor: componentColors.accentColor,
              iconColor: componentColors.iconColor,
              textColor: componentColors.textColor,
              mutedTextColor: currentTheme.mutedTextColor,
              leftAccent: {
                width: 3,
                colorStart: currentTheme.secondaryColor,
                colorEnd: componentColors.accentColor
              },
              iconBubble: {
                size: 38,
                backgroundColor: 'rgba(37,99,235,0.14)',
                iconSize: parseInt(currentTheme.iconSize || 20, 10),
                iconColor: componentColors.iconColor
              }
            }
          };
          applyReadOnlyProtocolContract(controlRecord, meta);
          if (isProtocolToggleSwitch(meta)) {
            controlRecord.componentType = 'switch';
            controlRecord.controlType = 'switch';
            controlRecord.valueType = 'boolean';
            controlRecord.flutterWidget = 'Switch';
            if (controlRecord.component) {
              controlRecord.component.type = 'switch';
              controlRecord.component.flutterWidget = 'Switch';
              controlRecord.component.valueType = 'boolean';
              controlRecord.component.initialValue = parseToggleInitialValue(controlRecord.component.initialValue);
              controlRecord.initialValue = controlRecord.component.initialValue;
            }
          }
          applyGetStatusResponseContract(controlRecord, meta);
          applyGetStatusCommandContract(controlRecord, meta);

          // Get Status command rows that resolve to a timer/slider must keep
          // 0–255s constraints and a slider widgetTree, not leftover switch props.
          const finalCatalogType = controlRecord.catalogComponentType || catalogComponentType;
          if (resolveParameterRenderType(finalCatalogType) === 'slider'
            || finalCatalogType === 'autoTriggerTimer'
            || controlRecord.componentType === 'slider') {
            const sliderCatalogType = finalCatalogType === 'autoTriggerTimer' ? 'autoTriggerTimer' : (finalCatalogType || 'slider');
            const sliderConstraints = resolveControlNumericConstraints(sliderCatalogType, meta, registeredComponent);
            controlRecord.constraints = sliderConstraints;
            controlRecord.valueType = 'number';
            const widgetName = String((controlRecord.component && controlRecord.component.flutterWidget) || controlRecord.flutterWidget || '').toLowerCase();
            const treeLooksLikeSwitch = widgetName === 'switch'
              || (controlRecord.component && controlRecord.component.type === 'switch')
              || (controlRecord.component && controlRecord.component.props && (controlRecord.component.props.checked != null || controlRecord.component.props.trueValues));
            // Always rebuild when the tree still looks like a switch, or when missing.
            if (!controlRecord.component || !controlRecord.component.widgetTree || treeLooksLikeSwitch || finalCatalogType === 'autoTriggerTimer') {
              controlRecord.component = buildInlineComponentSchema(sliderCatalogType, card, override, meta, value, binding);
              controlRecord.flutterWidget = controlRecord.component.flutterWidget || 'schemaSlider';
              controlRecord.componentType = 'slider';
              controlRecord.controlType = 'slider';
            }
            if (controlRecord.component) {
              controlRecord.component.valueType = 'number';
              if (!controlRecord.component.props || typeof controlRecord.component.props !== 'object') {
                controlRecord.component.props = {};
              }
              const variantConfig = getSliderVariantConfig(sliderCatalogType);
              controlRecord.component.props.variant = variantConfig.variant || (sliderCatalogType === 'autoTriggerTimer' ? 'timer' : 'default');
              controlRecord.component.props.valueSuffix = variantConfig.valueSuffix || (sliderCatalogType === 'autoTriggerTimer' ? 's' : null);
              controlRecord.component.props.min = sliderConstraints.minimum;
              controlRecord.component.props.max = sliderConstraints.maximum;
              controlRecord.component.props.step = sliderConstraints.step;
              if (variantConfig.variant === 'timer' || sliderCatalogType === 'autoTriggerTimer') {
                Object.assign(controlRecord.component.props, buildTimerSliderLabelStyleProps());
              }
              // Drop switch-like leftovers that survived a prior Get Status projection.
              delete controlRecord.component.props.activeTrackColor;
              delete controlRecord.component.props.inactiveTrackColor;
              delete controlRecord.component.props.activeThumbColor;
              delete controlRecord.component.props.inactiveThumbColor;
              delete controlRecord.component.props.checked;
              delete controlRecord.component.props.trueValues;
              delete controlRecord.component.props.falseValues;
            }
          }

          // Document web UI parts that are not separate controls (e.g. send button
          // on enterText). relatedUiCount matches the "N UI" chip when the send
          // affordance is counted as a third UI part of the group.
          const groupCard = card.closest('.param-group-card');
          const groupUiCount = groupCard
            ? groupCard.querySelectorAll(':scope > .param-component-stack > .param-card').length
            : 1;
          const hasSendButton = Boolean(controlRecord.component && controlRecord.component.props && controlRecord.component.props.sendButton && controlRecord.component.props.sendButton.visible !== false && catalogComponentType !== 'cmd' && schemaComponentType === 'textField' && writable);
          controlRecord.groupParameter = card.dataset.paramName || controlRecord.parameterName || '';
          controlRecord.uiCount = groupUiCount;
          controlRecord.relatedUiCount = groupUiCount + (hasSendButton ? 1 : 0);
          if (hasSendButton) {
            controlRecord.uiParts = ['textField', 'sendButton'];
          }

          applyGetStatusResponseContract(controlRecord, meta);
          applyGetStatusCommandContract(controlRecord, meta);

          // P0-3: parser-only response/error fields must NOT appear as visible controls.
          // Only ARRAY/parser payloads are hidden — a real Error row (e.g. TUNING)
          // whose default text is "Error" must remain in controlIds / controlOrder.
          const fieldSrc = String((meta && meta.ui_type_source) || '').toLowerCase();
          const isParserOnly = (fieldSrc === 'response' || fieldSrc === 'error')
            && (controlRecord.valueType === 'array'
              || String(controlRecord.label || controlRecord.parameterName || '').toUpperCase() === 'ARRAY'
              || controlRecord.componentType === 'array');
          if (isParserOnly) {
            controlRecord.visible = false;
            controlRecord.renderable = false;
            controlRecord.parserOnly = true;
            controlRecord.events = [];
            if (controlRecord.component) { controlRecord.component.events = []; }
          }

          controls.push(controlRecord);

          pagesMap[pageNo].controlIds.push(controlId);
          if (parameterKey && schemaComponentType) {
            componentTypeOverrides[parameterKey] = schemaComponentType;
          }
        });
      });

      controls.sort(function(a, b) {
        const pageA = parseInt(a.pageNo, 10) || 0;
        const pageB = parseInt(b.pageNo, 10) || 0;
        if (pageA !== pageB) return pageA - pageB;
        return (a.sequence || 0) - (b.sequence || 0);
      });
      currentTheme.controlOrder = controls.map(function(control) { return control.id; });

      const pages = Object.keys(pagesMap).map(function(pageNo) {
        return pagesMap[pageNo];
      }).sort(function(a, b) {
        return a.index - b.index;
      });

      return {
        controls: controls,
        pages: pages,
        componentTypeOverrides: componentTypeOverrides,
        controlActions: controlActions
      };
    }

    // DOM Elements
    const track = document.getElementById('slide-track');
    const slides = Array.from(document.querySelectorAll('.page-slide'));
    const pageButtons = Array.from(document.querySelectorAll('.page-button'));
    const prevButton = document.getElementById('prev-slide');
    const nextButton = document.getElementById('next-slide');
    const progressBar = document.getElementById('slide-progress');
    const title = document.getElementById('active-page-title');
    const subtitle = document.getElementById('active-page-subtitle');
    const studio = document.getElementById('ui-studio');
    const studioBackdrop = document.getElementById('studio-backdrop');
    const studioStatus = document.getElementById('studio-status');
    const schemaOutput = document.getElementById('schema-output');
    const schemaApiUrlInput = document.getElementById('schema-api-url');
    const orderList = document.getElementById('control-order-list');
    const phoneShell = document.querySelector('.phone-shell');
    const studioPreviewMount = document.getElementById('studio-preview-mount');
    const studioPreviewFrame = document.getElementById('studio-preview-frame');
    const studioPreviewZoomLabel = document.getElementById('studio-preview-zoom-label');
    const studioPreviewZoomInBtn = document.getElementById('studio-preview-zoom-in');
    const studioPreviewZoomOutBtn = document.getElementById('studio-preview-zoom-out');
    const studioPreviewZoomFitBtn = document.getElementById('studio-preview-zoom-fit');
    const pagePreviewMount = document.getElementById('page-preview-mount');
    const pagePreviewFrame = document.getElementById('page-preview-frame');
    const pagePreviewZoomLabel = document.getElementById('page-preview-zoom-label');
    const pagePreviewZoomInBtn = document.getElementById('page-preview-zoom-in');
    const pagePreviewZoomOutBtn = document.getElementById('page-preview-zoom-out');
    const pagePreviewZoomFitBtn = document.getElementById('page-preview-zoom-fit');
    const PREVIEW_ZOOM_MIN = 0.35;
    const PREVIEW_ZOOM_MAX = 2.5;
    const PREVIEW_ZOOM_STEP = 0.12;
    const previewZoomStates = {
      page: { autoFit: true, manualScale: 1 },
      studio: { autoFit: true, manualScale: 1 }
    };

    function queryPreviewAll(selector) {
      return phoneShell ? Array.from(phoneShell.querySelectorAll(selector)) : [];
    }
    const phoneHome = document.createComment('phone-shell-home');
