    function findLiveNodeDetail(nodeId) {
      const wanted = String(nodeId || '').trim().toLowerCase();
      const details = Array.isArray(deviceUiInfo && deviceUiInfo.node_details) ? deviceUiInfo.node_details : [];
      if (!wanted) return null;
      for (let index = 0; index < details.length; index += 1) {
        const id = nodeDetailId(details[index]).toLowerCase();
        if (id && id === wanted) return details[index];
      }
      return null;
    }

    function buildSchemaNodeDetails(resolvedNodeId, deviceConfig, connectivity) {
      const details = Array.isArray(deviceUiInfo && deviceUiInfo.node_details) ? deviceUiInfo.node_details : [];
      const matched = findLiveNodeDetail(resolvedNodeId);
      if (matched) {
        const matchedId = nodeDetailId(matched).toLowerCase();
        const primary = Object.assign({}, matched, {
          id: resolvedNodeId || nodeDetailId(matched),
          config: deviceConfig || matched.config || {},
          role: matched.role || 'primary'
        });
        const rest = details.filter(function(item) {
          return nodeDetailId(item).toLowerCase() !== matchedId;
        });
        return [primary].concat(rest);
      }
      return [{
        id: resolvedNodeId,
        config: deviceConfig || {},
        role: 'primary',
        status: {
          connectivity: {
            connected: !!(connectivity && connectivity.online),
            timestamp: (connectivity && connectivity.timestamp) || Date.now()
          }
        }
      }];
    }

    function getDeviceConnectivityState() {
      const wanted = (typeof getStudioNodeId === 'function' ? getStudioNodeId() : '') || resolvedStudioNodeId || '';
      const matched = wanted
        ? findLiveNodeDetail(wanted)
        : null;
      const status = matched && matched.status
        ? matched.status
        : null;
      const connectivity = status && status.connectivity ? status.connectivity : null;
      const hasConnected = connectivity && typeof connectivity.connected !== 'undefined';
      const online = hasConnected ? !!connectivity.connected : !!initialDeviceOnline;
      return {
        online: online,
        label: online ? 'Online' : 'Offline',
        timestamp: (connectivity && connectivity.timestamp) || initialDeviceOnlineTimestamp || Date.now(),
        source: hasConnected ? 'deviceUiInfo.node_details.status.connectivity.connected' : 'initialDeviceOnline'
      };
    }

