    currentTheme.pageTypography = currentTheme.pageTypography && typeof currentTheme.pageTypography === 'object' && !Array.isArray(currentTheme.pageTypography) ? currentTheme.pageTypography : {};
    (function applyMappingSequenceToTheme() {
      const mappingOrder = [];
      const seen = {};
      (Array.isArray(pageData) ? pageData : []).forEach(function(page) {
        const pageNo = String(page.page_no || '');
        const params = Array.isArray(page.params) ? page.params.slice() : [];
        params.sort(function(a, b) {
          return (parseInt(a.sequence, 10) || 0) - (parseInt(b.sequence, 10) || 0);
        });
        params.forEach(function(param) {
          const name = String(param.parameter || '').trim();
          if (!name || !pageNo) return;
          const key = pageNo + ':' + name;
          if (seen[key]) return;
          seen[key] = true;
          mappingOrder.push(key);
        });
      });
      if (!mappingOrder.length) return;
      const existing = Array.isArray(currentTheme.controlOrder) ? currentTheme.controlOrder : [];
      const extras = existing.filter(function(key) {
        return mappingOrder.indexOf(key) === -1;
