    function updateUndoRedoButtons() {
      const undoBtn = document.getElementById('undo-theme-btn');
      const redoBtn = document.getElementById('redo-theme-btn');
      if (undoBtn) undoBtn.disabled = themeHistory.undoStack.length <= 1;
      if (redoBtn) redoBtn.disabled = themeHistory.redoStack.length === 0;
    }

    function pushThemeHistorySnapshot() {
      if (themeHistory.isApplying) return;
      const snapshot = cloneThemeSnapshot();
      const last = themeHistory.undoStack[themeHistory.undoStack.length - 1];
      if (last && themeSnapshotsEqual(last, snapshot)) return;
      themeHistory.undoStack.push(snapshot);
      if (themeHistory.undoStack.length > themeHistory.maxSize) {
        themeHistory.undoStack.shift();
      }
      themeHistory.redoStack = [];
      updateUndoRedoButtons();
    }

    function commitThemeHistoryRecord() {
      window.clearTimeout(themeHistory.recordTimer);
      pushThemeHistorySnapshot();
    }

    function resetThemeHistoryBaseline() {
      window.clearTimeout(themeHistory.recordTimer);
      themeHistory.undoStack = [cloneThemeSnapshot()];
      themeHistory.redoStack = [];
      updateUndoRedoButtons();
    }

    function applyThemeSnapshot(snapshot) {
      if (!snapshot) return;
      themeHistory.isApplying = true;
      currentTheme = JSON.parse(JSON.stringify(snapshot.theme));
      currentTheme.parameterIcons = normalizeParameterIcons(currentTheme.parameterIcons);
      currentTheme.componentOverrides = currentTheme.componentOverrides && typeof currentTheme.componentOverrides === 'object' && !Array.isArray(currentTheme.componentOverrides) ? currentTheme.componentOverrides : {};
      currentTheme.pageTypography = currentTheme.pageTypography && typeof currentTheme.pageTypography === 'object' && !Array.isArray(currentTheme.pageTypography) ? currentTheme.pageTypography : {};
      selectedTypographyPage = snapshot.selectedTypographyPage || 'all';
      selectedParamKey = '';
      populateTypographyPageSelect();
      syncInputsFromTheme();
      syncThemeColorLabels();
      applyTheme(currentTheme, { reinitializeComponents: true });
      renderParametersButtons();
      renderOrderList();
      generateSchema();
      themeHistory.isApplying = false;
      updateUndoRedoButtons();
    }

    function undoThemeChange() {
      if (themeHistory.undoStack.length <= 1) return;
      const currentSnapshot = themeHistory.undoStack.pop();
      themeHistory.redoStack.push(currentSnapshot);
      applyThemeSnapshot(themeHistory.undoStack[themeHistory.undoStack.length - 1]);
      setStudioStatus('Undone.');
    }

    function redoThemeChange() {
      if (!themeHistory.redoStack.length) return;
      const nextSnapshot = themeHistory.redoStack.pop();
      themeHistory.undoStack.push(nextSnapshot);
