    function resolveRemoveNodeId() {
      return isUsableStudioNodeId(currentGatewayDetails && currentGatewayDetails.deviceId)
        || getStudioNodeId()
        || isUsableStudioNodeId(deviceUiInfo && deviceUiInfo.nodes)
        || isUsableStudioNodeId(deviceUiInfo && deviceUiInfo.node_details && deviceUiInfo.node_details[0] && deviceUiInfo.node_details[0].id)
        || '';
    }

    function getStudioAccessToken() {
      return String(studioAccessToken || '').trim();
    }

    function buildDeviceApiHeaders(token, contentType) {
      const headers = {
        Accept: 'application/json',
        'X-Requested-With': 'XMLHttpRequest'
      };
      if (contentType) headers['Content-Type'] = contentType;
      if (token) {
        headers.Authorization = 'Bearer ' + token;
      }
      return headers;
    }

    function buildRemoveNodeApiUrl(nodeId) {
      // node_id and operation must NOT appear in the URL — they belong in the JSON body.
      // access_token must NOT appear in the URL — it belongs in the Authorization header only.
      const base = String(v8DeviceApiBase || '').replace(/\/+$/, '');
      return base + '?action=remove_node';
    }

    function parseRemoveNodeResponse(response, rawText) {
      let data = null;
      try {
        data = rawText ? JSON.parse(rawText) : null;
      } catch (error) {
        data = null;
      }
      if (data && typeof data === 'object') {
        if (typeof data.success === 'undefined') {
          data.success = !data.status || String(data.status).toLowerCase() !== 'failure';
        }
        return data;
      }
      if (response && response.ok) {
        return {
          success: true,
          message: 'Device removed successfully.',
          raw: rawText || ''
        };
      }
      return {
        success: false,
        message: (data && (data.message || data.description || data.error))
          ? (data.message || data.description || data.error)
          : ('Remove device request failed (' + (response ? response.status : '0') + ').'),
        raw: rawText || ''
      };
    }

    function callRemoveNodeApi(nodeId) {
      const token = getStudioAccessToken();
      const headers = buildDeviceApiHeaders(token, 'application/json');

      if (removeDeviceUrl) {
        const body = new URLSearchParams();
        body.set('node_id', nodeId);
        return fetch(removeDeviceUrl, {
          method: 'POST',
          credentials: 'same-origin',
          headers: {
            'Accept': 'application/json',
            'Content-Type': 'application/x-www-form-urlencoded',
            'X-Requested-With': 'XMLHttpRequest'
          },
          body: body.toString()
        }).then(function(response) {
          return response.text().then(function(text) {
            const parsed = parseRemoveNodeResponse(response, text);
            if (parsed.success) return parsed;
            if (token && v8DeviceApiBase) {
              return callRemoveNodeApiDirect(nodeId, token, headers);
            }
            return parsed;
          });
        }).catch(function() {
          if (token && v8DeviceApiBase) {
            return callRemoveNodeApiDirect(nodeId, token, headers);
          }
          return { success: false, message: 'Could not reach remove device service.' };
        });
      }

      if (!token || !v8DeviceApiBase) {
        return Promise.resolve({ success: false, message: 'Access token is not available for remove device.' });
      }
      return callRemoveNodeApiDirect(nodeId, token, headers);
    }

    function callRemoveNodeApiDirect(nodeId, token, headers) {
      const url = buildRemoveNodeApiUrl(nodeId);
      return fetch(url, {
        method: 'POST',
        credentials: 'omit',
        headers: headers,
        body: JSON.stringify({
          node_id: nodeId
          // access_token must NOT be in the body — it is sent via Authorization header only.
          // operation is not required by the server contract.
        })
      }).then(function(response) {
        return response.text().then(function(text) {
          return parseRemoveNodeResponse(response, text);
        });
      });
    }

    function clearStudioNodeBindingAfterRemove() {
      if (schemaNodeIdInput) {
        schemaNodeIdInput.value = '';
      }
      currentTheme.nodeId = '';
      syncSchemaApiUrlField();
      generateSchema();
    }

    function removeDeviceFromGatewayDetails() {
      const nodeId = resolveRemoveNodeId();
      const details = currentGatewayDetails || {};
      if (!nodeId) {
        showSaveToast('Node ID is required before removing this device.');
        return;
      }

      const confirmLines = [
        'Remove this device from your account?',
        '',
        'Device Id: ' + (details.deviceId || nodeId),
        'Name: ' + (details.name || modelNo || '—'),
        'Type: ' + (details.type || '—')
      ];
      if (!window.confirm(confirmLines.join('\n'))) {
        return;
      }

      setGatewayDeleteButtonsBusy(true);
      setStudioStatus('Removing device ' + nodeId + '…');

      callRemoveNodeApi(nodeId).then(function(result) {
        setGatewayDeleteButtonsBusy(false);

        if (!result || result.success !== true) {
          const message = (result && (result.message || result.description || result.error))
            ? (result.message || result.description || result.error)
            : 'Could not remove device.';
          showSaveToast(message);
          setStudioStatus(message);
          return;
        }

        showSaveToast((result && result.message) ? result.message : 'Device removed successfully.');
        setStudioStatus('Device removed. Studio node binding cleared.');
        clearStudioNodeBindingAfterRemove();
        closeDeviceInfoModal();
      }).catch(function(error) {
        setGatewayDeleteButtonsBusy(false);
        const message = error && error.message ? error.message : 'Could not remove device.';
        showSaveToast(message);
        setStudioStatus(message);
      });
    }

    function firstPresent() {
      for (let index = 0; index < arguments.length; index += 1) {
        const value = arguments[index];
        if (value !== null && typeof value !== 'undefined' && String(value).trim() !== '') return value;
      }
      return '';
    }

    function flattenApiPayload(payload, prefix = '', output = {}) {
      if (payload === null || typeof payload === 'undefined') {
        return output;
      }
      if (Array.isArray(payload)) {
        payload.forEach(function(item, index) {
          flattenApiPayload(item, prefix ? prefix + '.' + index : String(index), output);
        });
        return output;
      }
      if (typeof payload === 'object') {
        Object.keys(payload).forEach(function(key) {
          if (key === '__apiUrl') return;
          const path = prefix ? prefix + '.' + key : key;
          const normalized = String(key).toLowerCase().replace(/[^a-z0-9]/g, '');
          const value = payload[key];
          if (value !== null && typeof value !== 'undefined' && typeof value !== 'object' && String(value).trim() !== '') {
            if (!output[normalized]) output[normalized] = value;
            if (!output[path.toLowerCase().replace(/[^a-z0-9]/g, '')]) output[path.toLowerCase().replace(/[^a-z0-9]/g, '')] = value;
          }
          flattenApiPayload(value, path, output);
        });
      }
      return output;
    }

    function pickApiValue(flat, aliases) {
      for (let index = 0; index < aliases.length; index += 1) {
        const key = String(aliases[index]).toLowerCase().replace(/[^a-z0-9]/g, '');
        if (flat[key] !== null && typeof flat[key] !== 'undefined' && String(flat[key]).trim() !== '') {
          return flat[key];
        }
      }
      return '';
    }

    function normalizeDeviceInfo(responseData) {
      const details = Array.isArray(responseData && responseData.node_details) ? responseData.node_details : [];
      const node = details.find(function(item) { return item && item.config; }) || details[0] || {};
      const config = node && node.config && typeof node.config === 'object' ? node.config : (responseData && responseData.deviceConfig ? responseData.deviceConfig : {});
      const info = config.info && typeof config.info === 'object'
        ? config.info
        : (responseData && responseData.info && typeof responseData.info === 'object' ? responseData.info : {});
      const devices = Array.isArray(config.devices) ? config.devices : [];
      const device = devices[0] && typeof devices[0] === 'object' ? devices[0] : {};
      const attributeList = []
        .concat(Array.isArray(config.attributes) ? config.attributes : [])
        .concat(Array.isArray(device.attributes) ? device.attributes : []);
      const attributes = {};
      attributeList.forEach(function(attribute) {
        if (attribute && attribute.name) attributes[String(attribute.name).toLowerCase()] = attribute.value;
      });

      return {
        deviceId: firstPresent(node.node_id, node.id, config.node_id, device['Device Id'], attributes['device id'], modelNo),
        name: firstPresent(info.name, device.name, info.product, info.product_name, modelNo),
        type: firstPresent(info.type, info.product_type, device.type, info.model, attributes.model, 'Gateway'),
        network: firstPresent(info.SSID, info.ssid, info.Access_Point, info.access_point, attributes.model, 'Efactor'),
        firmware: firstPresent(info.fw_version, info.firmware_version, info.version, responseData && responseData.version, '—'),
        guaranteeUrl: firstPresent(info.Guarantee_Card, info.guarantee_card, device.Guarantee_Card),
        userGuideUrl: firstPresent(info.Video, info.user_guide, info.User_Guide, device.Video),
        helpUrl: firstPresent(info.Need_Help, info.need_help, device.Need_Help),
        ticketsUrl: firstPresent(info.Track_Tickets, info.track_tickets, info.Auto_Test, info.auto_test),
        deviceConfig: config,
        pages: device.pages && typeof device.pages === 'object' ? device.pages : {}
      };
    }

    function createDetailRow(options) {
      const row = document.createElement(options.href ? 'a' : 'div');
      const copy = document.createElement('div');
      const label = document.createElement('span');
      row.className = 'device-detail-row';
      copy.className = 'device-detail-copy';
      label.className = 'device-detail-label';
      label.textContent = options.label;
      copy.appendChild(label);

      if (options.valueBelow) {
        const value = document.createElement('span');
        value.className = 'device-detail-value';
        value.textContent = String(options.valueBelow || '—');
        copy.appendChild(value);
      }
      row.appendChild(copy);

      if (options.sideValue) {
        const sideValue = document.createElement('span');
        sideValue.className = 'device-detail-side-value';
        sideValue.textContent = String(options.sideValue);
        row.appendChild(sideValue);
      } else if (options.removeDevice) {
        const removeButton = document.createElement('button');
        removeButton.type = 'button';
        removeButton.className = 'device-detail-remove-action';
        removeButton.id = 'device_info_delete_inline';
        removeButton.setAttribute('aria-label', 'Delete device');
        removeButton.innerHTML = iconSvg('trash-2') + '<span>Delete device</span>';
        removeButton.addEventListener('click', function(event) {
          event.preventDefault();
          event.stopPropagation();
          removeDeviceFromGatewayDetails();
        });
        row.appendChild(removeButton);
      } else if (options.icon) {
        const icon = document.createElement('span');
        icon.className = 'device-detail-action';
        icon.innerHTML = iconSvg(options.icon);
        row.appendChild(icon);
      }

      if (options.href) {
        row.href = options.href;
        row.target = '_blank';
        row.rel = 'noopener noreferrer';
        row.style.textDecoration = 'none';
      }
      return row;
    }

    function renderGatewayDetails(details) {
      if (!deviceInfoContent) return;
      currentGatewayDetails = details || null;
      deviceInfoContent.innerHTML = '';

      const identityGroup = document.createElement('section');
      identityGroup.className = 'device-details-group';
      identityGroup.appendChild(createDetailRow({
        label: 'Device Id',
        valueBelow: details.deviceId,
        removeDevice: true
      }));
      identityGroup.appendChild(createDetailRow({ label: 'Name', sideValue: details.name }));
      identityGroup.appendChild(createDetailRow({ label: 'Type', sideValue: details.type }));
      identityGroup.appendChild(createDetailRow({ label: 'Network Connection', valueBelow: details.network, icon: 'wifi' }));
      deviceInfoContent.appendChild(identityGroup);

      const firmwareGroup = document.createElement('section');
      firmwareGroup.className = 'device-details-group';
      firmwareGroup.appendChild(createDetailRow({ label: 'Firmware Version', sideValue: details.firmware }));
      deviceInfoContent.appendChild(firmwareGroup);

      const supportGroup = document.createElement('section');
      supportGroup.className = 'device-details-group';
      supportGroup.appendChild(createDetailRow({ label: 'Guarantee Card', valueBelow: 'Terms & Conditions', href: details.guaranteeUrl, icon: 'file' }));
      supportGroup.appendChild(createDetailRow({ label: 'User Guide', valueBelow: 'Troubleshooting', href: details.userGuideUrl, icon: 'chevron-right' }));
      supportGroup.appendChild(createDetailRow({ label: 'Need Help?', valueBelow: 'Chat with us', href: details.helpUrl, icon: 'help-circle' }));
      supportGroup.appendChild(createDetailRow({ label: 'Track tickets', valueBelow: 'Your service requests', href: details.ticketsUrl, icon: 'inbox' }));
      deviceInfoContent.appendChild(supportGroup);

      const deleteGroup = document.createElement('section');
