    function openDeviceInfoFromSchema() {
      if (!deviceInfoModal || !deviceInfoContent || !phoneShell) return;
      resetWifiProvisioningRuntime();
      deviceInfoModal.classList.remove('is-wifi');
      if (deviceInfoTitle) deviceInfoTitle.textContent = 'Gateway Details';
      deviceInfoContent.innerHTML = '<div class="info-modal-state">Loading gateway details…</div>';
      deviceInfoModal.classList.add('is-open');
      deviceInfoModal.setAttribute('aria-hidden', 'false');
      phoneShell.classList.add('is-showing-info');
      if (deviceInfoContent) deviceInfoContent.scrollTop = 0;

      fetch(deviceInfoUrl, { method: 'GET', credentials: 'same-origin' })
        .then(function(response) {
          if (!response.ok) throw new Error('Information request failed');
          return response.json();
        })
        .then(function(responseData) {
          renderGatewayDetails(normalizeDeviceInfo(responseData));
        })
        .catch(function() {
          renderGatewayDetails(normalizeDeviceInfo({ info: { name: modelNo, type: 'Gateway' } }));
        });
    } 

    function extractScanResultFromSchema(schema) {
      const root = schema && typeof schema === 'object' ? schema : {};
      const flat = flattenApiPayload(root);
      const scanState = root.state && root.state.scanResult && typeof root.state.scanResult === 'object'
        ? root.state.scanResult
        : {};
      const extensionsScan = root.extensions
        && root.extensions.scanResult
        && typeof root.extensions.scanResult === 'object'
        ? root.extensions.scanResult
        : {};
      const topScan = root.scanResult && typeof root.scanResult === 'object' ? root.scanResult : {};
      const dataScan = root.data && typeof root.data === 'object' ? root.data : {};
      const resultScan = root.result && typeof root.result === 'object' ? root.result : {};
      const value = firstPresent(
        scanState.value,
        scanState.code,
        scanState.data,
        scanState.result,
        scanState.qr,
        scanState.qrValue,
        extensionsScan.value,
        extensionsScan.code,
        extensionsScan.qr,
        topScan.value,
        topScan.code,
        topScan.qr,
        dataScan.value,
        dataScan.code,
        dataScan.qr,
        dataScan.scan,
        dataScan.scanResult,
        resultScan.value,
        resultScan.code,
        resultScan.qr,
        resultScan.scan,
        resultScan.scanResult,
        root.scan,
        root.scanned_value,
        root.scannedValue,
        root.qr,
        root.qrValue,
        root.qr_value,
        root.code,
        root.value,
        pickApiValue(flat, [
          'scan_value',
          'scanvalue',
          'scanned_value',
          'scannedvalue',
          'qr_value',
          'qrvalue',
          'qrcode',
          'barcode',
          'scan_code',
          'scanresult',
          'scan',
          'code',
          'value',
          'data'
        ]),
        typeof root.scanResult === 'string' ? root.scanResult : ''
      );
      if (value === '') return null;
      return {
        value: String(value),
        type: firstPresent(scanState.type, scanState.format, extensionsScan.type, topScan.type, dataScan.type, dataScan.format, resultScan.type, resultScan.format, 'qr'),
        scannedAt: firstPresent(scanState.scannedAt, scanState.updatedAt, extensionsScan.scannedAt, topScan.scannedAt, dataScan.scannedAt, dataScan.updatedAt, resultScan.scannedAt, resultScan.updatedAt, ''),
        source: firstPresent(scanState.source, extensionsScan.source, topScan.source, dataScan.source, resultScan.source, 'app'),
        nodeId: firstPresent(
          scanState.nodeId,
          topScan.nodeId,
          dataScan.nodeId,
          dataScan.node_id,
          resultScan.nodeId,
          resultScan.node_id,
          root.node_id && root.node_id.id,
          typeof root.node_id === 'string' ? root.node_id : '',
          root.deviceConfig && root.deviceConfig.node_id,
          pickApiValue(flat, ['node_id', 'nodeid', 'device_node_id']),
          ''
        ),
        apiUrl: root.__apiUrl || ''
      };
    }

    function renderScanResultPanel(scan) {
      if (!deviceInfoContent) return;
      if (!scan) {
        deviceInfoContent.innerHTML = ''
          + '<div class="info-modal-state">'
