          + '</div>';
        return;
      }
      const rows = [
        { label: 'QR value', value: scan.value },
        { label: 'Type', value: scan.type || '—' },
        { label: 'Source', value: scan.source || 'app' },
        { label: 'Scan API', value: scan.apiUrl || '-' },
        { label: 'Scanned at', value: scan.scannedAt || '—' },
        { label: 'Node ID', value: scan.nodeId || '—' }
      ];
      deviceInfoContent.innerHTML = ''
        + '<div class="device-details-card">'
        +   '<div class="device-details-list">'
        +     '<div class="device-details-row">'
        +       '<span class="device-details-label">QR value</span>'
        +       '<span class="device-details-value" style="word-break:break-all;font-weight:800;">' + escapeHtml(String(scan.value || '—')) + '</span>'
        +     '</div>'
        + rows.slice(1).map(function(row) {
            return ''
              + '<div class="device-details-row">'
              +   '<span class="device-details-label">' + escapeHtml(row.label) + '</span>'
              +   '<span class="device-details-value">' + escapeHtml(String(row.value || '—')) + '</span>'
              + '</div>';
          }).join('')
        +   '</div>'
        + '</div>';
    }

    function extractWifiConfigFromApi(payload) {
      const root = payload && typeof payload === 'object' ? payload : {};
      const flat = flattenApiPayload(root);
      const data = root.data && typeof root.data === 'object' ? root.data : {};
      const result = root.result && typeof root.result === 'object' ? root.result : {};
      const wifi = root.wifi && typeof root.wifi === 'object' ? root.wifi
        : (root.wifiConfig && typeof root.wifiConfig === 'object' ? root.wifiConfig
        : (data.wifi && typeof data.wifi === 'object' ? data.wifi
        : (data.wifiConfig && typeof data.wifiConfig === 'object' ? data.wifiConfig
        : (result.wifi && typeof result.wifi === 'object' ? result.wifi
        : (result.wifiConfig && typeof result.wifiConfig === 'object' ? result.wifiConfig : {})))));
      const ssid = firstPresent(
        wifi.ssid,
        wifi.SSID,
        wifi.name,
        wifi.network,
        data.ssid,
        data.SSID,
        data.wifi_ssid,
        result.ssid,
        result.SSID,
        result.wifi_ssid,
        root.ssid,
        root.SSID,
        root.wifi_ssid,
        pickApiValue(flat, ['ssid', 'wifi_ssid', 'wifissid', 'wifi_name', 'wifiname', 'network', 'networkname']),
        ''
      );
      const value = firstPresent(ssid, wifi.value, data.wifi, result.wifi, typeof root.wifi === 'string' ? root.wifi : '', '');
      if (value === '') return null;
      return {
        ssid: String(value),
        password: firstPresent(wifi.password, wifi.passphrase, data.password, data.wifi_password, result.password, result.wifi_password, root.password, root.wifi_password, pickApiValue(flat, ['password', 'wifi_password', 'wifipassword', 'wifi_pwd', 'wifipwd', 'passphrase']), '-'),
        status: firstPresent(wifi.status, wifi.connected, data.wifi_status, data.connected, result.wifi_status, result.connected, root.wifi_status, root.connected, pickApiValue(flat, ['wifi_status', 'wifistatus', 'connected', 'status']), 'connected'),
        security: firstPresent(wifi.security, wifi.encryption, data.security, data.encryption, result.security, result.encryption, pickApiValue(flat, ['security', 'encryption', 'authmode', 'auth_mode']), '-'),
        ipAddress: firstPresent(wifi.ip, wifi.ipAddress, data.ip, data.ipAddress, result.ip, result.ipAddress, root.ip, root.ipAddress, pickApiValue(flat, ['ip', 'ipaddress', 'ip_address', 'wifi_ip']), '-'),
        rssi: firstPresent(wifi.rssi, wifi.signal, data.rssi, data.signal, result.rssi, result.signal, root.rssi, root.signal, pickApiValue(flat, ['rssi', 'signal', 'signalstrength', 'wifi_signal']), '-'),
        nodeId: firstPresent(wifi.nodeId, wifi.node_id, data.nodeId, data.node_id, result.nodeId, result.node_id, root.node_id && root.node_id.id, typeof root.node_id === 'string' ? root.node_id : '', pickApiValue(flat, ['node_id', 'nodeid']), getStudioNodeId()),
        apiUrl: root.__apiUrl || ''
      };
    }

    function renderWifiConfigPanel(wifi) {
      if (!deviceInfoContent) return;
      if (!wifi) {
        deviceInfoContent.innerHTML = '<div class="info-modal-state"><strong>No WiFi found</strong><br>Connect WiFi in the app or check node id.</div>';
        return;
      }
      const rows = [
        { label: 'WiFi SSID', value: wifi.ssid },
        { label: 'Password', value: wifi.password || '-' },
        { label: 'Status', value: String(wifi.status) },
        { label: 'Security', value: wifi.security || '-' },
        { label: 'IP address', value: wifi.ipAddress || '-' },
        { label: 'Signal', value: wifi.rssi || '-' },
        { label: 'Node ID', value: wifi.nodeId || '-' },
        { label: 'WiFi API', value: wifi.apiUrl || '-' }
      ];
      deviceInfoContent.innerHTML = '<div class="device-details-card"><div class="device-details-list">'
        + rows.map(function(row, index) {
          return '<div class="device-details-row"><span class="device-details-label">' + escapeHtml(row.label) + '</span><span class="device-details-value" style="word-break:break-all;font-weight:' + (index === 0 ? '800' : '700') + ';">' + escapeHtml(String(row.value || '-')) + '</span></div>';
        }).join('')
        + '</div></div>';
    }

    function fetchScanApiPayload(button, loadingMessage) {
      const scanUrl = typeof buildScanApiUrlForStudio === 'function' ? buildScanApiUrlForStudio() : '';
      const scanNodeId = getStudioNodeId();
      setButtonLoading(button, true, 'Loading');
      if (!scanNodeId) {
        deviceInfoContent.innerHTML = '<div class="info-modal-state">Enter node id first.</div>';
        setStudioStatus('Enter node id first.');
        setButtonLoading(button, false);
        return Promise.resolve(null);
      }
      setStudioStatus(loadingMessage || 'Loading from scan API...');
      return fetch(scanUrl, { method: 'GET', credentials: 'same-origin' })
        .then(function(response) {
          if (!response.ok) throw new Error('Scan API request failed');
          return response.json();
        })
        .then(function(payload) {
          if (payload && typeof payload === 'object') payload.__apiUrl = scanUrl;
          return payload;
        })
        .catch(function() {
          setStudioStatus('Unable to load scan API values.');
          if (typeof showSaveToast === 'function') showSaveToast('Unable to load scan API values.');
          return null;
        })
        .finally(function() {
          setButtonLoading(button, false);
        });
    }

    function openDeviceScannerFromSchema() {
      if (!deviceInfoModal || !phoneShell || !deviceInfoContent) {
        setStudioStatus('Scan view is unavailable in this layout.');
        return;
      }

      resetWifiProvisioningRuntime();
      deviceInfoModal.classList.remove('is-wifi');
      const scanUrl = typeof buildScanApiUrlForStudio === 'function' ? buildScanApiUrlForStudio() : '';
      const scanButton = document.getElementById('device-scan-btn');
      const scanNodeId = getStudioNodeId();
      if (deviceInfoTitle) deviceInfoTitle.textContent = 'Scan Result';

      deviceInfoModal.classList.add('is-open');
      deviceInfoModal.setAttribute('aria-hidden', 'false');
      phoneShell.classList.add('is-showing-info');
      deviceInfoContent.scrollTop = 0;
      deviceInfoContent.innerHTML = '<div class="info-modal-state">Loading scan result…</div>';
      setStudioStatus('Loading scan result from schema API…');

      setStudioStatus('Loading scan result from scan API...');
      setButtonLoading(scanButton, true, 'Loading');

      if (!scanNodeId) {
        deviceInfoContent.innerHTML = '<div class="info-modal-state">Enter node id first, then scan.</div>';
        setStudioStatus('Enter node id first, then click Scan.');
        setButtonLoading(scanButton, false);
        return;
      }

      if (!scanUrl) {
        renderScanResultPanel(null);
        setStudioStatus('Please scan through the app.');
        setButtonLoading(scanButton, false);
        return;
      }

      fetch(scanUrl, { method: 'GET', credentials: 'same-origin' })
        .then(function(response) {
          if (!response.ok) throw new Error('Scan request failed');
          return response.json();
        })
        .then(function(scanResponse) {
          if (scanResponse && typeof scanResponse === 'object') {
            scanResponse.__apiUrl = scanUrl;
          }
          const scan = extractScanResultFromSchema(scanResponse);
          renderScanResultPanel(scan);
          if (scan) {
            setStudioStatus('Scan result loaded from scan API.');
            if (typeof showSaveToast === 'function') showSaveToast('Scan result loaded.');
          } else {
            setStudioStatus('Please scan through the app.');
            if (typeof showSaveToast === 'function') showSaveToast('Please scan through the app.');
          }
        })
        .catch(function() {
          renderScanResultPanel(null);
          setStudioStatus('Please scan through the app.');
          if (typeof showSaveToast === 'function') showSaveToast('Please scan through the app.');
        })
        .finally(function() {
          setButtonLoading(scanButton, false);
        });
    }

    function extractWifiNetworksFromPayload(payload) {
      const found = [];
      function walk(value) {
        if (!value) return;
        if (Array.isArray(value)) {
          value.forEach(walk);
          return;
        }
        if (typeof value !== 'object') return;
        const ssid = firstPresent(value.ssid, value.SSID, value.name, '');
        if (ssid) {
          found.push({
            ssid: String(ssid),
            security: firstPresent(value.security, value.encryption, 'WPA2'),
            securityLabel: firstPresent(value.securityLabel, value.security, value.encryption, 'WPA2'),
            rssi: Number(value.rssi || value.signal || -65),
            frequencyMHz: Number(value.frequencyMHz || value.frequency || 2412)
          });
        }
        Object.keys(value).forEach(function(key) {
          if (key === '__apiUrl' || key === 'ssid' || key === 'SSID' || key === 'name') return;
          walk(value[key]);
        });
      }
      walk(payload);
      return found;
    }

    function filterRouterNetworks(networks) {
      const unique = {};
      (networks || []).forEach(function(net) {
        if (!net || !net.ssid) return;
        if (String(net.ssid).toUpperCase().indexOf('EWIFI_') === 0) return;
        const freq = Number(net.frequencyMHz || 2412);
        if (freq && (freq < 2400 || freq > 2500)) return;
        unique[net.ssid] = net;
      });
      return Object.keys(unique).map(function(ssid) {
        return unique[ssid];
      }).sort(function(a, b) {
        return (Number(b.rssi) || -100) - (Number(a.rssi) || -100);
      });
    }

    function wifiSignalBars(rssi) {
      const value = Number(rssi);
      if (value >= -50) return 4;
      if (value >= -60) return 3;
      if (value >= -70) return 2;
      return 1;
    }

    function wifiSignalLabel(rssi) {
      const bars = wifiSignalBars(rssi);
      if (bars >= 4) return { text: 'Excellent', className: 'is-good' };
      if (bars === 3) return { text: 'Good', className: 'is-good' };
      if (bars === 2) return { text: 'Fair', className: 'is-fair' };
      return { text: 'Weak', className: 'is-weak' };
    }

    function wifiIsOpenNetwork(network) {
      if (!network) return false;
      if (network.open) return true;
      return String(network.security || network.securityLabel || '').toLowerCase() === 'open';
    }

    function wifiSignalHtml(rssi) {
      const bars = wifiSignalBars(rssi);
      let html = '<span class="wifi-signal" aria-hidden="true">';
      for (let index = 1; index <= 4; index += 1) {
        html += '<span' + (index <= bars ? ' class="is-on"' : '') + '></span>';
      }
      return html + '</span>';
    }

    function renderWifiHero(options) {
      const variant = options.variant || 'default';
      const radarClass = 'wifi-radar' + (options.large ? ' is-lg' : '') + (options.staticRadar ? ' is-static' : '');
      const heroClass = 'wifi-hero is-' + variant + (options.center ? ' is-center' : '');
      return '<div class="' + heroClass + '">'
        + '<div class="' + radarClass + '">'
        + '<span class="wifi-radar-ring"></span><span class="wifi-radar-ring"></span><span class="wifi-radar-ring"></span>'
        + '<span class="wifi-radar-core">' + iconSvg(options.icon || 'wifi') + '</span>'
        + '</div>'
        + '<div class="wifi-hero-copy">'
        + (options.kicker ? '<div class="wifi-hero-kicker">' + options.kicker + '</div>' : '')
        + '<h3>' + escapeHtml(options.title || '') + '</h3>'
        + (options.subtitle ? '<p>' + escapeHtml(options.subtitle) + '</p>' : '')
        + (options.extra || '')
        + '</div></div>';
    }

    function wifiMeterCircumference() {
      return 2 * Math.PI * 54;
    }

    function wifiMeterOffset(progress) {
      return wifiMeterCircumference() * (1 - Math.max(0, Math.min(1, Number(progress) || 0)));
    }

    function wifiMeterHtml() {
      const circumference = wifiMeterCircumference();
      return '<div class="wifi-meter" aria-hidden="true">'
        + '<svg viewBox="0 0 120 120">'
        + '<circle cx="60" cy="60" r="54" fill="none" stroke="color-mix(in srgb, var(--ui-muted) 18%, transparent)" stroke-width="8"></circle>'
        + '<circle class="wifi-meter-progress" data-wifi-meter-ring cx="60" cy="60" r="54" fill="none" stroke="var(--ui-accent)" stroke-width="8" stroke-linecap="round" stroke-dasharray="' + circumference.toFixed(2) + '" stroke-dashoffset="' + circumference.toFixed(2) + '"></circle>'
        + '</svg>'
        + '<div class="wifi-meter-label"><strong data-wifi-meter-count>0%</strong><span>Status</span></div>'
        + '</div>';
    }

    function isWifiSetupScreen(screen) {
      return screen === 'deviceDiscovery' || screen === 'provisioning' || screen === 'cloudConfirmation';
    }

    function wifiConnectProgress() {
      const screen = wifiProvisioningRuntime.screen;
      const total = Math.max(1, WIFI_PROVISIONING_STEPS.length);
      if (screen === 'deviceDiscovery') return 0.1;
      if (screen === 'cloudConfirmation') return 0.97;
      if (screen === 'wifiSuccess') return 1;
      const index = Number(wifiProvisioningRuntime.stageIndex) || 0;
      return 0.1 + ((index + 1) / total) * 0.84;
    }

    function wifiConnectStatusCopy() {
      const screen = wifiProvisioningRuntime.screen;
      const ssid = wifiProvisioningRuntime.selectedRouter && wifiProvisioningRuntime.selectedRouter.ssid
        ? wifiProvisioningRuntime.selectedRouter.ssid
        : 'Wi-Fi';
      if (screen === 'deviceDiscovery') {
        return {
          kicker: 'Searching',
          title: 'Finding your device',
          copy: 'Looking for a nearby EWIFI_ setup network.',
          wait: 'Loading, please wait…',
          now: 'Searching for device hotspot'
        };
      }
      if (screen === 'cloudConfirmation') {
        return {
          kicker: 'Almost done',
          title: 'Going online',
          copy: 'Waiting for the device to appear on ' + ssid + '.',
          wait: 'Please wait, almost done…',
          now: 'Confirming cloud connection'
        };
      }
      return {
        kicker: 'Connecting',
        title: WIFI_PROVISIONING_STEPS[wifiProvisioningRuntime.stageIndex] || 'Setting up',
        copy: 'Keep the app open while the device joins your network.',
        wait: 'Loading, please wait…',
        now: WIFI_PROVISIONING_STEPS[wifiProvisioningRuntime.stageIndex] || 'Setting up'
      };
    }

    function updateWifiConnectStatus() {
      if (!deviceInfoContent) return;
      const root = deviceInfoContent.querySelector('[data-wifi-connect-root]');
      if (!root) return;
      const screen = wifiProvisioningRuntime.screen;
      const copy = wifiConnectStatusCopy();
      const progress = wifiConnectProgress();
      const ring = root.querySelector('[data-wifi-meter-ring]');
      const count = root.querySelector('[data-wifi-meter-count]');
      const title = root.querySelector('[data-wifi-connect-title]');
      const kicker = root.querySelector('[data-wifi-connect-kicker]');
      const note = root.querySelector('[data-wifi-connect-copy]');
      const wait = root.querySelector('[data-wifi-connect-wait-text]');
      const now = root.querySelector('[data-wifi-connect-now]');
      const nowWrap = root.querySelector('[data-wifi-connect-now-wrap]');
      const chip = root.querySelector('[data-wifi-connect-chip]');
      root.setAttribute('data-wifi-screen', screen);
      if (ring) {
        if (!ring.style.strokeDashoffset) {
          ring.style.strokeDashoffset = wifiMeterCircumference().toFixed(2);
          window.requestAnimationFrame(function() {
            ring.style.strokeDashoffset = wifiMeterOffset(progress).toFixed(2);
          });
        } else {
          ring.style.strokeDashoffset = wifiMeterOffset(progress).toFixed(2);
        }
      }
      if (count) count.textContent = Math.round(progress * 100) + '%';
      if (kicker) kicker.textContent = copy.kicker;
      if (note) note.textContent = copy.copy;
      if (wait) wait.textContent = copy.wait || 'Loading, please wait…';
      if (now) now.textContent = copy.now;
      if (nowWrap) nowWrap.classList.toggle('is-done', screen === 'cloudConfirmation');
      if (chip) chip.classList.toggle('is-visible', screen === 'deviceDiscovery');
      if (title && title.textContent !== copy.title) {
        title.classList.add('is-swap');
        window.clearTimeout(wifiProvisioningRuntime.statusFadeTimer);
        wifiProvisioningRuntime.statusFadeTimer = window.setTimeout(function() {
          if (!wifiProvisioningRuntime.active) return;
          title.textContent = copy.title;
          title.classList.remove('is-swap');
        }, 180);
      }
      const index = Number(wifiProvisioningRuntime.stageIndex) || 0;
      const dots = root.querySelectorAll('.wifi-connect-dot');
      dots.forEach(function(dot, dotIndex) {
        dot.classList.remove('is-done', 'is-current');
        if (screen === 'cloudConfirmation' || (screen === 'provisioning' && dotIndex < index)) {
          dot.classList.add('is-done');
        } else if (screen === 'provisioning' && dotIndex === index) {
          dot.classList.add('is-current');
        }
      });
    }

    function renderWifiConnectStatusHtml() {
      const screen = wifiProvisioningRuntime.screen || 'provisioning';
      const copy = wifiConnectStatusCopy();
      const softAp = wifiProvisioningRuntime.selectedDeviceSoftAp && wifiProvisioningRuntime.selectedDeviceSoftAp.ssid
        ? wifiProvisioningRuntime.selectedDeviceSoftAp.ssid
        : 'EWIFI_';
      const dotsHtml = WIFI_PROVISIONING_STEPS.map(function() {
        return '<span class="wifi-connect-dot"></span>';
      }).join('');
      return '<div class="wifi-screen" data-wifi-screen="' + escapeHtml(screen) + '" data-wifi-connect-root="1">'
        + '<div class="wifi-connect">'
        + wifiMeterHtml()
        + '<div class="wifi-connect-kicker" data-wifi-connect-kicker>' + escapeHtml(copy.kicker) + '</div>'
        + '<h3 class="wifi-connect-title" data-wifi-connect-title>' + escapeHtml(copy.title) + '</h3>'
        + '<p class="wifi-connect-copy" data-wifi-connect-copy>' + escapeHtml(copy.copy) + '</p>'
        + '<span class="wifi-chip is-best wifi-connect-chip' + (screen === 'deviceDiscovery' ? ' is-visible' : '') + '" data-wifi-connect-chip>' + escapeHtml(softAp) + '</span>'
        + '<div class="wifi-connect-dots" aria-hidden="true">' + dotsHtml + '</div>'
        + '<p class="wifi-connect-wait" role="status" aria-live="polite"><span class="wifi-connect-wait-dot" aria-hidden="true"></span><span data-wifi-connect-wait-text>' + escapeHtml(copy.wait || 'Loading, please wait…') + '</span></p>'
        + '<div class="wifi-connect-now' + (screen === 'cloudConfirmation' ? ' is-done' : '') + '" data-wifi-connect-now-wrap>'
        + '<span class="wifi-connect-now-dot"></span>'
        + '<span data-wifi-connect-now>' + escapeHtml(copy.now) + '</span>'
        + '</div>'
        + '</div></div>';
    }

    function wifiScreenTitle(screen) {
      const titles = {
        wifiNetworkPicker: 'Select Wi-Fi',
        qrScanner: 'Scan QR',
        wifiPassword: 'Enter password',
        deviceDiscovery: 'Connecting',
        provisioning: 'Connecting',
        cloudConfirmation: 'Connecting',
        wifiSuccess: 'Connected',
        wifiError: 'Setup failed'
      };
      return titles[screen] || 'Wi-Fi';
    }

    function renderWifiNetworkPickerHtml() {
      const networks = wifiProvisioningRuntime.availableNetworks || [];
      const selectedSsid = wifiProvisioningRuntime.selectedRouter && wifiProvisioningRuntime.selectedRouter.ssid;
      const scanning = !!wifiProvisioningRuntime.scanning;
      let listHtml;
      if (scanning) {
        listHtml = '<div class="wifi-empty">' + iconSvg('wifi') + '<span>Scanning nearby 2.4 GHz networks…</span></div>';
      } else if (!networks.length) {
        listHtml = '<div class="wifi-empty">' + iconSvg('wifi') + '<span>No 2.4 GHz networks found.</span></div>';
      } else {
        listHtml = networks.map(function(net) {
          const selected = selectedSsid && net.ssid === selectedSsid ? ' is-selected' : '';
          const quality = wifiSignalLabel(net.rssi);
          const open = wifiIsOpenNetwork(net);
          return '<button type="button" class="wifi-net' + selected + '" data-wifi-action="selectRouter" data-ssid="' + escapeHtml(net.ssid) + '">'
            + '<span class="wifi-net-icon">' + iconSvg('wifi') + '</span>'
            + '<span class="wifi-net-copy"><strong>' + escapeHtml(net.ssid) + '</strong>'
            + '<span class="wifi-net-tags">'
            + '<span class="wifi-chip">2.4 GHz</span>'
            + '<span class="wifi-chip">' + escapeHtml(net.securityLabel || net.security || 'WPA2') + '</span>'
            + '<span class="wifi-chip ' + quality.className + '">' + escapeHtml(quality.text) + '</span>'
            + (net.recommended ? '<span class="wifi-chip is-best">Best</span>' : '')
            + '</span></span>'
            + '<span class="wifi-net-side">' + wifiSignalHtml(net.rssi)
            + (open ? '' : iconSvg('lock'))
            + iconSvg('chevron-right') + '</span></button>';
        }).join('');
      }
      return '<div class="wifi-screen" data-wifi-screen="wifiNetworkPicker">'
        + renderWifiHero({
          variant: 'default',
          icon: 'wifi',
          kicker: 'Home network',
          title: 'Choose  Wi-Fi',
          subtitle: 'Your device connects on 2.4 GHz.'
        })
        + '<div class="wifi-section-head"><strong>Nearby networks</strong>'
        + '<button type="button" class="wifi-ghost-btn' + (scanning ? ' is-busy' : '') + '" data-wifi-action="rescan">' + iconSvg('refresh-cw') + '<span>' + (scanning ? 'Scanning' : 'Rescan') + '</span></button></div>'
        + '<div class="wifi-network-list">' + listHtml + '</div>'
        // + '<p class="wifi-studio-note">Studio preview shows sample 2.4 GHz networks. The app scans native Wi-Fi.</p>'
        + '</div>';
    }

    function renderWifiPasswordHtml() {
      const network = wifiProvisioningRuntime.selectedRouter || {};
      const ssid = network.ssid || 'Wi-Fi';
      const open = wifiIsOpenNetwork(network);
      const quality = wifiSignalLabel(network.rssi);
      const inputType = wifiProvisioningRuntime.showPassword ? 'text' : 'password';
      const eyeIcon = wifiProvisioningRuntime.showPassword ? 'eye-off' : 'eye';
      const canContinue = open || String(wifiProvisioningRuntime.routerPassword || '').trim() !== '';
      return '<div class="wifi-screen" data-wifi-screen="wifiPassword">'
        + renderWifiHero({
          variant: 'lock',
          icon: open ? 'wifi' : 'lock',
          staticRadar: true,
          kicker: open ? 'Open network' : 'Protected network',
          title: ssid,
          subtitle: open ? 'This network does not need a password.' : 'Enter the router password. It is not saved in schema.'
        })
        + '<div class="wifi-ssid-card">'
        + '<span class="wifi-net-icon">' + iconSvg('wifi') + '</span>'
        + '<span class="wifi-net-copy"><strong>' + escapeHtml(ssid) + '</strong>'
        + '<span class="wifi-net-tags"><span class="wifi-chip">2.4 GHz</span>'
        + '<span class="wifi-chip">' + escapeHtml(network.securityLabel || network.security || 'WPA2') + '</span>'
        + '<span class="wifi-chip ' + quality.className + '">' + escapeHtml(quality.text) + '</span></span></span>'
        + '<span class="wifi-net-side">' + wifiSignalHtml(network.rssi) + (open ? '' : iconSvg('lock')) + '</span></div>'
        + (open ? '' : ('<div class="wifi-pass-card"><span class="wifi-field-label">Router password</span>'
        + '<div class="wifi-password-row"><span class="wifi-input-icon">' + iconSvg('key') + '</span>'
        + '<input type="' + inputType + '" data-wifi-field="routerPassword" autocomplete="off" value="' + escapeHtml(wifiProvisioningRuntime.routerPassword || '') + '" placeholder="Enter password">'
        + '<button type="button" class="wifi-password-toggle" data-wifi-action="togglePassword" aria-label="Show or hide password">' + iconSvg(eyeIcon) + '</button></div></div>'))
        + '<div class="wifi-actions is-inline"><button type="button" class="wifi-primary-btn" data-wifi-action="continuePassword"' + (canContinue ? '' : ' disabled') + '>' + iconSvg('chevron-right') + '<span>Connect</span></button></div>'
        + '</div>';
    }

    function renderWifiDiscoveryHtml() {
      return renderWifiConnectStatusHtml();
    }

    function renderWifiProvisioningHtml() {
      return renderWifiConnectStatusHtml();
    }

    function renderWifiCloudConfirmationHtml() {
      return renderWifiConnectStatusHtml();
    }

    function renderWifiSuccessHtml() {
      const ssid = wifiProvisioningRuntime.selectedRouter && wifiProvisioningRuntime.selectedRouter.ssid
        ? wifiProvisioningRuntime.selectedRouter.ssid
        : 'Wi-Fi';
      return '<div class="wifi-screen" data-wifi-screen="wifiSuccess">'
        + renderWifiHero({
          variant: 'success',
          icon: 'check-circle',
          staticRadar: true,
          kicker: 'Setup complete',
          title: 'Device connected',
          subtitle: 'The device is online and ready to use.'
        })
        + '<div class="wifi-panel wifi-status-card">'
        + '<div class="wifi-status-icon is-success">' + iconSvg('check') + '</div>'
        + '<h3>You\'re all set</h3>'
        + '<p>Connected to ' + escapeHtml(ssid) + ' and confirmed online.</p>'
        + '<div class="wifi-status-meta"><span class="wifi-chip is-good">Online</span><span class="wifi-chip is-best">' + escapeHtml(ssid) + '</span></div>'
        + '</div>'
        + '<div class="wifi-actions is-inline"><button type="button" class="wifi-primary-btn" data-wifi-action="done">' + iconSvg('check') + '<span>Done</span></button></div>'
        + '</div>';
    }

    function renderWifiErrorHtml() {
      return '<div class="wifi-screen" data-wifi-screen="wifiError">'
        + renderWifiHero({
          variant: 'error',
          icon: 'triangle-alert',
          staticRadar: true,
          kicker: 'Could not finish',
          title: 'Wi-Fi setup failed',
          subtitle: wifiProvisioningRuntime.errorMessage || 'The device could not join the selected network.'
        })
        + '<div class="wifi-panel wifi-status-card">'
        + '<div class="wifi-status-icon is-error">' + iconSvg('triangle-alert') + '</div>'
        + '<h3>Try another network</h3>'
        + '<p>Check the password, stay close to the router, and use a 2.4 GHz network.</p>'
        + '</div>'
        + '<div class="wifi-actions">'
        + '<button type="button" class="wifi-primary-btn" data-wifi-action="retry">' + iconSvg('refresh-cw') + '<span>Try again</span></button>'
        + '</div></div>';
    }

    function stopWifiQrScannerCamera() {
      const stream = wifiProvisioningRuntime.cameraStream;
      if (stream && typeof stream.getTracks === 'function') {
        stream.getTracks().forEach(function(track) {
          track.stop();
        });
      }
      wifiProvisioningRuntime.cameraStream = null;
      const video = deviceInfoContent && deviceInfoContent.querySelector('[data-wifi-scanner-video]');
      if (video) video.srcObject = null;
    }

    function startWifiQrScannerCamera() {
      const video = deviceInfoContent && deviceInfoContent.querySelector('[data-wifi-scanner-video]');
      if (!video) return;
      if (!navigator.mediaDevices || typeof navigator.mediaDevices.getUserMedia !== 'function') {
        setStudioStatus('App opens the camera scanner page to read a QR code.');
        return;
      }
      stopWifiQrScannerCamera();
      navigator.mediaDevices.getUserMedia({
        video: { facingMode: { ideal: 'environment' } },
        audio: false
      }).then(function(stream) {
        if (!wifiProvisioningRuntime.active || wifiProvisioningRuntime.screen !== 'qrScanner') {
          stream.getTracks().forEach(function(track) { track.stop(); });
          return;
        }
        wifiProvisioningRuntime.cameraStream = stream;
        video.srcObject = stream;
        const playResult = video.play();
        if (playResult && typeof playResult.catch === 'function') playResult.catch(function() {});
        setStudioStatus('Point the camera at a QR code.');
      }).catch(function() {
        setStudioStatus('Allow camera access to scan a QR code.');
      });
    }

    function renderWifiQrScannerHtml() {
      return '<div class="wifi-screen" data-wifi-screen="qrScanner">'
        + '<div class="wifi-scanner">'
        + '<video class="wifi-scanner-video" data-wifi-scanner-video autoplay muted playsinline></video>'
        + '<div class="wifi-scanner-overlay">'
        + '<div class="wifi-scanner-frame" aria-hidden="true"><span></span><span></span><span></span><span></span></div>'
        + '<div class="wifi-scanner-copy"><strong>Scan QR</strong><span>Align the QR code inside the frame</span></div>'
        + '</div></div></div>';
    }

    function openWifiQrScanner() {
      if (!wifiProvisioningRuntime.active) return;
      wifiProvisioningRuntime.screen = 'qrScanner';
      renderWifiProvisioningScreen();
      setStudioStatus('Opening camera scanner to read a QR code.');
    }

    function syncWifiHeaderScanButton() {
      const headerScan = document.getElementById('device-wifi-header-scan-btn');
      const screen = wifiProvisioningRuntime.screen || 'wifiNetworkPicker';
      const show = !!(wifiProvisioningRuntime.active && screen === 'wifiNetworkPicker');
      if (headerScan) {
        headerScan.hidden = !show;
        headerScan.classList.remove('is-busy');
      }
      if (deviceInfoModal) {
        deviceInfoModal.classList.toggle('is-scanner', !!(wifiProvisioningRuntime.active && screen === 'qrScanner'));
      }
      if (screen !== 'qrScanner') stopWifiQrScannerCamera();
    }

    function startWifiNetworkRescan() {
      if (!wifiProvisioningRuntime.active || wifiProvisioningRuntime.scanning) return;
      if (wifiProvisioningRuntime.screen !== 'wifiNetworkPicker') return;
      wifiProvisioningRuntime.scanning = true;
      renderWifiProvisioningScreen();
      setStudioStatus('Scanning 2.4 GHz networks…');
      wifiProvisioningRuntime.timers.push(window.setTimeout(function() {
        loadStudioWifiNetworks(true).then(function() {
          wifiProvisioningRuntime.scanning = false;
          if (!wifiProvisioningRuntime.active) return;
          renderWifiProvisioningScreen();
          setStudioStatus('Networks updated. Tap a network to connect.');
        });
      }, 720));
    }

    function renderWifiProvisioningScreen() {
      if (!deviceInfoContent || !wifiProvisioningRuntime.active) return;
      const screen = wifiProvisioningRuntime.screen || 'wifiNetworkPicker';
      if (deviceInfoTitle) deviceInfoTitle.textContent = isWifiSetupScreen(screen) ? 'Connecting' : wifiScreenTitle(screen);
      const currentRoot = deviceInfoContent.querySelector('[data-wifi-connect-root]');
      if (isWifiSetupScreen(screen) && currentRoot) {
        updateWifiConnectStatus();
        syncWifiHeaderScanButton();
        return;
      }
      let html = '';
      if (screen === 'qrScanner') html = renderWifiQrScannerHtml();
      else if (screen === 'wifiPassword') html = renderWifiPasswordHtml();
      else if (isWifiSetupScreen(screen)) html = renderWifiConnectStatusHtml();
      else if (screen === 'wifiSuccess') html = renderWifiSuccessHtml();
      else if (screen === 'wifiError') html = renderWifiErrorHtml();
      else html = renderWifiNetworkPickerHtml();
      deviceInfoContent.innerHTML = html;
      deviceInfoContent.scrollTop = 0;
      const screenEl = deviceInfoContent.querySelector('.wifi-screen');
      if (screenEl) {
        screenEl.classList.add('is-enter');
        screenEl.addEventListener('animationend', function() {
          screenEl.classList.remove('is-enter');
        }, { once: true });
      }
      if (isWifiSetupScreen(screen)) {
        window.requestAnimationFrame(function() {
          window.requestAnimationFrame(updateWifiConnectStatus);
        });
      }
      const passwordInput = deviceInfoContent.querySelector('[data-wifi-field="routerPassword"]');
      if (passwordInput) {
        passwordInput.focus();
        const cursor = passwordInput.value.length;
        passwordInput.setSelectionRange(cursor, cursor);
      }
      syncWifiHeaderScanButton();
      if (screen === 'qrScanner') {
        window.requestAnimationFrame(startWifiQrScannerCamera);
      }
    }

    function startWifiProvisioningSimulation() {
      wifiProvisioningRuntime.screen = 'provisioning';
      wifiProvisioningRuntime.busy = true;
      wifiProvisioningRuntime.stageIndex = 0;
      wifiProvisioningRuntime.stage = WIFI_PROVISIONING_STEPS[0];
      renderWifiProvisioningScreen();
      function tick() {
        if (!wifiProvisioningRuntime.active || wifiProvisioningRuntime.screen !== 'provisioning') return;
        wifiProvisioningRuntime.stageIndex += 1;
        if (wifiProvisioningRuntime.stageIndex >= WIFI_PROVISIONING_STEPS.length) {
          wifiProvisioningRuntime.screen = 'cloudConfirmation';
          wifiProvisioningRuntime.stage = 'Confirming the device is online';
          renderWifiProvisioningScreen();
          setStudioStatus('Confirming the device is online…');
          wifiProvisioningRuntime.timers.push(window.setTimeout(function() {
            if (!wifiProvisioningRuntime.active) return;
            wifiProvisioningRuntime.busy = false;
            wifiProvisioningRuntime.stage = 'success';
            wifiProvisioningRuntime.onlineConfirmed = true;
            wifiProvisioningRuntime.screen = 'wifiSuccess';
            renderWifiProvisioningScreen();
            setStudioStatus('Device connected.');
          }, 900));
          return;
        }
        wifiProvisioningRuntime.stage = WIFI_PROVISIONING_STEPS[wifiProvisioningRuntime.stageIndex];
        renderWifiProvisioningScreen();
        wifiProvisioningRuntime.timers.push(window.setTimeout(tick, 620));
      }
      wifiProvisioningRuntime.timers.push(window.setTimeout(tick, 620));
    }

    function startWifiDeviceDiscovery() {
      const nodeTail = String(getStudioNodeId() || modelNo || 'DEVICE').slice(-6);
      wifiProvisioningRuntime.screen = 'deviceDiscovery';
      wifiProvisioningRuntime.busy = true;
      wifiProvisioningRuntime.selectedDeviceSoftAp = { ssid: 'EWIFI_' + nodeTail, rssi: -48 };
      renderWifiProvisioningScreen();
      setStudioStatus('Finding your Efactor device…');
      wifiProvisioningRuntime.timers.push(window.setTimeout(function() {
        if (!wifiProvisioningRuntime.active) return;
        startWifiProvisioningSimulation();
      }, 1400));
    }

    function loadStudioWifiNetworks(forceDemo) {
      wifiProvisioningRuntime.availableNetworks = WIFI_STUDIO_DEMO_NETWORKS.slice();
      if (forceDemo) return Promise.resolve(wifiProvisioningRuntime.availableNetworks);
      const scanUrl = typeof buildScanApiUrlForStudio === 'function' ? buildScanApiUrlForStudio() : '';
      const scanNodeId = getStudioNodeId();
      if (!scanUrl || !scanNodeId) return Promise.resolve(wifiProvisioningRuntime.availableNetworks);
      return fetch(scanUrl, { method: 'GET', credentials: 'same-origin' })
        .then(function(response) {
          if (!response.ok) throw new Error('Scan API request failed');
          return response.json();
        })
        .then(function(payload) {
          const extracted = filterRouterNetworks(extractWifiNetworksFromPayload(payload));
          if (extracted.length) wifiProvisioningRuntime.availableNetworks = extracted;
          return wifiProvisioningRuntime.availableNetworks;
        })
        .catch(function() {
          return wifiProvisioningRuntime.availableNetworks;
        });
    }

    function goWifiProvisioningBack() {
      if (!wifiProvisioningRuntime.active) {
        closeDeviceInfoModal();
        return;
      }
      const screen = wifiProvisioningRuntime.screen;
      if (screen === 'wifiNetworkPicker' || screen === 'wifiSuccess') {
        closeDeviceInfoModal();
        setStudioStatus('Closed Wi-Fi setup.');
        return;
      }
      clearWifiProvisioningTimers();
      wifiProvisioningRuntime.busy = false;
      wifiProvisioningRuntime.stage = 'idle';
      wifiProvisioningRuntime.stageIndex = 0;
      if (screen === 'qrScanner' || screen === 'wifiPassword' || screen === 'wifiError') {
        wifiProvisioningRuntime.screen = 'wifiNetworkPicker';
      } else {
        wifiProvisioningRuntime.screen = wifiIsOpenNetwork(wifiProvisioningRuntime.selectedRouter)
          ? 'wifiNetworkPicker'
          : 'wifiPassword';
      }
      renderWifiProvisioningScreen();
    }

    function handleDeviceOverlayBack() {
      if (wifiProvisioningRuntime.active) {
        goWifiProvisioningBack();
        return;
      }
      closeDeviceInfoModal();
    }

    function handleWifiProvisioningClick(event) {
      const actionEl = event.target.closest('[data-wifi-action]');
      if (!actionEl || !wifiProvisioningRuntime.active) return;
      const action = actionEl.getAttribute('data-wifi-action');
      if (action === 'selectRouter') {
        const ssid = actionEl.getAttribute('data-ssid');
        const network = (wifiProvisioningRuntime.availableNetworks || []).filter(function(item) {
          return item.ssid === ssid;
        })[0];
        if (!network) return;
        wifiProvisioningRuntime.selectedRouter = network;
        wifiProvisioningRuntime.routerPassword = '';
        wifiProvisioningRuntime.showPassword = false;
        if (wifiIsOpenNetwork(network)) {
          startWifiDeviceDiscovery();
          return;
        }
        wifiProvisioningRuntime.screen = 'wifiPassword';
        renderWifiProvisioningScreen();
        return;
      }
      if (action === 'rescan') {
        startWifiNetworkRescan();
        return;
      }
      if (action === 'togglePassword') {
        const passwordInput = deviceInfoContent.querySelector('[data-wifi-field="routerPassword"]');
        if (passwordInput) wifiProvisioningRuntime.routerPassword = passwordInput.value;
        wifiProvisioningRuntime.showPassword = !wifiProvisioningRuntime.showPassword;
        renderWifiProvisioningScreen();
        return;
      }
      if (action === 'continuePassword') {
        const passwordInput = deviceInfoContent.querySelector('[data-wifi-field="routerPassword"]');
        const password = passwordInput ? String(passwordInput.value || '').trim() : String(wifiProvisioningRuntime.routerPassword || '').trim();
        const isOpen = wifiIsOpenNetwork(wifiProvisioningRuntime.selectedRouter);
        if (!password && !isOpen) {
          setStudioStatus('Enter the Wi-Fi password.');
          if (passwordInput) passwordInput.focus();
          return;
        }
        wifiProvisioningRuntime.routerPassword = password;
        startWifiDeviceDiscovery();
        return;
      }
      if (action === 'done') {
        closeDeviceInfoModal();
        setStudioStatus('Wi-Fi setup complete.');
        return;
      }
      if (action === 'retry') {
        clearWifiProvisioningTimers();
        wifiProvisioningRuntime.errorCode = null;
        wifiProvisioningRuntime.errorMessage = null;
        wifiProvisioningRuntime.stage = 'idle';
        wifiProvisioningRuntime.stageIndex = 0;
        wifiProvisioningRuntime.busy = false;
        wifiProvisioningRuntime.screen = 'wifiNetworkPicker';
        renderWifiProvisioningScreen();
      }
    }


    function handleWifiProvisioningInput(event) {
      if (!wifiProvisioningRuntime.active || !event.target) return;
      if (event.target.getAttribute('data-wifi-field') === 'routerPassword') {
        wifiProvisioningRuntime.routerPassword = event.target.value;
        const continueBtn = deviceInfoContent && deviceInfoContent.querySelector('[data-wifi-action="continuePassword"]');
        if (continueBtn) {
          const isOpen = wifiIsOpenNetwork(wifiProvisioningRuntime.selectedRouter);
          continueBtn.disabled = !isOpen && String(event.target.value || '').trim() === '';
        }
      }
    }

    function openDeviceWifiFromSchema() {
      if (!deviceInfoModal || !phoneShell || !deviceInfoContent) {
        setStudioStatus('WiFi view is unavailable in this layout.');
        return;
      }

      resetWifiProvisioningRuntime();
      wifiProvisioningRuntime.active = true;
      wifiProvisioningRuntime.screen = 'wifiNetworkPicker';
      wifiProvisioningRuntime.availableNetworks = WIFI_STUDIO_DEMO_NETWORKS.slice();
      if (deviceInfoTitle) deviceInfoTitle.textContent = 'Select Wi-Fi';
      deviceInfoModal.classList.add('is-open', 'is-wifi');
      deviceInfoModal.setAttribute('aria-hidden', 'false');
      phoneShell.classList.add('is-showing-info');
      renderWifiProvisioningScreen();
      setStudioStatus('Select your 2.4 GHz Wi-Fi network.');

      loadStudioWifiNetworks(false).then(function() {
        if (!wifiProvisioningRuntime.active || wifiProvisioningRuntime.screen !== 'wifiNetworkPicker') return;
        renderWifiProvisioningScreen();
      });
    }

    function getFilteredIconNames(filterText) {
      const searchTerm = String(filterText || '').trim().toLowerCase();
      const icons = Object.keys(FONTAWESOME_ICONS);
      if (!searchTerm) return icons;
      return icons.filter(function(name) {
        return name.toLowerCase().indexOf(searchTerm) !== -1 ||
          String(ICON_SEARCH_ALIASES[name] || '').toLowerCase().indexOf(searchTerm) !== -1;
      });
    }

    function getRangeInputStep(input) {
      if (!input) return 1;
      const raw = input.getAttribute('step');
      if (raw === null || raw === '') return 1;
      if (raw === 'any') return 0;
      const parsed = parseFloat(raw);
      return Number.isFinite(parsed) ? parsed : 1;
    }

    function snapRangeInputValue(input, value) {
      const min = parseFloat(input.min || '0');
      const max = parseFloat(input.max || '100');
      const step = getRangeInputStep(input);
      let numeric = parseFloat(value);
      if (!Number.isFinite(numeric)) numeric = min;
      let clamped = Math.max(min, Math.min(max, numeric));
      if (step > 0) {
        const steps = Math.round((clamped - min) / step);
        clamped = min + steps * step;
        const stepText = String(step);
        const decimals = stepText.indexOf('.') !== -1 ? (stepText.split('.')[1] || '').length : 0;
        if (decimals > 0) clamped = parseFloat(clamped.toFixed(decimals));
      }
      return clamped;
    }

    function parseRangeInputValue(input) {
      return snapRangeInputValue(input, parseFloat(input.value || input.min || '0'));
    }

    function setRangeInputValue(input, value) {
      if (!input || input.type !== 'range') return parseFloat(value || '0');
      const snapped = snapRangeInputValue(input, value);
      input.value = String(snapped);
      return snapped;
    }

    function formatRangeValue(input) {
      const key = input.dataset.themeKey || '';
      const suffixMap = {
        fontSize: 'px',
        letterSpacing: 'px',
        borderRadius: 'px',
        borderSize: 'px',
        shadowStrength: '%',
        cardBlur: 'px',
        pagePadding: 'px',
        cardPadding: 'px',
        cardSpacing: 'px',
        cardMargin: 'px',
        buttonSize: 'px',
        buttonRadius: 'px',
        headerHeight: 'px',
        iconSize: 'px'
      };
      const numeric = parseRangeInputValue(input);
      if (key === 'lineHeight') {
        const step = getRangeInputStep(input);
        const decimals = step <= 0.05 ? 2 : 1;
        return numeric.toFixed(decimals);
      }
      if (key === 'fontWeight') {
        return String(Math.round(numeric));
      }
      const step = getRangeInputStep(input);
      if (step > 0 && String(step).indexOf('.') !== -1) {
        const decimals = (String(step).split('.')[1] || '').length;
        return numeric.toFixed(decimals) + (suffixMap[key] || '');
      }
      return String(Math.round(numeric)) + (suffixMap[key] || '');
    }

    function updateRangeProgress(input) {
      if (!input || input.type !== 'range') return;
      const min = parseFloat(input.min || '0');
      const max = parseFloat(input.max || '100');
      const value = parseRangeInputValue(input);
      const span = max - min;
      const pct = span > 0 ? ((value - min) / span) * 100 : 0;
      input.style.setProperty('--range-progress', Math.max(0, Math.min(100, pct)) + '%');
    }

    function updateRangeBadge(input) {
      if (!input || input.type !== 'range') return;
      updateRangeProgress(input);
      const rangeField = input.closest('.studio-range-field');
      const legacyField = input.closest('.studio-field');
      const value = formatRangeValue(input);
      if (rangeField) {
        const output = rangeField.querySelector('.studio-range-output');
        if (output) output.textContent = value;
        return;
      }
      if (!legacyField) return;
      legacyField.classList.add('has-range');
      legacyField.dataset.rangeValue = value;
    }

    function parseParamApiMeta(card) {
      try {
        const parsed = JSON.parse(card.dataset.apiMeta || '{}');
        const meta = parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {};
        return normalizeParamApiMeta(meta);
      } catch (error) {
        return {};
      }
    }

    function isUsableApiUiType(uiType) {
      const normalized = String(uiType || '').toLowerCase().trim();
      return Boolean(normalized) && ['none', 'no', 'na', 'n/a', 'null', 'false', 'disabled'].indexOf(normalized) === -1;
    }

    function extractCommandFrameUiType(meta) {
      const frame = meta && meta.frame && typeof meta.frame === 'object' && !Array.isArray(meta.frame) ? meta.frame : {};
      const commands = Array.isArray(frame.commands) ? frame.commands : [];
      let fallback = '';
      for (let index = 0; index < commands.length; index += 1) {
        const field = commands[index];
        if (!field || typeof field !== 'object') continue;
        const uiType = String(field.ui_type || field.uiType || '').trim();
        if (!isUsableApiUiType(uiType)) continue;
        const description = String(field.Field_description || field.field_description || field.default_name || '').toLowerCase().trim();
        if (description === 'data' || description === 'trigger') {
          return uiType;
        }
        if (!fallback) fallback = uiType;
      }
      return fallback;
    }

    function normalizeParamApiMeta(meta) {
      const normalized = meta && typeof meta === 'object' && !Array.isArray(meta) ? Object.assign({}, meta) : {};
      if (isUsableApiUiType(normalized.ui_type) && normalized.ui_type_source) {
        return normalized;
      }
      const commandUiType = extractCommandFrameUiType(normalized);
      if (commandUiType) {
        normalized.ui_type = commandUiType;
        normalized.ui_type_source = 'command';
      }
      return normalized;
    }

    function isApiTextInputType(apiType, apiAccess) {
      apiType = String(apiType || '').toLowerCase().trim();
      apiAccess = String(apiAccess || '').toLowerCase().trim();

      if (!apiType) return false;
      if (apiType === 'console' || apiType === 'cmd' || apiType.indexOf('enter text') !== -1 || apiType === 'entertext') return true;
      if (apiType.indexOf('text field') !== -1 || apiType.indexOf('text input') !== -1) return true;
      // Access no longer gates detection; a read-only text field still renders as a
      // text component and is simply not editable.
      return apiType.indexOf('text') !== -1;
    }

    function resolveApiComponentType(paramName, meta) {
      meta = meta && typeof meta === 'object' && !Array.isArray(meta) ? meta : {};
      const apiType = String(meta.ui_type || '').toLowerCase();
      const apiAccess = String(meta.access || '').toLowerCase();
      const matched = matchApiUiTypeToCatalogId(apiType, paramName);
      if (matched !== 'auto') {
        return matched;
      }
      if (isApiTextInputType(apiType, apiAccess)) {
        return (apiType.indexOf('console') !== -1 || apiType.indexOf('cmd') !== -1) ? 'cmd' : 'enterText';
      }
      return 'auto';
    }

    function detectParamComponentTypeFromApi(card) {
      if (!card) return 'auto';
      return resolveApiComponentType(card.dataset.paramName, parseParamApiMeta(card));
    }

    function detectParamComponentType(card) {
      if (!card) return 'auto';
      const registeredVisual = card.querySelector('.registered-visual');
      if (registeredVisual && card.dataset.componentType && isRegisteredComponentType(card.dataset.componentType)) {
        return card.dataset.componentType;
      }
      const meta = parseParamApiMeta(card);
      const resolved = resolveApiComponentType(card.dataset.paramName, meta);
      if (resolved !== 'auto') {
        return resolved;
      }
      if (Boolean(card.querySelector('.segmented-visual'))) return 'segmented';
      if (Boolean(card.querySelector('.toggle-visual'))) return 'switch';
      if (Boolean(card.querySelector('.range-visual'))) return 'slider';
      if (Boolean(card.querySelector('.pointer-gauge-visual'))) return 'powerGauge';
      if (Boolean(card.querySelector('.needle-gauge-visual'))) return 'needleGauge';
      if (Boolean(card.querySelector('.power-button-ui, .action-dot'))) return 'button';
      const datasetType = card.dataset.componentType || 'auto';
      return datasetType === 'value' ? 'auto' : datasetType;
    }

    function getResolvedParamComponentType(card) {
      if (!card) return 'auto';
      const meta = parseParamApiMeta(card);
      if (isProtocolToggleSwitch(meta)) {
        return 'toggleSwitch';
      }
      const apiType = detectParamComponentTypeFromApi(card);
      if (apiType && apiType !== 'auto' && apiType !== 'value') {
        return apiType;
      }
      const override = getComponentOverride(card.dataset.paramKey);
      const overrideType = override.componentType || 'auto';
      if (overrideType !== 'auto' && overrideType !== 'value') {
        if (getParameterCatalogEntry(overrideType) || getRegisteredComponent(overrideType)) {
          return overrideType;
        }
      }
      return detectParamComponentType(card);
    }

    function flutterWidgetForComponentType(type) {
      const registered = getRegisteredComponent(type);
      if (registered) return registered.name;
      const entry = getComponentLibraryEntry(type);
      if (entry && entry.flutterWidget) return entry.flutterWidget;
      return 'ListTile';
    }

    function removeParamAccessories(card) {
      const valueEl = card.querySelector('.field-value');
      // Read the text value up front: the input now sits inside
      // .param-text-input-wrap (or the cmd console), which is cleared below.
      const existingInput = valueEl ? valueEl.querySelector('input.param-text-input, textarea.param-text-input') : null;
      const preservedValue = existingInput ? existingInput.value : null;
      card.querySelectorAll('.toggle-visual, .action-dot, .power-button-ui, .param-meta, .range-visual, .needle-gauge-visual, .power-gauge-visual, .segmented-visual, .param-dropdown, .param-text-input-wrap, .param-cmd-console, .registered-visual, .linear-gauge-visual, .elevated-action-btn').forEach(function(node) {
        node.remove();
      });
      if (valueEl && preservedValue !== null) {
        valueEl.textContent = preservedValue || valueEl.dataset.defaultValue || '';
      }
    }

    function resolveRangeInitialValue(card, meta, override, safeMin, safeMax) {
      const valueEl = card ? card.querySelector('.field-value') : null;
      const overrideValue = override && override.value !== '' && typeof override.value !== 'undefined' ? parseFloat(override.value) : NaN;
      if (Number.isFinite(overrideValue)) {
        return Math.max(safeMin, Math.min(safeMax, overrideValue));
      }

      const fromField = valueEl ? parseFloat(String(valueEl.textContent || '').trim()) : NaN;
      if (Number.isFinite(fromField)) {
        return Math.max(safeMin, Math.min(safeMax, fromField));
      }

      const defaultFromMeta = meta.default !== null && meta.default !== '' && typeof meta.default !== 'undefined'
        ? parseFloat(meta.default)
        : NaN;
      if (Number.isFinite(defaultFromMeta)) {
        return Math.max(safeMin, Math.min(safeMax, defaultFromMeta));
      }

      return safeMin;
    }

    function updateRangeTrackFill(wrap, value, min, max, options) {
      const opts = options || {};
      const input = wrap ? wrap.querySelector('.param-range-input') : null;
      if (!input) return;

      const safeMin = Number.isFinite(min) ? min : 0;
      let safeMax = Number.isFinite(max) ? max : 100;
      if (safeMax <= safeMin) {
        safeMax = safeMin + 255;
        if (!opts.skipValueAssign) {
        input.max = String(safeMax);
        }
      }

      const numeric = parseFloat(value);
      const clamped = Number.isFinite(numeric) ? Math.max(safeMin, Math.min(safeMax, numeric)) : safeMin;
      const percent = safeMax === safeMin ? 0 : ((clamped - safeMin) / (safeMax - safeMin)) * 100;
      const pct = Math.max(0, Math.min(100, percent)) + '%';
      const componentType = wrap && wrap.dataset.sliderComponentType ? wrap.dataset.sliderComponentType : 'slider';
      const variantConfig = getSliderVariantConfig(componentType);

      if (!opts.skipValueAssign) {
      input.value = String(clamped);
      }
      input.style.setProperty('--range-progress', pct);

      if (variantConfig.thumbFromHue) {
        const hue = resolveSliderHueAngle(clamped, safeMin, safeMax, variantConfig);
        const thumbColor = 'hsl(' + hue + ', 78%, 52%)';
        input.style.setProperty('--range-thumb-color', thumbColor);
        if (wrap) wrap.style.setProperty('--range-swatch-color', thumbColor);
      }

      const currentLabel = wrap.querySelector('.range-current');
      if (currentLabel) {
        currentLabel.textContent = opts.skipValueAssign
          ? formatSliderDisplayValue(value, safeMin, safeMax, variantConfig)
          : formatSliderDisplayValue(clamped, safeMin, safeMax, variantConfig);
      }
    }

    function buildRangeVisualElement(card, meta, override, componentType) {
      const catalogEntry = getParameterCatalogEntry(componentType || '');
      const variantConfig = getSliderVariantConfig(componentType || 'slider');
      const sliderLabel = (catalogEntry && catalogEntry.sliderLabel) || (variantConfig.variant !== 'default' ? String(catalogEntry && catalogEntry.label || '').toUpperCase() : '');
      const min = meta.minimum === null || typeof meta.minimum === 'undefined' || meta.minimum === '' ? 0 : parseFloat(meta.minimum);
      const max = meta.maximum === null || typeof meta.maximum === 'undefined' || meta.maximum === '' ? (variantConfig.defaultHueMax || 255) : parseFloat(meta.maximum);
      const step = meta.step === null || typeof meta.step === 'undefined' || meta.step === '' ? 1 : parseFloat(meta.step);
      const safeMin = Number.isFinite(min) ? min : 0;
      let safeMax = Number.isFinite(max) ? max : (variantConfig.defaultHueMax || 255);
      if (safeMax <= safeMin) {
        safeMax = safeMin + (variantConfig.defaultHueMax || 255);
      }
      const safeStep = Number.isFinite(step) && step > 0 ? step : 1;
      const valueEl = card.querySelector('.field-value');
      const current = resolveRangeInitialValue(card, meta, override, safeMin, safeMax);
      const rangeLabels = buildSliderRangeLabels(safeMin, safeMax, variantConfig);
      const displayValue = formatSliderDisplayValue(current, safeMin, safeMax, variantConfig);
      const wrap = document.createElement('div');
      wrap.className = 'range-visual range-visual--' + variantConfig.variant;
      wrap.dataset.sliderVariant = variantConfig.variant;
      wrap.dataset.sliderComponentType = componentType || 'slider';
      wrap.innerHTML =
        (sliderLabel ? '<div class="range-kicker"><span class="range-kicker-icon">' + iconSvg(variantConfig.icon || 'gauge') + '</span><span>' + escapeHtml(sliderLabel) + '</span></div>' : '') +
        '<div class="range-header">' +
          '<span class="range-min">' + escapeHtml(rangeLabels.minText) + '</span>' +
          '<strong class="range-current">' + escapeHtml(displayValue) + '</strong>' +
          '<span class="range-max">' + escapeHtml(rangeLabels.maxText) + '</span>' +
        '</div>' +
        '<div class="range-track-shell"><div class="range-track-bg" aria-hidden="true"></div></div>';
      const input = document.createElement('input');
      input.type = 'range';
      input.className = 'param-range-input param-component';
      input.min = String(safeMin);
      input.max = String(safeMax);
      input.step = String(safeStep);
      input.value = String(current);
      const trackShell = wrap.querySelector('.range-track-shell');
      if (trackShell) trackShell.appendChild(input);
      updateRangeTrackFill(wrap, current, safeMin, safeMax);
      if (valueEl && !valueEl.querySelector('input, select, textarea')) {
        valueEl.textContent = formatSliderDisplayValue(current, safeMin, safeMax, variantConfig);
      }
      let rangeVisualRaf = 0;
      const syncRangeVisual = function(skipValueAssign) {
        if (rangeVisualRaf) {
          cancelAnimationFrame(rangeVisualRaf);
        }
        rangeVisualRaf = requestAnimationFrame(function() {
          rangeVisualRaf = 0;
          updateRangeTrackFill(wrap, input.value, safeMin, safeMax, { skipValueAssign: skipValueAssign });
          if (valueEl && !valueEl.querySelector('input, select, textarea')) {
            valueEl.textContent = input.value;
          }
        });
      };
      const commitRangeValue = function() {
        if (rangeVisualRaf) {
          cancelAnimationFrame(rangeVisualRaf);
          rangeVisualRaf = 0;
        }
        updateRangeTrackFill(wrap, input.value, safeMin, safeMax);
        if (valueEl && !valueEl.querySelector('input, select, textarea')) {
          valueEl.textContent = input.value;
        }
        getComponentOverride(card.dataset.paramKey).value = input.value;
        generateSchema();
      };
      input.addEventListener('input', function() {
        syncRangeVisual(true);
        getComponentOverride(card.dataset.paramKey).value = input.value;
        scheduleThemeSchemaSync();
      });
      input.addEventListener('change', commitRangeValue);
      requestAnimationFrame(function() {
        updateRangeTrackFill(wrap, input.value, safeMin, safeMax);
      });
      return wrap;
    }

    function appendParamDropdown(card, meta, override) {
      const valueEl = card.querySelector('.field-value');
      const options = parseOptionPairs(meta, card && card.dataset.paramName);
      const select = document.createElement('select');
      select.className = 'param-dropdown param-component is-placeholder';
      select.required = true;
      select.setAttribute('aria-label', 'Choose ' + (card.dataset.paramName || 'parameter'));
      const placeholder = document.createElement('option');
      placeholder.value = '';
      placeholder.textContent = 'Choose';
      placeholder.disabled = true;
      placeholder.selected = true;
      select.appendChild(placeholder);
      options.forEach(function(option) {
        const opt = document.createElement('option');
        opt.value = option.value;
        opt.textContent = option.label;
        select.appendChild(opt);
      });
      const selected = String(override.value || '').trim();
      const hasSelected = selected !== '' && options.some(function(option) {
        return String(option.value) === selected;
      });
      select.value = hasSelected ? selected : '';
      select.classList.toggle('is-placeholder', !hasSelected);
      if (valueEl && hasSelected) valueEl.textContent = selected;
      select.addEventListener('change', function() {
        select.classList.toggle('is-placeholder', select.value === '');
        if (valueEl) valueEl.textContent = select.value;
        getComponentOverride(card.dataset.paramKey).value = select.value;
        generateSchema();
      });
      return select;
    }

    function matchOptionValue(options, raw, paramName) {
      const list = Array.isArray(options) ? options : [];
      const text = String(raw == null ? '' : raw).trim();
      if (!text && list[0]) return list[0].value;
      for (let i = 0; i < list.length; i += 1) {
        if (String(list[i].value) === text || String(list[i].label).toLowerCase() === text.toLowerCase()) {
          return list[i].value;
        }
      }
      if (isDirectionParameter(paramName) && /^(0|1|00|01)$/i.test(text)) {
        for (let i = 0; i < list.length; i += 1) {
          if (/^(0|1|00|01)$/i.test(String(list[i].value)) && parseInt(list[i].value, 10) === parseInt(text, 10)) {
            return list[i].value;
          }
        }
      }
      if (isDirectionParameter(paramName) && /direction/i.test(text) && list[0]) {
        return list[0].value;
      }
      return list[0] ? list[0].value : text;
    }

    function optionLabelForValue(options, value) {
      const list = Array.isArray(options) ? options : [];
      for (let i = 0; i < list.length; i += 1) {
        if (String(list[i].value) === String(value)) return list[i].label;
      }
      return String(value || '');
    }

    function buildSegmentedControlElement(card, meta, override) {
      const valueEl = card.querySelector('.field-value');
      const parsedOptions = parseOptionPairs(meta, card && card.dataset.paramName);
      const options = parsedOptions.length ? parsedOptions : [{ label: 'Low', value: 'Low' }, { label: 'Mid', value: 'Mid' }, { label: 'High', value: 'High' }];
      const rawCurrent = override.value || (valueEl ? valueEl.textContent.trim() : '');
      const current = matchOptionValue(options, rawCurrent, card && card.dataset.paramName);
      const wrap = document.createElement('div');
      const isDirection = isDirectionParameter(card && card.dataset.paramName);
      wrap.className = 'segmented-visual param-component' + (isDirection ? ' is-direction-control' : '');
      wrap.setAttribute('role', 'group');
      wrap.setAttribute('aria-label', 'Select ' + (card.dataset.paramName || 'parameter'));
      wrap.dataset.value = current;
      options.forEach(function(option) {
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'segmented-option' + (String(option.value) === String(current) ? ' is-active' : '');
        btn.dataset.value = option.value;
        if (isDirection) {
          btn.innerHTML = iconSvg(option.icon || directionOptionIcon(option.label)) + '<span>' + escapeHtml(option.label) + '</span>';
        } else {
          btn.textContent = option.label;
        }
        btn.addEventListener('click', function(event) {
          event.stopPropagation();
          wrap.dataset.value = option.value;
          wrap.querySelectorAll('.segmented-option').forEach(function(node) {
            node.classList.toggle('is-active', node === btn);
          });
          if (valueEl && !valueEl.querySelector('input, select, textarea')) {
            valueEl.textContent = isDirection ? option.label : option.value;
          }
          const metaValue = card.querySelector('.meta-value');
          if (metaValue) metaValue.textContent = option.label;
          const paramOverride = getComponentOverride(card.dataset.paramKey);
          paramOverride.value = option.value;
          generateSchema();
        });
        wrap.appendChild(btn);
      });
      if (valueEl && !valueEl.querySelector('input, select, textarea')) {
        valueEl.textContent = isDirection ? optionLabelForValue(options, current) : current;
      }
      return wrap;
    }

    function createInteractiveSwitch(card, override) {
      const valueEl = card.querySelector('.field-value');
      const paramOverride = getComponentOverride(card.dataset.paramKey);
      const isOn = parseToggleInitialValue(paramOverride.value || override.value || (valueEl ? valueEl.textContent : 'OFF'));
      const toggle = document.createElement('button');
      toggle.type = 'button';
      toggle.className = 'toggle-visual param-component param-switch' + (isOn ? ' is-on' : '');
      toggle.setAttribute('aria-pressed', isOn ? 'true' : 'false');
      toggle.setAttribute('aria-label', 'Toggle ' + (card.dataset.paramName || 'parameter'));
      toggle.addEventListener('click', function(event) {
        event.stopPropagation();
        const nextOn = !toggle.classList.contains('is-on');
        toggle.classList.toggle('is-on', nextOn);
        toggle.setAttribute('aria-pressed', nextOn ? 'true' : 'false');
        const nextVal = switchDisplayLabel(paramOverride, nextOn);
        if (valueEl) valueEl.textContent = nextVal;
        paramOverride.value = nextOn ? 'ON' : 'OFF';
        generateSchema();
      });
      if (valueEl && !paramOverride.value && !override.value) {
        valueEl.textContent = switchDisplayLabel(paramOverride, isOn);
      }
      return toggle;
    }

    function createInteractiveButton(card, override, pushButton) {
      const valueEl = card.querySelector('.field-value');
      const paramOverride = getComponentOverride(card.dataset.paramKey);
      const isOn = parseToggleInitialValue(paramOverride.value || override.value || (valueEl ? valueEl.textContent : 'OFF'));
      const button = document.createElement('button');
      button.type = 'button';
      button.className = 'power-button-ui action-dot param-component param-button' + (pushButton ? ' is-push-button' : '') + (isOn ? ' is-on' : ' is-off');
      button.setAttribute('aria-pressed', isOn ? 'true' : 'false');
      button.setAttribute('aria-label', 'Power ' + (card.dataset.paramName || 'parameter'));
      button.innerHTML = '<span class="power-button-ring" aria-hidden="true"></span><span class="power-button-core" aria-hidden="true">' + iconSvg('power-off') + '</span>';
      button.addEventListener('click', function(event) {
        event.stopPropagation();
        const nextOn = !button.classList.contains('is-on');
        button.classList.toggle('is-on', nextOn);
        button.classList.toggle('is-off', !nextOn);
        button.setAttribute('aria-pressed', nextOn ? 'true' : 'false');
        button.classList.add('is-pressed');
        const nextVal = nextOn ? 'ON' : 'OFF';
        if (valueEl) valueEl.textContent = nextVal;
        paramOverride.value = nextVal;
        generateSchema();
        setTimeout(function() { button.classList.remove('is-pressed'); }, 260);
      });
      if (valueEl && !paramOverride.value && !override.value) valueEl.textContent = isOn ? 'ON' : 'OFF';
      return button;
    }

    function createInteractiveElevatedButton(card, override) {
      const valueEl = card.querySelector('.field-value');
      const button = document.createElement('button');
      button.type = 'button';
      button.className = 'elevated-action-btn param-component';
      button.textContent = override.value || (valueEl ? valueEl.textContent.trim() : '') || 'COMMAND';
      button.setAttribute('aria-label', 'Command ' + (card.dataset.paramName || 'parameter'));
      button.addEventListener('click', function(event) {
        event.stopPropagation();
        button.classList.add('is-pressed');
        if (valueEl) valueEl.textContent = button.textContent;
        getComponentOverride(card.dataset.paramKey).value = button.textContent;
        setTimeout(function() { button.classList.remove('is-pressed'); }, 260);
        generateSchema();
      });
      return button;
    }

    function buildLinearGaugeVisualElement(card, meta, override) {
      const valueEl = card.querySelector('.field-value');
      const min = meta.minimum === null || typeof meta.minimum === 'undefined' || meta.minimum === '' ? 0 : parseFloat(meta.minimum);
      const max = meta.maximum === null || typeof meta.maximum === 'undefined' || meta.maximum === '' ? 100 : parseFloat(meta.maximum);
      const safeMin = Number.isFinite(min) ? min : 0;
      const safeMax = Number.isFinite(max) ? max : 100;
      const raw = override && override.value != null && override.value !== ''
        ? override.value
        : (valueEl ? valueEl.textContent.trim() : '75');
      const parsed = parseFloat(String(raw).replace(/[^\d.-]/g, ''));
      const current = Number.isFinite(parsed) ? parsed : 75;
      const clamped = Math.max(safeMin, Math.min(safeMax, current));
      const percent = safeMax === safeMin ? 0 : ((clamped - safeMin) / (safeMax - safeMin)) * 100;
      const wrap = document.createElement('div');
      wrap.className = 'linear-gauge-visual param-component';
      wrap.dataset.value = String(clamped);
      wrap.innerHTML =
        '<div class="linear-gauge-header">' +
          '<span class="linear-gauge-label">Signal</span>' +
          '<strong class="linear-gauge-value">' + escapeHtml(String(Math.round(clamped))) + '%</strong>' +
        '</div>' +
        '<div class="linear-gauge-track"><div class="linear-gauge-fill" style="width:' + percent + '%"></div></div>';
      if (valueEl && !valueEl.querySelector('input, select, textarea')) {
        valueEl.textContent = String(Math.round(clamped));
      }
      return wrap;
    }

    function applyTextFieldComponent(card, override, meta) {
      const valueEl = card.querySelector('.field-value');
      if (!valueEl) return;
      if (!valueEl.dataset.defaultValue) valueEl.dataset.defaultValue = valueEl.textContent;
      const current = override.value || valueEl.dataset.defaultValue || valueEl.textContent || '';
      const editable = textFieldIsEditable(meta || getEffectiveParamMeta(card));
      const label = escapeHtml(card.dataset.paramName || 'parameter');
      // Only an editable field gets a send action; a read-only one has nothing
      // to submit, so the button would be a dead control.
      valueEl.innerHTML = '<span class="param-text-input-wrap param-component">'
        + '<input type="text" class="param-text-input" value="' + escapeHtml(current) + '"'
        + (editable ? '' : ' readonly')
        + ' aria-label="' + label + '">'
        + (editable ? '<button type="button" class="param-send-btn" aria-label="Send ' + label + '">' + iconSvg('send') + '</button>' : '')
        + '</span>';
      const input = valueEl.querySelector('input');
      if (!input || !editable) return;
      input.addEventListener('input', function() {
        valueEl.dataset.liveValue = input.value;
        generateSchema();
      });
      const commit = function() {
        valueEl.dataset.liveValue = input.value;
        getComponentOverride(card.dataset.paramKey).value = input.value;
        generateSchema();
      };
      input.addEventListener('change', commit);
      input.addEventListener('keydown', function(event) {
        if (event.key === 'Enter') {
          event.preventDefault();
          commit();
        }
      });
      const sendBtn = valueEl.querySelector('.param-send-btn');
      if (sendBtn) {
        sendBtn.addEventListener('click', function(event) {
          event.stopPropagation();
          sendBtn.classList.add('is-pressed');
          commit();
          setTimeout(function() { sendBtn.classList.remove('is-pressed'); }, 260);
        });
      }
    }

    function initializeParamComponents() {
      queryPreviewAll('.param-card').forEach(function(card) {
        applyParameterComponentType(card, getResolvedParamComponentType(card));
      });
      resizeAllCmdConsoleFields(phoneShell);
      bindGetStatusResponseDropdown();
    }

    function setGetStatusResponseOpen(panel, open) {
      if (!panel) return;
      const group = panel.closest('.param-group-card');
      panel.classList.toggle('is-open', !!open);
      panel.dataset.expanded = open ? '1' : '0';
      if (group) group.classList.toggle('is-response-open', !!open);
      if (!group) return;
      group.querySelectorAll('.param-card[data-get-status-command="1"]').forEach(function(card) {
        const button = card.querySelector('.param-button, .elevated-action-btn, .power-button-ui, .action-dot');
        if (button) button.setAttribute('aria-expanded', open ? 'true' : 'false');
      });
    }

    function bindGetStatusResponseDropdown() {
      if (window.__getStatusResponseDropdownBound) return;
      window.__getStatusResponseDropdownBound = true;
      document.addEventListener('click', function(event) {
        const commandCard = event.target.closest && event.target.closest('.param-card[data-get-status-command="1"]');
        if (!commandCard) return;
        if (event.target.closest('.param-icon, [data-icon-picker-trigger]')) return;
        const action = event.target.closest('button, .param-button, .elevated-action-btn, .power-button-ui, .action-dot');
        if (!action || !commandCard.contains(action)) return;
        if (action.classList && action.classList.contains('param-icon')) return;
        const group = commandCard.closest('.param-group-card');
        const panel = group ? group.querySelector('.get-status-response-panel') : null;
        if (!panel) return;
        setGetStatusResponseOpen(panel, !panel.classList.contains('is-open'));
      }, true);
    }

    function isStackedComponentType(type) {
      return isStackedParamLayout(type) || isRegisteredComponentType(type);
    }

    function syncParamCardDisplay(card) {
      if (!card) return;
      const override = getComponentOverride(card.dataset.paramKey);
      if (override.hidden || card.classList.contains('is-hidden')) {
        card.style.display = 'none';
        return;
      }
      card.style.removeProperty('display');
    }

    function ensureParamMainRow(card) {
      if (!card) return null;
      let mainRow = card.querySelector('.param-main-row');
      if (!mainRow) {
        mainRow = document.createElement('div');
        mainRow.className = 'param-main-row';
        const stackChildren = '.range-visual, .needle-gauge-visual, .pointer-gauge-visual, .power-gauge-visual, .segmented-visual, .linear-gauge-visual, .registered-visual';
        Array.from(card.children).forEach(function(child) {
          if (!child.matches(stackChildren)) {
            mainRow.appendChild(child);
          }
        });
        card.insertBefore(mainRow, card.firstChild);
      }
      return mainRow;
    }

    function resizeCmdConsoleField(field) {
      if (!field) return;
      field.style.height = 'auto';
      const nextHeight = Math.max(field.scrollHeight || 0, 18);
      field.style.height = nextHeight + 'px';
    }

    function resizeAllCmdConsoleFields(root) {
      const scope = root && root.querySelectorAll ? root : document;
      scope.querySelectorAll('.param-cmd-input, .param-console-input').forEach(resizeCmdConsoleField);
    }

    function setCmdConsoleValue(card, valueText) {
      if (!card) return;
      const field = card.querySelector('.param-cmd-input, .param-console-input');
      const valueEl = card.querySelector('.field-value');
      const nextValue = valueText == null ? '' : String(valueText);
      if (field) {
        field.value = nextValue;
        resizeCmdConsoleField(field);
      }
      if (valueEl) valueEl.dataset.liveValue = nextValue;
    }

    document.addEventListener('input', function(event) {
      const field = event.target;
      if (!field || !field.classList) return;
      if (!field.classList.contains('param-cmd-input') && !field.classList.contains('param-console-input')) return;
      resizeCmdConsoleField(field);
      const valueEl = field.closest('.field-value');
      if (valueEl) valueEl.dataset.liveValue = field.value;
    }, true);

    window.addEventListener('resize', function() {
      resizeAllCmdConsoleFields(phoneShell);
    });

    function applyReadOnlyFieldComponent(card, override, options) {
      options = options || {};
      const valueEl = card.querySelector('.field-value');
      if (!valueEl) return;
      const existingCmd = valueEl.querySelector('.param-cmd-input');
      const current = override.value
        || (existingCmd ? existingCmd.value : '')
        || valueEl.dataset.liveValue
        || (!existingCmd ? valueEl.textContent.trim() : '')
        || '';
      if (options.cmd) {
        valueEl.innerHTML = '<span class="param-cmd-console param-component">'
          + '<span class="param-cmd-prompt" aria-hidden="true">&gt;</span>'
          + '<textarea class="param-text-input param-cmd-input" readonly rows="1" aria-label="' + escapeHtml(card.dataset.paramName || 'cmd') + '">' + escapeHtml(current) + '</textarea>'
          + '</span>';
        valueEl.dataset.liveValue = current;
        resizeCmdConsoleField(valueEl.querySelector('.param-cmd-input'));
        return;
      }
      if (options.toast) {
        valueEl.innerHTML = '<span class="param-toast-display param-component">' + escapeHtml(current || 'Toast message') + '</span>';
        return;
      }
      valueEl.textContent = current || '—';
    }

    function applyParameterComponentType(card, type) {
      if (!card || !type) return;
      if (type === 'auto' || type === 'value') {
        type = detectParamComponentType(card);
      }
      const catalogEntry = getParameterCatalogEntry(type);
      const renderType = resolveParameterRenderType(type);
      const override = getComponentOverride(card.dataset.paramKey);
      const meta = getEffectiveParamMeta(card);
      removeParamAccessories(card);
      card.classList.remove('layout-stacked', 'is-registered-component', 'has-push-button');
      const mainRow = ensureParamMainRow(card);

      if (renderType === 'switch') {
        mainRow.appendChild(createInteractiveSwitch(card, override));
      } else if (renderType === 'slider') {
        card.classList.add('layout-stacked');
        card.appendChild(buildRangeVisualElement(card, meta, override, type));
      } else if (renderType === 'needleGauge') {
        card.classList.add('layout-stacked');
        card.appendChild(buildNeedleGaugeVisualElement(card, meta, override));
      } else if (renderType === 'powerGauge') {
        card.classList.add('layout-stacked');
        card.appendChild(buildPointerGaugeVisualElement(card, meta, override, type));
      } else if (renderType === 'button') {
        card.classList.toggle('has-push-button', Boolean(catalogEntry && catalogEntry.pushButton));
        mainRow.appendChild(createInteractiveButton(card, override, catalogEntry && catalogEntry.pushButton));
      } else if (renderType === 'elevatedButton') {
        mainRow.appendChild(createInteractiveElevatedButton(card, override));
      } else if (renderType === 'linearGauge') {
        card.classList.add('layout-stacked');
        card.appendChild(buildLinearGaugeVisualElement(card, meta, override));
      } else if (renderType === 'dropdown') {
        mainRow.appendChild(appendParamDropdown(card, meta, override));
      } else if (renderType === 'segmented') {
        card.classList.add('layout-stacked');
        card.appendChild(buildSegmentedControlElement(card, meta, override));
      } else if (renderType === 'textField') {
        applyTextFieldComponent(card, override, meta);
      } else if (renderType === 'cmd') {
        applyReadOnlyFieldComponent(card, override, { cmd: true });
      } else if (renderType === 'toastDisplay') {
        applyReadOnlyFieldComponent(card, override, { toast: true });
      } else if (renderType === 'display') {
        applyReadOnlyFieldComponent(card, override);
      } else if (isRegisteredComponentType(type)) {
        const registered = getRegisteredComponent(type);
        const binding = controlBindingKey(card.dataset.paramKey);
        const valueEl = card.querySelector('.field-value');
        const current = valueEl ? valueEl.textContent.trim() : '';
        if (!override.value && registered) {
          if (registered.valueType === 'number' && registered.defaultValue != null) {
            const defaultValue = String(registered.defaultValue);
            if (valueEl && !current) valueEl.textContent = defaultValue;
            override.value = defaultValue;
          } else if (registered.valueType === 'boolean') {
            const defaultValue = String(registered.defaultValue || 'UNLOCKED');
            if (valueEl && (!current || current === (card.dataset.paramName || 'Parameter'))) valueEl.textContent = defaultValue;
            override.value = defaultValue;
          } else if (registered.valueType === 'enum') {
            const defaultValue = String(registered.defaultValue || (registered.options && registered.options[0] ? registered.options[0].value : ''));
            if (valueEl && (!current || current === (card.dataset.paramName || 'Parameter'))) valueEl.textContent = defaultValue;
            override.value = defaultValue;
          }
        }
        const liveValue = String(getParamLiveValue(card, type, override) || '');
        card.classList.add('is-registered-component', 'layout-stacked');
        card.appendChild(buildRegisteredComponentPreview(card, registered, binding, liveValue));
      }

      card.dataset.componentType = type;
      syncParamCardDisplay(card);
    }

    function parseLockState(value) {
      const normalized = String(value || '').trim().toUpperCase();
      return normalized === 'LOCKED' || normalized === 'LOCK' || normalized === 'ON' || normalized === '1' || normalized === 'TRUE';
    }

    function commitRegisteredValue(card, nextValue, options) {
      const opts = options || {};
      const valueEl = card.querySelector('.field-value');
      const override = getComponentOverride(card.dataset.paramKey);
      const textValue = String(nextValue);
      override.value = textValue;
      const visual = card.querySelector('.registered-visual');
      if (visual) visual.dataset.value = textValue;
      if (valueEl && !valueEl.querySelector('input, select, textarea')) {
        valueEl.textContent = textValue;
      }
      if (opts.refresh !== false && visual && visual.dataset.registeredType) {
        refreshRegisteredComponentPreview(card);
      } else {
        generateSchema();
      }
    }

    function buildToggleButtonPreview(card, registered, binding, liveValue) {
      const wrap = document.createElement('div');
      const isLocked = parseLockState(liveValue);
      const stateLabel = isLocked ? 'LOCKED' : 'UNLOCKED';
      wrap.className = 'registered-interactive registered-interactive--toggle' + (isLocked ? ' is-locked' : '');
      wrap.setAttribute('role', 'button');
      wrap.setAttribute('tabindex', '0');
      wrap.setAttribute('aria-pressed', isLocked ? 'true' : 'false');
      wrap.innerHTML =
        '<span class="registered-toggle-icon">' + iconSvg(isLocked ? 'lock' : 'unlock') + '</span>' +
        '<span>' +
          '<span class="registered-interactive-kicker">LOCK STATUS</span>' +
          '<strong class="registered-interactive-value">' + escapeHtml(stateLabel) + '</strong>' +
        '</span>';
      const toggle = function() {
        const nextLocked = !parseLockState(getParamLiveValue(card, 'toggleButton', getComponentOverride(card.dataset.paramKey)));
        commitRegisteredValue(card, nextLocked ? 'LOCKED' : 'UNLOCKED');
      };
      wrap.addEventListener('click', function(event) {
        event.stopPropagation();
        toggle();
      });
      wrap.addEventListener('keydown', function(event) {
        if (event.key === 'Enter' || event.key === ' ') {
          event.preventDefault();
          toggle();
        }
      });
      return wrap;
    }

    function buildButtonGroupPreview(card, registered, binding, liveValue) {
      const wrap = document.createElement('div');
      wrap.className = 'registered-interactive registered-interactive--group';
      const override = getComponentOverride(card.dataset.paramKey);
      const meta = getEffectiveParamMeta(card);
      const props = buildButtonGroupProps(override, meta, registered, parseOptionPairs(meta, card && card.dataset.paramName));
      const options = Array.isArray(props.options) && props.options.length
        ? props.options
        : [{ label: 'A', value: 'A' }, { label: 'B', value: 'B' }, { label: 'C', value: 'C' }];
      const current = String(liveValue || registered.defaultValue || options[0].value);
      wrap.style.background = props.containerBackgroundColor || '';
      wrap.style.border = (props.containerBorderWidth || 0) + 'px solid ' + (props.containerBorderColor || 'transparent');
      wrap.style.borderRadius = (props.containerBorderRadius || 14) + 'px';
      wrap.style.padding = (props.containerPadding || 12) + 'px';
      wrap.innerHTML =
        '<span class="registered-interactive-kicker">MODE</span>' +
        '<div class="registered-button-group" role="group" aria-label="Mode selector"></div>';
      const group = wrap.querySelector('.registered-button-group');
      if (props.spacing) group.style.gap = props.spacing + 'px';
      options.forEach(function(option) {
        const btn = document.createElement('button');
        btn.type = 'button';
        const isActive = String(option.value) === String(current);
        btn.className = 'registered-group-btn' + (isActive ? ' is-active' : '');
        btn.textContent = option.label;
        btn.dataset.actionValue = option.value;
        btn.style.borderRadius = (props.buttonBorderRadius || 10) + 'px';
        if (isActive) {
          btn.style.background = props.selectedBackgroundColor || '';
          btn.style.color = props.selectedTextColor || '#FFFFFF';
        } else {
          btn.style.background = props.unselectedBackgroundColor || '';
          btn.style.color = props.unselectedTextColor || '';
        }
        btn.addEventListener('click', function(event) {
          event.stopPropagation();
          commitRegisteredValue(card, option.value);
        });
        group.appendChild(btn);
      });
      return wrap;
    }

    function buildFireControlPanelPreview(card, registered, binding, liveValue) {
      const wrap = document.createElement('div');
      wrap.className = 'registered-interactive registered-interactive--fire';
      const options = Array.isArray(registered.options) && registered.options.length
        ? registered.options
        : [{ label: 'START', value: 'START' }, { label: 'STOP', value: 'STOP' }];
      const current = String(liveValue || registered.defaultValue || 'STOP');
      wrap.innerHTML =
        '<span class="registered-interactive-kicker">FIRE SYSTEM</span>' +
        '<div class="registered-button-group" role="group" aria-label="Fire control"></div>' +
        '<strong class="registered-interactive-value" style="margin-top:8px;display:block;">' + escapeHtml(current) + '</strong>';
      const group = wrap.querySelector('.registered-button-group');
      options.forEach(function(option) {
        const btn = document.createElement('button');
        btn.type = 'button';
        const modifier = option.value === 'START' ? ' registered-group-btn--start' : (option.value === 'STOP' ? ' registered-group-btn--stop' : '');
        btn.className = 'registered-group-btn' + modifier + (String(option.value) === String(current) ? ' is-active' : '');
        btn.textContent = option.label;
        btn.addEventListener('click', function(event) {
          event.stopPropagation();
          commitRegisteredValue(card, option.value);
        });
        group.appendChild(btn);
      });
      return wrap;
    }

    function buildSliderWithLabelPreview(card, registered, binding, liveValue) {
      const wrap = document.createElement('div');
      wrap.className = 'registered-interactive registered-interactive--slider';
      const meta = parseParamApiMeta(card);
      const min = registered.min != null ? registered.min : (meta.minimum != null && meta.minimum !== '' ? parseFloat(meta.minimum) : 0);
      const max = registered.max != null ? registered.max : (meta.maximum != null && meta.maximum !== '' ? parseFloat(meta.maximum) : 100);
      const step = registered.step != null ? registered.step : (meta.step != null && meta.step !== '' ? parseFloat(meta.step) : 1);
      const safeMin = Number.isFinite(min) ? min : 0;
      const safeMax = Number.isFinite(max) ? max : 100;
      const safeStep = Number.isFinite(step) ? step : 1;
      const parsed = parseFloat(String(liveValue).replace(/[^\d.-]/g, ''));
      const current = Number.isFinite(parsed) ? Math.max(safeMin, Math.min(safeMax, parsed)) : (registered.defaultValue != null ? registered.defaultValue : 50);
      const percent = safeMax === safeMin ? 0 : ((current - safeMin) / (safeMax - safeMin)) * 100;
      wrap.innerHTML =
        '<div class="registered-slider-header">' +
          '<span class="registered-interactive-kicker">BRIGHTNESS</span>' +
          '<strong class="registered-interactive-value registered-slider-value">' + escapeHtml(String(Math.round(current))) + '</strong>' +
        '</div>' +
        '<div class="registered-slider-track">' +
          '<div class="registered-slider-fill" style="width:' + percent + '%"></div>' +
          '<input type="range" class="registered-slider-input param-component" min="' + safeMin + '" max="' + safeMax + '" step="' + safeStep + '" value="' + current + '" aria-label="Brightness">' +
        '</div>';
      const input = wrap.querySelector('.registered-slider-input');
      const fill = wrap.querySelector('.registered-slider-fill');
      const valueLabel = wrap.querySelector('.registered-slider-value');
      let sliderVisualRaf = 0;
      const updateRegisteredSliderVisual = function(nextValue, skipSchema) {
        const numeric = Math.max(safeMin, Math.min(safeMax, parseFloat(nextValue)));
        const pct = safeMax === safeMin ? 0 : ((numeric - safeMin) / (safeMax - safeMin)) * 100;
        if (fill) fill.style.width = pct + '%';
        if (valueLabel) valueLabel.textContent = String(Math.round(numeric));
        const valueEl = card.querySelector('.field-value');
        const override = getComponentOverride(card.dataset.paramKey);
        override.value = String(Math.round(numeric));
        const visual = card.querySelector('.registered-visual');
        if (visual) visual.dataset.value = String(Math.round(numeric));
        if (valueEl && !valueEl.querySelector('input, select, textarea')) {
          valueEl.textContent = String(Math.round(numeric));
        }
        if (!skipSchema) {
        generateSchema();
        } else {
          scheduleThemeSchemaSync();
        }
      };
      const queueRegisteredSliderVisual = function(nextValue) {
        if (sliderVisualRaf) {
          cancelAnimationFrame(sliderVisualRaf);
        }
        sliderVisualRaf = requestAnimationFrame(function() {
          sliderVisualRaf = 0;
          updateRegisteredSliderVisual(nextValue, true);
        });
      };
      if (input) {
        input.addEventListener('input', function() {
          queueRegisteredSliderVisual(input.value);
        });
        input.addEventListener('change', function() {
          if (sliderVisualRaf) {
            cancelAnimationFrame(sliderVisualRaf);
            sliderVisualRaf = 0;
          }
          updateRegisteredSliderVisual(input.value, false);
        });
      }
      return wrap;
    }

    function buildRegisteredComponentPreview(card, registered, binding, liveValue) {
      const wrap = document.createElement('div');
      wrap.className = 'registered-visual param-component';
      if (registered && registered.id) {
        wrap.dataset.registeredType = registered.id;
      }
      const resolvedBinding = binding || controlBindingKey(card.dataset.paramKey);
      const resolvedValue = typeof liveValue === 'string'
        ? liveValue
        : String(getParamLiveValue(card, card.dataset.componentType, getComponentOverride(card.dataset.paramKey)) || '');
      wrap.dataset.value = resolvedValue;

      const specializedBuilders = {
        toggleButton: buildToggleButtonPreview,
        buttonGroup: buildButtonGroupPreview,
        sliderWithLabel: buildSliderWithLabelPreview,
        fireControlPanel: buildFireControlPanelPreview
      };

      if (registered && specializedBuilders[registered.id]) {
        wrap.appendChild(specializedBuilders[registered.id](card, registered, resolvedBinding, resolvedValue));
        return wrap;
      }

      const widgetTree = substituteRegisteredBindings(
        registered && registered.buildWidgetTree ? registered.buildWidgetTree() : null,
        resolvedBinding,
        resolvedValue
      );
      if (widgetTree) {
        wrap.appendChild(renderRegisteredWidgetNode(widgetTree, card, resolvedBinding, resolvedValue));
      } else {
        wrap.innerHTML =
          '<span class="registered-visual-icon">' + iconSvg((registered && registered.icon) || 'gauge') + '</span>' +
          '<span class="registered-visual-text">' +
            '<span class="registered-visual-kicker">' + escapeHtml((registered && registered.label) || 'Custom Component').toUpperCase() + '</span>' +
            '<span class="registered-visual-value">' + escapeHtml(resolvedValue || 'Live value') + '</span>' +
          '</span>';
      }
      return wrap;
    }

    function getParamIcon(card) {
      if (!card) return currentTheme.parameterIcon || 'gauge';
      const iconButton = card.querySelector('.param-icon');
      const domIcon = iconButton && iconButton.dataset.icon ? String(iconButton.dataset.icon).trim() : '';
      return currentTheme.parameterIcons[card.dataset.paramKey] || domIcon || currentTheme.parameterIcon || 'gauge';
    }

    function getParamMetaIcon(card) {
      if (!card) return 'gauge';
      const metaButton = card.querySelector('.param-meta');
      const domMetaIcon = metaButton && metaButton.dataset.metaIcon ? String(metaButton.dataset.metaIcon).trim() : '';
      const override = getComponentOverride(card.dataset.paramKey);
      return override.metaIcon || domMetaIcon || 'gauge';
    }

    function applyComponentTypeSelection(card, type) {
      if (!card) return;
      const override = getComponentOverride(card.dataset.paramKey);
      if (!type || type === 'auto') {
        delete override.componentType;
        applyParameterComponentType(card, detectParamComponentTypeFromApi(card));
      } else {
        override.componentType = type;
        applyParameterComponentType(card, type);
      }
      applyComponentOverrides();
      generateSchema();
      setStudioStatus('Component updated to ' + getComponentChoiceLabel(type || 'auto') + '. Save changes to keep it.');
      commitThemeHistoryRecord();
    }

    function getComponentOverride(key) {
      currentTheme.componentOverrides = currentTheme.componentOverrides && typeof currentTheme.componentOverrides === 'object' ? currentTheme.componentOverrides : {};
      currentTheme.componentOverrides[key] = currentTheme.componentOverrides[key] && typeof currentTheme.componentOverrides[key] === 'object' && !Array.isArray(currentTheme.componentOverrides[key]) ? currentTheme.componentOverrides[key] : {};
      return currentTheme.componentOverrides[key];
    }

    function getEffectiveComponentColors(override) {
      const source = override || {};
      return {
        cardColor: source.cardColor || currentTheme.cardColor,
        borderColor: source.borderColor || currentTheme.borderColor,
        statusColor: source.statusColor || currentTheme.successColor,
        accentColor: source.accentColor || currentTheme.accentColor,
        iconColor: source.iconColor || currentTheme.iconColor || currentTheme.accentColor,
        textColor: source.textColor || currentTheme.textColor
      };
    }

    function buildComponentOverridePayload(override) {
      const source = override || {};
      const colors = getEffectiveComponentColors(source);
      const payload = {
        title: source.title || null,
        value: source.value != null && source.value !== '' ? String(source.value) : null,
        hidden: Boolean(source.hidden),
        componentType: source.componentType === 'value' ? 'auto' : (source.componentType || 'auto'),
        metaIcon: source.metaIcon || null,
        onLabel: source.onLabel || null,
        offLabel: source.offLabel || null,
        minimum: source.minimum != null && source.minimum !== '' ? source.minimum : null,
        maximum: source.maximum != null && source.maximum !== '' ? source.maximum : null,
        step: source.step != null && source.step !== '' ? source.step : null,
        unit: source.unit || null,
        optionsText: source.optionsText || null,
        colors: colors
      };
      if (Array.isArray(source.options) && source.options.length) {
        payload.options = source.options;
      }
      [
        'selectedBackgroundColor',
        'selectedTextColor',
        'unselectedBackgroundColor',
        'unselectedTextColor',
        'valuePlacement'
      ].forEach(function(key) {
        if (source[key] != null && source[key] !== '') payload[key] = source[key];
      });
      return payload;
    }

    function mergeParamMetaWithOverride(meta, override) {
      const merged = Object.assign({}, meta || {});
      const source = override || {};
      if (source.minimum !== '' && source.minimum != null) merged.minimum = source.minimum;
      if (source.maximum !== '' && source.maximum != null) merged.maximum = source.maximum;
      if (source.step !== '' && source.step != null) merged.step = source.step;
      if (source.unit) merged.unit = source.unit;
      if (source.optionsText) {
        merged.items = String(source.optionsText).split(',').map(function(item) {
          return item.trim();
        }).filter(Boolean);
      }
      if (Array.isArray(source.options) && source.options.length) {
        merged.options = source.options;
      }
      return merged;
    }

    function getEffectiveParamMeta(card) {
      if (!card) return {};
      return mergeParamMetaWithOverride(parseParamApiMeta(card), getComponentOverride(card.dataset.paramKey));
    }

    function buildParameterActionFieldsMarkup(resolvedType, override, meta) {
      const merged = mergeParamMetaWithOverride(meta, override);
      const renderType = resolveParameterRenderType(resolvedType);
      if (renderType === 'slider' || renderType === 'powerGauge' || renderType === 'needleGauge' || renderType === 'linearGauge') {
        const defaultMax = (renderType === 'powerGauge' || renderType === 'needleGauge' || renderType === 'linearGauge') ? 100 : 255;
        const minValue = override.minimum != null && override.minimum !== '' ? override.minimum : (merged.minimum != null && merged.minimum !== '' ? merged.minimum : 0);
        const maxValue = override.maximum != null && override.maximum !== '' ? override.maximum : (merged.maximum != null && merged.maximum !== '' ? merged.maximum : defaultMax);
        const stepValue = override.step != null && override.step !== '' ? override.step : (merged.step != null && merged.step !== '' ? merged.step : 1);
        const unitValue = override.unit || merged.unit || '';
        const rangeLabel = renderType === 'powerGauge' || renderType === 'needleGauge' ? 'Gauge range' : 'Slider range';
        return '<div class="studio-panel-group" style="margin-top:12px">' +
          '<p class="studio-panel-label">Component actions</p>' +
          '<div class="studio-grid">' +
            '<label class="studio-field"><span>' + rangeLabel + ' · Min</span><input type="number" data-param-prop="minimum" value="' + escapeHtml(String(minValue)) + '" step="any"></label>' +
            '<label class="studio-field"><span>Max</span><input type="number" data-param-prop="maximum" value="' + escapeHtml(String(maxValue)) + '" step="any"></label>' +
            '<label class="studio-field"><span>Step</span><input type="number" data-param-prop="step" value="' + escapeHtml(String(stepValue)) + '" step="any" min="0"></label>' +
            ((renderType === 'powerGauge' || renderType === 'needleGauge') ? '<label class="studio-field"><span>Unit label</span><input type="text" data-param-prop="unit" value="' + escapeHtml(unitValue) + '" placeholder="%, °C, kW"></label>' : '') +
          '</div>' +
        '</div>';
      }

      if (renderType === 'segmented' || renderType === 'dropdown' || resolvedType === 'buttonGroup' || resolvedType === 'fireControlPanel') {
        const optionsValue = override.optionsText || (Array.isArray(merged.items) ? merged.items.join(', ') : '');
        const optionsPlaceholder = resolvedType === 'fireControlPanel' ? 'START, STOP' : 'Low, Medium, High';
        return '<div class="studio-panel-group" style="margin-top:12px">' +
          '<p class="studio-panel-label">Component actions</p>' +
          '<label class="studio-field"><span>Options (comma separated)</span><input type="text" data-param-prop="optionsText" value="' + escapeHtml(optionsValue) + '" placeholder="' + escapeHtml(optionsPlaceholder) + '"></label>' +
        '</div>';
      }

      if (renderType === 'switch' || resolvedType === 'toggleButton' || renderType === 'button') {
        const onLabel = override.onLabel || 'ON';
        const offLabel = override.offLabel || 'OFF';
        return '<div class="studio-panel-group" style="margin-top:12px">' +
          '<p class="studio-panel-label">Component actions</p>' +
          '<div class="studio-grid">' +
            '<label class="studio-field"><span>On label</span><input type="text" data-param-prop="onLabel" value="' + escapeHtml(onLabel) + '"></label>' +
            '<label class="studio-field"><span>Off label</span><input type="text" data-param-prop="offLabel" value="' + escapeHtml(offLabel) + '"></label>' +
          '</div>' +
        '</div>';
      }

      return '';
    }

    function refreshParameterComponentAfterActionChange(card, override) {
      if (!card) return;
      const resolvedType = getResolvedParamComponentType(card);
      applyParameterComponentType(card, resolvedType);
      applyComponentOverrides();
      const valueEl = card.querySelector('.field-value');
      const valueText = override && override.value !== '' && override.value != null
        ? String(override.value)
        : (valueEl ? valueEl.textContent.trim() : '');
      if (valueText) {
        syncInteractiveValueFromOverride(card, resolvedType, Object.assign({}, override, { value: valueText }));
      }
    }

    function syncInteractiveValueFromOverride(card, resolvedType, override) {
      if (!card || !override || override.value === '' || typeof override.value === 'undefined' || override.value === null) return;
      const valueEl = card.querySelector('.field-value');
      const valueText = String(override.value);
      const renderType = resolveParameterRenderType(resolvedType);

      if (renderType === 'switch') {
        const isOn = parseToggleInitialValue(valueText);
        const toggle = card.querySelector('.param-switch');
        if (toggle) {
          toggle.classList.toggle('is-on', isOn);
          toggle.setAttribute('aria-pressed', isOn ? 'true' : 'false');
        }
        if (valueEl && !valueEl.querySelector('input, select, textarea')) {
          valueEl.textContent = isOn ? (override.onLabel || 'ON') : (override.offLabel || 'OFF');
        }
        return;
      }

      if (resolvedType === 'toggleButton') {
        const isOn = parseToggleInitialValue(valueText);
        const button = card.querySelector('.toggle-button-ui, .param-toggle-button');
        if (button) {
          button.classList.toggle('is-on', isOn);
          button.textContent = isOn ? (override.onLabel || 'ON') : (override.offLabel || 'OFF');
        }
        if (valueEl && !valueEl.querySelector('input, select, textarea')) {
          valueEl.textContent = isOn ? (override.onLabel || 'ON') : (override.offLabel || 'OFF');
        }
        return;
      }

      if (renderType === 'slider') {
        const meta = getEffectiveParamMeta(card);
        const input = card.querySelector('.param-range-input');
        const parsed = parseFloat(valueText);
        const rangeWrap = card.querySelector('.range-visual');
        const variantConfig = getSliderVariantConfig(resolvedType);
        const min = meta.minimum === null || typeof meta.minimum === 'undefined' || meta.minimum === '' ? 0 : parseFloat(meta.minimum);
        const max = meta.maximum === null || typeof meta.maximum === 'undefined' || meta.maximum === '' ? (variantConfig.defaultHueMax || 255) : parseFloat(meta.maximum);
        const safeMin = Number.isFinite(min) ? min : 0;
        let safeMax = Number.isFinite(max) ? max : (variantConfig.defaultHueMax || 255);
        if (safeMax <= safeMin) {
          safeMax = safeMin + (variantConfig.defaultHueMax || 255);
        }
        if (input && Number.isFinite(parsed)) {
          updateRangeTrackFill(rangeWrap, parsed, safeMin, safeMax);
        }
        if (valueEl && !valueEl.querySelector('input, select, textarea')) {
          valueEl.textContent = Number.isFinite(parsed)
            ? formatSliderDisplayValue(parsed, safeMin, safeMax, variantConfig)
            : valueText;
        }
        return;
      }

      if (renderType === 'powerGauge' || renderType === 'needleGauge') {
        const meta = getEffectiveParamMeta(card);
        const gauge = card.querySelector('.needle-gauge-visual, .pointer-gauge-visual, .power-gauge-visual');
        if (gauge) {
          const bounds = resolveGaugeNumericBounds(meta, valueText);
          updatePowerGaugeVisual(gauge, bounds, card);
        }
        return;
      }

      if (renderType === 'button') {
        const button = card.querySelector('.power-button-ui, .param-button');
        const isOn = parseToggleInitialValue(valueText);
        if (button) {
          button.classList.toggle('is-on', isOn);
          button.classList.toggle('is-off', !isOn);
          button.setAttribute('aria-pressed', isOn ? 'true' : 'false');
        }
        if (valueEl && !valueEl.querySelector('input, select, textarea')) {
          valueEl.textContent = isOn ? 'ON' : 'OFF';
        }
        return;
      }

      if (renderType === 'dropdown') {
        const select = card.querySelector('.param-dropdown');
        if (select) select.value = valueText;
        if (valueEl && !valueEl.querySelector('input, select, textarea')) valueEl.textContent = valueText;
        return;
      }

      if (renderType === 'segmented') {
        const wrap = card.querySelector('.segmented-visual');
        if (wrap) {
          wrap.dataset.value = valueText;
          wrap.querySelectorAll('.segmented-option').forEach(function(node) {
            node.classList.toggle('is-active', String(node.dataset.value) === String(valueText));
          });
        }
        if (valueEl && !valueEl.querySelector('input, select, textarea')) valueEl.textContent = valueText;
        const metaValue = card.querySelector('.meta-value');
        if (metaValue) metaValue.textContent = valueText;
        return;
      }

      if (renderType === 'textField') {
        const input = card.querySelector('.param-text-input:not(.param-cmd-input)');
        if (input) {
          input.value = valueText;
          if (valueEl) valueEl.dataset.liveValue = valueText;
        }
        return;
      }

      if (renderType === 'cmd') {
        setCmdConsoleValue(card, valueText);
        return;
      }

      if (renderType === 'elevatedButton') {
        const button = card.querySelector('.elevated-action-btn');
        if (button) button.textContent = valueText;
        return;
      }

      if (isRegisteredComponentType(resolvedType)) {
        refreshRegisteredComponentPreview(card);
        return;
      }

      if (renderType === 'linearGauge') {
        const meta = parseParamApiMeta(card);
        const gauge = card.querySelector('.linear-gauge-visual');
        if (gauge) {
          const rebuilt = buildLinearGaugeVisualElement(card, meta, override);
          gauge.replaceWith(rebuilt);
        }
      }
    }

    function switchDisplayLabel(override, isOn) {
      const source = override || {};
      return isOn ? (source.onLabel || 'ON') : (source.offLabel || 'OFF');
    }

    function applyComponentOverrides() {
      queryPreviewAll('.param-card').forEach(function(card) {
        const override = getComponentOverride(card.dataset.paramKey);
        const colors = getEffectiveComponentColors(override);
        const label = card.querySelector('.field-label');
        const value = card.querySelector('.field-value');

        if (value && !value.dataset.defaultValue && !value.querySelector('.param-cmd-input')) {
          value.dataset.defaultValue = value.textContent;
        }
        // Grouped cards render no caption at all, so this only ever runs for
        // standalone cards where the label is the parameter name.
        if (label) {
          const paramName = card.dataset.paramName || '';
          const typeName = card.dataset.componentLabel || '';
          const groupedMulti = card.classList.contains('is-grouped-component');
          if (groupedMulti) {
            const customTitle = override.title && override.title !== paramName ? override.title : '';
            label.textContent = customTitle || typeName || label.textContent || 'UI';
          } else {
            label.textContent = override.title || paramName || 'Parameter';
          }
          if (override.textColor) {
            label.style.color = colors.textColor;
          } else {
            label.style.removeProperty('color');
          }
        }
        if (value) {
          const interactiveField = value.querySelector('input, select, textarea');
          const isCmdField = interactiveField && interactiveField.classList.contains('param-cmd-input');
          // The cmd console keeps its own palette: a theme text colour picked for
          // a white card would be unreadable on the black terminal.
          if (isCmdField) {
            if (override.value !== '' && typeof override.value !== 'undefined' && override.value !== null) {
              setCmdConsoleValue(card, override.value);
            } else {
              resizeCmdConsoleField(interactiveField);
            }
            value.style.removeProperty('color');
          } else if (interactiveField) {
            const isDropdownPlaceholder = interactiveField.classList.contains('param-dropdown')
              && (interactiveField.value === '' || interactiveField.classList.contains('is-placeholder'));
            if (isDropdownPlaceholder) {
              interactiveField.style.removeProperty('color');
            } else {
              interactiveField.style.color = themeInputTextColor(colors.textColor);
            }
            interactiveField.style.backgroundColor = themeInputFillColor(colors.cardColor);
            interactiveField.style.borderColor = currentTheme.borderColor || '';
          } else {
          value.textContent = card.classList.contains('is-grouped-component')
            ? (override.value || card.dataset.componentValue || value.dataset.defaultValue || '')
            : (override.value || value.dataset.defaultValue || '');
          value.style.color = colors.textColor;
          }
        }

        if (override.cardColor) {
          card.style.background = colors.cardColor;
        } else {
          card.style.removeProperty('background');
        }
        if (override.borderColor) {
          card.style.borderColor = colors.borderColor;
        } else {
          card.style.removeProperty('border-color');
        }

        const iconButton = card.querySelector('.param-icon');
        if (iconButton) {
          if (override.iconColor) {
            iconButton.style.color = colors.iconColor;
          } else {
            iconButton.style.removeProperty('color');
          }
        }

        const metaButton = card.querySelector('.param-meta');
        if (metaButton) {
          const sequenceValue = metaButton.querySelector('.meta-value') ? metaButton.querySelector('.meta-value').textContent : card.dataset.sequence || '';
          const metaIcon = getParamMetaIcon(card);
          metaButton.innerHTML = iconSvg(metaIcon) + '<span class="meta-value">' + escapeHtml(sequenceValue || '') + '</span>';
          metaButton.dataset.metaIcon = metaIcon;
        }

        if (override.statusColor) {
          const meta = card.querySelector('.param-meta');
          if (meta) meta.style.background = colors.statusColor;
          const dot = card.querySelector('.action-dot');
          if (dot) dot.style.background = colors.statusColor;
        } else {
          const meta = card.querySelector('.param-meta');
          if (meta) meta.style.removeProperty('background');
          const dot = card.querySelector('.action-dot');
          if (dot) dot.style.removeProperty('background');
        }

        card.classList.toggle('is-hidden', Boolean(override.hidden));
        syncParamCardDisplay(card);

        const resolvedType = getResolvedParamComponentType(card);
        if (!card.dataset.componentType || card.dataset.componentType !== resolvedType) {
          applyParameterComponentType(card, resolvedType);
        } else if (isRegisteredComponentType(resolvedType)) {
          refreshRegisteredComponentPreview(card);
        } else if (override.value !== '' && typeof override.value !== 'undefined' && override.value !== null) {
          syncInteractiveValueFromOverride(card, resolvedType, override);
        }

          const accentFill = colors.accentColor;
          card.querySelectorAll('.param-range-input').forEach(function(input) {
            input.style.setProperty('--ui-accent', accentFill);
          });
        card.querySelectorAll('.segmented-option').forEach(function(button) {
          if (button.classList.contains('is-active')) {
            button.style.background = override.accentColor ? accentFill : '';
            button.style.color = override.accentColor ? '#FFFFFF' : '';
          } else {
            button.style.removeProperty('background');
            button.style.removeProperty('color');
          }
        });
        const linearFill = card.querySelector('.linear-gauge-fill');
        if (linearFill) {
          linearFill.style.background = override.accentColor ? accentFill : '';
        }
          const gaugeWrap = card.querySelector('.needle-gauge-visual, .pointer-gauge-visual, .power-gauge-visual');
          if (gaugeWrap) {
            const prevAccent = currentTheme.accentColor;
          currentTheme.accentColor = accentFill;
            const meta = getEffectiveParamMeta(card);
            const bounds = resolveGaugeNumericBounds(meta, gaugeWrap.dataset.value || '');
            updatePowerGaugeVisual(gaugeWrap, bounds, card);
            currentTheme.accentColor = prevAccent;
        }
      });
    }

    // Slider Navigation
    function showSlide(index) {
      if (!slides.length || !track) return;

      activeIndex = Math.max(0, Math.min(index, slides.length - 1));
      const targetSlide = slides[activeIndex];
      const slideWindow = track.parentElement;
      const viewportWidth = slideWindow && slideWindow.clientWidth
        ? slideWindow.clientWidth
        : (phoneShell ? phoneShell.clientWidth : 0);
      const targetOffset = viewportWidth > 0 ? activeIndex * viewportWidth : (targetSlide ? targetSlide.offsetLeft : 0);
      track.style.transform = 'translateX(-' + targetOffset + 'px)';

      pageButtons.forEach((button, buttonIndex) => {
        button.classList.toggle('is-active', buttonIndex === activeIndex);
      });

      if (prevButton) prevButton.disabled = activeIndex === 0;
      if (nextButton) nextButton.disabled = activeIndex === slides.length - 1;
      if (progressBar) progressBar.style.width = (((activeIndex + 1) / slides.length) * 100) + '%';

      if (targetSlide) {
        if (title) title.textContent = targetSlide.dataset.pageTitle || 'Model UI';
        if (subtitle) subtitle.textContent = 'Page ' + (targetSlide.dataset.pageNo || (activeIndex + 1)) + '.Operation';
        targetSlide.scrollTop = 0;
      }
    }

    function syncSlideViewportWidth() {
      if (!track) return;
      const slideWindow = track.parentElement;
      const viewportWidth = slideWindow && slideWindow.clientWidth
        ? slideWindow.clientWidth
        : (phoneShell ? phoneShell.clientWidth : 0);
      if (viewportWidth > 0) {
        track.style.setProperty('--slide-viewport-width', viewportWidth + 'px');
      }
      showSlide(activeIndex);
    }

    function attemptHorizontalPageNav(delta) {
      if (!slides.length) return false;
      const now = Date.now();
      if (now - lastHorizontalNavAt < 220) return false;
      const threshold = 26;
      if (Math.abs(delta) < threshold) return false;
      const direction = delta > 0 ? 1 : -1;
      const nextIndex = activeIndex + direction;
      if (nextIndex < 0 || nextIndex >= slides.length) return false;
      lastHorizontalNavAt = now;
      showSlide(nextIndex);
      return true;
    }

    function getPreviewScrollTarget() {
      if (!phoneShell) return null;
      if (phoneShell.classList.contains('is-showing-info')) {
        return phoneShell.querySelector('.device-details-body');
      }
      if (!slides.length) {
        return phoneShell.querySelector('.empty-ui');
      }
      return slides[activeIndex] || slides[0] || null;
    }

    function forwardPreviewWheel(event) {
      if (Math.abs(event.deltaX) > Math.abs(event.deltaY)) {
        if (attemptHorizontalPageNav(event.deltaX)) {
          event.preventDefault();
          return true;
        }
        return false;
      }
      const scrollTarget = getPreviewScrollTarget();
      if (!scrollTarget) return false;
      const maxScroll = scrollTarget.scrollHeight - scrollTarget.clientHeight;
      if (maxScroll <= 0) return false;
      const nextScrollTop = scrollTarget.scrollTop + event.deltaY;
      if ((event.deltaY < 0 && scrollTarget.scrollTop <= 0 && nextScrollTop <= 0) ||
          (event.deltaY > 0 && scrollTarget.scrollTop >= maxScroll && nextScrollTop >= maxScroll)) {
        return false;
      }
      scrollTarget.scrollTop = Math.max(0, Math.min(maxScroll, nextScrollTop));
      event.preventDefault();
      return true;
    }

    function bindSlideSwipe() {
      if (!track || !track.parentElement) return;
      const swipeHost = track.parentElement;
      let startX = 0;
      let startY = 0;
      let tracking = false;

      swipeHost.addEventListener('touchstart', function(event) {
        if (!event.touches || !event.touches.length) return;
        const touch = event.touches[0];
        startX = touch.clientX;
        startY = touch.clientY;
        tracking = true;
      }, { passive: true });

      swipeHost.addEventListener('touchend', function(event) {
        if (!tracking || !event.changedTouches || !event.changedTouches.length) return;
        const touch = event.changedTouches[0];
        const dx = touch.clientX - startX;
        const dy = touch.clientY - startY;
        tracking = false;
        if (Math.abs(dx) > Math.abs(dy) && Math.abs(dx) > 40) {
          attemptHorizontalPageNav(-dx);
        }
      }, { passive: true });
    }

    function getMobileViewportElement() {
      if (!phoneShell) return null;
      if (phoneShell.classList.contains('is-showing-info')) {
        return phoneShell.querySelector('.device-details-view') || phoneShell.querySelector('.device-details-body');
      }
      if (!slides.length) {
        return phoneShell.querySelector('.empty-ui');
      }
      return phoneShell.querySelector('.slide-window');
    }

    function isPointerOverMobileViewport(clientX, clientY) {
      const viewport = getMobileViewportElement();
      if (!viewport) return false;
      const rect = viewport.getBoundingClientRect();
      return clientX >= rect.left && clientX <= rect.right && clientY >= rect.top && clientY <= rect.bottom;
    }

    function getActivePreviewMount() {
      return document.body.classList.contains('studio-open') ? studioPreviewMount : pagePreviewMount;
    }

    function handlePreviewWheel(event) {
      if (event.ctrlKey) return;
      if (!isPointerOverMobileViewport(event.clientX, event.clientY)) return;

      if (phoneShell && phoneShell.classList.contains('is-showing-info')) {
        const infoBody = phoneShell.querySelector('.device-details-body');
        if (infoBody) {
          const maxScroll = infoBody.scrollHeight - infoBody.clientHeight;
          if (maxScroll > 0) {
            infoBody.scrollTop = Math.max(0, Math.min(maxScroll, infoBody.scrollTop + event.deltaY));
            event.preventDefault();
            event.stopPropagation();
          }
          return;
        }
      }

      if (forwardPreviewWheel(event)) {
        event.preventDefault();
        event.stopPropagation();
        return;
      }
      const scrollTarget = getPreviewScrollTarget();
      const mount = getActivePreviewMount();
      if (!scrollTarget || !mount) return;
      const maxScroll = scrollTarget.scrollHeight - scrollTarget.clientHeight;
      if (maxScroll <= 0) return;
      const atTop = scrollTarget.scrollTop <= 0 && event.deltaY < 0;
      const atBottom = scrollTarget.scrollTop >= maxScroll && event.deltaY > 0;
      if (!atTop && !atBottom) {
        event.preventDefault();
        event.stopPropagation();
      }
    }

    function bindPreviewScrollBridge() {
      document.addEventListener('wheel', handlePreviewWheel, { passive: false, capture: true });
    }

    bindPreviewScrollBridge();
    bindSlideSwipe();

    if (prevButton) {
      prevButton.addEventListener('click', function() {
        showSlide(activeIndex - 1);
      });
    }

    if (nextButton) {
      nextButton.addEventListener('click', function() {
        showSlide(activeIndex + 1);
      });
    }

    pageButtons.forEach(function(button) {
      button.addEventListener('click', function() {
        showSlide(parseInt(button.dataset.slideIndex || '0', 10));
      });
    });

    window.addEventListener('resize', function() {
      syncSlideViewportWidth();
    });

    const TYPOGRAPHY_KEYS = ['fontFamily', 'fontSize', 'fontWeight', 'letterSpacing', 'lineHeight', 'textAlign'];

    function normalizePageTypographyStore() {
      currentTheme.pageTypography = currentTheme.pageTypography && typeof currentTheme.pageTypography === 'object' && !Array.isArray(currentTheme.pageTypography)
        ? currentTheme.pageTypography
        : {};
    }

    function getTypographyForPage(pageNo) {
      normalizePageTypographyStore();
      const typography = {};
      TYPOGRAPHY_KEYS.forEach(function(key) {
        typography[key] = currentTheme[key];
      });
      const override = currentTheme.pageTypography[String(pageNo)];
      if (override && typeof override === 'object') {
        TYPOGRAPHY_KEYS.forEach(function(key) {
          if (override[key] !== undefined && override[key] !== null && override[key] !== '') {
            typography[key] = override[key];
          }
        });
      }
      return typography;
    }

    function getActiveTypographyValues() {
      if (selectedTypographyPage === 'all') {
        const values = {};
        TYPOGRAPHY_KEYS.forEach(function(key) {
          values[key] = currentTheme[key];
        });
        return values;
      }
      return getTypographyForPage(selectedTypographyPage);
    }

    function setActiveTypographyValue(key, value) {
      if (selectedTypographyPage === 'all') {
        currentTheme[key] = value;
        return;
      }
      normalizePageTypographyStore();
      const pageKey = String(selectedTypographyPage);
      if (!currentTheme.pageTypography[pageKey] || typeof currentTheme.pageTypography[pageKey] !== 'object') {
        currentTheme.pageTypography[pageKey] = {};
      }
      currentTheme.pageTypography[pageKey][key] = value;
    }

    function applyTypographyVarsToElement(el, typography) {
      if (!el || !typography) return;
      el.style.setProperty('--ui-font', '"' + typography.fontFamily + '", "Segoe UI", Arial, sans-serif');
      el.style.setProperty('--ui-font-size', typography.fontSize + 'px');
      el.style.setProperty('--ui-font-weight', typography.fontWeight);
      el.style.setProperty('--ui-letter-spacing', typography.letterSpacing + 'px');
      el.style.setProperty('--ui-line-height', typography.lineHeight);
      el.style.setProperty('--ui-text-align', typography.textAlign || 'left');
      el.style.fontFamily = 'var(--ui-font)';
      el.style.fontSize = 'var(--ui-font-size)';
      el.style.fontWeight = 'var(--ui-font-weight)';
      el.style.letterSpacing = 'var(--ui-letter-spacing)';
      el.style.lineHeight = 'var(--ui-line-height)';
      el.style.textAlign = 'var(--ui-text-align)';
    }

    function applyAllPageTypography() {
      queryPreviewAll('.page-slide').forEach(function(slide) {
        applyTypographyVarsToElement(slide, getTypographyForPage(slide.dataset.pageNo || ''));
      });
    }

    function populateTypographyPageSelect() {
      const select = document.getElementById('studio-typography-page-select');
      if (!select) return;
      const pages = getParamPagesFromCards(getEditableParamCards());
      if (!pages.length) {
        Array.from(document.querySelectorAll('.page-slide')).forEach(function(slide) {
          const pageNo = String(slide.dataset.pageNo || '');
          if (!pageNo || pages.some(function(page) { return String(page.pageNo) === pageNo; })) return;
          pages.push({ pageNo: pageNo, pageName: slide.dataset.pageTitle || '' });
        });
      }
      const previous = selectedTypographyPage;
      select.innerHTML = '<option value="all">All pages</option>' + pages.map(function(page) {
        const label = 'Page ' + page.pageNo + (page.pageName ? ' - ' + page.pageName : '');
        return '<option value="' + escapeHtml(String(page.pageNo)) + '">' + escapeHtml(label) + '</option>';
      }).join('');
      const hasPrevious = previous === 'all' || pages.some(function(page) {
        return String(page.pageNo) === String(previous);
      });
      selectedTypographyPage = hasPrevious ? previous : 'all';
      select.value = selectedTypographyPage;
    }

    function bindTypographyPageSelect() {
      const select = document.getElementById('studio-typography-page-select');
      if (!select || select.dataset.bound === '1') return;
      select.dataset.bound = '1';
      select.addEventListener('change', function() {
        selectedTypographyPage = select.value || 'all';
        syncInputsFromTheme();
        if (selectedTypographyPage !== 'all') {
          const targetSlide = queryPreviewAll('.page-slide').find(function(slide) {
            return String(slide.dataset.pageNo) === String(selectedTypographyPage);
          });
          if (targetSlide) {
            const slideIndex = slides.indexOf(targetSlide);
            if (slideIndex >= 0) showSlide(slideIndex);
          }
        }
        setStudioStatus(selectedTypographyPage === 'all'
          ? 'Editing typography for all pages.'
          : 'Editing typography for Page ' + selectedTypographyPage + ' only.');
      });
    }

    function syncGlobalCardStyles(theme) {
      const borderSize = parseInt(theme.borderSize || 1, 10) + 'px';
      const borderRadius = parseInt(theme.borderRadius || 16, 10) + 'px';
      const cardPadding = parseInt(theme.cardPadding || 14, 10) + 'px';
      const cardBlur = parseInt(theme.cardBlur || 0, 10);
      const cardMargin = parseInt(theme.cardMargin || 0, 10);
      const cardSpacing = parseInt(theme.cardSpacing || 12, 10) + 'px';
      const borderColor = theme.borderColor || '#E2E8F0';
      const shadow = Math.max(0, Math.min(100, parseInt(theme.shadowStrength || 42, 10))) / 1000;
      const cardShadowY = Math.round(4 + shadow * 24);
      const cardShadowBlur = Math.round(10 + shadow * 28);
      const cardShadowAlpha = Math.min(.14, shadow * 2.2).toFixed(3);
      const cardShadow = parseInt(theme.shadowStrength || 0, 10) <= 0
        ? 'none'
        : '0 1px 2px rgba(15, 23, 42, ' + (shadow * 1.4).toFixed(3) + '), 0 ' + cardShadowY + 'px ' + cardShadowBlur + 'px rgba(15, 23, 42, ' + cardShadowAlpha + ')';
      const blurFilter = cardBlur > 0 ? 'blur(' + cardBlur + 'px)' : 'none';
      const marginValue = cardMargin > 0 ? cardMargin + 'px' : '0px';

      queryPreviewAll('.param-list').forEach(function(list) {
        list.style.gap = '14px';
      });

      queryPreviewAll('.device-card, .param-card').forEach(function(card) {
        const override = card.dataset.paramKey ? getComponentOverride(card.dataset.paramKey) : null;
        const isGrouped = card.classList.contains('is-grouped-component');

        if (isGrouped) {
          card.style.borderRadius = '0px';
          card.style.boxShadow = 'none';
          card.style.marginTop = '0px';
          card.style.marginBottom = '0px';
          card.style.padding = card.classList.contains('layout-stacked') ? '8px 4px 10px' : '8px 4px';
          card.style.minHeight = card.classList.contains('layout-stacked') ? '0px' : '44px';
          card.style.backdropFilter = 'none';
          card.style.webkitBackdropFilter = 'none';
          if (!override || !override.borderColor) {
            card.style.borderWidth = '0px';
            card.style.borderStyle = 'none';
            card.style.borderColor = 'transparent';
          }
          if (!override || !override.cardColor) {
            card.style.background = 'transparent';
          }
          return;
        }

        card.style.borderRadius = borderRadius;
        card.style.padding = cardPadding;
        card.style.boxShadow = cardShadow;
        card.style.backdropFilter = blurFilter;
        card.style.webkitBackdropFilter = blurFilter;
        card.style.marginTop = marginValue;
        card.style.marginBottom = marginValue;

        if (!override || !override.borderColor) {
          card.style.borderWidth = borderSize;
          card.style.borderStyle = 'solid';
          card.style.borderColor = borderColor;
        }
        if (!override || !override.cardColor) {
          card.style.background = theme.cardColor || '';
        }
      });

      queryPreviewAll('.param-card.layout-stacked:not(.is-grouped-component)').forEach(function(card) {
        card.style.paddingBottom = 'calc(' + cardPadding + ' + 4px)';
      });
    }

    // Theme Application
    function applyTheme(theme, options) {
      const settings = options || {};
      document.body.setAttribute('data-studio-theme-mode', String(theme.themeMode || 'pro').toLowerCase());
      const root = phoneShell;
      if (root) {
        root.style.setProperty('--ui-bg', theme.backgroundColor);
        root.style.setProperty('--ui-shell', theme.shellColor);
        root.style.setProperty('--ui-surface', theme.cardColor);
        root.style.setProperty('--ui-surface-2', theme.shellColor);
        root.style.setProperty('--ui-text', theme.textColor);
        root.style.setProperty('--ui-muted', theme.mutedTextColor);
        root.style.setProperty('--ui-graphite', theme.topbarColor);
        root.style.setProperty('--ui-accent', theme.accentColor);
        root.style.setProperty('--ui-green', theme.accentColor);
        root.style.setProperty('--ui-green-dark', theme.accentColor);
        root.style.setProperty('--ui-blue', theme.secondaryColor);
        root.style.setProperty('--ui-steel', theme.secondaryColor);
        root.style.setProperty('--ui-toggle-on', theme.toggleOnColor);
        root.style.setProperty('--ui-toggle-off', theme.toggleOffColor);
        root.style.setProperty('--ui-radius', parseInt(theme.borderRadius || 18, 10) + 'px');
        root.style.setProperty('--ui-font', '"' + theme.fontFamily + '", "Segoe UI", Arial, sans-serif');
        root.style.setProperty('--ui-font-size', theme.fontSize + 'px');
        root.style.setProperty('--ui-font-weight', theme.fontWeight);
        root.style.setProperty('--ui-letter-spacing', theme.letterSpacing + 'px');
        root.style.setProperty('--ui-line-height', theme.lineHeight);
        root.style.setProperty('--ui-text-align', theme.textAlign || 'left');
        root.style.setProperty('--ui-button-bg', theme.buttonBgColor || theme.accentColor);
        root.style.setProperty('--ui-button-text', theme.buttonTextColor || '#FFFFFF');
        root.style.setProperty('--ui-success', theme.successColor || '#10B981');
        root.style.setProperty('--ui-warning', theme.warningColor || '#F59E0B');
        root.style.setProperty('--ui-error', theme.errorColor || '#EF4444');
        root.style.setProperty('--ui-icon-size', parseInt(theme.iconSize || 20, 10) + 'px');
        root.style.setProperty('--ui-icon-color', theme.iconColor || theme.accentColor);
        root.style.setProperty('--ui-header-height', parseInt(theme.headerHeight || 84, 10) + 'px');
        root.style.setProperty('--ui-border-size', parseInt(theme.borderSize || 1, 10) + 'px');
        root.style.setProperty('--ui-border', theme.borderColor || 'rgba(106, 142, 174, .28)');
        root.style.setProperty('--ui-border-color', theme.borderColor || '#DCE8EF');
        const isDarkMode = String(theme.themeMode || '').toLowerCase() === 'dark';
        root.style.setProperty('--ui-input-bg', isDarkMode ? (theme.backgroundColor || theme.shellColor || '#0B1220') : '#FFFFFF');
        root.style.setProperty('--ui-input-text', isDarkMode ? '#FFFFFF' : (theme.textColor || '#0F172A'));
        root.style.setProperty('--ui-input-border', theme.borderColor || (isDarkMode ? '#334155' : '#E2E8F0'));
        root.style.setProperty('--ui-well', isDarkMode ? '#111827' : '#F1F5F9');
        root.style.setProperty('--ui-card-blur', parseInt(theme.cardBlur || 0, 10) + 'px');
        root.style.setProperty('--ui-page-padding', parseInt(theme.pagePadding || 18, 10) + 'px');
        root.style.setProperty('--ui-card-padding', parseInt(theme.cardPadding || 16, 10) + 'px');
        root.style.setProperty('--ui-card-spacing', parseInt(theme.cardSpacing || 14, 10) + 'px');
        root.style.setProperty('--ui-card-margin', parseInt(theme.cardMargin || 0, 10) + 'px');
        root.style.setProperty('--ui-button-height', parseInt(theme.buttonSize || 44, 10) + 'px');
        root.style.setProperty('--ui-button-radius', parseInt(theme.buttonRadius || 16, 10) + 'px');
        const shadow = Math.max(0, Math.min(100, parseInt(theme.shadowStrength || 42, 10))) / 1000;
        const cardShadowY = Math.round(4 + shadow * 24);
        const cardShadowBlur = Math.round(10 + shadow * 28);
        const cardShadowAlpha = Math.min(.14, shadow * 2.2).toFixed(3);
        root.style.setProperty('--ui-card-shadow', '0 1px 2px rgba(15, 23, 42, ' + (shadow * 1.4).toFixed(3) + '), 0 ' + cardShadowY + 'px ' + cardShadowBlur + 'px rgba(15, 23, 42, ' + cardShadowAlpha + ')');
        root.style.setProperty('--ui-shadow', '0 8px 24px rgba(15, 23, 42, ' + Math.min(.16, shadow * 2.8).toFixed(3) + ')');

        applyAllPageTypography();

        theme.backgroundType = 'gradient';
          root.style.background = 'linear-gradient(165deg, ' + theme.backgroundColor + ' 0%, ' + (theme.gradientColor || theme.shellColor) + ' 55%, ' + theme.backgroundColor + ' 100%)';
        root.style.setProperty('--ui-surface-2', theme.shellColor || theme.backgroundColor);
      }

      queryPreviewAll('.save-btn').forEach(function(button) {
        const target = theme.buttonTarget || 'save';
        const isSave = button.id === 'save-ui-btn';
        const isCustomize = button.id === 'open-studio-footer-btn';
        const shouldStyle = target === 'all' || (target === 'save' && isSave) || (target === 'customize' && isCustomize);
        button.style.background = shouldStyle ? (theme.buttonBgColor || theme.accentColor) : '';
        button.style.color = shouldStyle ? (theme.buttonTextColor || '#fff') : '';
        button.style.minHeight = (parseInt(theme.buttonSize || 44, 10)) + 'px';
        button.style.borderRadius = (parseInt(theme.buttonRadius || 16, 10)) + 'px';
        button.classList.remove('is-hover-lift', 'is-hover-glow');
        const hover = theme.buttonHover || 'lift';
        if (hover && hover !== 'none') {
          button.classList.add('is-hover-' + hover);
        }
      });

      const saveUiButton = phoneShell ? phoneShell.querySelector('#save-ui-btn') : null;
      if (saveUiButton) {
        const label = escapeHtml(theme.buttonText || 'Save');
        const saveIcon = iconSvg('save');
        if (theme.buttonIconPosition === 'none') {
          saveUiButton.innerHTML = label;
        } else if (theme.buttonIconPosition === 'right') {
          saveUiButton.innerHTML = label + ' ' + saveIcon;
        } else {
          saveUiButton.innerHTML = saveIcon + ' ' + label;
        }
      }

      queryPreviewAll('.app-topbar').forEach(function(topbar) {
        topbar.classList.remove('is-align-center', 'is-align-right');
        const alignment = theme.headerAlignment || 'left';
        if (alignment === 'center') {
          topbar.classList.add('is-align-center');
        } else if (alignment === 'right') {
          topbar.classList.add('is-align-right');
        }
        topbar.style.background = topbarBackgroundCss(theme);
      });

      queryPreviewAll('.field-value').forEach(function(el) {
        if (el.querySelector('.param-cmd-input')) {
          el.style.removeProperty('color');
          return;
        }
        el.style.color = theme.textColor || '';
      });
      resizeAllCmdConsoleFields(root);

      queryPreviewAll('.top-actions').forEach(function(actions) {
        actions.style.display = String(theme.showHeaderIcons) === '0' ? 'none' : 'flex';
      });

      queryPreviewAll('.brand-strip').forEach(function(brand) {
        brand.style.display = String(theme.brandVisible) === '0' ? 'none' : 'grid';
        brand.style.background = '';
        brand.style.color = '';
        brand.style.boxShadow = '';
      });

      queryPreviewAll('.name-card').forEach(function(card) {
        card.style.display = String(theme.nameCardVisible) === '0' ? 'none' : 'grid';
      });

      queryPreviewAll('.progress-shell, .slider-controls').forEach(function(nav) {
        nav.style.display = String(theme.pageNavigatorVisible) === '0' ? 'none' : '';
      });

      queryPreviewAll('.footer-actions').forEach(function(footer) {
        footer.style.display = String(theme.footerVisible) === '0' ? 'none' : '';
      });

      queryPreviewAll('.online-state').forEach(function(state) {
        state.style.display = String(theme.showStatus) === '0' ? 'none' : 'inline-flex';
      });
      refreshOnlineStateBadges();

      queryPreviewAll('.param-card').forEach(function(card) {
        const iconButton = card.querySelector('.param-icon');
        if (!iconButton) return;
        const iconName = getParamIcon(card);
        iconButton.innerHTML = iconSvg(iconName);
        iconButton.dataset.icon = iconName;
      });

      applyControlOrder();
      if (settings.reinitializeComponents) {
        initializeParamComponents();
      }
      applyComponentOverrides();
      syncGlobalCardStyles(theme);
      if (document.body.classList.contains('studio-open') || document.getElementById('page-preview-shell')) {
        requestAnimationFrame(applyActivePreviewZoom);
      }
    }

    function buildDeviceUiResponsiveContract() {
      return {
        version: '1.0',
        unit: 'logicalPx',
        dimensionPolicy: 'logical',
        scaleLegacyDimensions: false,
        safeArea: true,
        breakpoints: {
          narrow: { minimumWidth: 0, maximumWidth: 359 },
          compact: { minimumWidth: 360, maximumWidth: 599 },
          medium: { minimumWidth: 600, maximumWidth: 839 },
          expanded: { minimumWidth: 840 }
        },
        layouts: {
          narrow: { maxContentWidth: 359, columns: 1, navigation: 'pager', pagePadding: 12, cardGap: 10, density: 'comfortable' },
          compact: { maxContentWidth: 430, columns: 1, navigation: 'pager', pagePadding: 16, cardGap: 12, density: 'comfortable' },
          medium: { maxContentWidth: 720, columns: 1, navigation: 'pager', pagePadding: 22, cardGap: 14, density: 'comfortable' },
          expanded: { maxContentWidth: 840, columns: 1, navigation: 'sidebar-pager', pagePadding: 28, cardGap: 16, density: 'comfortable' }
        }
      };
    }

    function buildDeviceUiResponsiveLayout(role) {
      const common = { safeArea: true, width: 'matchParent' };
      const layouts = {
        viewport: {
          all: common,
          narrow: { maxContentWidth: 359, padding: { left: 0, right: 0 } },
          compact: { maxContentWidth: 430, padding: { left: 0, right: 0 } },
          medium: { maxContentWidth: 720, padding: { left: 24, right: 24 } },
          expanded: { maxContentWidth: 840, padding: { left: 32, right: 32 } }
        },
        screen: {
          all: { width: 'matchParent', height: 'matchParent', overflow: 'clip' },
          narrow: { maxWidth: 359 },
          compact: { maxWidth: 430 },
          medium: { maxWidth: 720 },
          expanded: { maxWidth: 840 }
        },
        appBar: {
          all: { width: 'matchParent' },
          narrow: { minHeight: 64, padding: { top: 12, right: 12, bottom: 10, left: 12 } },
          compact: { minHeight: 72, padding: { top: 14, right: 16, bottom: 12, left: 16 } },
          medium: { minHeight: 76, padding: { top: 16, right: 22, bottom: 14, left: 22 } },
          expanded: { minHeight: 80, padding: { top: 16, right: 28, bottom: 14, left: 28 } }
        },
        brandBar: {
          all: { width: 'matchParent' },
          narrow: { margin: { top: 8, right: 12, bottom: 10, left: 12 }, padding: 14 },
          compact: { margin: { top: 10, right: 16, bottom: 12, left: 16 }, padding: 16 },
          medium: { margin: { top: 10, right: 22, bottom: 12, left: 22 }, padding: 16 },
          expanded: { margin: { top: 10, right: 28, bottom: 12, left: 28 }, padding: 18 }
        },
        page: {
          all: { width: 'matchParent', scrollable: true },
          narrow: { padding: { top: 12, right: 12, bottom: 6, left: 12 }, gap: 10 },
          compact: { padding: { top: 16, right: 16, bottom: 6, left: 16 }, gap: 12 },
          medium: { padding: { top: 22, right: 22, bottom: 8, left: 22 }, gap: 14 },
          expanded: { padding: { top: 28, right: 28, bottom: 10, left: 28 }, gap: 16 }
        },
        hero: {
          all: { width: 'matchParent' },
          narrow: { minHeight: 96, padding: 14 },
          compact: { minHeight: 112, padding: 18 },
          medium: { minHeight: 120, padding: 20 },
          expanded: { minHeight: 128, padding: 22 }
        },
        parameterCard: {
          all: { width: 'matchParent' },
          narrow: { minHeight: 60, padding: 12 },
          compact: { minHeight: 66, padding: 14 },
          medium: { minHeight: 68, padding: 16 },
          expanded: { minHeight: 70, padding: 18 }
        },
        pager: {
          all: { width: 'matchParent' },
          narrow: { margin: { top: 6, right: 12, bottom: 0, left: 12 }, padding: 10 },
          compact: { margin: { top: 6, right: 18, bottom: 0, left: 18 }, padding: 12 },
          medium: { margin: { top: 8, right: 22, bottom: 0, left: 22 }, padding: 12 },
          expanded: { margin: { top: 10, right: 28, bottom: 0, left: 28 }, padding: 14 }
        },
        footer: {
          all: { width: 'matchParent' },
          narrow: { padding: { top: 10, right: 12, bottom: 14, left: 12 } },
          compact: { padding: { top: 12, right: 16, bottom: 20, left: 16 } },
          medium: { padding: { top: 14, right: 22, bottom: 22, left: 22 } },
          expanded: { padding: { top: 16, right: 28, bottom: 24, left: 28 } }
        }
      };
      return layouts[role] || { all: common };
    }

    function syncThemeStateFromPreview() {
      normalizedControlOrder();
      currentTheme.componentOverrides = currentTheme.componentOverrides && typeof currentTheme.componentOverrides === 'object' && !Array.isArray(currentTheme.componentOverrides)
        ? currentTheme.componentOverrides
        : {};
      currentTheme.parameterIcons = normalizeParameterIcons(currentTheme.parameterIcons);

      queryPreviewAll('.param-card').forEach(function(card) {
        const key = card.dataset.paramKey;
        if (!key) return;
        const override = getComponentOverride(key);
        const componentType = getResolvedParamComponentType(card);
        const liveValue = getParamLiveValue(card, componentType, override);
        if (liveValue !== '') {
          override.value = liveValue;
        }
        const icon = getParamIcon(card);
        if (icon) {
          currentTheme.parameterIcons[key] = icon;
        }
        const metaIcon = getParamMetaIcon(card);
        if (metaIcon) {
          override.metaIcon = metaIcon;
        }
        if (!override.componentType || override.componentType === 'auto' || override.componentType === 'value') {
          const detectedType = detectParamComponentType(card);
          if (detectedType && detectedType !== 'auto' && detectedType !== 'value') {
            override.componentType = detectedType;
          } else {
            override.componentType = 'auto';
          }
        }
      });
    }

    function buildThemePayloadForSave() {
      syncThemeStateFromPreview();
      const themeForSave = JSON.parse(JSON.stringify(currentTheme));
      const liveKeys = liveSchemaMapKeys((typeof buildControlsSchema === 'function') ? (buildControlsSchema().controls || []) : []);
      themeForSave.parameterIcons = pruneObjectMapToKeys(normalizeParameterIcons(themeForSave.parameterIcons), liveKeys);
      themeForSave.componentOverrides = pruneObjectMapToKeys(
        themeForSave.componentOverrides && typeof themeForSave.componentOverrides === 'object' && !Array.isArray(themeForSave.componentOverrides)
          ? themeForSave.componentOverrides
          : {},
        liveKeys
      );
      themeForSave.controlOrder = Array.isArray(themeForSave.controlOrder)
        ? themeForSave.controlOrder.filter(function(key) { return liveKeys[key]; })
        : [];
      themeForSave.nodeId = getStudioNodeId();
      currentTheme.parameterIcons = themeForSave.parameterIcons;
      currentTheme.componentOverrides = themeForSave.componentOverrides;
      currentTheme.controlOrder = themeForSave.controlOrder;
      return themeForSave;
    }

    function parseSaveResponse(response) {
      return response.text().then(function(raw) {
        let result = {};
        try {
          result = raw ? JSON.parse(raw) : {};
        } catch (error) {
          throw new Error('Server returned an invalid response while saving.');
        }
        if (!response.ok) {
          throw new Error(result.message || ('Save failed with status ' + response.status + '.'));
        }
        return result;
      });
    }

    function parseColorInput(value) {
      if (!value) return '';
      const raw = String(value).trim();
      const rgbMatch = raw.match(/^rgba?\(\s*(\d{1,3})\s*,\s*(\d{1,3})\s*,\s*(\d{1,3})/i);
      if (rgbMatch) {
        const parts = [rgbMatch[1], rgbMatch[2], rgbMatch[3]].map(function(part) {
          return Math.max(0, Math.min(255, parseInt(part, 10))).toString(16).padStart(2, '0');
        });
        return ('#' + parts.join('')).toUpperCase();
      }
      const hex = raw.replace(/^#/, '').toUpperCase();
      if (/^[0-9A-F]{6}$/.test(hex)) return '#' + hex;
      return '';
    }

    function cssColorIsDark(value) {
      const parsed = parseColorInput(value);
      let r = 15;
      let g = 23;
      let b = 42;
      if (parsed) {
        r = parseInt(parsed.slice(1, 3), 16);
        g = parseInt(parsed.slice(3, 5), 16);
        b = parseInt(parsed.slice(5, 7), 16);
      } else {
        const rgbMatch = String(value || '').match(/^rgba?\(\s*(\d{1,3})\s*,\s*(\d{1,3})\s*,\s*(\d{1,3})/i);
        if (rgbMatch) {
          r = parseInt(rgbMatch[1], 10);
          g = parseInt(rgbMatch[2], 10);
          b = parseInt(rgbMatch[3], 10);
        }
      }
      return ((0.299 * r) + (0.587 * g) + (0.114 * b)) < 160;
    }

    function headerChromeFromTheme(theme) {
      const topbarBg = (theme && theme.topbarColor) || '#0F172A';
      const dark = cssColorIsDark(topbarBg);
      return {
        backgroundColor: topbarBg,
        secondaryColor: (theme && theme.secondaryColor) || topbarBg,
        titleColor: dark ? '#FFFFFF' : ((theme && theme.textColor) || '#0F172A'),
        subtitleColor: dark ? 'rgba(255,255,255,0.72)' : ((theme && theme.mutedTextColor) || '#64748B'),
        backBackground: dark ? 'rgba(255,255,255,0.10)' : '#FFFFFF',
        backForeground: dark ? '#FFFFFF' : ((theme && theme.textColor) || '#0F172A'),
        actionBackground: dark ? 'rgba(255,255,255,0.10)' : 'rgba(37,99,235,0.10)',
        actionBorder: dark ? 'rgba(255,255,255,0.12)' : 'rgba(37,99,235,0.16)',
        actionForeground: dark ? '#FFFFFF' : ((theme && theme.accentColor) || '#2563EB'),
        isDark: dark
      };
    }

    function topbarBackgroundCss(theme) {
      const chrome = headerChromeFromTheme(theme || currentTheme);
      return 'linear-gradient(145deg, ' + chrome.backgroundColor + ', ' + chrome.secondaryColor + '), ' + chrome.backgroundColor;
    }

    function formatColorDisplay(value) {
      return parseColorInput(value) || String(value || '').trim().toUpperCase();
    }

    function syncColorRowHex(row) {
      const colorInput = row.querySelector('input[type="color"]');
      const hexInput = row.querySelector('.studio-color-hex');
      if (colorInput && hexInput) {
        hexInput.value = formatColorDisplay(colorInput.value);
      }
    }

    function bindStudioColorRow(row) {
      if (!row || row.dataset.colorBound === '1') return;
      const colorInput = row.querySelector('input[type="color"]');
      const hexInput = row.querySelector('.studio-color-hex');
      if (!colorInput || !hexInput) return;
      row.dataset.colorBound = '1';

      hexInput.setAttribute('title', 'Hex (#RRGGBB) or rgb(r, g, b)');
      if (!hexInput.getAttribute('placeholder')) {
        hexInput.setAttribute('placeholder', '#2563EB');
      }

      colorInput.addEventListener('input', function() {
        hexInput.value = formatColorDisplay(colorInput.value);
      });

      hexInput.addEventListener('change', function() {
        const parsed = parseColorInput(hexInput.value);
        if (!parsed) {
          hexInput.value = formatColorDisplay(colorInput.value);
          return;
        }
        colorInput.value = parsed;
        hexInput.value = parsed;
        colorInput.dispatchEvent(new Event('input', { bubbles: true }));
        colorInput.dispatchEvent(new Event('change', { bubbles: true }));
      });

      hexInput.addEventListener('keydown', function(event) {
        if (event.key === 'Enter') {
          event.preventDefault();
          hexInput.blur();
        }
      });
    }

    function bindStudioColorRows(root) {
      (root || document).querySelectorAll('.studio-color-row').forEach(bindStudioColorRow);
    }

    function buildParamColorRow(label, hint, prop, value) {
      const safeValue = formatColorDisplay(value || '#FFFFFF') || '#FFFFFF';
      return '<div class="studio-color-row">' +
        '<label>' + escapeHtml(label) + '<span class="studio-color-hint">' + escapeHtml(hint) + '</span></label>' +
        '<div class="studio-color-control">' +
          '<input type="color" data-param-prop="' + escapeHtml(prop) + '" value="' + escapeHtml(safeValue) + '">' +
          '<input type="text" class="studio-color-hex" value="' + escapeHtml(safeValue) + '" spellcheck="false" autocomplete="off" aria-label="' + escapeHtml(label) + ' value" title="Hex (#RRGGBB) or rgb(r, g, b)" placeholder="#2563EB">' +
        '</div>' +
      '</div>';
    }

    function syncThemeColorLabels() {
      document.querySelectorAll('#studio-theme-section .studio-color-row, #studio-general-section .studio-color-row').forEach(function(row) {
        syncColorRowHex(row);
        const input = row.querySelector('input[type="color"]');
        const label = row.querySelector('label');
        if (!input) return;
        if (label) {
          const hint = label.querySelector('.studio-color-hint');
          const labelText = hint
            ? String(label.textContent || '').replace(hint.textContent, '').trim()
            : String(label.textContent || '').trim();
          input.setAttribute('aria-label', labelText || input.dataset.themeKey || 'Theme color');
        }
      });
    }

    function syncInputsFromTheme() {
      themeInputs.forEach(function(input) {
        const key = input.dataset.themeKey;
        const typographyValues = TYPOGRAPHY_KEYS.indexOf(key) !== -1 ? getActiveTypographyValues() : null;
        const source = typographyValues || currentTheme;
        if (source[key] !== undefined) {
          if (input.type === 'checkbox') {
            input.checked = String(source[key]) !== '0';
          } else if (input.type === 'range') {
            const synced = setRangeInputValue(input, source[key]);
            if (typographyValues) {
              setActiveTypographyValue(key, synced);
            } else {
            currentTheme[key] = synced;
            }
          } else {
            input.value = source[key];
          }
          updateRangeBadge(input);
        }
      });

      document.querySelectorAll('[data-segment-key]').forEach(function(group) {
        const key = group.dataset.segmentKey;
        group.querySelectorAll('[data-segment-value]').forEach(function(button) {
          button.classList.toggle('is-active', String(currentTheme[key]) === String(button.dataset.segmentValue));
        });
      });

      document.querySelectorAll('[data-preset]').forEach(function(button) {
        button.classList.toggle('is-active', String(currentTheme.themeMode) === String(button.dataset.preset));
      });

      syncThemeColorLabels();
    }

    // Icon Library
    function renderIconLibrary(filterText) {
      if (!iconLibraryGrid) return;
      const filtered = getFilteredIconNames(filterText);

      iconLibraryGrid.innerHTML = filtered.map(iconName => {
        return '<button type="button" class="icon-choice" data-icon-name="' + escapeHtml(iconName) + '" title="' + escapeHtml(iconName) + '" aria-label="' + escapeHtml(iconName) + '">' + iconSvg(iconName) + '</button>';
      }).join('');

      document.querySelectorAll('#icon-library-grid .icon-choice').forEach(btn => {
        btn.addEventListener('click', function() {
          const iconName = this.dataset.iconName;
          currentTheme.parameterIcon = iconName;
          applyTheme(currentTheme);
          generateSchema();
          setStudioStatus('Default parameter icon updated to ' + iconName + '.');
          commitThemeHistoryRecord();
        });
      });
    }

    if (iconSearchInput) {
      iconSearchInput.addEventListener('input', function() {
        renderIconLibrary(this.value);
      });
    }

    function getEditableParamCards() {
      const lists = queryPreviewAll('.param-list');
      const sourceLists = lists.length
        ? lists
        : Array.from(document.querySelectorAll('.page-slide .param-list'));
      const items = [];

      sourceLists.forEach(function(list) {
        Array.from(list.children).forEach(function(block) {
          if (!block.matches || (!block.matches('.param-group-card') && !block.matches('.param-card'))) {
            return;
          }

          const slide = block.closest('.page-slide');
          const componentCards = block.matches('.param-group-card')
            ? Array.from(block.querySelectorAll(':scope > .param-component-stack > .param-card'))
            : [block];
          const firstComponentCard = componentCards[0] || block;
          const parameterKey = block.dataset.paramKey || (firstComponentCard ? firstComponentCard.dataset.paramKey : '');
          if (!parameterKey || !componentCards.length) return;

          items.push({
            block: block,
            parameterKey: parameterKey,
            name: block.dataset.paramName || (firstComponentCard ? firstComponentCard.dataset.paramName : '') || 'Parameter',
            pageNo: slide ? slide.dataset.pageNo : '',
            pageName: slide ? slide.dataset.pageTitle : '',
            componentCount: componentCards.length,
            componentCards: componentCards.map(function(card, index) {
              return {
                card: card,
                key: card.dataset.paramKey || (parameterKey + ':component-' + (index + 1)),
                label: card.dataset.componentLabel || card.dataset.apiUiSource || ('Component ' + (index + 1)),
                source: card.dataset.apiUiSource || '',
                fieldIndex: card.dataset.apiFieldIndex || String(index)
              };
            })
          });
        });
      });

      return items;
    }

    function getEditableComponentCards() {
      const components = [];
      getEditableParamCards().forEach(function(parameter) {
        parameter.componentCards.forEach(function(component) {
          components.push(Object.assign({}, component, {
            block: parameter.block,
            parameterKey: parameter.parameterKey,
            parameterName: parameter.name,
            pageNo: parameter.pageNo,
            pageName: parameter.pageName,
            componentCount: parameter.componentCount
          }));
        });
      });
      return components;
    }

    function getSelectedParamCard() {
      if (!selectedParamKey) return null;
      const match = getEditableComponentCards().find(function(item) {
        return item.key === selectedParamKey;
      });
      return match ? match.card : null;
    }

    function refreshStudioParameterPanels() {
      renderParametersButtons();
      renderOrderList();
      populateOrderPageSelect();
    }

    function getParamPagesFromCards(params) {
      const seen = {};
      const pages = [];
      params.forEach(function(item) {
        const pageKey = String(item.pageNo);
        if (seen[pageKey]) return;
        seen[pageKey] = true;
        pages.push({ pageNo: item.pageNo, pageName: item.pageName });
      });
      return pages;
    }

    function scrollToSelectedParamCard(key) {
      const selectedCard = getEditableComponentCards().find(function(item) {
        return item.key === key;
      });
      if (selectedCard && selectedCard.card) {
        selectedCard.card.scrollIntoView({ behavior: 'smooth', block: 'center' });
      }
    }

    // Parameters Buttons Management
    function renderParametersButtons() {
      if (!paramsButtonsContainer) return;
      const parameters = getEditableParamCards();
      const components = getEditableComponentCards();

      if (!parameters.length || !components.length) {
        paramsButtonsContainer.innerHTML = '<div class="param-editor-card"><h4>No parameters found</h4></div>';
        return;
      }

      const selectedExists = components.some(function(item) { return item.key === selectedParamKey; });
      if (!selectedExists) selectedParamKey = components[0].key;

      const selected = components.find(function(item) { return item.key === selectedParamKey; }) || components[0];
      const pages = getParamPagesFromCards(parameters);
      const selectedPageNo = String(selected.pageNo);
      const pageParameters = parameters.filter(function(item) {
        return String(item.pageNo) === selectedPageNo;
      });
      const selectedParameter = pageParameters.find(function(item) {
        return item.parameterKey === selected.parameterKey;
      }) || pageParameters[0];
      const parameterComponents = selectedParameter ? selectedParameter.componentCards : [];
      const card = selected.card;
      const override = getComponentOverride(selected.key);
      const paramMeta = parseParamApiMeta(card);
      const currentIcon = getParamIcon(card);
      const resolvedComponentType = getResolvedParamComponentType(card);
      const selectedComponentType = override.componentType || 'auto';
      const previewComponentType = selectedComponentType === 'auto' || selectedComponentType === 'value'
        ? resolvedComponentType
        : selectedComponentType;
      const componentTypeLabel = selectedComponentType === 'auto' || selectedComponentType === 'value'
        ? 'Auto � ' + getComponentChoiceLabel(resolvedComponentType)
        : getComponentChoiceLabel(selectedComponentType);
      const componentColors = getEffectiveComponentColors(override);
      const metaIconButton = (card.querySelector('.param-meta') || ['slider', 'dropdown'].indexOf(resolvedComponentType) !== -1)
        ? '<button type="button" class="studio-btn param-meta-icon-edit" title="Meta icon">' + iconSvg(getParamMetaIcon(card)) + ' Meta Icon</button>'
        : '';

      paramsButtonsContainer.innerHTML =
        '<label class="studio-field">' +
          '<span>Select page</span>' +
          '<select id="studio-param-page-select">' +
            pages.map(function(page) {
              const label = 'Page ' + page.pageNo + (page.pageName ? ' - ' + page.pageName : '');
              return '<option value="' + escapeHtml(String(page.pageNo)) + '"' + (String(page.pageNo) === selectedPageNo ? ' selected' : '') + '>' + escapeHtml(label) + '</option>';
            }).join('') +
          '</select>' +
        '</label>' +
        '<label class="studio-field">' +
          '<span>Select parameter</span>' +
          '<select id="studio-param-parameter-select">' +
            pageParameters.map(function(item) {
              return '<option value="' + escapeHtml(item.parameterKey) + '"' + (item.parameterKey === selected.parameterKey ? ' selected' : '') + '>' + escapeHtml(item.name) + '</option>';
            }).join('') +
          '</select>' +
        '</label>' +
        '<label class="studio-field">' +
          '<span>Select component</span>' +
          '<select id="studio-param-component-select">' +
            parameterComponents.map(function(item, index) {
              const label = item.label || ('Component ' + (index + 1));
              return '<option value="' + escapeHtml(item.key) + '"' + (item.key === selected.key ? ' selected' : '') + '>' + escapeHtml(label) + '</option>';
            }).join('') +
          '</select>' +
        '</label>' +
        '<div class="param-editor-card">' +
          '<div style="display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:12px;">' +
            '<div><h4>' + escapeHtml(selected.parameterName) + ' � ' + escapeHtml(selected.label) + '</h4><small style="color:var(--ui-muted);font-weight:800;">Page ' + escapeHtml(selected.pageNo) + ' - ' + escapeHtml(selected.pageName) + '</small></div>' +
            '<div class="param-editor-actions">' +
              '<button type="button" class="studio-btn param-icon-edit" title="Main icon">' + iconSvg(currentIcon) + ' Main Icon</button>' +
              metaIconButton +
            '</div>' +
          '</div>' +
          '<label class="studio-field"><span>Component type</span>' +
            '<button type="button" class="studio-btn param-component-edit" id="param-component-edit-btn" title="Choose component">' +
              '<span class="component-choice-preview">' + componentPreviewMarkup(previewComponentType) + '</span>' +
              '<span><strong>' + escapeHtml(componentTypeLabel) + '</strong><br><small style="color:var(--ui-muted);font-weight:700;">' + escapeHtml(flutterWidgetForComponentType(resolvedComponentType)) + '</small></span>' +
            '</button>' +
          '</label>' +
          buildParameterActionFieldsMarkup(resolvedComponentType, override, paramMeta) +
          '<div class="studio-panel-group" style="margin-top:12px">' +
            '<p class="studio-panel-label">Component colors</p>' +
            '<div class="studio-color-grid">' +
              buildParamColorRow('Card background', 'Fill for this parameter card', 'cardColor', componentColors.cardColor || '#FFFFFF') +
              buildParamColorRow('Border color', 'Outline around this card', 'borderColor', componentColors.borderColor || '#DCE8EF') +
              buildParamColorRow('Accent / control', 'Slider, toggle and links', 'accentColor', componentColors.accentColor || '#2563EB') +
              buildParamColorRow('Icon color', 'Main and meta icons', 'iconColor', componentColors.iconColor || '#2563EB') +
              buildParamColorRow('Text color', 'Title and value text', 'textColor', componentColors.textColor || '#0F172A') +
              buildParamColorRow('Status / chip', 'Badge and status chip', 'statusColor', componentColors.statusColor || '#10B981') +
            '</div>' +
          '</div>' +
          '<div class="studio-grid">' +
            '<label class="studio-field"><span>Title</span><input type="text" data-param-prop="title" value="' + escapeHtml(override.title || selected.parameterName || '') + '"></label>' +
            '<label class="studio-field"><span>Value</span><input type="text" data-param-prop="value" value="' + escapeHtml(override.value || '') + '" placeholder="Use live value"></label>' +
          '</div>' +
          '<label class="studio-toggle-row">Hide this parameter <input type="checkbox" data-param-prop="hidden" ' + (override.hidden ? 'checked' : '') + '></label>' +
          '<p class="studio-section-note">Resolved component: <strong>' + escapeHtml(resolvedComponentType) + '</strong> · Flutter: <strong>' + escapeHtml(flutterWidgetForComponentType(resolvedComponentType)) + '</strong> · Icon: <strong>' + escapeHtml(currentIcon) + '</strong></p>' +
        '</div>';

      const pageSelect = document.getElementById('studio-param-page-select');
      if (pageSelect) {
        pageSelect.addEventListener('change', function() {
          const pageItems = getEditableParamCards().filter(function(item) {
            return String(item.pageNo) === String(pageSelect.value);
          });
          if (pageItems.length) {
            selectedParamKey = pageItems[0].componentCards[0].key;
            scrollToSelectedParamCard(selectedParamKey);
          }
          renderParametersButtons();
        });
      }

      const parameterSelect = document.getElementById('studio-param-parameter-select');
      if (parameterSelect) {
        parameterSelect.addEventListener('change', function() {
          const parameter = getEditableParamCards().find(function(item) {
            return item.parameterKey === parameterSelect.value && String(item.pageNo) === String(selectedPageNo);
          });
          if (parameter && parameter.componentCards.length) {
            selectedParamKey = parameter.componentCards[0].key;
            scrollToSelectedParamCard(selectedParamKey);
          }
          renderParametersButtons();
        });
      }

      const componentSelect = document.getElementById('studio-param-component-select');
      if (componentSelect) {
        componentSelect.addEventListener('change', function() {
          selectedParamKey = componentSelect.value;
          scrollToSelectedParamCard(selectedParamKey);
          renderParametersButtons();
        });
      }

      const mainIconEdit = paramsButtonsContainer.querySelector('.param-icon-edit');
      if (mainIconEdit) {
        mainIconEdit.addEventListener('click', function(event) {
          activeIconCard = card;
          activeIconTargetType = 'param';
          renderParamIconPicker(card, 'param');
          openIconPicker(event.currentTarget);
        });
      }

      const metaIconEdit = paramsButtonsContainer.querySelector('.param-meta-icon-edit');
      if (metaIconEdit) {
        metaIconEdit.addEventListener('click', function(event) {
          activeIconCard = card;
          activeIconTargetType = 'meta';
          renderParamIconPicker(card, 'meta');
          openIconPicker(event.currentTarget);
        });
      }

      const componentEdit = paramsButtonsContainer.querySelector('.param-component-edit');
      if (componentEdit) {
        componentEdit.addEventListener('click', function(event) {
          activeComponentCard = card;
          renderComponentPicker(card);
          openComponentPicker(event.currentTarget);
        });
      }

      paramsButtonsContainer.querySelectorAll('[data-param-prop]').forEach(function(input) {
        const updateParameterOverride = function() {
          const activeKey = selectedParamKey || selected.key;
          const activeCard = getSelectedParamCard() || card;
          const nextOverride = getComponentOverride(activeKey);
          const prop = input.dataset.paramProp;
          nextOverride[prop] = input.type === 'checkbox' ? input.checked : input.value;
          const actionProps = ['minimum', 'maximum', 'step', 'unit', 'optionsText', 'onLabel', 'offLabel'];
          const colorProps = ['cardColor', 'borderColor', 'accentColor', 'iconColor', 'textColor', 'statusColor'];
          if (actionProps.indexOf(prop) !== -1) {
            refreshParameterComponentAfterActionChange(activeCard, nextOverride);
          } else if (colorProps.indexOf(prop) !== -1) {
            applyComponentOverrides();
            const liveType = activeCard ? getResolvedParamComponentType(activeCard) : resolvedComponentType;
            if (isRegisteredComponentType(liveType) || resolveParameterRenderType(liveType) === 'segmented') {
              refreshParameterComponentAfterActionChange(activeCard, nextOverride);
            }
          } else {
            applyComponentOverrides();
          }
          generateSchema();
          setStudioStatus('Parameter updated. Save changes to keep it.');
        };
        input.addEventListener('input', updateParameterOverride);
        input.addEventListener('change', function() {
          updateParameterOverride();
          commitThemeHistoryRecord();
      });
      });

      bindStudioColorRows(paramsButtonsContainer);
    }

    function renderComponentPicker(card) {
      if (!card || !componentPickerGrid) return;
      const override = getComponentOverride(card.dataset.paramKey);
      const currentType = override.componentType || 'auto';
      const paramName = card.dataset.paramName || 'parameter';
      if (componentPickerTitle) {
        componentPickerTitle.textContent = 'Component for ' + paramName;
      }
      const catalogChoices = getParameterComponentPickerChoices();
      componentPickerGrid.innerHTML = catalogChoices.map(function(item) {
        return '<button type="button" class="component-choice' + (item.id === currentType ? ' is-active' : '') + '" data-component-type="' + escapeHtml(item.id) + '" aria-label="' + escapeHtml(item.label) + '">' +
          '<span class="component-choice-preview">' + componentPreviewMarkup(item.id) + '</span>' +
          '<span class="component-choice-label">' + escapeHtml(item.label) + '</span>' +
        '</button>';
      }).join('');

      componentPickerGrid.querySelectorAll('.component-choice').forEach(function(button) {
        button.addEventListener('click', function() {
          if (!activeComponentCard) return;
          applyComponentTypeSelection(activeComponentCard, button.dataset.componentType);
          closeComponentPicker();
          renderParametersButtons();
        });
      });
    }

    function openComponentPicker(anchor) {
      if (!componentPicker) return;
      closeIconPicker();
      const rect = anchor ? anchor.getBoundingClientRect() : null;
      const pickerHeight = Math.min(560, window.innerHeight - 28);
      if (rect) {
        const left = Math.max(12, Math.min(window.innerWidth - 372, rect.left));
        let top = rect.bottom + 8;
        if (top + pickerHeight > window.innerHeight - 12) {
          top = Math.max(12, rect.top - pickerHeight - 8);
        }
        componentPicker.style.left = left + 'px';
        componentPicker.style.top = top + 'px';
        componentPicker.style.maxHeight = pickerHeight + 'px';
      } else {
        componentPicker.style.left = 'auto';
        componentPicker.style.right = '24px';
        componentPicker.style.top = '86px';
        componentPicker.style.maxHeight = pickerHeight + 'px';
      }
      componentPicker.classList.add('is-open');
    }

    function closeComponentPicker() {
      if (componentPicker) componentPicker.classList.remove('is-open');
      activeComponentCard = null;
    }

    // Icon Picker for Parameters
    function renderParamIconPicker(card, targetType, filterText) {
      if (!card || !iconPickerGrid) return;
      const type = targetType || activeIconTargetType || 'param';
      const currentIcon = type === 'meta' ? getParamMetaIcon(card) : getParamIcon(card);
      const paramName = card.dataset.paramName || 'parameter';
      const icons = getFilteredIconNames(filterText);

      iconPickerTitle.textContent = (type === 'meta' ? 'Meta icon for ' : 'Icon for ') + paramName;
      iconPickerGrid.innerHTML = icons.length ? icons.map(iconName => {
        return '<button type="button" class="icon-choice' + (iconName === currentIcon ? ' is-active' : '') + '" data-icon-name="' + escapeHtml(iconName) + '" aria-label="' + escapeHtml(iconName) + '">' + iconSvg(iconName) + '</button>';
      }).join('') : '<div style="grid-column:1/-1;color:var(--ui-muted);font-weight:800;font-size:12px;padding:12px;">No icons found</div>';

      document.querySelectorAll('#icon-picker-grid .icon-choice').forEach(btn => {
        btn.addEventListener('click', function() {
          const iconName = this.dataset.iconName;
          if (activeIconCard) {
            if (activeIconTargetType === 'meta') {
              const override = getComponentOverride(activeIconCard.dataset.paramKey);
              override.metaIcon = iconName;
              const metaButton = activeIconCard.querySelector('.param-meta');
              if (metaButton) {
                const sequenceValue = metaButton.querySelector('.meta-value') ? metaButton.querySelector('.meta-value').textContent : '';
                metaButton.innerHTML = iconSvg(iconName) + '<span class="meta-value">' + escapeHtml(sequenceValue || '') + '</span>';
                metaButton.dataset.metaIcon = iconName;
              }
            } else {
              currentTheme.parameterIcons[activeIconCard.dataset.paramKey] = iconName;
              const iconButton = activeIconCard.querySelector('.param-icon');
              if (iconButton) {
                iconButton.innerHTML = iconSvg(iconName);
                iconButton.dataset.icon = iconName;
              }
            }
            generateSchema();
            setStudioStatus((activeIconTargetType === 'meta' ? 'Parameter meta icon' : 'Parameter icon') + ' updated. Save Studio to keep it.');
            closeIconPicker();
            renderParametersButtons();
            commitThemeHistoryRecord();
          }
        });
      });
    }

    function renderHeaderIconPicker(filterText) {
      if (!iconPickerGrid) return;
      const currentIcon = currentTheme.iconStyle || 'signal';
      const icons = getFilteredIconNames(filterText);
      iconPickerTitle.textContent = 'Header icon';
      iconPickerGrid.innerHTML = icons.length ? icons.map(iconName => {
        return '<button type="button" class="icon-choice' + (iconName === currentIcon ? ' is-active' : '') + '" data-icon-name="' + escapeHtml(iconName) + '" aria-label="' + escapeHtml(iconName) + '">' + iconSvg(iconName) + '</button>';
      }).join('') : '<div style="grid-column:1/-1;color:var(--ui-muted);font-weight:800;font-size:12px;padding:12px;">No icons found</div>';

      document.querySelectorAll('#icon-picker-grid .icon-choice').forEach(btn => {
        btn.addEventListener('click', function() {
          currentTheme.iconStyle = this.dataset.iconName;
          const headerButton = document.getElementById('header-icon-picker-btn');
          if (headerButton) headerButton.innerHTML = iconSvg(currentTheme.iconStyle) + ' Choose header icon';
          applyTheme(currentTheme);
          generateSchema();
          closeIconPicker();
          setStudioStatus('Header icon updated. Save changes to keep it.');
          commitThemeHistoryRecord();
        });
      });
    }

    function openIconPicker(anchor) {
      if (!iconPicker) return;
      closeComponentPicker();
      if (paramIconSearchInput) {
        paramIconSearchInput.value = '';
      }
      const rect = anchor ? anchor.getBoundingClientRect() : null;
      if (rect) {
        iconPicker.style.left = Math.max(12, Math.min(window.innerWidth - 340, rect.left)) + 'px';
        iconPicker.style.top = Math.min(window.innerHeight - 280, rect.bottom + 8) + 'px';
      } else {
        iconPicker.style.left = 'auto';
        iconPicker.style.right = '24px';
        iconPicker.style.top = '86px';
      }
      iconPicker.classList.add('is-open');
      if (paramIconSearchInput) {
        window.setTimeout(function() { paramIconSearchInput.focus(); }, 30);
      }
    }

    function closeIconPicker() {
      if (iconPicker) iconPicker.classList.remove('is-open');
      activeIconCard = null;
      activeIconTargetType = 'param';
    }

    if (paramIconSearchInput) {
      paramIconSearchInput.addEventListener('input', function() {
        if (activeIconTargetType === 'header') {
          renderHeaderIconPicker(paramIconSearchInput.value);
        } else if (activeIconCard) {
          renderParamIconPicker(activeIconCard, activeIconTargetType, paramIconSearchInput.value);
        }
      });
    }

    window.addEventListener('scroll', function(event) {
      if (event.target && iconPicker && iconPicker.contains(event.target)) return;
      if (event.target && componentPicker && componentPicker.contains(event.target)) return;
      closeIconPicker();
      closeComponentPicker();
    }, true);

    // Control Order
    function getTopLevelControlBlocks(scope) {
      const root = scope || document;
      return Array.from(root.querySelectorAll('.param-list')).reduce(function(blocks, list) {
        Array.from(list.children).forEach(function(child) {
          if (child.matches && (child.matches('.param-group-card') || child.matches('.param-card'))) {
            blocks.push(child);
          }
        });
        return blocks;
      }, []);
    }

    function getControlsGroupedByPage() {
      const groups = [];
      const slides = queryPreviewAll('.page-slide');
      const slideSource = slides.length ? slides : Array.from(document.querySelectorAll('.page-slide'));
      slideSource.forEach(function(slide) {
        const pageNo = String(slide.dataset.pageNo || '');
        const pageName = String(slide.dataset.pageTitle || ('Page ' + pageNo));
        const controls = getTopLevelControlBlocks(slide).map(function(block) {
          return {
            key: block.dataset.paramKey,
            name: block.dataset.paramName || block.dataset.paramKey
          };
        }).filter(function(item) {
          return item.key;
        });
        groups.push({ pageNo: pageNo, pageName: pageName, controls: controls });
      });
      return groups;
    }

    function getAllControlKeys() {
      const keys = [];
      getControlsGroupedByPage().forEach(function(group) {
        group.controls.forEach(function(item) {
          keys.push(item);
        });
      });
      return keys;
    }

    function normalizedControlOrder() {
      const all = getAllControlKeys();
      const known = new Set(all.map(function(item) { return item.key; }));
      const saved = Array.isArray(currentTheme.controlOrder) ? currentTheme.controlOrder.filter(function(key) {
        return known.has(key);
      }) : [];
      all.forEach(function(item) {
        if (saved.indexOf(item.key) === -1) saved.push(item.key);
      });
      currentTheme.controlOrder = saved;
      return saved;
    }

    function getOrderedKeysForPage(pageNo) {
      const group = getControlsGroupedByPage().find(function(item) {
        return String(item.pageNo) === String(pageNo);
      });
      if (!group) return [];
      const groupKeys = group.controls.map(function(item) { return item.key; });
      const savedOrder = normalizedControlOrder();
      const orderedKeys = savedOrder.filter(function(key) {
        return groupKeys.indexOf(key) !== -1;
      });
      groupKeys.forEach(function(key) {
        if (orderedKeys.indexOf(key) === -1) orderedKeys.push(key);
      });
      return orderedKeys;
    }

    function setPageControlOrder(pageNo, orderedKeys) {
      normalizedControlOrder();
      const groups = getControlsGroupedByPage();
      const newOrder = [];
      groups.forEach(function(group) {
        if (String(group.pageNo) === String(pageNo)) {
          orderedKeys.forEach(function(key) {
            if (newOrder.indexOf(key) === -1) newOrder.push(key);
          });
          return;
        }
        const groupKeys = group.controls.map(function(item) { return item.key; });
        currentTheme.controlOrder.forEach(function(key) {
          if (groupKeys.indexOf(key) !== -1 && newOrder.indexOf(key) === -1) newOrder.push(key);
        });
        groupKeys.forEach(function(key) {
          if (newOrder.indexOf(key) === -1) newOrder.push(key);
        });
      });
      currentTheme.controlOrder = newOrder;
      return newOrder;
    }

    function populateOrderPageSelect() {
      const select = document.getElementById('studio-order-page-select');
      if (!select) return;
      const groups = getControlsGroupedByPage();
      const previous = selectedOrderPage;
      select.innerHTML = '<option value="">Choose page</option>' + groups.map(function(group) {
        const label = 'Page ' + group.pageNo + (group.pageName ? ' - ' + group.pageName : '');
        return '<option value="' + escapeHtml(String(group.pageNo)) + '">' + escapeHtml(label) + '</option>';
      }).join('');
      const hasPrevious = previous && groups.some(function(group) {
        return String(group.pageNo) === String(previous);
      });
      selectedOrderPage = hasPrevious ? previous : (groups[0] ? String(groups[0].pageNo) : '');
      if (selectedOrderPage) {
        select.value = selectedOrderPage;
      }
    }

    function bindOrderPageSelect() {
      const select = document.getElementById('studio-order-page-select');
      if (!select || select.dataset.bound === '1') return;
      select.dataset.bound = '1';
      select.addEventListener('change', function() {
        selectedOrderPage = select.value || '';
        renderOrderList();
        if (selectedOrderPage) {
          const targetSlide = Array.from(document.querySelectorAll('.page-slide')).find(function(slide) {
            return String(slide.dataset.pageNo) === String(selectedOrderPage);
          });
          if (targetSlide) {
            const slideIndex = slides.indexOf(targetSlide);
            if (slideIndex >= 0) showSlide(slideIndex);
          }
          setStudioStatus('Reordering controls for Page ' + selectedOrderPage + '.');
        }
      });
    }

    function moveControlInSelectedPage(key, delta) {
      if (!selectedOrderPage || !key) return;
      const keys = getOrderedKeysForPage(selectedOrderPage);
      const index = keys.indexOf(key);
      if (index < 0) return;
      const newIndex = index + delta;
      if (newIndex < 0 || newIndex >= keys.length) return;
      keys.splice(index, 1);
      keys.splice(newIndex, 0, key);
      setPageControlOrder(selectedOrderPage, keys);
      applyControlOrder();
      generateSchema();
      setStudioStatus('Control order updated for Page ' + selectedOrderPage + '.');
      commitThemeHistoryRecord();
    }

    function renderOrderList() {
      if (!orderList) return;
      populateOrderPageSelect();
      const groups = getControlsGroupedByPage();
      const controlsByKey = {};
      getAllControlKeys().forEach(function(item) {
        controlsByKey[item.key] = item.name;
      });

      if (!groups.length) {
        orderList.innerHTML = '<p class="order-page-hint">No linked parameters yet. Add parameters to a page to reorder them here.</p>';
        return;
      }

      if (!selectedOrderPage) {
        orderList.innerHTML = '<p class="order-page-hint">Select a page above to reorder its controls.</p>';
        return;
      }

      const orderedKeys = getOrderedKeysForPage(selectedOrderPage);
      orderList.innerHTML = '';
      if (!orderedKeys.length) {
        orderList.innerHTML = '<p class="order-page-hint">No controls found on this page.</p>';
        return;
      }

        orderedKeys.forEach(function(key, index) {
          const row = document.createElement('div');
          row.className = 'order-row';
          row.draggable = true;
          row.dataset.orderKey = key;
        row.dataset.pageNo = selectedOrderPage;
          row.innerHTML =
            '<span class="order-row-index">' + (index + 1) + '</span>' +
            '<span class="order-row-name" title="' + escapeHtml(key) + '">' + escapeHtml(controlsByKey[key] || key) + '</span>' +
          '<div class="order-row-actions">' +
            '<button type="button" class="order-move-btn" data-order-move="up" aria-label="Move up"' + (index === 0 ? ' disabled' : '') + '>' + iconSvg('chevron-left') + '</button>' +
            '<button type="button" class="order-move-btn" data-order-move="down" aria-label="Move down"' + (index === orderedKeys.length - 1 ? ' disabled' : '') + '>' + iconSvg('chevron-left') + '</button>' +
          '</div>' +
            '<span class="order-grip">' + iconSvg('move') + '</span>';
        orderList.appendChild(row);
      });
    }

    function rebuildControlOrderFromDom() {
      if (!orderList || !selectedOrderPage) return currentTheme.controlOrder || [];
      const pageKeys = [];
      orderList.querySelectorAll('.order-row').forEach(function(row) {
        pageKeys.push(row.dataset.orderKey);
      });
      return setPageControlOrder(selectedOrderPage, pageKeys);
    }

    function applyControlOrder() {
      normalizedControlOrder();
      document.querySelectorAll('.param-list').forEach(function(list) {
        const blocks = Array.from(list.children).filter(function(child) {
          return child.matches && (child.matches('.param-group-card') || child.matches('.param-card'));
        });
        blocks.sort(function(a, b) {
          const aIndex = controlOrderIndexForKey(currentTheme.controlOrder, a.dataset.paramKey);
          const bIndex = controlOrderIndexForKey(currentTheme.controlOrder, b.dataset.paramKey);
          if (aIndex === -1 && bIndex === -1) {
            const aSeq = parseInt(a.dataset.sequence || '0', 10) || 0;
            const bSeq = parseInt(b.dataset.sequence || '0', 10) || 0;
            return aSeq - bSeq;
          }
          if (aIndex === -1) return 1;
          if (bIndex === -1) return -1;
          if (aIndex !== bIndex) return aIndex - bIndex;
          const aSeq = parseInt(a.dataset.sequence || '0', 10) || 0;
          const bSeq = parseInt(b.dataset.sequence || '0', 10) || 0;
          return aSeq - bSeq;
        });
        blocks.forEach(function(block) {
          list.appendChild(block);
        });
      });
      renderOrderList();
    }

    function bindControlOrderList() {
      if (!orderList || orderList.dataset.bound === '1') return;
      orderList.dataset.bound = '1';

      orderList.addEventListener('click', function(event) {
        const moveButton = event.target.closest('.order-move-btn');
        if (!moveButton || moveButton.disabled) return;
        event.preventDefault();
        event.stopPropagation();
        const row = moveButton.closest('.order-row');
        if (!row) return;
        moveControlInSelectedPage(row.dataset.orderKey, moveButton.dataset.orderMove === 'up' ? -1 : 1);
      });

      orderList.addEventListener('dragstart', function(event) {
        if (event.target.closest('.order-move-btn')) {
          event.preventDefault();
          return;
        }
        const row = event.target.closest('.order-row');
        if (!row) return;
        draggedOrderKey = row.dataset.orderKey;
        draggedOrderPageNo = selectedOrderPage || row.dataset.pageNo || '';
        row.classList.add('is-dragging');
        event.dataTransfer.effectAllowed = 'move';
      });

      orderList.addEventListener('dragend', function(event) {
        const row = event.target.closest('.order-row');
        if (row) row.classList.remove('is-dragging');
        draggedOrderKey = '';
        draggedOrderPageNo = '';
      });

      orderList.addEventListener('dragover', function(event) {
        const row = event.target.closest('.order-row');
        if (!row || !draggedOrderKey) return;
        event.preventDefault();
      });

      orderList.addEventListener('drop', function(event) {
        event.preventDefault();
        const targetRow = event.target.closest('.order-row');
        if (!targetRow || !draggedOrderKey || targetRow.dataset.orderKey === draggedOrderKey) return;

        const rows = Array.from(orderList.querySelectorAll('.order-row'));
        const fromIndex = rows.findIndex(function(row) { return row.dataset.orderKey === draggedOrderKey; });
        const toIndex = rows.findIndex(function(row) { return row.dataset.orderKey === targetRow.dataset.orderKey; });
        if (fromIndex < 0 || toIndex < 0 || fromIndex === toIndex) return;

        const moved = rows.splice(fromIndex, 1)[0];
        rows.splice(toIndex, 0, moved);
        rows.forEach(function(row) {
          orderList.appendChild(row);
        });

        rebuildControlOrderFromDom();
        applyControlOrder();
        generateSchema();
        setStudioStatus('Control order updated for Page ' + (selectedOrderPage || targetRow.dataset.pageNo || '') + '.');
        commitThemeHistoryRecord();
      });
    }

    // Convert the exact browser preview into a renderer-neutral document.  The
    // neutral core is the source of truth; preview-specific HTML/CSS is retained
    // under extensions so older consumers can still reproduce this screen.
    function buildUniversalSchema(previewSchema, pages, controls) {
