          saveTheme: action('onTap', 'api', saveThemeUrl || '', { modalId: modalId, modelNo: modelNo, operation: 'saveTheme' }),
          openEditUi: action('onTap', 'navigation', editPageLinkingUrl || '', { modalId: modalId, modelNo: modelNo }),
          previousPage: action('onTap', 'update', 'activePageIndex=max(activePageIndex-1,0)'),
          nextPage: action('onTap', 'update', 'activePageIndex=min(activePageIndex+1,pages.length-1)'),
          selectPage: action('onTap', 'update', 'activePageIndex={pageIndex}')
        }, controlsBundle.controlActions || {}),
        mobileView: {
          device: {
            mode: currentTheme.deviceMode || 'mobile',
            previewWidth: 375,
            previewHeight: 812,
            rootClass: 'phone-shell'
          },
          shell: {
            backgroundType: currentTheme.backgroundType,
            backgroundColor: currentTheme.backgroundColor,
            gradientColor: currentTheme.gradientColor,
            screenColor: currentTheme.shellColor,
            pagePadding: pagePadding,
            width: 'min(100%, 430px)',
            height: 'matchParent',
            maxHeight: 'matchParent',
            overflow: 'hidden',
            scrollRegion: 'page-slide',
            layoutMode: 'adaptiveSafeArea',
            previewOnly: {
              width: 375,
              height: 812,
              role: 'studioPreviewOnly'
            }
          },
          header: {
            height: n(currentTheme.headerHeight, 72),
            backgroundColor: headerChrome.backgroundColor,
            foregroundColor: headerChrome.titleColor,
            alignment: headerAlignment,
            titleSource: 'state.activePageName',
            subtitlePattern: 'Page {pageNo}.Operation',
            showHeaderIcons: bool(currentTheme.showHeaderIcons),
            backButton: {
              backgroundColor: headerChrome.backBackground,
              foregroundColor: headerChrome.backForeground,
              borderColor: headerChrome.actionBorder
            },
            actions: [
              { id: 'scan', icon: 'scan', label: 'Scan', action: 'openScanner', plugin: 'qrBarcodeScan', iconColor: headerChrome.actionForeground },
              { id: 'wifi', icon: 'wifi', label: 'WiFi', action: 'openWifiConfig', plugin: 'efactor.wifi', schemaPath: 'wifiProvisioning', entryScreen: 'wifiNetworkPicker', iconColor: headerChrome.actionForeground },
              { id: 'info', icon: 'info', label: 'Information', action: 'openDeviceInfo', schemaPath: 'infoPage', entryScreen: 'gatewayDetails', iconColor: headerChrome.actionForeground }
            ]
          },
          brandStrip: {
            visible: bool(currentTheme.brandVisible),
            modelNo: modelNo,
            showStatus: bool(currentTheme.showStatus),
            statusText: getDeviceConnectivityState().label,
            logoUrl: (brandLogo && brandLogo.url) || '',
            logoPath: (brandLogo && brandLogo.path) || '',
            logoFileName: (brandLogo && brandLogo.fileName) || ''
          },
          pageContent: {
            heroVisible: false,
            nameCardVisible: false,
            pageNavigatorVisible: bool(currentTheme.pageNavigatorVisible),
            footerVisible: includeFooterSaveButton,
            headerText: currentTheme.headerText || ''
          },
          footer: {
            visible: includeFooterSaveButton,
            buttonText: buttonLabel,
            buttonHeight: buttonHeight,
            buttonRadius: buttonRadius,
            buttonBg: buttonBg,
            buttonTextColor: buttonTextColor,
            buttonTarget: currentTheme.buttonTarget || 'save',
            buttonHover: currentTheme.buttonHover || 'lift',
            buttonIconPosition: currentTheme.buttonIconPosition || 'left',
            action: 'saveTheme'
          }
        },
        extensions: {
          universalUi: buildSchema(),
          notes: 'Primary Flutter contract is schema v4. extensions.universalUi contains the cross-platform neutral schema (v2.1) for HTML/Android/Swift/React Native renderers.'
        },
        ui: {
          widgetTree: root
        },
        wifiProvisioning: wifiProvisioning,
        infoPage: infoPage,
        validation: extendedSchema.validation,
        updatedAt: generatedStamp.ist,
        updateReason: 'Production v4 schema with Flutter render entry at ui.widgetTree, typed state.parameters bindings, rendererContract, and full extended contracts for app consumption.'
      };
      return attachProductionFlutterPayload(normalizeSchemaForAppDeveloperReport(resolveSchemaValues(schema)));
    }

    const schemaCache = {
      dirty: true,
      schema: null,
      compact: '',
      pretty: ''
    };

    function markSchemaDirty() {
      schemaCache.dirty = true;
      scheduleAutoSchemaGenerate();
      schemaCache.pretty = '';
    }

    function stringifySchemaSafe(value, pretty) {
      const ancestors = [];
      try {
        return JSON.stringify(value, function(key, current) {
          if (current && typeof current === 'object') {
            if (typeof Node !== 'undefined' && current instanceof Node) return undefined;
            while (ancestors.length && ancestors[ancestors.length - 1] !== this) {
              ancestors.pop();
            }
            if (ancestors.indexOf(current) !== -1) return undefined;
            ancestors.push(current);
          }
          if (typeof current === 'function') return undefined;
          if (typeof current === 'number' && !isFinite(current)) return null;
          return current;
        }, pretty ? 2 : undefined);
      } catch (error) {
        throw new Error('Schema JSON serialization failed: ' + (error && error.message ? error.message : String(error)));
      }
    }

    function writeCachedSchemaOutput() {
      if (!schemaOutput) return;
      if (!schemaCache.pretty && schemaCache.schema) {
        schemaCache.pretty = stringifySchemaSafe(schemaCache.schema, true);
      }
      schemaOutput.value = schemaCache.pretty || schemaCache.compact || '';
    }

    let autoSchemaGenerateTimer = null;

    function scheduleAutoSchemaGenerate() {
      window.clearTimeout(autoSchemaGenerateTimer);
      autoSchemaGenerateTimer = window.setTimeout(function() {
        generateSchema({ force: true });
      }, 400);
    }

    function generateSchema(options) {
      options = options || {};
      const writeOutput = options.writeOutput === true;
      // Rebuild when forced/saved/Skema — or automatically when cache is dirty/empty
      // so designers do not need to click Skema after every Studio change.
      let rebuild = options.force === true || options.forSave === true || writeOutput === true;
      if (!rebuild) {
        if (schemaCache.dirty || !schemaCache.schema) {
          rebuild = true;
        } else {
          return schemaCache.schema;
        }
      }

      if (!options.force && !options.forSave && !writeOutput && !schemaCache.dirty && schemaCache.schema) {
        if (writeOutput) writeCachedSchemaOutput();
        syncSchemaApiUrlField();
        return schemaCache.schema;
      }

      try {
        syncThemeStateFromPreview();
        currentTheme.nodeId = getStudioNodeId();
        const schema = buildFlutterWidgetSchema();
        schemaCache.schema = schema;
        schemaCache.compact = stringifySchemaSafe(schema);
        schemaCache.pretty = writeOutput ? stringifySchemaSafe(schema, true) : '';
        schemaCache.dirty = false;
        if (writeOutput) writeCachedSchemaOutput();
        syncSchemaApiUrlField();
        return schema;
      } catch (error) {
        console.error('Schema generation failed:', error);
        if (schemaOutput) {
          schemaOutput.value = JSON.stringify({
            error: 'Schema generation failed',
            message: error && error.message ? error.message : String(error)
          }, null, 2);
        }
        setStudioStatus('Schema generation failed. Check the browser console for details.');
        return null;
      }
    }

    function isUsableStudioNodeId(value) {
      const id = String(value || '').trim();
      if (!id) return '';
      if (modelNo && id.toLowerCase() === String(modelNo).toLowerCase()) return '';
      return id;
    }

    function getStudioNodeId() {
      return isUsableStudioNodeId(schemaNodeIdInput ? schemaNodeIdInput.value : '')
        || isUsableStudioNodeId(currentTheme && currentTheme.nodeId)
        || isUsableStudioNodeId(resolvedStudioNodeId)
        || isUsableStudioNodeId(deviceUiInfo && deviceUiInfo.nodes)
        || '';
    }

    function buildQueryApiUrl(baseUrl, params) {
      const base = String(baseUrl || '').trim();
      if (!base) return '';
      try {
        const url = new URL(base, window.location.origin || undefined);
        Object.keys(params || {}).forEach(function(key) {
          const value = params[key];
          if (value !== undefined && value !== null && String(value).trim() !== '') {
            url.searchParams.set(key, String(value).trim());
          }
        });
        if (url.protocol === 'http:' && url.hostname !== 'localhost' && url.hostname !== '127.0.0.1') {
          url.protocol = 'https:';
        }
        return url.toString();
      } catch (error) {
        const query = Object.keys(params || {}).filter(function(key) {
          const value = params[key];
          return value !== undefined && value !== null && String(value).trim() !== '';
        }).map(function(key) {
          return encodeURIComponent(key) + '=' + encodeURIComponent(String(params[key]).trim());
        }).join('&');
        return base + (base.indexOf('?') === -1 ? '?' : '&') + query;
      }
    }

    function buildSchemaApiUrlForStudio(nodeIdOverride) {
      const nodeId = typeof nodeIdOverride === 'string' ? nodeIdOverride.trim() : getStudioNodeId();
      return buildQueryApiUrl(v8SchemaApiBase || schemaApiUrl, {
        model_no: modelNo || '',
        node_id: nodeId || ''
      });
    }

    function getStudioSchemaPageNo() {
      if (!schemaPageNoInput) return '';
      const raw = String(schemaPageNoInput.value || '').trim();
      if (!raw) return '';
      const num = parseInt(raw, 10);
      if (!Number.isFinite(num) || num < 1) return '';
      return String(num);
    }

    function buildStudioSchemaApiUrl() {
      const params = {
        model_no: modelNo || '',
        node_id: getStudioNodeId() || ''
      };
      const pageNo = getStudioSchemaPageNo();
      if (pageNo) {
        params.page_no = pageNo;
      }
      return buildQueryApiUrl(v8SchemaApiBase || schemaApiUrl, params);
    }

    function buildScanApiUrlForStudio() {
      return buildQueryApiUrl(legacyScanApiBase, {
        model_no: modelNo || '',
        node_id: getStudioNodeId() || ''
      });
    }

    function syncSchemaApiUrlField() {
      if (!schemaApiUrlInput) return;
      // Studio preview URL may include page_no; published schema URLs stay full (no page_no).
      schemaApiUrlInput.value = buildStudioSchemaApiUrl();
    }

    function buildNodeIdSchemaSection(resolvedNodeId) {
      const nodeId = resolvedNodeId || getStudioNodeId() || '';
      return {
        id: nodeId,
        modelNo: modelNo || '',
        model_id: modelNo || '',
        value: nodeId,
        source: nodeId ? (getStudioNodeId() ? 'studio' : 'api') : 'none',
        binding: 'node_id.id',
        schemaApi: buildSchemaApiUrlForStudio(nodeId)
      };
    }

    function getSchemaApiUrl() {
      return String((schemaApiUrlInput && schemaApiUrlInput.value) || buildSchemaApiUrlForStudio() || schemaApiUrl || '').trim();
    }

    function loadSchemaFromApi(button) {
      const url = getSchemaApiUrl();
      if (!url) {
        setStudioStatus('Schema API URL is empty.');
        return Promise.resolve(null);
      }
      setStudioStatus('Loading schema from API...');
      setButtonLoading(button, true, 'Loading');
      if (schemaOutput) {
        schemaOutput.value = 'Loading schema from API...';
      }
      return fetch(url, { method: 'GET', credentials: 'same-origin' })
        .then(function(response) {
          return response.text().then(function(body) {
            if (!response.ok) {
              throw new Error(body || 'Schema API request failed.');
            }
            try {
              return JSON.parse(body);
            } catch (error) {
              return body;
            }
          });
        })
        .then(function(payload) {
          if (schemaOutput) {
            schemaOutput.value = typeof payload === 'string' ? payload : JSON.stringify(payload, null, 2);
          }
          setStudioStatus('Schema API response loaded.');
          return payload;
        })
        .catch(function(error) {
          if (schemaOutput) {
            schemaOutput.value = JSON.stringify({
              error: 'Schema API request failed',
              message: error && error.message ? error.message : String(error),
              url: url
            }, null, 2);
          }
          setStudioStatus(error && error.message ? error.message : 'Schema API request failed.');
          return null;
        })
        .finally(function() {
          setButtonLoading(button, false);
        });
    }

    function copyStudioText(text, successMessage, button) {
      const onCopied = function() {
        setStudioStatus(successMessage);
        if (button) {
          const originalHtml = button.getAttribute('data-copy-label') || button.innerHTML;
          if (!button.getAttribute('data-copy-label')) {
            button.setAttribute('data-copy-label', originalHtml);
          }
          button.classList.add('is-copied');
          button.textContent = 'Copied';
          window.clearTimeout(button._copyResetTimer);
          button._copyResetTimer = window.setTimeout(function() {
            button.classList.remove('is-copied');
            button.innerHTML = button.getAttribute('data-copy-label') || originalHtml;
          }, 1600);
        }
        showSaveToast(successMessage || 'Copied');
      };
      if (!text) {
        setStudioStatus('Nothing to copy.');
        return;
      }
      if (navigator.clipboard && window.isSecureContext) {
        navigator.clipboard.writeText(text).then(onCopied).catch(function() {
          const temp = document.createElement('textarea');
          temp.value = text;
          document.body.appendChild(temp);
          temp.select();
          document.execCommand('copy');
          document.body.removeChild(temp);
          onCopied();
        });
      } else {
        const temp = document.createElement('textarea');
        temp.value = text;
        document.body.appendChild(temp);
        temp.select();
        document.execCommand('copy');
        document.body.removeChild(temp);
        onCopied();
      }
    }

    function buildSduiSchema() {
      if (!window.EfactorSdui || typeof window.EfactorSdui.buildDocument !== 'function') {
        throw new Error('EfactorSdui core library failed to load (assets/js/sdui/sdui-core.js).');
      }

      const controlsBundle = buildControlsSchema();
      const pagesMeta = controlsBundle.pages || [];
      const visibleControls = (controlsBundle.controls || []).filter(function(control) {
        return control.visible !== false;
      }).map(function(control) {
        const lookupKey = String(control.id || control.parameterKey || '');
        const card = lookupKey
          ? document.querySelector('.param-card[data-param-key="' + lookupKey.replace(/"/g, '') + '"]')
          : null;
        const meta = card ? getEffectiveParamMeta(card) : {};
        return Object.assign({}, control, {
          meta: {
            command_id: meta.command_id || meta.commandId || null,
            function_code: meta.function_code || meta.functionCode || null,
            action_id: meta.action_id || meta.actionId || null,
            frame: control.deviceFrame || buildDeviceFrameFromMeta(control.parameterName || control.label, meta)
          },
          deviceFrame: control.deviceFrame || buildDeviceFrameFromMeta(control.parameterName || control.label, meta),
          readOnly: control.readOnly === true || !!(control.component && control.component.readOnly) || control.componentType === 'linearGauge',
          interactive: control.writable === true && (control.componentType === 'powerGauge' || control.componentType === 'needleGauge')
        });
      });
      const usedIconNames = collectUsedIconNames(visibleControls);
      const fontFamily = currentTheme.fontFamily || 'Inter';
      const fontAsset = fontAssetForFamily(fontFamily) || ('assets/fonts/' + String(fontFamily).replace(/\s+/g, '') + '-Regular.ttf');
      const schemaDocsUrl = (window.location.origin || '') + '/assets/js/sdui/schema/server-driven-ui.schema.json';

      return window.EfactorSdui.buildDocument({
        theme: currentTheme,
        controls: visibleControls,
        pages: pagesMeta,
        modelNo: modelNo || 'Linked UI',
        modalId: modalId,
        activeIndex: typeof activeIndex === 'number' ? activeIndex : 0,
        locale: document.documentElement.lang || 'en-IN',
        origin: window.location.origin,
        fontAsset: fontAsset,
        parametersApiUrl: parametersApiUrl || '',
        saveThemeUrl: saveThemeUrl || '',
        deviceInfoUrl: deviceInfoUrl || '',
        scanApiUrl: buildScanApiUrlForStudio(),
        wifiApiUrl: buildScanApiUrlForStudio(),
        schemaApiUrl: schemaApiUrl || '',
        schemaDocsUrl: schemaDocsUrl,
        usedIconNames: usedIconNames,
        arcStart: typeof POWER_GAUGE_ARC_START !== 'undefined' ? POWER_GAUGE_ARC_START : -210,
        arcSweep: typeof POWER_GAUGE_ARC_SWEEP !== 'undefined' ? POWER_GAUGE_ARC_SWEEP : 240
      });
    }

    function getPreviewZoomConfig(type) {
      const isStudio = type === 'studio';
      return {
        mount: isStudio ? studioPreviewMount : pagePreviewMount,
        frame: isStudio ? studioPreviewFrame : pagePreviewFrame,
        labelEl: isStudio ? studioPreviewZoomLabel : pagePreviewZoomLabel,
        inBtn: isStudio ? studioPreviewZoomInBtn : pagePreviewZoomInBtn,
        outBtn: isStudio ? studioPreviewZoomOutBtn : pagePreviewZoomOutBtn,
        fitBtn: isStudio ? studioPreviewZoomFitBtn : pagePreviewZoomFitBtn,
        state: previewZoomStates[type],
        isActive: function() {
          return isStudio
            ? document.body.classList.contains('studio-open')
            : !document.body.classList.contains('studio-open');
        }
      };
    }

    function getActivePreviewZoomConfig() {
      return document.body.classList.contains('studio-open')
        ? getPreviewZoomConfig('studio')
        : getPreviewZoomConfig('page');
    }

    function getPreviewFitScale(config) {
      if (!config.mount || !config.frame) return 1;
      config.frame.style.transform = '';
      config.frame.style.marginBottom = '';
      const mountHeight = config.mount.clientHeight;
      const mountWidth = config.mount.clientWidth;
      const frameHeight = config.frame.offsetHeight;
      const frameWidth = config.frame.offsetWidth;
      if (!mountHeight || !frameHeight) return 1;
      const scaleY = (mountHeight - 16) / frameHeight;
      const scaleX = (mountWidth > 0 && frameWidth > 0) ? (mountWidth - 16) / frameWidth : 1;
      return Math.max(PREVIEW_ZOOM_MIN, Math.min(1, scaleX, scaleY));
    }

    function updatePreviewZoomUi(config, scale) {
      if (config.labelEl) {
        config.labelEl.textContent = Math.round(scale * 100) + '%';
      }
      if (config.outBtn) {
        config.outBtn.disabled = !config.state.autoFit && scale <= PREVIEW_ZOOM_MIN + 0.001;
      }
      if (config.inBtn) {
        config.inBtn.disabled = !config.state.autoFit && scale >= PREVIEW_ZOOM_MAX - 0.001;
      }
      if (config.fitBtn) {
        config.fitBtn.classList.toggle('is-active', config.state.autoFit);
      }
    }

    function applyPreviewZoom(config) {
      if (!config || !config.mount || !config.frame || !config.isActive()) return;
      let scale = config.state.autoFit ? getPreviewFitScale(config) : config.state.manualScale;
      if (!config.state.autoFit) {
        scale = Math.max(PREVIEW_ZOOM_MIN, Math.min(PREVIEW_ZOOM_MAX, scale));
        config.state.manualScale = scale;
      }
      const frameHeight = config.frame.offsetHeight;
      if (Math.abs(scale - 1) > 0.001) {
        config.frame.style.transform = 'scale(' + scale + ')';
        config.frame.style.marginBottom = ((frameHeight * scale) - frameHeight) + 'px';
      } else {
        config.frame.style.transform = '';
        config.frame.style.marginBottom = '';
      }
      updatePreviewZoomUi(config, scale);
    }

    function applyActivePreviewZoom() {
      applyPreviewZoom(getActivePreviewZoomConfig());
      syncSlideViewportWidth();
    }

    function zoomPreviewBy(config, delta) {
      if (!config || !config.isActive()) return;
      if (config.state.autoFit) {
        config.state.manualScale = getPreviewFitScale(config);
        config.state.autoFit = false;
      }
      config.state.manualScale = Math.max(
        PREVIEW_ZOOM_MIN,
        Math.min(PREVIEW_ZOOM_MAX, config.state.manualScale + delta)
      );
      applyPreviewZoom(config);
    }

    function zoomActivePreviewBy(delta) {
      zoomPreviewBy(getActivePreviewZoomConfig(), delta);
    }

    function resetPreviewZoomFit(config) {
      if (!config) return;
      config.state.autoFit = true;
      applyPreviewZoom(config);
    }

    function resetActivePreviewZoomFit() {
      resetPreviewZoomFit(getActivePreviewZoomConfig());
    }

    function bindPreviewZoomMount(config) {
      if (!config.mount) return;
      config.mount.addEventListener('wheel', function(event) {
        if (!config.isActive() || !event.ctrlKey) return;
        event.preventDefault();
        zoomPreviewBy(config, event.deltaY > 0 ? -PREVIEW_ZOOM_STEP : PREVIEW_ZOOM_STEP);
      }, { passive: false });
    }

    // Studio Controls
    function openStudio(event) {
      if (event && typeof event.preventDefault === 'function') {
        event.preventDefault();
      }
      if (event && typeof event.stopPropagation === 'function') {
        event.stopPropagation();
      }
      try {
        if (!studio) {
          console.error('Design Studio panel #ui-studio was not found.');
          return;
        }
        studio.classList.add('is-open');
        if (studioBackdrop) {
          studioBackdrop.classList.add('is-open');
        }
        document.body.classList.add('studio-open');
        const previewTarget = studioPreviewFrame || studioPreviewMount;
        if (phoneShell && previewTarget && phoneShell.parentNode !== previewTarget) {
          previewTarget.appendChild(phoneShell);
        }
        studio.setAttribute('aria-hidden', 'false');
        syncInputsFromTheme();
        applyTheme(currentTheme, { reinitializeComponents: true });
        activateStudioSection('studio-theme-section');
        refreshStudioParameterPanels();
        renderIconLibrary('');
        // Do not wipe schema cache on open — regenerating on every open makes Copy Schema very slow.
        previewZoomStates.studio.autoFit = true;
        previewZoomStates.studio.manualScale = 1;
        requestAnimationFrame(function() {
          syncSlideViewportWidth();
          applyTheme(currentTheme, { reinitializeComponents: false });
          refreshStudioParameterPanels();
          applyActivePreviewZoom();
          requestAnimationFrame(function() {
            refreshStudioParameterPanels();
            syncSlideViewportWidth();
            applyActivePreviewZoom();
          });
        });
      } catch (error) {
        console.error('Unable to open Design Studio:', error);
        if (studio) {
          studio.classList.add('is-open');
          studio.setAttribute('aria-hidden', 'false');
        }
        document.body.classList.add('studio-open');
        setStudioStatus('Studio opened with limited controls. Check the browser console for details.');
      }
    }
    window.openViewPageStudio = openStudio;

    function closeStudio() {
      if (studio) {
        studio.classList.remove('is-open');
        studio.setAttribute('aria-hidden', 'true');
      }
      if (studioBackdrop) {
        studioBackdrop.classList.remove('is-open');
      }
      document.body.classList.remove('studio-open');
      previewZoomStates.studio.autoFit = true;
      previewZoomStates.studio.manualScale = 1;
      if (studioPreviewFrame) {
        studioPreviewFrame.style.transform = '';
        studioPreviewFrame.style.marginBottom = '';
      }
      if (phoneShell && pagePreviewFrame && phoneShell.parentNode !== pagePreviewFrame) {
        pagePreviewFrame.appendChild(phoneShell);
      } else if (phoneShell && phoneHome.parentNode) {
        phoneHome.parentNode.insertBefore(phoneShell, phoneHome.nextSibling);
      }
      previewZoomStates.page.autoFit = true;
      previewZoomStates.page.manualScale = 1;
      requestAnimationFrame(function() {
        applyActivePreviewZoom();
        syncSlideViewportWidth();
      });
      closeIconPicker();
      closeComponentPicker();
    }

    let themeSchemaSyncTimer = null;

    function scheduleThemeSchemaSync() {
      // Debounce Studio edits → auto regenerates schema (no Skema click).
      markSchemaDirty();
    }

    // Theme Input Listeners
    themeInputs.forEach(function(input) {
      const updateThemeFromInput = function(commitSchema) {
        const key = input.dataset.themeKey;
        let value;
        if (input.type === 'checkbox') {
          value = input.checked ? '1' : '0';
        } else if (input.type === 'range') {
          value = parseRangeInputValue(input);
          input.value = String(value);
        } else {
          value = input.value;
        }
        if (TYPOGRAPHY_KEYS.indexOf(key) !== -1) {
          setActiveTypographyValue(key, value);
        } else {
          currentTheme[key] = value;
        }
        updateRangeBadge(input);
        if (input.type === 'color' && input.closest('#studio-theme-section, #studio-general-section')) {
          syncThemeColorLabels();
        }
        applyTheme(currentTheme);
        if (commitSchema) {
          window.clearTimeout(themeSchemaSyncTimer);
          generateSchema();
          commitThemeHistoryRecord();
        } else {
          scheduleThemeSchemaSync();
        }
      };
      input.addEventListener('input', function() {
        updateThemeFromInput(false);
      });
      input.addEventListener('change', function() {
        updateThemeFromInput(true);
      });
    });

    const themePresets = {
      light: {
        themeMode: 'pro', backgroundType: 'gradient', backgroundColor: '#F8FAFC', gradientColor: '#EEF2F7',
        shellColor: '#F8FAFC', cardColor: '#FFFFFF', textColor: '#0F172A', mutedTextColor: '#64748B',
        topbarColor: '#0F172A', accentColor: '#2563EB', secondaryColor: '#94A3B8', buttonBgColor: '#2563EB',
        buttonTextColor: '#FFFFFF', iconColor: '#2563EB', borderColor: '#E2E8F0', toggleOnColor: '#2563EB',
        toggleOffColor: '#CBD5E1', fontFamily: 'Inter', fontSize: 15, fontWeight: 500, letterSpacing: -0.2,
        lineHeight: 1.5, borderRadius: 16, shadowStrength: 42, headerHeight: 72, cardSpacing: 12, pagePadding: 16
      },
      dark: {
        themeMode: 'dark', backgroundType: 'gradient', backgroundColor: '#0B1220', gradientColor: '#111827',
        shellColor: '#0F172A', cardColor: '#1E293B', textColor: '#F8FAFC', mutedTextColor: '#94A3B8',
        topbarColor: '#020617', accentColor: '#60A5FA', secondaryColor: '#64748B', buttonBgColor: '#2563EB',
        buttonTextColor: '#FFFFFF', iconColor: '#60A5FA', borderColor: '#334155', toggleOnColor: '#60A5FA', toggleOffColor: '#475569',
        fontFamily: 'Inter', fontWeight: 500, shadowStrength: 50
      },
      ocean: {
        themeMode: 'ocean', backgroundType: 'gradient', backgroundColor: '#EFF6FF', gradientColor: '#DBEAFE',
        shellColor: '#F8FAFC', cardColor: '#FFFFFF', textColor: '#0F172A', mutedTextColor: '#64748B',
        topbarColor: '#1E3A8A', accentColor: '#2563EB', secondaryColor: '#93C5FD', buttonBgColor: '#2563EB',
        buttonTextColor: '#FFFFFF', iconColor: '#2563EB', borderColor: '#BFDBFE', fontFamily: 'Inter', fontWeight: 500
      },
      nature: {
        themeMode: 'nature', backgroundType: 'gradient', backgroundColor: '#ECFDF5', gradientColor: '#D1FAE5',
        shellColor: '#F0FDF4', cardColor: '#FFFFFF', textColor: '#0F172A', mutedTextColor: '#64748B',
        topbarColor: '#064E3B', accentColor: '#2563EB', secondaryColor: '#6EE7B7', buttonBgColor: '#2563EB',
        buttonTextColor: '#FFFFFF', iconColor: '#2563EB', borderColor: '#A7F3D0', fontFamily: 'Inter', fontWeight: 500
      },
      glass: {
        themeMode: 'glass', backgroundType: 'gradient', backgroundColor: '#F8FAFC', gradientColor: '#E2E8F0',
        shellColor: '#F8FAFC', cardColor: 'rgba(255,255,255,0.82)', textColor: '#0F172A', mutedTextColor: '#64748B',
        topbarColor: '#1E293B', accentColor: '#475569', secondaryColor: '#94A3B8', buttonBgColor: '#334155',
        buttonTextColor: '#FFFFFF', iconColor: '#334155', borderColor: '#CBD5E1', cardBlur: 12, shadowStrength: 36,
        fontFamily: 'Inter', fontWeight: 500
      }
    };

    document.querySelectorAll('[data-preset]').forEach(function(button) {
      button.addEventListener('click', function() {
        currentTheme = Object.assign({}, currentTheme, themePresets[button.dataset.preset] || {});
        syncInputsFromTheme();
        applyTheme(currentTheme);
        generateSchema();
        setStudioStatus('Preset applied. Save changes to keep it.');
        commitThemeHistoryRecord();
      });
    });

    document.querySelectorAll('[data-segment-key]').forEach(function(group) {
      group.addEventListener('click', function(event) {
        const button = event.target.closest('[data-segment-value]');
        if (!button) return;
        currentTheme[group.dataset.segmentKey] = button.dataset.segmentValue;
        syncInputsFromTheme();
        applyTheme(currentTheme);
        generateSchema();
        commitThemeHistoryRecord();
      });
    });

    function activateStudioSection(sectionId) {
      document.querySelectorAll('.studio-controls > .studio-section, .studio-inspector > .studio-section').forEach(function(section) {
        section.classList.toggle('is-active', section.id === sectionId);
      });

      document.querySelectorAll('.studio-controls, .studio-inspector').forEach(function(panel) {
        panel.classList.toggle('has-active', Boolean(panel.querySelector('.studio-section.is-active')));
      });

      document.querySelectorAll('.studio-nav-btn[data-studio-target]').forEach(function(navButton) {
        navButton.classList.toggle('is-active', navButton.dataset.studioTarget === sectionId);
      });

      renderParametersButtons();
      renderOrderList();
      renderIconLibrary(iconSearchInput ? iconSearchInput.value : '');
      if (sectionId === 'studio-schema-section') {
        syncSchemaApiUrlField();
      }
    }

    document.querySelectorAll('.studio-nav-btn[data-studio-target]').forEach(function(button) {
      button.addEventListener('click', function() {
        const sectionId = button.dataset.studioTarget;
        activateStudioSection(sectionId);
        if (sectionId !== 'studio-schema-section') return;
        if (!schemaCache.dirty && schemaCache.schema && schemaOutput && schemaOutput.value) {
          syncSchemaApiUrlField();
          return;
        }
        setButtonLoading(button, true, 'Loading');
        afterStudioPaint(function() {
          generateSchema({ writeOutput: true });
          setButtonLoading(button, false);
          setStudioStatus('Device UI skema ready.');
        });
      });
    });

    // Icon Picker Outside Click
    document.addEventListener('click', function(event) {
      const iconTrigger = event.target.closest('[data-icon-picker-trigger]');
      if (iconTrigger) {
        event.preventDefault();
        activeIconCard = iconTrigger.closest('.param-card');
        activeIconTargetType = 'param';
        if (activeIconCard) {
          renderParamIconPicker(activeIconCard, 'param');
          openIconPicker(iconTrigger);
        }
        return;
      }

      const metaIconTrigger = event.target.closest('[data-meta-icon-picker-trigger]');
      if (metaIconTrigger) {
        event.preventDefault();
        activeIconCard = metaIconTrigger.closest('.param-card');
        activeIconTargetType = 'meta';
        if (activeIconCard) {
          renderParamIconPicker(activeIconCard, 'meta');
          openIconPicker(metaIconTrigger);
        }
        return;
      }

      if (iconPicker && iconPicker.classList.contains('is-open') && !event.target.closest('#param-icon-picker')) {
        closeIconPicker();
      }
      if (componentPicker && componentPicker.classList.contains('is-open') && !event.target.closest('#param-component-picker') && !event.target.closest('.param-component-edit')) {
        closeComponentPicker();
      }
    });

    function handleBackButton() {
      window.history.back();
    }

    function handleAppBackNavigation(event) {
      if (event && event.preventDefault) {
        event.preventDefault();
      }
      handleBackButton();
    }

    // Button Click Handlers
    bindClick('open-studio-btn', openStudio);
    bindClick('view-page-ui-back', handleAppBackNavigation);
    bindClick('phone-back-btn', handleAppBackNavigation);
    bindClick('open-studio-footer-btn', openStudio);
    bindClick('close-studio-btn', closeStudio);
    bindClick('studio-preview-zoom-in', function() {
      zoomPreviewBy(getPreviewZoomConfig('studio'), PREVIEW_ZOOM_STEP);
    });
    bindClick('studio-preview-zoom-out', function() {
      zoomPreviewBy(getPreviewZoomConfig('studio'), -PREVIEW_ZOOM_STEP);
    });
    bindClick('studio-preview-zoom-fit', function() {
      resetPreviewZoomFit(getPreviewZoomConfig('studio'));
    });
    bindClick('page-preview-zoom-in', function() {
      zoomPreviewBy(getPreviewZoomConfig('page'), PREVIEW_ZOOM_STEP);
    });
    bindClick('page-preview-zoom-out', function() {
      zoomPreviewBy(getPreviewZoomConfig('page'), -PREVIEW_ZOOM_STEP);
    });
    bindClick('page-preview-zoom-fit', function() {
      resetPreviewZoomFit(getPreviewZoomConfig('page'));
    });
    window.addEventListener('resize', applyActivePreviewZoom);
    bindPreviewZoomMount(getPreviewZoomConfig('page'));
    bindPreviewZoomMount(getPreviewZoomConfig('studio'));
    requestAnimationFrame(function() {
      applyActivePreviewZoom();
      requestAnimationFrame(applyActivePreviewZoom);
    });
    bindClick('device-info-btn', openDeviceInfoFromSchema);
    bindClick('device-scan-btn', openDeviceScannerFromSchema);
    bindClick('device-wifi-btn', openDeviceWifiFromSchema);
    bindClick('device-info-close-btn', handleDeviceOverlayBack);
    bindClick('device-wifi-header-scan-btn', openWifiQrScanner);
    if (deviceInfoContent && !deviceInfoContent.dataset.wifiBound) {
      deviceInfoContent.dataset.wifiBound = '1';
      deviceInfoContent.addEventListener('click', handleWifiProvisioningClick);
      deviceInfoContent.addEventListener('input', handleWifiProvisioningInput);
    }
    if (deviceInfoModal) {
      deviceInfoModal.addEventListener('click', function(event) {
        if (event.target === deviceInfoModal) closeDeviceInfoModal();
      });
    }
    document.addEventListener('keydown', function(event) {
      if (event.key === 'Escape' && deviceInfoModal && deviceInfoModal.classList.contains('is-open')) {
        handleDeviceOverlayBack();
      }
    });
    bindClick('header-icon-picker-btn', function(event) {
      activeIconCard = null;
      activeIconTargetType = 'header';
      renderHeaderIconPicker('');
      openIconPicker(event.currentTarget);
    });

    function resetThemePreview() {
      currentTheme = Object.assign({}, defaultTheme);
      currentTheme.parameterIcons = {};
      currentTheme.componentOverrides = {};
      currentTheme.pageTypography = {};
      selectedTypographyPage = 'all';
      populateTypographyPageSelect();
      syncInputsFromTheme();
      applyTheme(currentTheme, { reinitializeComponents: true });
      generateSchema();
      setStudioStatus('Theme reset in preview. Save to keep it.');
      commitThemeHistoryRecord();
    }

    bindClick('undo-theme-btn', undoThemeChange);
    bindClick('redo-theme-btn', redoThemeChange);
    bindClick('reset-theme-btn', resetThemePreview);
    bindClick('reset-theme-inline-btn', resetThemePreview);

    document.addEventListener('keydown', function(event) {
      const studio = document.getElementById('ui-studio');
      if (!studio || studio.getAttribute('aria-hidden') === 'true') return;
      const targetTag = event.target && event.target.tagName ? event.target.tagName.toLowerCase() : '';
      if (targetTag === 'input' || targetTag === 'textarea' || targetTag === 'select') return;
      const key = String(event.key || '').toLowerCase();
      if ((event.ctrlKey || event.metaKey) && !event.altKey && key === 'z' && !event.shiftKey) {
        event.preventDefault();
        undoThemeChange();
      } else if ((event.ctrlKey || event.metaKey) && !event.altKey && (key === 'y' || (key === 'z' && event.shiftKey))) {
        event.preventDefault();
        redoThemeChange();
      }
    });

    function generateSchemaFromButton(event) {
      const button = event && event.currentTarget ? event.currentTarget : document.getElementById('generate-schema-btn');
      activateStudioSection('studio-schema-section');
      if (!schemaCache.dirty && schemaCache.schema && schemaOutput && schemaOutput.value) {
        syncSchemaApiUrlField();
        setStudioStatus('Device UI skema ready.');
        return;
      }
      setButtonLoading(button, true, 'Loading');
      afterStudioPaint(function() {
        generateSchema({ writeOutput: true });
        setStudioStatus('Device UI skema generated successfully.');
        setButtonLoading(button, false);
      });
    }

    bindClick('generate-schema-btn', generateSchemaFromButton);

    bindClick('copy-schema-btn', function(event) {
      const button = event && event.currentTarget ? event.currentTarget : document.getElementById('copy-schema-btn');
      const copyReadyText = function() {
        copyStudioText(
          (schemaOutput && schemaOutput.value) || schemaCache.compact || schemaCache.pretty || '',
          'Schema copied to clipboard.',
          button
        );
      };
      if ((schemaOutput && schemaOutput.value) || schemaCache.compact || schemaCache.pretty || schemaCache.schema) {
        if (!schemaCache.compact && schemaCache.schema) {
          schemaCache.compact = stringifySchemaSafe(schemaCache.schema);
        }
        copyReadyText();
        return;
      }
      setButtonLoading(button, true, 'Copying');
      afterStudioPaint(function() {
        generateSchema({ writeOutput: false, force: true });
        copyReadyText();
        setButtonLoading(button, false);
      });
    });

    bindClick('copy-schema-api-url-btn', function(event) {
      const button = event && event.currentTarget ? event.currentTarget : document.getElementById('copy-schema-api-url-btn');
      syncSchemaApiUrlField();
      copyStudioText(getSchemaApiUrl(), 'Schema API URL copied.', button);
    });

    bindClick('view-schema-api-btn', function(event) {
      syncSchemaApiUrlField();
      loadSchemaFromApi(event.currentTarget);
    });

    if (schemaNodeIdInput) {
      let nodeIdSchemaTimer = null;
      const applyNodeIdChange = function(commit) {
        currentTheme.nodeId = getStudioNodeId();
        syncSchemaApiUrlField();
        window.clearTimeout(nodeIdSchemaTimer);
        if (commit) {
          generateSchema();
          setStudioStatus(getStudioNodeId()
            ? 'Node ID updated. Save to apply — only this node_id API will work after save.'
            : 'Node ID cleared. Save to apply — API will use model only.');
          commitThemeHistoryRecord();
          return;
        }
        nodeIdSchemaTimer = window.setTimeout(function() {
          generateSchema();
        }, 220);
      };
      schemaNodeIdInput.addEventListener('input', function() {
        applyNodeIdChange(false);
      });
      schemaNodeIdInput.addEventListener('change', function() {
        applyNodeIdChange(true);
      });
    }

    if (schemaPageNoInput) {
      const applyPageNoChange = function() {
        syncSchemaApiUrlField();
        const pageNo = getStudioSchemaPageNo();
        setStudioStatus(pageNo
          ? ('Schema API set to page_no=' + pageNo + '. Click View Skema to load that page.')
          : 'Schema API set to full schema. Click View Skema to load.');
      };
      schemaPageNoInput.addEventListener('input', applyPageNoChange);
      schemaPageNoInput.addEventListener('change', applyPageNoChange);
    }

    bindClick('save-theme-btn', function() {
      const saveButton = document.getElementById('save-theme-btn');
      setStudioStatus('Saving...');
      setButtonLoading(saveButton, true, 'Saving');
      afterStudioPaint(function() {
        const schema = generateSchema({ forSave: true, force: true });
        if (!schema) {
          setStudioStatus('Cannot save — schema generation failed.');
          setButtonLoading(saveButton, false);
          return;
        }
        const formData = new FormData();
        const themeForSave = buildThemePayloadForSave();
        formData.append('modelno', modelNo);
        formData.append('theme_json', JSON.stringify(themeForSave));
        formData.append('schema_json', schemaCache.compact || stringifySchemaSafe(schema));

        fetch(saveThemeUrl, {
          method: 'POST',
          body: formData,
          credentials: 'same-origin'
        })
        .then(parseSaveResponse)
        .then(function(result) {
          const saved = result.success === true || result.success === 1 || result.success === '1';
          setStudioStatus(result.message || (saved ? 'Saved successfully.' : 'Save failed.'));
          if (saved) {
            closeStudio();
            showSaveToast('UI created successfully.');
          }
        })
        .catch(function(error) {
          setStudioStatus(error && error.message ? error.message : 'Save failed. Please try again.');
        })
        .finally(function() {
          setButtonLoading(saveButton, false);
        });
      });
    });

    bindClick('save-ui-btn', function() {
      openStudio();
      setStudioStatus('Use Save Changes to store the device UI schema.');
    });

    // Initialization
    syncSlideViewportWidth();
    populateTypographyPageSelect();
    bindTypographyPageSelect();
    populateOrderPageSelect();
    bindOrderPageSelect();
    bindControlOrderList();
    syncInputsFromTheme();
    bindStudioColorRows(document.getElementById('studio-theme-section'));
    bindStudioColorRows(document.getElementById('studio-general-section'));
    applyTheme(currentTheme, { reinitializeComponents: true });
    resetThemeHistoryBaseline();
    refreshStudioParameterPanels();
    if (schemaNodeIdInput && !String(schemaNodeIdInput.value || '').trim()) {
      const autoNodeId = getStudioNodeId();
      if (autoNodeId) {
        schemaNodeIdInput.value = autoNodeId;
        currentTheme.nodeId = autoNodeId;
      }
    } else if (schemaNodeIdInput && String(schemaNodeIdInput.value || '').trim()) {
      currentTheme.nodeId = String(schemaNodeIdInput.value).trim();
    }
    syncSchemaApiUrlField();
    requestAnimationFrame(function() {
      syncSlideViewportWidth();
      refreshStudioParameterPanels();
    });
    if (shouldSyncLinkedSchema && modelNo) {
      afterStudioPaint(function() {
        function runLinkedSchemaSync(attempt) {
          attempt = attempt || 0;
          const sduiReady = !!(window.EfactorSdui && typeof window.EfactorSdui.buildDocument === 'function');
          if (!sduiReady && attempt < 24) {
            setTimeout(function() { runLinkedSchemaSync(attempt + 1); }, 250);
            return;
          }

          const initialSchema = generateSchema({ forSave: true, force: true });
          if (!initialSchema) {
            showSaveToast('Linked pages synced on server. Use Generate Schema if the Flutter document still looks stale.');
            if (window.history && window.history.replaceState) {
              const cleanUrl = new URL(window.location.href);
              cleanUrl.searchParams.delete('schema_sync');
              window.history.replaceState({}, document.title, cleanUrl.toString());
            }
            return;
          }

          const syncData = new FormData();
          const syncTheme = buildThemePayloadForSave();
          syncData.append('modelno', modelNo);
          syncData.append('theme_json', JSON.stringify(syncTheme));
          syncData.append('schema_json', schemaCache.compact || JSON.stringify(initialSchema));
          fetch(saveThemeUrl, { method: 'POST', body: syncData, credentials: 'same-origin' })
            .then(function(response) { return response.json(); })
            .then(function(result) {
              if (result && (result.success === true || result.success === 1 || result.success === '1')) {
                showSaveToast('Linked pages saved to schema.');
              } else {
                showSaveToast((result && result.message) ? result.message : 'Linked pages synced on server; Studio schema save failed.');
              }
              if (window.history && window.history.replaceState) {
                const cleanUrl = new URL(window.location.href);
                cleanUrl.searchParams.delete('schema_sync');
                window.history.replaceState({}, document.title, cleanUrl.toString());
              }
            })
            .catch(function() {
              showSaveToast('Linked pages synced on server, but Studio schema upload failed.');
              if (window.history && window.history.replaceState) {
                const cleanUrl = new URL(window.location.href);
                cleanUrl.searchParams.delete('schema_sync');
                window.history.replaceState({}, document.title, cleanUrl.toString());
              }
            });
        }
        runLinkedSchemaSync(0);
      });
    }
  </script>
</body>
</html>







